// MARK: - ArchiveStore Part 1 - v206 - Core (核心路由器适配模板目录) - 修复同步路径识别

class ArchiveStore: ObservableObject {
    // MARK: - Published States
    @Published var categories: [ArchiveCategory] = []
    @Published var templates: [ArchiveTemplate] = []
    @Published var smartViews: [SmartViewConfig] = []
    @Published var unmatchedTables: [ArchiveTable] = []
    @Published var taskLists: [ArchiveTable] = []
    
    @Published var collisionMessage: String? = nil
    
    // MARK: - Internal States
    let lock = NSRecursiveLock()
    var isFreshLaunch = false
    
    let fm = FileManager.default
    var fileModificationCache: [UUID: Date] = [:]
    struct FileCacheEntry { let modificationDate: Date; let table: ArchiveTable }
    var fileMetadataCache: [URL: FileCacheEntry] = [:]
    
    var smartResultsCache: [UUID: [SmartResultItem]] = [:]
    
    private var dirtyFilePaths: Set<String> = []
    
    var editingTableID: UUID? = nil
    var isUserEditing: Bool {
        get { editingTableID != nil }
        set { if !newValue { exitEditingMode() } }
    }
    
    // MARK: - Configuration & Constants
    @AppStorage("archive_category_sort_option_v1") var categorySortOption: CategorySortOption = .custom
    @AppStorage("archive_table_sort_option_v1") var tableSortOption: TableSortOption = .timeDesc
    
    enum CategorySortOption: String, CaseIterable, Codable {
        case custom = "用户自调", timeAsc = "时间正序", timeDesc = "时间逆序", nameAsc = "按照名字顺序", nameDesc = "按照名字逆序"
    }
    enum TableSortOption: String, CaseIterable, Codable {
        case timeAsc = "时间正序", timeDesc = "时间逆序", nameAsc = "按照名字顺序", nameDesc = "按照名字逆序"
    }

    let templateFileName = "archives_templates.json"
    let smartViewFileName = "archives_smart.json"
    let unmatchedFileName = "archives_unmatched.json"
    let orderFileName = "archives_category_order.json"
    
    var configRootURL: URL { CloudFileManager.shared.getCloudDir(.tables) }
    var tasksDirURL: URL { CloudFileManager.shared.getCloudDir(.records).appendingPathComponent("TaskLists") }

    struct SystemIDs {
        static let recycleBin = UUID(uuidString: "00000000-0000-0000-0000-000000000001")!
        static let autoFill   = UUID(uuidString: "00000000-0000-0000-0000-000000000002")!
        static let myFolder   = UUID(uuidString: "00000000-0000-0000-0000-000000000003")!
        static let importFolder = UUID(uuidString: "00000000-0000-0000-0000-000000000004")!
    }
    
    struct TemplateSimilarity: Identifiable {
        let id = UUID()
        let targetTemplate: ArchiveTemplate
        let type: SimilarityType
        let missingKeys: [String]
        let extraKeys: [String]
        enum SimilarityType: String {
            case exact = "完全一致"
            case subset = "子集 (可无损合并)"
            case superset = "超集 (需补充数据)"
        }
    }
    
    var userCategories: [ArchiveCategory] {
        let rawUserCats = categories.filter { $0.id != SystemIDs.recycleBin && $0.id != SystemIDs.autoFill }
        switch categorySortOption {
        case .custom: return rawUserCats
        case .nameAsc: return rawUserCats.sorted { $0.title.localizedStandardCompare($1.title) == .orderedAscending }
        case .nameDesc: return rawUserCats.sorted { $0.title.localizedStandardCompare($1.title) == .orderedDescending }
        case .timeAsc: return rawUserCats
        case .timeDesc: return rawUserCats.reversed()
        }
    }
    
    func getRecycleBin() -> ArchiveCategory? { categories.first(where: { $0.id == SystemIDs.recycleBin }) }
    func getAutoFill() -> ArchiveCategory? { categories.first(where: { $0.id == SystemIDs.autoFill }) }
    func clearSmartCache() { smartResultsCache.removeAll() }

    // MARK: - Initialization
    init() {
        let taskURL = CloudFileManager.shared.getCloudDir(.records).appendingPathComponent("TaskLists")
        try? fm.createDirectory(at: taskURL, withIntermediateDirectories: true)
        
        loadConfig()
        
        DispatchQueue.global(qos: .utility).async { [weak self] in
            guard let self = self else { return }
            self.loadDataFromFileSystem()
            self.loadTaskLists()
            
            DispatchQueue.main.async {
                self.ensureSystemFolders()
                self.scanImportFolder()
            }
        }
        
        NotificationCenter.default.addObserver(self, selector: NSSelectorFromString("handleCloudUpdate"), name: NSNotification.Name("CloudDataUpdated"), object: nil)
        NotificationCenter.default.addObserver(self, selector: #selector(handleCloudFileChange), name: .CloudFileDidChange, object: nil)
    }

    // MARK: - Core Internal Methods
    
    /// 处理文件级变更
    @objc func handleCloudFileChange(_ notification: Notification) {
        if !lock.try() { return }; defer { lock.unlock() }
        
        guard let userInfo = notification.userInfo,
              let path = userInfo["path"] as? String else { return }
        
        // 【186号核心修改】：增加对“模板/”路径的感知
        if editingTableID != nil {
            // 如果正在编辑，只有涉及到表格数据和清单数据的内容需要被拦截存入脏路径
            let isTableData = path.hasPrefix("表格/") || path.hasPrefix("记录/TaskLists/")
            
            // 配置文件现在主要存在于“模板/”和“表格/”根目录（旧数据）
            // 如果是表格数据且不是配置文件，则存入待处理集合
            if isTableData && !path.contains("archives_") {
                dirtyFilePaths.insert(path)
                return
            }
        }
        
        // 对于“模板/”下的配置文件变更或非编辑态下的数据变更，直接触发分发
        dispatchFileUpdate(path: path)
    }
    
    /// 退出编辑模式并处理积压更新
    func exitEditingMode() {
        editingTableID = nil
        if !dirtyFilePaths.isEmpty {
            let paths = dirtyFilePaths
            dirtyFilePaths.removeAll()
            for path in paths { dispatchFileUpdate(path: path) }
        }
    }
    
    /// 路由分发
    private func dispatchFileUpdate(path: String) {
        NotificationCenter.default.post(name: NSNotification.Name("ArchiveFileUpdateInternal"), object: nil, userInfo: ["path": path])
    }
}

// MARK: - ArchiveStore Part2 - Logic (逻辑树核心算法) - v201 - 支持6层深度
//
// extension ArchiveStore
// (修改：将最大层级限制从 4 (L5) 提升至 5 (L6))


extension ArchiveStore {
    
    // MARK: - Core Tree Algorithms
    
    func findSubtreeRange(in rows: [ArchiveRow], from rootIndex: Int) -> ClosedRange<Int> {
        guard rows.indices.contains(rootIndex),
              let rootData = parseTaskData(rows[rootIndex].value) else { return rootIndex...rootIndex }
        
        let rootLevel = rootData.level
        var endIndex = rootIndex
        
        for i in (rootIndex + 1)..<rows.count {
            if let data = parseTaskData(rows[i].value), data.level > rootLevel {
                endIndex = i
            } else {
                break
            }
        }
        return rootIndex...endIndex
    }

    func validateHierarchy(_ rows: inout [ArchiveRow]) {
        guard !rows.isEmpty else { return }
        
        // 1. 根节点约束
        if var firstData = parseTaskData(rows[0].value), firstData.level != 0 {
            firstData.level = 0
            if let json = try? JSONEncoder().encode(firstData), let s = String(data: json, encoding: .utf8) {
                rows[0].value = s
            }
        }
        
        // 2. 向下生长限制
        for i in 1..<rows.count {
            guard let prevData = parseTaskData(rows[i-1].value),
                  var currData = parseTaskData(rows[i].value) else { continue }
            
            let maxAllowed = prevData.level + 1
            if currData.level > maxAllowed {
                currData.level = maxAllowed
                // 【核心修改】深度封顶：最高 5 (L6)
                if currData.level > 5 { currData.level = 5 }
                
                if let json = try? JSONEncoder().encode(currData), let s = String(data: json, encoding: .utf8) {
                    rows[i].value = s
                }
            }
        }
    }

    func adjustBranchLevel(templateID: UUID, rootIDs: Set<UUID>, delta: Int) {
        lock.lock(); defer { lock.unlock() }
        guard let idx = templates.firstIndex(where: { $0.id == templateID }) else { return }
        var rows = templates[idx].taskRows
        
        var effectiveRoots: [Int] = []
        let sortedIndices = rootIDs.compactMap { id in rows.firstIndex(where: { $0.id == id }) }.sorted()
        
        for i in sortedIndices {
            if !effectiveRoots.contains(where: { findSubtreeRange(in: rows, from: $0).contains(i) }) {
                effectiveRoots.append(i)
            }
        }
        
        var hasCollision = false
        
        for rootIdx in effectiveRoots {
            let range = findSubtreeRange(in: rows, from: rootIdx)
            
            if let rootData = parseTaskData(rows[rootIdx].value) {
                if delta < 0 && rootIdx == 0 { hasCollision = true; continue }
                if delta > 0 {
                    let prevLevel = rootIdx > 0 ? (parseTaskData(rows[rootIdx-1].value)?.level ?? -1) : -1
                    if rootData.level + delta > prevLevel + 1 { hasCollision = true; continue }
                }
                // 【核心修改】边界检查：最大 5
                if delta > 0 && rootData.level + delta > 5 { hasCollision = true; continue }
            }
            
            for i in range {
                if var data = parseTaskData(rows[i].value) {
                    // 【核心修改】计算新层级：最大 5
                    let newLevel = max(0, min(5, data.level + delta))
                    data.level = newLevel
                    if let json = try? JSONEncoder().encode(data), let s = String(data: json, encoding: .utf8) {
                        rows[i].value = s
                    }
                }
            }
        }
        
        if hasCollision { triggerCollision("触碰层级边界，部分操作已忽略") }
        
        templates[idx].taskRows = rows
        saveTemplates()
        objectWillChange.send()
    }

    func deleteBranches(templateID: UUID, rootIDs: Set<UUID>) {
        lock.lock(); defer { lock.unlock() }
        guard let idx = templates.firstIndex(where: { $0.id == templateID }) else { return }
        var rows = templates[idx].taskRows
        
        var indicesToDelete = Set<Int>()
        for id in rootIDs {
            if let i = rows.firstIndex(where: { $0.id == id }) {
                let range = findSubtreeRange(in: rows, from: i)
                range.forEach { indicesToDelete.insert($0) }
            }
        }
        
        let sortedToRemove = indicesToDelete.sorted(by: >)
        for i in sortedToRemove { rows.remove(at: i) }
        
        validateHierarchy(&rows)
        templates[idx].taskRows = rows
        saveTemplates()
        objectWillChange.send()
    }

    // MARK: - Helper Methods

    func triggerCollision(_ msg: String) {
        DispatchQueue.main.async {
            self.collisionMessage = msg
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { self.collisionMessage = nil }
        }
    }

    func parseTaskData(_ js: String) -> TaskRowData? {
        guard let d = js.data(using: .utf8) else { return nil }
        return try? JSONDecoder().decode(TaskRowData.self, from: d)
    }

    func hasChildren(in rows: [ArchiveRow], at index: Int) -> Bool {
        guard rows.indices.contains(index), rows.indices.contains(index + 1) else { return false }
        guard let currentData = parseTaskData(rows[index].value),
              let nextData = parseTaskData(rows[index+1].value) else { return false }
        return nextData.level > currentData.level
    }
    
    func findParentIndices(in rows: [ArchiveRow], for targetIndex: Int) -> [Int] {
        guard rows.indices.contains(targetIndex),
              let targetData = parseTaskData(rows[targetIndex].value) else { return [] }
        var parents = [Int]()
        var currentLevel = targetData.level
        
        for i in (0..<targetIndex).reversed() {
            if let rowData = parseTaskData(rows[i].value), rowData.level < currentLevel {
                parents.append(i)
                currentLevel = rowData.level
                if currentLevel == 0 { break }
            }
        }
        return parents
    }
    
    func getAllDescendantIDs(in rows: [ArchiveRow], from startIndex: Int) -> [UUID] {
        let range = findSubtreeRange(in: rows, from: startIndex)
        if range.count <= 1 { return [] }
        return rows[range].dropFirst().map { $0.id }
    }
    
    func findLastDescendantIndex(in rows: [ArchiveRow], from startIndex: Int) -> Int {
        guard rows.indices.contains(startIndex),
              let pD = parseTaskData(rows[startIndex].value) else { return startIndex }
        let pL = pD.level
        var lI = startIndex
        for i in (startIndex+1)..<rows.count {
            if let d = parseTaskData(rows[i].value), d.level > pL {
                lI = i
            } else {
                break
            }
        }
        return lI
    }

    // MARK: - Checkbox Logic (Parent-Child Linking)

    func updateHierarchyStatus(rows: inout [ArchiveRow], targetID: UUID) {
        guard let idx = rows.firstIndex(where: { $0.id == targetID }),
              let tD = parseTaskData(rows[idx].value) else { return }
        
        let nS = tD.isCompleted
        let tL = tD.level
        
        // 1. 向下联动
        if idx+1 < rows.count {
            for i in (idx+1)..<rows.count {
                guard var cD = parseTaskData(rows[i].value) else { break }
                if cD.level > tL {
                    cD.isCompleted = nS
                    if let j = try? JSONEncoder().encode(cD), let s = String(data: j, encoding: .utf8) {
                        rows[i].value = s
                    }
                } else {
                    break
                }
            }
        }
        
        // 2. 向上联动
        updateParentStatus(rows: &rows, currentIndex: idx)
    }

    private func updateParentStatus(rows: inout [ArchiveRow], currentIndex: Int) {
        guard let cD = parseTaskData(rows[currentIndex].value) else { return }
        let cL = cD.level
        if cL == 0 { return }
        
        var pI: Int? = nil
        for i in (0..<currentIndex).reversed() {
            if let d = parseTaskData(rows[i].value), d.level == cL - 1 {
                pI = i
                break
            }
        }
        
        guard let pIdx = pI else { return }
        
        var allD = true
        for i in (pIdx+1)..<rows.count {
            guard let d = parseTaskData(rows[i].value) else { break }
            if d.level < cL { break }
            if d.level == cL && !d.isCompleted {
                allD = false
                break
            }
        }
        
        if var pData = parseTaskData(rows[pIdx].value) {
            if pData.isCompleted != allD {
                pData.isCompleted = allD
                if let j = try? JSONEncoder().encode(pData), let s = String(data: j, encoding: .utf8) {
                    rows[pIdx].value = s
                    updateParentStatus(rows: &rows, currentIndex: pIdx)
                }
            }
        }
    }

    func expandParentsOfMatches(rows: [ArchiveRow], matchIDs: [UUID], foldedIDs: inout Set<UUID>) {
        for mID in matchIDs {
            if let idx = rows.firstIndex(where: { $0.id == mID }) {
                let parentIndices = findParentIndices(in: rows, for: idx)
                for pIdx in parentIndices {
                    foldedIDs.remove(rows[pIdx].id)
                }
            }
        }
    }
}

// MARK: - ArchiveStore Part 8 - v11 - 优化教案清单初始化逻辑，实现已有文件物理复用

extension ArchiveStore {
    
    private func lessonPlanTemplateIndex(for planName: String) -> Int? {
        let exactTitle = "教案_\(planName)"
        if let exactIndex = templates.firstIndex(where: { $0.title == exactTitle }) {
            return exactIndex
        }
        return templates.firstIndex(where: { $0.title.hasPrefix(exactTitle) })
    }
    
    // 1. 创建教案母本资源
    func createLessonPlanResources(planName: String) {
        lock.lock(); defer { lock.unlock() }
        let tmplBaseName = "教案_\(planName)"
        var tmplName = tmplBaseName
        var counter = 1
        while templates.contains(where: { $0.title == tmplName }) {
            tmplName = "\(tmplBaseName)_\(counter)"
            counter += 1
        }
        let newTemplateID = UUID()
        let newTemplate = ArchiveTemplate(id: newTemplateID, title: tmplName, keys: [], type: .taskList)
        templates.append(newTemplate)
        saveTemplates()
        DispatchQueue.main.async { self.objectWillChange.send() }
    }
    
    // 2. 教案重命名联动
    func renameLessonPlanResources(oldPlanName: String, newPlanName: String) {
        lock.lock(); defer { lock.unlock() }
        let oldTemplateName = "教案_\(oldPlanName)"; let targetTemplateName = "教案_\(newPlanName)"
        guard let currentIdx = templates.firstIndex(where: { $0.title == oldTemplateName }) else { return }
        if let conflictIdx = templates.firstIndex(where: { $0.title == targetTemplateName && $0.id != templates[currentIdx].id }) {
            var suffix = 1; var resolvedName = "\(targetTemplateName)_\(suffix)"
            while templates.contains(where: { $0.title == resolvedName }) { suffix += 1; resolvedName = "\(targetTemplateName)_\(suffix)" }
            templates[conflictIdx].title = resolvedName
        }
        templates[currentIdx].title = targetTemplateName
        saveTemplates()
        DispatchQueue.main.async { self.objectWillChange.send() }
    }

    /// 3. 【231号核心修改】：学生档案初始化（移除备份逻辑，实现复用）
    func initializeStudentArchives(studentName: String, planNames: [String], aidTemplateIDs: [UUID]) {
        lock.lock(); defer { lock.unlock() }
        
        // A. 物理文件夹自愈
        let cloudDir = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName)
        let localDir = CloudFileManager.shared.getLocalMirrorDir(.tables).appendingPathComponent(studentName)
        try? fm.createDirectory(at: cloudDir, withIntermediateDirectories: true)
        try? fm.createDirectory(at: localDir, withIntermediateDirectories: true)
        
        // B. 内存分类管理
        var studentCatID: UUID
        if let cat = categories.first(where: { $0.title == studentName }) {
            studentCatID = cat.id
        } else {
            studentCatID = UUID()
            let newCat = ArchiveCategory(id: studentCatID, title: studentName, tables: [])
            categories.append(newCat)
            saveCategoryOrder()
        }
        
        guard let catIdx = categories.firstIndex(where: { $0.id == studentCatID }) else { return }
        
        // C. 处理教案具体清单
        for plan in planNames {
            if let templateIndex = lessonPlanTemplateIndex(for: plan) {
                let planTemplate = templates[templateIndex]
                
                let listName = "教案_\(plan)_完成情况_\(studentName)"
                
                // 【231号修改点】：如果文件已存在，直接跳过创建，不再改名为 _旧
                if categories[catIdx].tables.contains(where: { $0.title == listName }) {
                    continue
                }
                
                // 仅在不存在时创建新清单
                var newTable = ArchiveTable(id: UUID(), title: listName, rows: [], templateID: planTemplate.id, type: .taskList)
                newTable.rows = castNewRowsFromTemplate(oldRows: [], templateRows: planTemplate.taskRows)
                categories[catIdx].tables.insert(newTable, at: 0)
                saveTableToFile(newTable, categoryTitle: studentName)
            }
        }
        
        // D. 处理教助清单
        for aidID in aidTemplateIDs {
            if let tmpl = templates.first(where: { $0.id == aidID }) {
                let listName = "\(tmpl.title)_\(studentName)"
                if !categories[catIdx].tables.contains(where: { $0.title == listName }) {
                    var newAidTable = ArchiveTable(id: UUID(), title: listName, rows: [], templateID: tmpl.id, type: .taskList)
                    newAidTable.rows = castNewRowsFromTemplate(oldRows: [], templateRows: tmpl.taskRows)
                    categories[catIdx].tables.insert(newAidTable, at: 0)
                    saveTableToFile(newAidTable, categoryTitle: studentName)
                }
            }
        }
        
        clearSmartCache()
        DispatchQueue.main.async { self.objectWillChange.send() }
    }
}

// MARK: - ArchiveStore Part 3 - Persistence (模板文件夹专供版) - v213 - 彻底切断旧路径回溯与统一震动

extension ArchiveStore {
    
    @objc func handleCloudUpdate() {
        if editingTableID != nil { return }
        if !lock.try() { return }; defer { lock.unlock() }
        self.fileMetadataCache.removeAll(); clearSmartCache()
        DispatchQueue.global(qos: .utility).async { [weak self] in
            guard let self = self else { return }
            let nT = self.loadTemplatesData(); let nS = self.loadSmartViewsData(); let nU = self.loadUnmatchedData()
            self.loadDataFromFileSystem(); self.loadTaskLists()
            DispatchQueue.main.async { if let t = nT { self.templates = t }; if let s = nS { self.smartViews = s }; if let u = nU { self.unmatchedTables = u }; if self.isFreshLaunch { self.isFreshLaunch = false }; self.ensureSystemFolders() }
        }
    }
    
    func loadConfig() { if let t = loadTemplatesData() { templates = t }; if let s = loadSmartViewsData() { smartViews = s }; if let u = loadUnmatchedData() { unmatchedTables = u } }
    
    // 【195号核心修改】：不再从 .tables 读取，仅信任 .templates 文件夹
    func loadTemplatesData() -> [ArchiveTemplate]? {
        if let d = CloudFileManager.shared.smartLoad(folder: .templates, fileName: templateFileName), let t = try? JSONDecoder().decode([ArchiveTemplate].self, from: d) { return t }
        return nil
    }
    
    func loadSmartViewsData() -> [SmartViewConfig]? {
        if let d = CloudFileManager.shared.smartLoad(folder: .templates, fileName: smartViewFileName), let s = try? JSONDecoder().decode([SmartViewConfig].self, from: d) { return s }
        return nil
    }
    
    func loadUnmatchedData() -> [ArchiveTable]? {
        if let d = CloudFileManager.shared.smartLoad(folder: .templates, fileName: unmatchedFileName), let u = try? JSONDecoder().decode([ArchiveTable].self, from: d) { return u }
        return nil
    }
    
    func loadDataFromFileSystem() {
        let root = CloudFileManager.shared.getCloudDir(.tables)
        guard let folders = try? fm.contentsOfDirectory(at: root, includingPropertiesForKeys: [.isDirectoryKey], options: .skipsHiddenFiles) else { DispatchQueue.main.async { self.isFreshLaunch = true }; return }
        if folders.isEmpty { DispatchQueue.main.async { self.isFreshLaunch = true }; return }
        var tempCategories: [ArchiveCategory] = []
        for folderURL in folders {
            let res = try? folderURL.resourceValues(forKeys: [.isDirectoryKey])
            if res?.isDirectory == false || folderURL.lastPathComponent.starts(with: ".") { continue }
            let catTitle = folderURL.lastPathComponent; var tablesByLogicalID:[UUID: (date: Date, table: ArchiveTable, url: URL)] = [:]; var urlsToDelete = [URL]()
            if let files = try? fm.contentsOfDirectory(at: folderURL, includingPropertiesForKeys: [.contentModificationDateKey], options: .skipsHiddenFiles) {
                for fileURL in files where fileURL.pathExtension.lowercased() == "csv" {
                    let attrs = try? fileURL.resourceValues(forKeys:[.contentModificationDateKey]); let modDate = attrs?.contentModificationDate ?? Date.distantPast
                    var table: ArchiveTable?; self.lock.lock(); let cachedEntry = self.fileMetadataCache[fileURL]; self.lock.unlock()
                    if let cached = cachedEntry, cached.modificationDate == modDate { table = cached.table }
                    else if let newTable = loadTableFromCSV(url: fileURL) { self.lock.lock(); self.fileMetadataCache[fileURL] = FileCacheEntry(modificationDate: modDate, table: newTable); self.lock.unlock(); table = newTable }
                    if let t = table { if let existing = tablesByLogicalID[t.id] { if modDate > existing.date { urlsToDelete.append(existing.url); tablesByLogicalID[t.id] = (modDate, t, fileURL) } else { urlsToDelete.append(fileURL) } } else { tablesByLogicalID[t.id] = (modDate, t, fileURL) } }
                }
            }
            for url in urlsToDelete { CloudFileManager.shared.deleteTableDual(categoryName: catTitle, fileName: url.lastPathComponent) }
            let finalTables = tablesByLogicalID.values.map { $0.table }.sorted { $0.createdAt > $1.createdAt }
            tempCategories.append(ArchiveCategory(id: UUID(), title: catTitle, tables: finalTables))
        }
        DispatchQueue.main.async { if !tempCategories.isEmpty { self.isFreshLaunch = false }; var final = [ArchiveCategory](); for tC in tempCategories { var fc = tC; if let ex = self.categories.first(where: { $0.title == tC.title }) { fc.id = ex.id } else { if fc.title == "删除回收" { fc.id = SystemIDs.recycleBin } else if fc.title == "自动填写" { fc.id = SystemIDs.autoFill } else if fc.title == "导入" { fc.id = SystemIDs.importFolder } else if fc.title == "我的文件夹" { fc.id = SystemIDs.myFolder } }; final.append(fc) }; self.categories = final; self.sortCategories() }
    }
    
    func loadTaskLists() {
        guard let files = try? fm.contentsOfDirectory(at: tasksDirURL, includingPropertiesForKeys:[.contentModificationDateKey]) else { return }
        var loadedByLogicalID:[UUID: (date: Date, table: ArchiveTable, url: URL)] = [:]; var urlsToDelete = [URL]()
        for url in files where url.pathExtension == "csv" {
            let attrs = try? url.resourceValues(forKeys: [.contentModificationDateKey]); let modDate = attrs?.contentModificationDate ?? Date.distantPast
            var table: ArchiveTable?; self.lock.lock(); let cachedEntry = self.fileMetadataCache[url]; self.lock.unlock()
            if let cached = cachedEntry, cached.modificationDate == modDate { table = cached.table }
            else if let newTable = loadTableFromCSV(url: url) { var t = newTable; t.type = .taskList; self.lock.lock(); self.fileMetadataCache[url] = FileCacheEntry(modificationDate: modDate, table: t); self.lock.unlock(); table = t }
            if let t = table { if let existing = loadedByLogicalID[t.id] { if modDate > existing.date { urlsToDelete.append(existing.url); loadedByLogicalID[t.id] = (modDate, t, url) } else { urlsToDelete.append(url) } } else { loadedByLogicalID[t.id] = (modDate, t, url) } }
        }
        for urlToDel in urlsToDelete { try? fm.removeItem(at: urlToDel); let localMirror = CloudFileManager.shared.getLocalMirrorDir(.records).appendingPathComponent("TaskLists").appendingPathComponent(urlToDel.lastPathComponent); try? fm.removeItem(at: localMirror) }
        DispatchQueue.main.async { self.taskLists = loadedByLogicalID.values.map { $0.table }.sorted { $0.createdAt > $1.createdAt } }
    }
    
    // 【195号核心修改】：分类排序文件也彻底切断老路径回溯
    func sortCategories() {
        let templatesURL = CloudFileManager.shared.getCloudDir(.templates).appendingPathComponent(orderFileName)
        
        var loadedData: Data? = nil
        if fm.fileExists(atPath: templatesURL.path) {
            loadedData = try? Data(contentsOf: templatesURL)
        }
        
        if let d = loadedData, let order = try? JSONDecoder().decode([String].self, from: d) {
            categories.sort { (order.firstIndex(of: $0.title) ?? 999) < (order.firstIndex(of: $1.title) ?? 999) }
        } else {
            categories.sort { c1, c2 in
                if c1.id == SystemIDs.recycleBin { return true }
                if c2.id == SystemIDs.recycleBin { return false }
                if c1.id == SystemIDs.autoFill { return true }
                if c2.id == SystemIDs.autoFill { return false }
                if c1.id == SystemIDs.importFolder { return true }
                if c2.id == SystemIDs.importFolder { return false }
                return c1.title < c2.title
            }
        }
    }
    
    func ensureSystemFolders() {
        func ensureInMemory(title: String, id: UUID) { if !categories.contains(where: { $0.id == id }) { if let idx = categories.firstIndex(where: { $0.title == title }) { var cat = categories[idx]; cat.id = id; categories[idx] = cat } else { categories.append(ArchiveCategory(id: id, title: title, tables:[])) } } }
        ensureInMemory(title: "删除回收", id: SystemIDs.recycleBin); ensureInMemory(title: "自动填写", id: SystemIDs.autoFill); ensureInMemory(title: "导入", id: SystemIDs.importFolder)
        if !isFreshLaunch { for cat in categories { let cD = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(cat.title); let lD = CloudFileManager.shared.getLocalMirrorDir(.tables).appendingPathComponent(cat.title); try? fm.createDirectory(at: cD, withIntermediateDirectories: true); try? fm.createDirectory(at: lD, withIntermediateDirectories: true) }; saveCategoryOrder() }
    }
    
    func addCategory(title: String, fixedID: UUID? = nil) { lock.lock(); defer { lock.unlock() }; let id = fixedID ?? UUID(); if !categories.contains(where: { $0.id == id }) { categories.append(ArchiveCategory(id: id, title: title, tables:[])) }; let cD = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(title); let lD = CloudFileManager.shared.getLocalMirrorDir(.tables).appendingPathComponent(title); try? fm.createDirectory(at: cD, withIntermediateDirectories: true); try? fm.createDirectory(at: lD, withIntermediateDirectories: true); isFreshLaunch = false; saveCategoryOrder() }
    func renameCategory(_ cat: ArchiveCategory, newName: String) { lock.lock(); defer { lock.unlock() }; guard let i = categories.firstIndex(where: { $0.id == cat.id }) else { return }; let old = categories[i].title; categories[i].title = newName; CloudFileManager.shared.moveCategoryDual(oldName: old, newName: newName); saveCategoryOrder() }
    func deleteCategory(at off: IndexSet) { lock.lock(); defer { lock.unlock() }; off.forEach { i in let c = categories[i]; if c.title != "删除回收" && c.title != "自动填写" && c.title != "导入" { CloudFileManager.shared.deleteCategoryDual(categoryName: c.title) } }; categories.remove(atOffsets: off); saveCategoryOrder(); clearSmartCache() }
    func deleteCategory(id: UUID) { lock.lock(); defer { lock.unlock() }; guard let i = categories.firstIndex(where: { $0.id == id }) else { return }; let c = categories[i]; if c.title != "删除回收" && c.title != "自动填写" && c.title != "导入" { CloudFileManager.shared.deleteCategoryDual(categoryName: c.title) }; categories.remove(at: i); saveCategoryOrder(); clearSmartCache() }
    func moveCategory(from src: IndexSet, to dst: Int) { lock.lock(); defer { lock.unlock() }; let sc = categories.prefix(while: { $0.id == SystemIDs.recycleBin || $0.id == SystemIDs.autoFill }).count; let rSrc = src.map { $0 + sc }; let rDst = dst + sc; if rSrc.allSatisfy({ $0 >= sc }) && rDst >= sc { categories.move(fromOffsets: IndexSet(rSrc), toOffset: rDst); saveCategoryOrder() } }
    func saveCategoryOrder() { let ord = categories.map { $0.title }; if let d = try? JSONEncoder().encode(ord) { CloudSyncManager.shared.ignoreNextUpdate(relativePath: "模板/\(orderFileName)"); CloudFileManager.shared.saveDual(data: d, folder: .templates, fileName: orderFileName) } }
    
    func persistTableChanges(table: ArchiveTable, categoryID: UUID, oldTitle: String) { lock.lock(); defer { lock.unlock() }; isFreshLaunch = false; guard let cat = categories.first(where: { $0.id == categoryID }) else { return }; let sNew = CloudFileManager.shared.getSanitizedFileName(table.title); let sOld = CloudFileManager.shared.getSanitizedFileName(oldTitle); if sNew != sOld { if checkTableExists(title: sNew, inCategoryID: categoryID, excludeTableID: table.id) { return }; CloudSyncManager.shared.ignoreNextUpdate(relativePath: "表格/\(cat.title)/\(sNew).csv"); CloudFileManager.shared.atomicRenameTable(categoryName: cat.title, oldFileName: "\(sOld).csv", newFileName: "\(sNew).csv", tableData: generateCSVString(table)) } else { saveTableToFile(table, categoryTitle: cat.title) }; fileModificationCache[table.id] = Date(); if let ci = categories.firstIndex(where: { $0.id == categoryID }), let ti = categories[ci].tables.firstIndex(where: { $0.id == table.id }) { categories[ci].tables[ti] = table }; clearSmartCache() }
    func checkExternalFileChange(tableID: UUID, categoryID: UUID, lastKnownDate: Date) -> (table: ArchiveTable, modifiedDate: Date)? { guard let cat = categories.first(where: { $0.id == categoryID }), let currentTable = cat.tables.first(where: { $0.id == tableID }) else { return nil }; lock.lock(); let cachedDate = fileModificationCache[tableID]; lock.unlock(); if let cachedDate = cachedDate, cachedDate > lastKnownDate { return (currentTable, cachedDate) }; return nil }
    func saveTableToFile(_ table: ArchiveTable, categoryTitle: String) { let fileName = "\(getSafeName(table)).csv"; CloudSyncManager.shared.ignoreNextUpdate(relativePath: "表格/\(categoryTitle)/\(fileName)"); CloudFileManager.shared.saveTableDual(csvString: generateCSVString(table), categoryName: categoryTitle, fileName: fileName) }
    func softDeleteTable(tableID: UUID, categoryID: UUID) { lock.lock(); defer { lock.unlock() }; guard let ci = categories.firstIndex(where: { $0.id == categoryID }), let ti = categories[ci].tables.firstIndex(where: { $0.id == tableID }), let trashI = categories.firstIndex(where: { $0.id == SystemIDs.recycleBin }) else { return }; let sT = categories[ci].title; var t = categories[ci].tables[ti]; t.sourceCategoryID = categoryID; t.deletedAt = Date(); categories[ci].tables.remove(at: ti); categories[trashI].tables.insert(t, at: 0); CloudFileManager.shared.deleteTableDual(categoryName: sT, fileName: "\(getSafeName(t)).csv"); saveTableToFile(t, categoryTitle: "删除回收"); fileModificationCache.removeValue(forKey: tableID); clearSmartCache() }
    func renameTable(catID: UUID, tableID: UUID, newName: String) { guard let ci = categories.firstIndex(where: { $0.id == catID }), let ti = categories[ci].tables.firstIndex(where: { $0.id == tableID }) else { return }; let oldT = categories[ci].tables[ti]; var newT = oldT; newT.title = newName; persistTableChanges(table: newT, categoryID: catID, oldTitle: oldT.title) }
    func permanentDeleteTable(tableID: UUID) { lock.lock(); defer { lock.unlock() }; guard let trashIdx = categories.firstIndex(where: { $0.id == SystemIDs.recycleBin }), let ti = categories[trashIdx].tables.firstIndex(where: { $0.id == tableID }) else { return }; let t = categories[trashIdx].tables[ti]; MarkdownAssetManager.shared.deleteAssets(for: tableID); categories[trashIdx].tables.remove(at: ti); CloudFileManager.shared.deleteTableDual(categoryName: "删除回收", fileName: "\(getSafeName(t)).csv") }
    func restoreTable(tableID: UUID) { lock.lock(); defer { lock.unlock() }; guard let trashIdx = categories.firstIndex(where: { $0.id == SystemIDs.recycleBin }), let ti = categories[trashIdx].tables.firstIndex(where: { $0.id == tableID }) else { return }; var t = categories[trashIdx].tables[ti]; t.deletedAt = nil; let targetID = t.sourceCategoryID ?? SystemIDs.myFolder; guard let tIdx = categories.firstIndex(where: { $0.id == targetID }) else { return }; let tTitle = categories[tIdx].title; categories[trashIdx].tables.remove(at: ti); categories[tIdx].tables.insert(t, at: 0); CloudFileManager.shared.deleteTableDual(categoryName: "删除回收", fileName: "\(getSafeName(t)).csv"); saveTableToFile(t, categoryTitle: tTitle); clearSmartCache() }
    func emptyRecycleBin() { lock.lock(); defer { lock.unlock() }; guard let trashIdx = categories.firstIndex(where: { $0.id == SystemIDs.recycleBin }) else { return }; for t in categories[trashIdx].tables { MarkdownAssetManager.shared.deleteAssets(for: t.id); CloudFileManager.shared.deleteTableDual(categoryName: "删除回收", fileName: "\(getSafeName(t)).csv") }; categories[trashIdx].tables.removeAll(); objectWillChange.send() }
    func moveTables(tableIDs: Set<UUID>, from sCatID: UUID, to tCatID: UUID) { lock.lock(); defer { lock.unlock() }; guard let si = categories.firstIndex(where: { $0.id == sCatID }), let ti = categories.firstIndex(where: { $0.id == tCatID }) else { return }; let sT = categories[si].title; let tT = categories[ti].title; let mv = categories[si].tables.filter { tableIDs.contains($0.id) }; categories[si].tables.removeAll { tableIDs.contains($0.id) }; categories[ti].tables.insert(contentsOf: mv, at: 0); for t in mv { CloudFileManager.shared.deleteTableDual(categoryName: sT, fileName: "\(getSafeName(t)).csv"); saveTableToFile(t, categoryTitle: tT) }; clearSmartCache() }
    func checkTableExists(title: String, inCategoryID catID: UUID, excludeTableID: UUID? = nil) -> Bool { guard let cat = categories.first(where: { $0.id == catID }) else { return false }; return cat.tables.contains { $0.title.trimmingCharacters(in: .whitespaces) == title.trimmingCharacters(in: .whitespaces) && $0.id != excludeTableID } }
    func addTaskList(title: String) { lock.lock(); defer { lock.unlock() }; let nt = ArchiveTable(id: UUID(), title: title, rows:[], type: .taskList); saveTaskList(nt) }
    func deleteTaskList(id: UUID) { lock.lock(); defer { lock.unlock() }; if let idx = taskLists.firstIndex(where: {$0.id == id}) { let t = taskLists[idx]; taskLists.remove(at: idx); let p = "TaskLists/\(t.id.uuidString).csv"; try? fm.removeItem(at: CloudFileManager.shared.getCloudDir(.records).appendingPathComponent(p)); try? fm.removeItem(at: CloudFileManager.shared.getLocalMirrorDir(.records).appendingPathComponent(p)) } }
    func saveTaskList(_ t: ArchiveTable) { if let d = generateCSVString(t).data(using: .utf8) { let fileName = "\(t.id.uuidString).csv"; CloudSyncManager.shared.ignoreNextUpdate(relativePath: "记录/TaskLists/\(fileName)"); CloudFileManager.shared.saveDual(data: d, folder: .records, fileName: "TaskLists/\(fileName)") }; if let idx = taskLists.firstIndex(where: {$0.id == t.id}) { taskLists[idx] = t } else { taskLists.insert(t, at: 0) } }
    
    func loadTableFromCSV(url: URL) -> ArchiveTable? {
        guard let content = try? String(contentsOf: url, encoding: .utf8) else { return nil }
        let lines = content.components(separatedBy: .newlines); let fileName = url.deletingPathExtension().lastPathComponent
        var id = UUID(); var rows: [ArchiveRow] = []; var templateID: UUID? = nil; var createdAt = Date(); var deletedAt: Date? = nil; var type: TableType = .standard; var sourceCategoryID: UUID? = nil
        if let firstLine = lines.first { let cleanHeader = firstLine.trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "\u{FEFF}", with: ""); if cleanHeader.starts(with: "UUID,Prefix,Content,SourceID") { type = .lessonPlanNodes } }
        for line in lines {
            let p = line.components(separatedBy: ","); if line.starts(with: "[META_TYPE],") && p.count > 1 { type = TableType(rawValue: p[1].trimmingCharacters(in: .whitespaces)) ?? type }
            else if line.starts(with: "[META_ID],") && p.count > 1 { id = UUID(uuidString: p[1].trimmingCharacters(in: .whitespaces)) ?? id }
            else if line.starts(with: "[META_TEMPLATE],") && p.count > 1 { templateID = (p[1].trimmingCharacters(in: .whitespaces) == "nil" ? nil : UUID(uuidString: p[1].trimmingCharacters(in: .whitespaces))) }
            else if line.starts(with: "[META_CREATED],") && p.count > 1, let t = Double(p[1].trimmingCharacters(in: .whitespaces)) { createdAt = Date(timeIntervalSince1970: t) }
            else if line.starts(with: "[META_DELETED],") && p.count > 1, let t = Double(p[1].trimmingCharacters(in: .whitespaces)) { deletedAt = Date(timeIntervalSince1970: t) }
            else if line.starts(with: "[META_SOURCE_CAT],") && p.count > 1 { sourceCategoryID = UUID(uuidString: p[1].trimmingCharacters(in: .whitespaces)) }
        }
        if type == .taskList { rows = parseTaskListContent(lines) }
        else if type == .lessonPlanNodes { let nodes = parseLessonPlanCSV(content); rows = nodes.map { n in let json = (try? JSONEncoder().encode(n)).flatMap { String(data: $0, encoding: .utf8) } ?? ""; return ArchiveRow(id: n.id, key: n.type.rawValue, value: json) } }
        else { for line in lines { if line.starts(with: "[META") { continue }; let cols = parseCSVRow(line); if cols.count < 2 { continue }; let dT = cols[0].trimmingCharacters(in: .whitespaces); if dT == "词条名" || dT == "\u{FEFF}词条名" || dT.isEmpty { continue }; let cV = cols[1].replacingOccurrences(of: "{{BR}}", with: "\n").replacingOccurrences(of: "{{TAB}}", with: "\t"); let aK: String = (cols.count > 3 && !cols[3].isEmpty) ? cols[3].trimmingCharacters(in: .whitespaces) : dT; let data = StandardRowData(title: dT, content: cV); if let jsonData = try? JSONEncoder().encode(data), let js = String(data: jsonData, encoding: .utf8) { rows.append(ArchiveRow(key: aK, value: js)) } } }
        return ArchiveTable(id: id, title: fileName, rows: rows, createdAt: createdAt, templateID: templateID, deletedAt: deletedAt, type: type, sourceCategoryID: sourceCategoryID)
    }
    
    func parseTaskListContent(_ lines: [String]) -> [ArchiveRow] {
        var rows = [ArchiveRow](); for line in lines {
            if line.starts(with: "[META") || (line.contains("任务项") && line.contains("层级")) { continue }; let cols = parseCSVRow(line); if cols.count < 2 { continue }
            let title = cols[0].replacingOccurrences(of: "{{BR}}", with: "\n").replacingOccurrences(of: "{{TAB}}", with: "\t"); let lvl = Int(cols[1]) ?? 0; let done = (cols.count > 2 && (cols[2] == "1" || cols[2].lowercased() == "true"))
            var sID: UUID? = nil; if cols.count > 3 && !cols[3].isEmpty { sID = UUID(uuidString: cols[3].trimmingCharacters(in: .whitespaces)) }
            var sFile: String? = nil; if cols.count > 4 && !cols[4].isEmpty { sFile = cols[4].trimmingCharacters(in: .whitespaces) }
            let data = TaskRowData(title: title, isCompleted: done, level: lvl, sourceID: sID, sourceFile: sFile)
            let key = sID?.uuidString ?? UUID().uuidString
            if let json = try? JSONEncoder().encode(data), let js = String(data: json, encoding: .utf8) { rows.append(ArchiveRow(id: UUID(), key: key, value: js)) }
        }
        return rows
    }
    
    func generateCSVString(_ t: ArchiveTable) -> String {
        var csv = ""; if t.type == .taskList {
            csv = "\u{FEFF}任务项,层级,状态,SourceID,SourceFile\n"
            for r in t.rows { if let data = parseTaskData(r.value) { csv += "\(escapeCSVField(data.title)),\(data.level),\(data.isCompleted ? "1" : "0"),\(data.sourceID?.uuidString ?? ""),\(data.sourceFile ?? "")\n" } }
        } else if t.type == .lessonPlanNodes { let nodes = t.rows.compactMap { r -> LPRowNode? in try? JSONDecoder().decode(LPRowNode.self, from: r.value.data(using: .utf8) ?? Data()) }; csv = generateLessonPlanCSV(from: nodes) }
        else { csv = "\u{FEFF}词条名,内容,预留,Key\n"; for r in t.rows { var dT = ""; var dC = ""; if let d = try? JSONDecoder().decode(StandardRowData.self, from: r.value.data(using: .utf8) ?? Data()) { dT = d.title; dC = d.content } else { dT = r.key; dC = r.value }; csv += "\(escapeCSVField(dT)),\(escapeCSVField(dC)),0,\(escapeCSVField(r.key))\n" } }
        csv += "\n[META_ID],\(t.id.uuidString)\n[META_TITLE],\(escapeCSVField(t.title))\n[META_TEMPLATE],\(t.templateID?.uuidString ?? "nil")\n[META_CREATED],\(t.createdAt.timeIntervalSince1970)\n[META_TYPE],\(t.type.rawValue)\n"
        if let sc = t.sourceCategoryID { csv += "[META_SOURCE_CAT],\(sc.uuidString)\n" }; if let del = t.deletedAt { csv += "[META_DELETED],\(del.timeIntervalSince1970)\n" }; return csv
    }
    
    func escapeCSVField(_ field: String) -> String { var f = field.replacingOccurrences(of: "\n", with: "{{BR}}").replacingOccurrences(of: "\t", with: "{{TAB}}"); if f.contains(",") || f.contains("\"") { f = f.replacingOccurrences(of: "\"", with: "\"\""); return "\"\(f)\"" }; return f }
    func getSafeName(_ t: ArchiveTable) -> String { return CloudFileManager.shared.getSanitizedFileName(t.title) }
    func exportCSVFile(for t: ArchiveTable) -> URL? { let csv = generateCSVString(t); let url = fm.temporaryDirectory.appendingPathComponent("\(t.title).csv"); try? csv.write(to: url, atomically: true, encoding: .utf8); return url }
    func getImportableFiles() ->[URL] { let dir = CloudFileManager.shared.getImportDir(); guard let files = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil) else { return[] }; return files.filter { $0.pathExtension.lowercased() == "csv" } }
    
    func importInternalFile(url: URL) {
        lock.lock(); defer { lock.unlock() }
        guard let content = try? String(contentsOf: url, encoding: .utf8), !content.isEmpty else { return }
        let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }; if lines.isEmpty { return }
        let fR = parseCSVRow(lines[0]); if fR.isEmpty { return }
        let header = fR[0].trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "\u{FEFF}", with: "")
        let rawN = url.deletingPathExtension().lastPathComponent
        if header == "清单" || header == "任务项" { importAsTaskList(rawN, lines) } else if header == "表格" || header == "词条名" { importAsStandardTable(rawN, lines) }
        try? fm.removeItem(at: url)
        triggerHapticFeedback(style: 2)
        objectWillChange.send()
    }
    
    func scanImportFolder() { lock.lock(); defer { lock.unlock() }; let dir = CloudFileManager.shared.getImportDir(); guard let files = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil) else { return }; var ch = false; for url in files { var imp: ArchiveTable? = nil; if url.pathExtension.lowercased() == "csv", let t = loadTableFromCSV(url: url) { var nt = t; nt.id = UUID() ; imp = nt }; if var t = imp { if let m = findMatchingTemplate(for: t) { t.templateID = m.id; if categories.count > 1 { categories[1].tables.insert(t, at: 0); saveTableToFile(t, categoryTitle: categories[1].title) } } else { unmatchedTables.insert(t, at: 0); saveUnmatched() }; ch = true; try? fm.removeItem(at: url) } }; if ch { objectWillChange.send() }; clearSmartCache() }
    private func findMatchingTemplate(for t: ArchiveTable) -> ArchiveTemplate? { let tableKeys = Set(t.rows.map { $0.key }); for tmpl in templates where tmpl.type == .table { let templateKeys = Set(tmpl.keys.map { $0.id.uuidString }); if !tableKeys.isEmpty && tableKeys.isSubset(of: templateKeys) { return tmpl } }; return nil }
    private func importAsStandardTable(_ name: String, _ lines: [String]) { var tKs: [TemplateKey] = []; var cts: [String: String] = [:]; for i in 1..<lines.count { let cols = parseCSVRow(lines[i]); if cols.count >= 1 { let kn = cols[0].trimmingCharacters(in: .whitespacesAndNewlines); if kn.isEmpty { continue }; let tk = TemplateKey(name: kn); tKs.append(tk); if cols.count >= 2 { cts[tk.id.uuidString] = cols[1].replacingOccurrences(of: "{{BR}}", with: "\n").replacingOccurrences(of: "{{TAB}}", with: "\t") } } }; let fTT = getUniqueTemplateTitle(base: name); let tid = UUID(); self.templates.append(ArchiveTemplate(id: tid, title: fTT, keys: tKs, type: .table)); saveTemplates(); let rows = tKs.map { tk in let d = StandardRowData(title: tk.name, content: cts[tk.id.uuidString] ?? ""); let j = (try? JSONEncoder().encode(d)).flatMap { String(data: $0, encoding: .utf8) } ?? ""; return ArchiveRow(key: tk.id.uuidString, value: j) }; let nt = ArchiveTable(id: UUID(), title: getUniqueTableTitle(base: name, categoryID: SystemIDs.importFolder), rows: rows, templateID: tid, type: .standard); if let idx = categories.firstIndex(where: { $0.id == SystemIDs.importFolder }) { categories[idx].tables.insert(nt, at: 0); saveTableToFile(nt, categoryTitle: "导入") } }
    private func importAsTaskList(_ name: String, _ lines: [String]) { var tRs: [ArchiveRow] = []; var iRs: [ArchiveRow] = [] ; for i in 1..<lines.count { let cols = parseCSVRow(lines[i]); if cols.count >= 1 { let title = cols[0].trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "\n", with: "{{BR}}"); if title.isEmpty { continue }; let lvl = (cols.count >= 2) ? max(0, Int(cols[1]) ?? 0) : 0; let done = (cols.count >= 3 && (cols[2] == "1" || cols[2].lowercased() == "true")); let data = TaskRowData(title: title, isCompleted: done, level: lvl); let rid = UUID(); let aK = UUID().uuidString; if let json = try? JSONEncoder().encode(data), let js = String(data: json, encoding: .utf8) { tRs.append(ArchiveRow(id: rid, key: aK, value: js)); var iD = data; iD.isCompleted = done; if let iJ = try? JSONEncoder().encode(iD), let iS = String(data: iJ, encoding: .utf8) { iRs.append(ArchiveRow(id: UUID(), key: aK, value: iS)) } } } }; let fTT = getUniqueTemplateTitle(base: name); let tid = UUID(); self.templates.append(ArchiveTemplate(id: tid, title: fTT, keys:[], type: .taskList, taskRows: tRs)); saveTemplates(); let nt = ArchiveTable(id: UUID(), title: getUniqueTableTitle(base: name, categoryID: SystemIDs.importFolder), rows: iRs, templateID: tid, type: .taskList); if let idx = categories.firstIndex(where: { $0.id == SystemIDs.importFolder }) { categories[idx].tables.insert(nt, at: 0); saveTableToFile(nt, categoryTitle: "导入") } }

    func saveTemplates() {
        if let d = try? JSONEncoder().encode(templates) {
            CloudSyncManager.shared.ignoreNextUpdate(relativePath: "模板/\(templateFileName)")
            Task { await CloudFileManager.shared.saveDualAsync(data: d, folder: .templates, fileName: templateFileName) }
        }
    }
    
    func saveSmartViews() {
        if let d = try? JSONEncoder().encode(smartViews) {
            CloudSyncManager.shared.ignoreNextUpdate(relativePath: "模板/\(smartViewFileName)")
            Task { await CloudFileManager.shared.saveDualAsync(data: d, folder: .templates, fileName: smartViewFileName) }
        }
    }
    
    func saveUnmatched() {
        if let d = try? JSONEncoder().encode(unmatchedTables) {
            CloudSyncManager.shared.ignoreNextUpdate(relativePath: "模板/\(unmatchedFileName)")
            Task { await CloudFileManager.shared.saveDualAsync(data: d, folder: .templates, fileName: unmatchedFileName) }
        }
    }
    
    func getBackupList() -> [BackupFile] { BackupManager.shared.getHistory(module: "Archives", subID: "Global") }
    func getTableHistory(tableID: UUID) -> [BackupFile] { BackupManager.shared.getHistory(module: "Archives", subID: tableID.uuidString) }
    func restoreTable(from b: BackupFile, targetTableID: UUID) { lock.lock(); defer { lock.unlock() }; guard let d = try? Data(contentsOf: b.url), let r = try? JSONDecoder().decode(ArchiveTable.self, from: d) else { return }; for ci in 0..<categories.count { if let ti = categories[ci].tables.firstIndex(where: { $0.id == targetTableID }) { var nt = r; nt.id = targetTableID; categories[ci].tables[ti] = nt; saveTableToFile(nt, categoryTitle: categories[ci].title); break } }; clearSmartCache() }
    func restoreFromBackup(url: URL) {}
}

// MARK: - ArchiveStore Part 4 - v5 - 模板与智能视图 (修正清单 UUID 继承链)

extension ArchiveStore {
    
    // MARK: - Template Management
    
    func getUniqueTemplateTitle(base: String) -> String {
        var n = base; while templates.contains(where: { $0.title == n }) { n += "_重名" }; return n
    }
    
    func getUniqueTableTitle(base: String, categoryID: UUID) -> String {
        var n = base; guard let c = categories.first(where: { $0.id == categoryID }) else { return n }
        while c.tables.contains(where: { $0.title == n }) { n += "_重名" }; return n
    }
    
    func checkTemplateNameExists(name: String, excludeID: UUID? = nil) -> Bool {
        return templates.contains { $0.title.trimmingCharacters(in: .whitespaces) == name.trimmingCharacters(in: .whitespaces) && $0.id != excludeID }
    }
    
    func addTemplate(title: String, keys: [String], type: ArchiveTemplate.TemplateType = .table) -> UUID {
        lock.lock(); defer { lock.unlock() }; let tka = keys.map { TemplateKey(name: $0) }; let nt = ArchiveTemplate(id: UUID(), title: title, keys: tka, type: type)
        templates.append(nt); saveTemplates(); return nt.id
    }
    
    func renameTemplate(id: UUID, newName: String) {
        lock.lock(); defer { lock.unlock() }; if let idx = templates.firstIndex(where: {$0.id == id}) { templates[idx].title = newName; saveTemplates() }
    }
    
    func saveTaskListTemplate(templateID: UUID, rows: [ArchiveRow]) {
        lock.lock(); guard let idx = templates.firstIndex(where: {$0.id == templateID}) else { lock.unlock(); return }
        var validated = rows; validateHierarchy(&validated); templates[idx].taskRows = validated; lock.unlock(); saveTemplates(); syncAllInstancesToTemplate(templateID: templateID)
    }
    
    func deleteTemplateWithCascade(templateID: UUID) {
        lock.lock(); defer { lock.unlock() }; smartViews.removeAll { $0.templateID == templateID }; saveSmartViews()
        for i in 0..<categories.count { let title = categories[i].title; let toD = categories[i].tables.filter { $0.templateID == templateID }; for t in toD { CloudFileManager.shared.deleteTableDual(categoryName: title, fileName: "\(getSafeName(t)).csv") }; categories[i].tables.removeAll { $0.templateID == templateID } }
        templates.removeAll { $0.id == templateID }; saveTemplates(); clearSmartCache()
    }
    
    func getTemplateName(by id: UUID?) -> String {
        guard let id = id, let tmpl = templates.first(where: { $0.id == id }) else { return "无模板" }; return tmpl.title
    }
    
    func getDependentTablesInfo(templateID: UUID) -> [String] {
        var res = [String](); for c in categories { for t in c.tables { if t.templateID == templateID { res.append(t.title) } } }; return res
    }
    
    func renameTemplateKey(templateID: UUID, index: Int, newName: String) {
        lock.lock(); defer { lock.unlock() }; guard !newName.isEmpty, let ti = templates.firstIndex(where: {$0.id == templateID}), templates[ti].keys.indices.contains(index) else { return }
        let oN = templates[ti].keys[index].name; if oN == newName { return }; templates[ti].keys[index].name = newName
        if let cfg = templates[ti].keyConfig? [oN] { if templates[ti].keyConfig == nil { templates[ti].keyConfig = [:] }; templates[ti].keyConfig? [newName] = cfg; templates[ti].keyConfig?.removeValue(forKey: oN) }
        saveTemplates(); syncAllInstancesToTemplate(templateID: templateID); clearSmartCache()
    }
    
    func moveTemplateKeys(templateID: UUID, from src: IndexSet, to dst: Int) {
        lock.lock(); defer { lock.unlock() }; guard let ti = templates.firstIndex(where: {$0.id == templateID}) else { return }; templates[ti].keys.move(fromOffsets: src, toOffset: dst); saveTemplates(); syncAllInstancesToTemplate(templateID: templateID); clearSmartCache()
    }
    
    func removeKeyFromTemplateCascade(templateID: UUID, keyIndex: Int, keyName: String) {
        lock.lock(); defer { lock.unlock() }; guard let ti = templates.firstIndex(where: {$0.id == templateID}) else { return }
        if templates[ti].keys.indices.contains(keyIndex) { let kid = templates[ti].keys[keyIndex].id.uuidString; templates[ti].keys.remove(at: keyIndex); templates[ti].keyConfig?.removeValue(forKey: kid); saveTemplates() }
        syncAllInstancesToTemplate(templateID: templateID); clearSmartCache()
    }
    
    func deleteMultipleTemplateKeys(templateID: UUID, keyIDs: Set<UUID>) {
        lock.lock(); defer { lock.unlock() }; guard let idx = templates.firstIndex(where: { $0.id == templateID }) else { return }
        let ids = Set(keyIDs.map { $0.uuidString }); templates[idx].keys.removeAll { keyIDs.contains($0.id) }
        if var cfg = templates[idx].keyConfig { ids.forEach { cfg.removeValue(forKey: $0) }; templates[idx].keyConfig = cfg }
        saveTemplates(); syncAllInstancesToTemplate(templateID: templateID); clearSmartCache(); objectWillChange.send()
    }
    
    func addKeyToTemplateCascade(templateID: UUID, newKey: String) -> UUID? {
        lock.lock(); defer { lock.unlock() }; guard let ti = templates.firstIndex(where: {$0.id == templateID}) else { return nil }
        if templates[ti].keys.contains(where: { $0.name == newKey }) { return nil }; let nK = TemplateKey(name: newKey); templates[ti].keys.append(nK); saveTemplates(); syncAllInstancesToTemplate(templateID: templateID); clearSmartCache(); return nK.id
    }
    
    func syncAllInstancesToTemplate(templateID: UUID) {
        Task(priority: .background) {
            let tmplSnapshot: ArchiveTemplate? = await MainActor.run { templates.first(where: { $0.id == templateID }) }; guard let tmpl = tmplSnapshot else { return }
            var updatedCategories = await MainActor.run { categories }
            for ci in updatedCategories.indices { for ti in updatedCategories[ci].tables.indices { if updatedCategories[ci].tables[ti].templateID == templateID { var t = updatedCategories[ci].tables[ti]; t.rows = t.type == .taskList ? castNewRowsFromTemplate(oldRows: t.rows, templateRows: tmpl.taskRows) : castNewStandardRows(oldRows: t.rows, templateKeys: tmpl.keys); updatedCategories[ci].tables[ti] = t; saveTableToFile(t, categoryTitle: updatedCategories[ci].title) } } }
            var updatedTaskLists = await MainActor.run { taskLists }
            for ti in updatedTaskLists.indices { if updatedTaskLists[ti].templateID == templateID { var t = updatedTaskLists[ti]; t.rows = t.type == .taskList ? castNewRowsFromTemplate(oldRows: t.rows, templateRows: tmpl.taskRows) : castNewStandardRows(oldRows: t.rows, templateKeys: tmpl.keys); updatedTaskLists[ti] = t; saveTaskList(t) } }
            await MainActor.run { self.categories = updatedCategories; self.taskLists = updatedTaskLists }
        }
    }
    
    func mergeTemplates(from sID: UUID, to tID: UUID) {
        lock.lock(); defer { lock.unlock() }; guard let sT = templates.first(where: {$0.id == sID}), let tT = templates.first(where: {$0.id == tID}) else { return }
        for ci in categories.indices { for ti in categories[ci].tables.indices { if categories[ci].tables[ti].templateID == sID { var t = categories[ci].tables[ti]; t.rows = sT.type == .table ? castNewStandardRows(oldRows: t.rows, templateKeys: tT.keys) : t.rows; t.templateID = tID; categories[ci].tables[ti] = t; saveTableToFile(t, categoryTitle: categories[ci].title) } } }
        deleteTemplateWithCascade(templateID: sID); saveTemplates(); clearSmartCache()
    }
    
    func castNewStandardRows(oldRows: [ArchiveRow], templateKeys: [TemplateKey]) -> [ArchiveRow] {
        var ctM: [String: String] = [:]; for r in oldRows { if let d = try? JSONDecoder().decode(StandardRowData.self, from: r.value.data(using: .utf8) ?? Data()) { ctM[r.key] = d.content } else { ctM[r.key] = r.value } }
        return templateKeys.map { tk in let d = StandardRowData(title: tk.name, content: ctM[tk.id.uuidString] ?? ""); let j = (try? JSONEncoder().encode(d)).flatMap { String(data: $0, encoding: .utf8) } ?? ""; return ArchiveRow(key: tk.id.uuidString, value: j) }
    }
    
    /// 【16号修复】：生成学生具体清单的核心方法
    func castNewRowsFromTemplate(oldRows: [ArchiveRow], templateRows: [ArchiveRow]) -> [ArchiveRow] {
        var idMap: [String: Bool] = [:]; var titleMap: [String: Bool] = [:]
        for or in oldRows { if let od = parseTaskData(or.value) { idMap[or.key] = od.isCompleted; titleMap[od.title.trimmingCharacters(in: .whitespaces)] = od.isCompleted } }
        
        return templateRows.map { tr in
            guard var td = parseTaskData(tr.value) else { return ArchiveRow(key: UUID().uuidString, value: "") }
            
            // 【16号修正点】：rowKey 必须等于 tr.key (即母本 UUID)，而不是 tr.id (模板行 ID)
            let rowKey = tr.key
            let rowTitle = td.title.trimmingCharacters(in: .whitespaces)
            
            // 状态继承逻辑
            if let doneByID = idMap[rowKey] { td.isCompleted = doneByID }
            else if let doneByTitle = titleMap[rowTitle] { td.isCompleted = doneByTitle }
            else { td.isCompleted = false }
            
            let j = (try? JSONEncoder().encode(td)).flatMap { String(data: $0, encoding: .utf8) } ?? ""
            // 返回的 ArchiveRow，key 字段现在正确持有母本 UUID
            return ArchiveRow(id: UUID(), key: rowKey, value: j)
        }
    }
    
    func findSimilarTemplates(for source: ArchiveTemplate) -> [TemplateSimilarity] {
        var res = [TemplateSimilarity](); let sN = Set(source.keys.map { $0.name })
        for t in templates { if t.id == source.id || t.type != source.type { continue }; let tN = Set(t.keys.map { $0.name })
            if sN == tN { res.append(TemplateSimilarity(targetTemplate: t, type: .exact, missingKeys: [], extraKeys: [])) } else if sN.isSubset(of: tN) { res.append(TemplateSimilarity(targetTemplate: t, type: .subset, missingKeys: [], extraKeys: Array(tN.subtracting(sN)).sorted())) } else if tN.isSubset(of: sN) { res.append(TemplateSimilarity(targetTemplate: t, type: .superset, missingKeys: Array(sN.subtracting(tN)).sorted(), extraKeys: [])) }
        }
        return res
    }
    
    // MARK: - Smart View Logic (保持不变)
    func checkSmartViewNameExists(name: String, excludeID: UUID? = nil) -> Bool { return smartViews.contains { $0.title.trimmingCharacters(in: .whitespaces) == name.trimmingCharacters(in: .whitespaces) && $0.id != excludeID } }
    func addSmartView(_ c: SmartViewConfig) { lock.lock(); defer { lock.unlock() }; smartViews.append(c); saveSmartViews(); clearSmartCache() }
    func deleteSmartViews(ids: Set<UUID>) { lock.lock(); defer { lock.unlock() }; smartViews.removeAll { ids.contains($0.id) }; saveSmartViews(); clearSmartCache() }
    func deleteSmartView(at: IndexSet) { lock.lock(); defer { lock.unlock() }; smartViews.remove(atOffsets: at); saveSmartViews(); clearSmartCache() }
    func renameSmartView(id: UUID, newName: String) { lock.lock(); defer { lock.unlock() }; if let i = smartViews.firstIndex(where: {$0.id == id}) { smartViews[i].title = newName; saveSmartViews() }; clearSmartCache() }
    func updateSmartViewNote(id: UUID, newNote: String) { lock.lock(); defer { lock.unlock() }; if let i = smartViews.firstIndex(where: {$0.id == id}) { smartViews[i].note = newNote; saveSmartViews() }; clearSmartCache() }
    func updateSmartViewSort(id: UUID, sortKey: String, isAscending: Bool) { lock.lock(); defer { lock.unlock() }; if let i = smartViews.firstIndex(where: {$0.id == id}) { smartViews[i].sortKey = sortKey; smartViews[i].isAscending = isAscending; saveSmartViews() }; clearSmartCache() }
    func performSmartQuery(config: SmartViewConfig) async -> [SmartResultItem] { return await MainActor.run { self.querySmartView(config) } }
    func querySmartView(_ config: SmartViewConfig) -> [SmartResultItem] { if let cached = smartResultsCache[config.id] { return cached }; var results = [SmartResultItem](); guard let tmpl = templates.first(where: { $0.id == config.templateID }) else { return [] }; var n2id = [String: String](); for k in tmpl.keys { n2id[k.name] = k.id.uuidString }; for cat in categories { if cat.title == "删除回收" || cat.title == "自动填写" { continue }; for table in cat.tables { if table.templateID == config.templateID { var isMatch = true; for f in config.filters { guard let tid = n2id[f.key] else { isMatch = false; break }; if let r = table.rows.first(where: { $0.key == tid }) { let val = (try? JSONDecoder().decode(StandardRowData.self, from: r.value.data(using: .utf8) ?? Data()))?.content ?? r.value; if !val.contains(f.value) { isMatch = false; break } } else { isMatch = false; break } }; if isMatch { var disp = [(String, String, KeyStyleConfig)](); let keysToDisp = config.displayKeys.isEmpty ? tmpl.keys.prefix(3).map { $0.name } : config.displayKeys; for kn in keysToDisp { if let kid = n2id[kn] { let style = getKeyConfigObj(templateID: table.templateID, key: kid); let rowData = table.rows.first(where: { $0.key == kid })?.value.data(using: .utf8) ?? Data(); let val = (try? JSONDecoder().decode(StandardRowData.self, from: rowData))?.content ?? ""; disp.append((kn, val, style)) } }; results.append(SmartResultItem(id: table.id, tableName: table.title, tableCreatedAt: table.createdAt, originalTable: table, displayValuesWithStyle: disp)) } } } }; let sorted = results.sorted { (i1, i2) in if config.sortKey == "created" { return config.isAscending ? i1.tableCreatedAt < i2.tableCreatedAt : i1.tableCreatedAt > i2.tableCreatedAt } else { let v1 = i1.displayValuesWithStyle.first(where: { $0.0 == config.sortKey })?.1 ?? ""; let v2 = i1.displayValuesWithStyle.first(where: { $0.0 == config.sortKey })?.1 ?? ""; return config.isAscending ? v1.localizedStandardCompare(v2) == .orderedAscending : v1.localizedStandardCompare(v2) == .orderedDescending } }; smartResultsCache[config.id] = sorted; return sorted }
    
    // MARK: - Style Config (保持不变)
    func getLevelStyleObj(templateID: UUID?, level: Int) -> KeyStyleConfig { let levelKey = "level_\(level)"; guard let tid = templateID, let tmpl = templates.first(where: {$0.id == tid}), let js = tmpl.keyConfig? [levelKey], let data = js.data(using: .utf8), let cfg = try? JSONDecoder().decode(KeyStyleConfig.self, from: data) else { return KeyStyleConfig() }; return cfg }
    func saveLevelStyleObj(templateID: UUID, level: Int, config: KeyStyleConfig) { lock.lock(); defer { lock.unlock() }; let levelKey = "level_\(level)"; guard let idx = templates.firstIndex(where: {$0.id == templateID}) else { return }; if let d = try? JSONEncoder().encode(config), let s = String(data: d, encoding: .utf8) { if templates[idx].keyConfig == nil { templates[idx].keyConfig = [:] }; templates[idx].keyConfig? [levelKey] = s; saveTemplates(); objectWillChange.send() } }
    func getKeyConfigObj(templateID: UUID?, key: String) -> KeyStyleConfig { guard let tid = templateID, let tmpl = templates.first(where: {$0.id == tid}), let js = tmpl.keyConfig? [key], let data = js.data(using: .utf8), let cfg = try? JSONDecoder().decode(KeyStyleConfig.self, from: data) else { return KeyStyleConfig() }; return cfg }
    func saveKeyConfigObj(templateID: UUID, key: String, config: KeyStyleConfig) { lock.lock(); defer { lock.unlock() }; guard let idx = templates.firstIndex(where: {$0.id == templateID}) else { return }; if let d = try? JSONEncoder().encode(config), let s = String(data: d, encoding: .utf8) { if templates[idx].keyConfig == nil { templates[idx].keyConfig = [:] }; templates[idx].keyConfig? [key] = s; saveTemplates(); clearSmartCache(); objectWillChange.send() } }
    
    // MARK: - Table Transformation (保持不变)
    func addTableFromTemplate(to catID: UUID, template: ArchiveTemplate, customTitle: String, sourceTableID: UUID? = nil) -> UUID? { lock.lock(); defer { lock.unlock() }; guard let idx = categories.firstIndex(where: {$0.id == catID}) else { return nil }; var iRs = [ArchiveRow](); if template.type == .table { if let sID = sourceTableID, let sTab = getTable(by: sID) { iRs = castNewStandardRows(oldRows: sTab.rows, templateKeys: template.keys) } else { iRs = template.keys.map { tk in let j = (try? JSONEncoder().encode(StandardRowData(title: tk.name, content: ""))).flatMap { String(data: $0, encoding: .utf8) } ?? ""; return ArchiveRow(key: tk.id.uuidString, value: j) } } } else { iRs = template.taskRows.map { tr in if let d = parseTaskData(tr.value) { var nd = d; nd.isCompleted = false; if let j = try? JSONEncoder().encode(nd), let s = String(data: j, encoding: .utf8) { return ArchiveRow(id: UUID(), key: tr.id.uuidString, value: s) } }; return ArchiveRow(key: UUID().uuidString, value: "") } }; let nt = ArchiveTable(title: customTitle, rows: iRs, templateID: template.id, type: template.type == .table ? .standard : .taskList); categories[idx].tables.insert(nt, at: 0); saveTableToFile(nt, categoryTitle: categories[idx].title); clearSmartCache(); return nt.id }
    func changeTableTemplate(tableID: UUID, categoryID: UUID, newTemplateID: UUID) { lock.lock(); defer { lock.unlock() }; guard let ci = categories.firstIndex(where: { $0.id == categoryID }), let ti = categories[ci].tables.firstIndex(where: { $0.id == tableID }), let nTmpl = templates.first(where: { $0.id == newTemplateID }) else { return }; let oT = categories[ci].tables[ti]; let catT = categories[ci].title; var ctM = [String:String](); for r in oT.rows { if let d = try? JSONDecoder().decode(StandardRowData.self, from: r.value.data(using: .utf8) ?? Data()) { ctM[d.title] = d.content } }; let nRs = nTmpl.keys.map { tk in let j = (try? JSONEncoder().encode(StandardRowData(title: tk.name, content: ctM[tk.name] ?? ""))).flatMap { String(data: $0, encoding: .utf8) } ?? ""; return ArchiveRow(key: tk.id.uuidString, value: j) }; var trsh = oT; trsh.title = "归并前_" + oT.title; trsh.deletedAt = Date(); CloudFileManager.shared.deleteTableDual(categoryName: catT, fileName: "\(getSafeName(oT)).csv"); let nt = ArchiveTable(id: UUID(), title: oT.title, rows: nRs, templateID: newTemplateID); categories[ci].tables[ti] = nt; if let tridx = categories.firstIndex(where: {$0.id == SystemIDs.recycleBin}) { categories[tridx].tables.insert(trsh, at: 0); saveTableToFile(trsh, categoryTitle: "删除回收") }; saveTableToFile(nt, categoryTitle: catT); clearSmartCache(); objectWillChange.send() }
    func getTablesInAutoFillFolder() -> [ArchiveTable] { categories.first(where: {$0.title == "自动填写"})?.tables ?? [] }
    func deleteUnmatchedTable(at: IndexSet) { lock.lock(); defer { lock.unlock() }; unmatchedTables.remove(atOffsets: at); saveUnmatched() }
    func convertUnmatchedTable(tableID: UUID, templateID: UUID) { lock.lock(); defer { lock.unlock() }; guard let i = unmatchedTables.firstIndex(where: {$0.id == tableID}), let tmpl = templates.first(where: {$0.id == templateID}) else { return }; var t = unmatchedTables[i]; t.templateID = tmpl.id; t.rows = castNewStandardRows(oldRows: t.rows, templateKeys: tmpl.keys); if categories.count > 1 { categories[1].tables.insert(t, at: 0); saveTableToFile(t, categoryTitle: categories[1].title) }; unmatchedTables.remove(at: i); saveUnmatched(); clearSmartCache() }
    func getTable(by id: UUID) -> ArchiveTable? { for c in categories { if let t = c.tables.first(where: { $0.id == id }) { return t } }; if let t = taskLists.first(where: { $0.id == id }) { return t }; if let t = unmatchedTables.first(where: { $0.id == id }) { return t }; return nil }
    func getTablesByTemplate(templateID: UUID) -> [(table: ArchiveTable, categoryName: String, categoryID: UUID)] { var res = [(ArchiveTable, String, UUID)](); for c in categories { for t in c.tables { if t.templateID == templateID { res.append((t, c.title, c.id)) } } }; return res.sorted { $0.0.createdAt > $1.0.createdAt } }
}

// MARK: - ArchiveStore Part5 - Utils & Text Operations (文本与工具) - V104
//
// extension ArchiveStore
// (修改：移除未使用变量 nEx, cleanText)

extension ArchiveStore {
    
    // MARK: - CSV Parsing Helper
    
    func parseCSVRow(_ line: String) -> [String] {
        var res = [String]()
        var cur = ""
        var inQ = false
        let chars = Array(line)
        var i = 0
        while i < chars.count {
            let c = chars[i]
            if c == "\"" {
                if inQ && i+1 < chars.count && chars[i+1] == "\"" { cur.append("\""); i += 1 }
                else { inQ.toggle() }
            } else if c == "," && !inQ { res.append(cur); cur = "" }
            else { cur.append(c) }
            i += 1
        }
        res.append(cur)
        return res
    }
    
    // MARK: - Standard Row Helpers
    
    func getStandardContent(_ v: String) -> String {
        if let d = v.data(using: .utf8),
           let dec = try? JSONDecoder().decode(StandardRowData.self, from: d) { return dec.content }
        return v
    }
    
    // MARK: - Smart List Logic
    
    func normalizeListLine(_ line: String) -> String {
        if let (ind, bul, content) = parseListLine(line) {
            let trimmedContent = content.trimmingCharacters(in: .whitespaces)
            return "\(ind)\(bul) \(trimmedContent)"
        }
        return line
    }
    
    func handleSmartListInput(oldValue: String, newValue: String, cursorIndex: Int) -> (String, Int?) {
        if newValue.hasSuffix("\t") && newValue.count > oldValue.count {
            let lines = newValue.split(separator: "\n", omittingEmptySubsequences: false)
            if let last = lines.last {
                let c = String(last.dropLast())
                if let (ind, _, r) = parseListLine(c), r.trimmingCharacters(in: .whitespaces).isEmpty {
                    let currentTabCount = ind.filter { $0 == "\t" }.count
                    if currentTabCount < 5 {
                        let l = currentTabCount + 1
                        let b = getBulletForLevel(l, index: 1)
                        var nLs = lines.dropLast()
                        nLs.append(Substring("\(ind)\t\(b) "))
                        return (nLs.joined(separator: "\n"), nil)
                    } else {
                         return (oldValue, nil)
                    }
                }
            }
        }
        
        if newValue.count > oldValue.count && newValue.contains("\n") {
            let oL = oldValue.components(separatedBy: .newlines)
            let nL = newValue.components(separatedBy: .newlines)
            
            if nL.count == oL.count + 1 {
                for i in 0..<nL.count {
                    if i < oL.count && nL[i] == oL[i] { continue }
                    
                    if i > 0 {
                        let p = nL[i-1]
                        if let (ind, bul, _) = parseListLine(p) {
                            let nextBullet = generateNextBullet(from: p) ?? bul
                            let nB = "\(ind)\(nextBullet.trimmingCharacters(in: .whitespaces)) "
                            var pL = nL
                            
                            if parseListLine(pL[i]) == nil {
                                pL[i] = nB + pL[i].trimmingCharacters(in: .whitespaces)
                            }
                            
                            // 【修复】移除未使用的 nEx 变量
                            
                            var pos = 0
                            for k in 0..<i { pos += pL[k].count + 1 }
                            return (pL.joined(separator: "\n"), pos + nB.count)
                        }
                    }
                    break
                }
            }
        }
        return (newValue, nil)
    }
    
    func smartDecreaseIndent(text: String, allRows: [ArchiveRow], currentIndex: Int) -> String {
        let dec = decreaseListLevel(text: text)
        guard let (tInd, _, ct) = parseListLine(dec) else { return dec }
        
        for i in (0..<currentIndex).reversed() {
            let pR = getStandardContent(allRows[i].value)
            if let (pI, _, _) = parseListLine(pR) {
                if pI.count < tInd.count {
                    let newBul = getBulletForLevel(tInd.count, index: 1)
                    return "\(tInd)\(newBul) \(ct.trimmingCharacters(in: .whitespaces))"
                }
                if pI == tInd, let nB = generateNextBullet(from: pR) {
                    return nB + ct.trimmingCharacters(in: .whitespaces)
                }
            }
        }
        let newBul = getBulletForLevel(tInd.count, index: 1)
        return "\(tInd)\(newBul) \(ct.trimmingCharacters(in: .whitespaces))"
    }
    
    func decreaseListLevel(text: String) -> String {
        let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
        guard let last = lines.last.map(String.init) else { return text }
        
        if let (ind, _, res) = parseListLine(last) {
            let cur = ind.filter { $0 == "\t" }.count
            if cur > 0 {
                let nL = cur - 1
                let nB = getBulletForLevel(nL, index: 1)
                let nI = String(repeating: "\t", count: nL)
                var nLines = lines.dropLast()
                nLines.append(Substring("\(nI)\(nB) \(res.trimmingCharacters(in: .whitespaces))"))
                return nLines.joined(separator: "\n")
            } else {
                var nLines = lines.dropLast()
                nLines.append(Substring(res.trimmingCharacters(in: .whitespaces)))
                return nLines.joined(separator: "\n")
            }
        }
        return text
    }
    
    func increaseListLevel(text: String) -> String {
        let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
        guard let last = lines.last.map(String.init) else { return text + "\t" }
        
        if let (ind, _, res) = parseListLine(last) {
            let nL = ind.filter { $0 == "\t" }.count + 1
            if nL > 5 { return text }
            
            let nI = String(repeating: "\t", count: nL)
            let nB = getBulletForLevel(nL, index: 1)
            var nLines = lines.dropLast()
            nLines.append(Substring("\(nI)\(nB) \(res.trimmingCharacters(in: .whitespaces))"))
            return nLines.joined(separator: "\n")
        }
        return text + "\t"
    }
    
    func detectLevel(of line: String) -> Int {
        guard let (ind, _, _) = parseListLine(line) else { return -1 }
        let tabs = ind.filter { $0 == "\t" }.count
        return min(5, max(0, tabs))
    }
    
    func startNewNumbering(text: String) -> String {
        if let (ind, _, content) = parseListLine(text) {
            let level = ind.filter { $0 == "\t" }.count
            let startBul = getBulletForLevel(level, index: 1)
            return "\(ind)\(startBul) \(content.trimmingCharacters(in: .whitespaces))"
        }
        return "1. " + text.trimmingCharacters(in: .whitespaces)
    }
    
    func continueNumbering(text: String) -> String {
        // 【修复】移除未使用的 cleanText 变量
        return normalizeListLine(text)
    }
    
    // MARK: - Regex & Parsing Utils
    
    func parseListLine(_ line: String) -> (String, String, String)? {
        let pattern = "^(\\t*)((\\d+\\.)|([a-z]+\\.)|([ivx]+\\.)|(（\\d+）)|(<\\d+>)|-)\\s*"
        guard let regex = try? NSRegularExpression(pattern: pattern, options: .caseInsensitive) else { return nil }
        
        let range = NSRange(location: 0, length: line.utf16.count)
        guard let match = regex.firstMatch(in: line, options: [], range: range) else { return nil }
        
        if let r1 = Range(match.range(at: 1), in: line),
           let r2 = Range(match.range(at: 2), in: line) {
            let indent = String(line[r1])
            let bullet = String(line[r2])
            let restIndex = line.index(line.startIndex, offsetBy: match.range.length)
            let rest = String(line[restIndex...])
            return (indent, bullet, rest)
        }
        return nil
    }
    
    func generateNextBullet(from line: String) -> String? {
        guard let (ind, bul, _) = parseListLine(line) else { return nil }
        let indentStr = ind
        
        if bul == "-" { return "\(indentStr)- " }
        
        if bul.hasPrefix("<") && bul.hasSuffix(">") {
            let numStr = bul.dropFirst().dropLast()
            if let num = Int(numStr) { return "\(indentStr)<\(num + 1)> " }
        }
        
        if bul.hasPrefix("（") && bul.hasSuffix("）") {
            let numStr = bul.dropFirst().dropLast()
            if let num = Int(numStr) { return "\(indentStr)（\(num + 1)） " }
        }
        
        if let num = Int(bul.dropLast()), bul.last == "." {
            return "\(indentStr)\(num + 1). "
        }
        
        let low = bul.lowercased()
        let romans = ["i.", "ii.", "iii.", "iv.", "v.", "vi.", "vii.", "viii.", "ix.", "x."]
        if let idx = romans.firstIndex(of: low) {
            if idx + 1 < romans.count { return "\(indentStr)\(romans[idx + 1]) " }
            else { return "\(indentStr)\(low) " }
        }
        
        if low.hasSuffix(".") {
            let letterPart = low.dropLast()
            if let nextLetter = incrementAlpha(String(letterPart)) {
                return "\(indentStr)\(nextLetter). "
            }
        }
        
        return nil
    }
    
    private func incrementAlpha(_ s: String) -> String? {
        let scalars = Array(s.unicodeScalars)
        var result = ""
        var carry = true
        for scalar in scalars.reversed() {
            if carry {
                if scalar.value >= 122 { result = "a" + result }
                else {
                    if let next = UnicodeScalar(scalar.value + 1) {
                        result = String(Character(next)) + result; carry = false
                    }
                }
            } else { result = String(Character(scalar)) + result }
        }
        if carry { result = "a" + result }
        return result
    }
    
    func getBulletForLevel(_ l: Int, index: Int) -> String {
        switch l {
        case 0: return "\(index)."
        case 1: return intToAlpha(index) + "."
        case 2: return intToRoman(index) + "."
        case 3: return "（\(index)）"
        case 4: return "<\(index)>"
        case 5: return "-"
        default: return "-"
        }
    }
    
    private func intToAlpha(_ i: Int) -> String {
        var n = i
        var res = ""
        while n > 0 {
            n -= 1
            let charCode = n % 26 + 97
            if let scalar = UnicodeScalar(charCode) { res = String(Character(scalar)) + res }
            n /= 26
        }
        return res.isEmpty ? "a" : res
    }
    
    private func intToRoman(_ i: Int) -> String {
        let arr = ["", "i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x"]
        if i > 0 && i < arr.count { return arr[i] }
        return "i"
    }
    
    // MARK: - Basic Table/Row Operations
    
    func addTaskNode(tableID: UUID, title: String, parentID: UUID?) {
        lock.lock(); defer { lock.unlock() }
        guard let idx = taskLists.firstIndex(where: {$0.id == tableID}) else { return }
        var t = taskLists[idx]
        
        let d = TaskRowData(title: title, isCompleted: false, level: 0)
        if let j = try? JSONEncoder().encode(d), let s = String(data: j, encoding: .utf8) {
            t.rows.append(ArchiveRow(key: UUID().uuidString, value: s))
            saveTaskList(t)
        }
    }
    
    func toggleTaskNode(tableID: UUID, nodeID: String) {
        lock.lock(); defer { lock.unlock() }
        guard let ti = taskLists.firstIndex(where: {$0.id == tableID}) else { return }
        var t = taskLists[ti]
        
        guard let ri = t.rows.firstIndex(where: {$0.key == nodeID}),
              var d = parseTaskData(t.rows[ri].value) else { return }
        
        d.isCompleted.toggle()
        
        if let j = try? JSONEncoder().encode(d), let s = String(data: j, encoding: .utf8) {
            t.rows[ri].value = s
        }
        saveTaskList(t)
    }
    
    func generateTaskReport(tableID: UUID) -> String {
        guard let t = taskLists.first(where: {$0.id == tableID}) else { return "" }
        var res = [String]()
        for r in t.rows {
            if let d = parseTaskData(r.value), d.isCompleted {
                res.append("完成 \(d.title)")
            }
        }
        return res.joined(separator: "\n")
    }
    
    func updateValueByTableID(tableID: UUID, key: String, newValue: String) {
        lock.lock(); defer { lock.unlock() }
        
        for ci in 0..<categories.count {
            if let ti = categories[ci].tables.firstIndex(where:{$0.id == tableID}) {
                var t = categories[ci].tables[ti]
                
                if let ri = t.rows.firstIndex(where: {$0.key == key}) {
                    if t.type == .standard {
                        var tit = key
                        if let o = try? JSONDecoder().decode(StandardRowData.self, from: t.rows[ri].value.data(using: .utf8) ?? Data()) {
                            tit = o.title
                        }
                        if let j = try? JSONEncoder().encode(StandardRowData(title: tit, content: newValue)),
                           let s = String(data: j, encoding: .utf8) {
                            t.rows[ri].value = s
                        }
                    } else {
                        t.rows[ri].value = newValue
                    }
                }
                
                categories[ci].tables[ti] = t
                saveTableToFile(t, categoryTitle: categories[ci].title)
                clearSmartCache()
                return
            }
        }
    }
    
    func addRow(to tID: UUID, in cID: UUID, key: String, value: String) {
        if let t = getTable(by: tID) {
            var nt = t
            nt.rows.append(ArchiveRow(key: key, value: value))
            persistTableChanges(table: nt, categoryID: cID, oldTitle: t.title)
        }
    }
    
    func updateRow(catID: UUID, tableID: UUID, row: ArchiveRow) {
        if let t = getTable(by: tableID), let i = t.rows.firstIndex(where: {$0.id == row.id}) {
            var nt = t
            nt.rows[i] = row
            persistTableChanges(table: nt, categoryID: catID, oldTitle: t.title)
        }
    }
    
    func deleteRow(catID: UUID, tableID: UUID, at off: IndexSet) {
        if let t = getTable(by: tableID) {
            var nt = t
            nt.rows.remove(atOffsets: off)
            persistTableChanges(table: nt, categoryID: catID, oldTitle: t.title)
        }
    }
}

// MARK: - ArchiveStore Part 7-1 - v28 - PDF 导出绘图引擎 (上) - 适配 macOS
//
// extension ArchiveStore
// (修改：
//  1. 从原 Part 7 截断出 PDF 与核心绘制逻辑。
//  2. 针对 UIGraphics 和 UIPrintPageRenderer 等纯 UIKit 渲染器，添加 #if !os(macOS) 屏蔽。
//  3. 优化 URL.BookmarkResolutionOptions 判定，兼容 macOS 原生书签权限。)

extension ArchiveStore {
    
    // 【355号修正】：去掉 private，允许编辑器视野监视器调用
    @MainActor
    static var headlessMathRenderer = LPHeadlessMathRenderer()

    /// 【341号核心重构】：PDF 绘图引擎 (异步预渲染版)
    func generateAdvancedPDF(nodes: [LPRowNode], title: String, style: LPGlobalStyle) async -> URL? {
        #if os(macOS)
        var uniqueFormulas = Set<String>()
        for node in nodes {
            for request in LPRerender.extractFormulaRequests(from: node.content) {
                uniqueFormulas.insert(request.formulaText)
            }
        }
        
        let formulaMap: [String: LPFormulaRenderAsset] = await withCheckedContinuation { continuation in
            Self.headlessMathRenderer.render(formulas: uniqueFormulas, style: style.body, dark: false) { results in
                continuation.resume(returning: results)
            }
        }
        
        let pageSize = CGSize(width: 595.2, height: 841.8)
        let margin: CGFloat = 40.0
        let scale: CGFloat = 0.4
        let indentStep: CGFloat = 42.0 * scale
        let maxWidth = pageSize.width - (margin * 2)
        
        let fileURL = FileManager.default.temporaryDirectory.appendingPathComponent("\(UUID().uuidString).pdf")
        var mediaBox = CGRect(origin: .zero, size: pageSize)
        guard let consumer = CGDataConsumer(url: fileURL as CFURL),
              let context = CGContext(consumer: consumer, mediaBox: &mediaBox, nil) else { return nil }
        
        func pdfY(topY: CGFloat, height: CGFloat) -> CGFloat {
            pageSize.height - topY - height
        }
        
        let drawPDFBranding = {
            let brandingText = "Generated By 李知本·时间管理器"
            let brandingFont = NSFont.systemFont(ofSize: 9.6 * scale, weight: .black)
            let attrString = NSAttributedString(string: brandingText, attributes:[
                .font: brandingFont,
                .foregroundColor: NSColor.black,
                .kern: 0.5
            ])
            let brandingSize = attrString.size()
            attrString.draw(at: CGPoint(
                x: pageSize.width - brandingSize.width - margin,
                y: pdfY(topY: 20.0, height: brandingSize.height)
            ))
        }
        
        let numberingMap = LPNumberingEngine.generateNumbers(for: nodes, style: style)
        
        var currentY: CGFloat = margin + 20.0
        
        var pageOpen = false
        func beginPage() {
            if pageOpen { context.endPDFPage() }
            context.beginPDFPage(nil)
            pageOpen = true
            let nsContext = NSGraphicsContext(cgContext: context, flipped: false)
            NSGraphicsContext.current = nsContext
            drawPDFBranding()
        }
        
        beginPage()
        
        for node in nodes {
            let config = getTargetStyleConfig(node: node, style: style)
            let rowColor = LPRerender.lpAdaptiveColor(hex: config.color, dark: false)
            let staggerIndent: CGFloat = calculatePhysicalIndent(type: node.type, step: indentStep)
            let numberPrefix = numberingMap[node.id] ?? ""
            let textX = margin + staggerIndent
            let textWidth = maxWidth - staggerIndent
            
            if let imgInfo = LPRenderer.extractImageInfo(from: node.content) {
                let fileURL = MarkdownAssetManager.shared.getFileURL(assetID: imgInfo.assetID)
                if let image = NSImage(contentsOfFile: fileURL.path) {
                    let ratio = image.size.height / image.size.width
                    let targetCm = imgInfo.widthCm ?? 10.0
                    let imgDisplayWidth = min(targetCm * (72.0 / 2.54) * scale, textWidth)
                    let imgDisplayHeight = imgDisplayWidth * ratio
                    if currentY + imgDisplayHeight > pageSize.height - margin {
                        beginPage()
                        currentY = margin + 20.0
                    }
                    NSGraphicsContext.saveGraphicsState()
                    image.draw(in: CGRect(
                        x: textX,
                        y: pdfY(topY: currentY + (config.spaceAbove * scale), height: imgDisplayHeight),
                        width: imgDisplayWidth,
                        height: imgDisplayHeight
                    ))
                    NSGraphicsContext.restoreGraphicsState()
                    currentY += imgDisplayHeight + (config.spaceAbove + config.spaceBelow) * scale
                    continue
                }
            }
            
            let processedAttrString = LPRerender.renderNS(node.content, styleConfig: config, scale: scale, isDark: false, hierarchicalIndent: 0, formulaImages: formulaMap)
            let finalAttrString = NSMutableAttributedString()
            if !numberPrefix.isEmpty {
                let numFont = LPRerender.resolveUIFont(name: config.fontName, size: config.size * scale, isBold: config.isBold)
                finalAttrString.append(NSAttributedString(string: "\(numberPrefix) ", attributes: [.font: numFont, .foregroundColor: NSColor(rowColor)]))
            }
            finalAttrString.append(processedAttrString)
            
            let textRect = finalAttrString.boundingRect(
                with: CGSize(width: textWidth, height: .greatestFiniteMagnitude),
                options: [.usesLineFragmentOrigin, .usesFontLeading]
            )
            let totalRowHeight = textRect.height + (config.spaceAbove + config.spaceBelow) * scale
            
            if currentY + totalRowHeight > pageSize.height - margin {
                beginPage()
                currentY = margin + 20.0
            }
            
            NSGraphicsContext.saveGraphicsState()
            if config.showBackground {
                let barHeight = textRect.height + (8 * scale)
                let barRect = CGRect(
                    x: textX - (10 * scale),
                    y: pdfY(topY: currentY + (config.spaceAbove * scale) - (4 * scale), height: barHeight),
                    width: pageSize.width - margin - (textX - (10 * scale)),
                    height: barHeight
                )
                NSColor(rowColor).withAlphaComponent(0.12).setFill()
                let path = NSBezierPath(roundedRect: barRect, xRadius: 15.0 * scale, yRadius: 15.0 * scale)
                path.fill()
            }
            
            let drawOrigin = CGPoint(
                x: textX,
                y: pdfY(topY: currentY + (config.spaceAbove * scale), height: textRect.height)
            )
            finalAttrString.draw(
                with: CGRect(origin: drawOrigin, size: CGSize(width: textWidth, height: textRect.height)),
                options: [.usesLineFragmentOrigin, .usesFontLeading]
            )
            NSGraphicsContext.restoreGraphicsState()
            
            currentY += totalRowHeight
        }
        
        if pageOpen { context.endPDFPage() }
        context.closePDF()
        return fileURL
        #else
        var uniqueFormulas = Set<String>()
        for node in nodes {
            for request in LPRerender.extractFormulaRequests(from: node.content) {
                uniqueFormulas.insert(request.formulaText)
            }
        }
        
        // --- 阶段二：异步获取公式图片映射表 ---
        let formulaMap:[String: LPFormulaRenderAsset] = await withCheckedContinuation { continuation in
            Self.headlessMathRenderer.render(formulas: uniqueFormulas, style: style.body, dark: false) { results in
                continuation.resume(returning: results)
            }
        }
        
        // --- 阶段三：物理绘图流程 ---
        let pdfData = NSMutableData()
        let pageSize = CGSize(width: 595.2, height: 841.8)
        let pageRect = CGRect(origin: .zero, size: pageSize)
        let margin: CGFloat = 40.0
        let scale: CGFloat = 0.4
        let indentStep: CGFloat = 42.0 * scale
        let maxWidth = pageSize.width - (margin * 2)
        
        let drawPDFBranding = { (context: CGContext) in
            let brandingText = "Generated By 李知本·时间管理器"
            let brandingFont = UIFont.systemFont(ofSize: 9.6 * scale, weight: .black)
            let attrString = NSAttributedString(string: brandingText, attributes:[.font: brandingFont, .foregroundColor: UIColor.black, .kern: 0.5])
            attrString.draw(at: CGPoint(x: pageSize.width - attrString.size().width - margin, y: 20.0))
        }
        
        UIGraphicsBeginPDFContextToData(pdfData, pageRect, nil)
        UIGraphicsBeginPDFPage()
        guard let context = UIGraphicsGetCurrentContext() else { return nil }
        drawPDFBranding(context)
        
        var currentY: CGFloat = margin + 20.0
        let numberingMap = LPNumberingEngine.generateNumbers(for: nodes, style: style)
        
        let textStorage = NSTextStorage()
        let layoutManager = NSLayoutManager()
        let textContainer = NSTextContainer()
        textStorage.addLayoutManager(layoutManager)
        layoutManager.addTextContainer(textContainer)
        textContainer.lineFragmentPadding = 0
        
        for node in nodes {
            let config = getTargetStyleConfig(node: node, style: style)
            let rowColor = LPRenderer.lpAdaptiveColor(hex: config.color, dark: false)
            let staggerIndent: CGFloat = calculatePhysicalIndent(type: node.type, step: indentStep)
            let numberPrefix = numberingMap[node.id] ?? ""
            let textX = margin + staggerIndent
            let textWidth = maxWidth - staggerIndent
            
            if let imgInfo = LPRenderer.extractImageInfo(from: node.content) {
                let fileURL = MarkdownAssetManager.shared.getFileURL(assetID: imgInfo.assetID)
                if let image = UIImage(contentsOfFile: fileURL.path) {
                    let ratio = image.size.height / image.size.width
                    let targetCm = imgInfo.widthCm ?? 10.0
                    let imgDisplayWidth = min(targetCm * (72.0 / 2.54) * scale, textWidth)
                    let imgDisplayHeight = imgDisplayWidth * ratio
                    if currentY + imgDisplayHeight > pageSize.height - margin { UIGraphicsBeginPDFPage(); drawPDFBranding(context); currentY = margin + 20.0 }
                    image.draw(in: CGRect(x: textX, y: currentY + (config.spaceAbove * scale), width: imgDisplayWidth, height: imgDisplayHeight))
                    currentY += imgDisplayHeight + (config.spaceAbove + config.spaceBelow) * scale
                    continue
                }
            }
            
            let processedAttrString = LPRerender.renderNS(node.content, styleConfig: config, scale: scale, isDark: false, hierarchicalIndent: 0, formulaImages: formulaMap)
            let finalAttrString = NSMutableAttributedString()
            if !numberPrefix.isEmpty {
                let numFont = LPRerender.resolveUIFont(name: config.fontName, size: config.size * scale, isBold: config.isBold)
                finalAttrString.append(NSAttributedString(string: "\(numberPrefix) ", attributes: [.font: numFont, .foregroundColor: UIColor(rowColor)]))
            }
            finalAttrString.append(processedAttrString)
            
            textStorage.setAttributedString(finalAttrString)
            textContainer.size = CGSize(width: textWidth, height: .greatestFiniteMagnitude)
            
            let glyphRange = layoutManager.glyphRange(for: textContainer)
            let textRect = layoutManager.usedRect(for: textContainer)
            let totalRowHeight = textRect.height + (config.spaceAbove + config.spaceBelow) * scale
            
            if currentY + totalRowHeight > pageSize.height - margin { UIGraphicsBeginPDFPage(); drawPDFBranding(context); currentY = margin + 20.0 }
            
            if config.showBackground {
                let barRect = CGRect(x: textX - (10 * scale), y: currentY + (config.spaceAbove * scale) - (4 * scale), width: pageSize.width - margin - (textX - (10 * scale)), height: textRect.height + (8 * scale))
                context.saveGState()
                UIColor(rowColor).withAlphaComponent(0.12).setFill()
                UIBezierPath(roundedRect: barRect, cornerRadius: 15.0 * scale).fill()
                context.restoreGState()
            }
            
            context.saveGState()
            let drawOrigin = CGPoint(x: textX, y: currentY + (config.spaceAbove * scale))
            layoutManager.drawBackground(forGlyphRange: glyphRange, at: drawOrigin)
            layoutManager.drawGlyphs(forGlyphRange: glyphRange, at: drawOrigin)
            context.restoreGState()
            
            currentY += totalRowHeight
        }
        
        UIGraphicsEndPDFContext()
        let fileURL = FileManager.default.temporaryDirectory.appendingPathComponent("\(UUID().uuidString).pdf")
        do { try pdfData.write(to: fileURL); return fileURL } catch { return nil }
        #endif
    }

    func saveAdvancedPDFToCustomPath(tempURL: URL, title: String, folderPath: String, bookmarkData: Data?) -> String? {
        var targetFolderURL: URL? = nil; var isStale = false; var isSecurelyAccessed = false
        if let data = bookmarkData { do {
            // 【适配 macOS】: 增加 os(macOS) 判定，确保在 Mac 原生下获取正确的权限
            #if os(macOS) || targetEnvironment(macCatalyst)
            let options = URL.BookmarkResolutionOptions.withSecurityScope
            #else
            let options = URL.BookmarkResolutionOptions([])
            #endif
            targetFolderURL = try URL(resolvingBookmarkData: data, options: options, relativeTo: nil, bookmarkDataIsStale: &isStale)
        } catch { print("[Export] 搬运书签解析异常: \(error.localizedDescription)") } }
        if targetFolderURL == nil { var cleanPath = folderPath; if cleanPath.hasPrefix("file://") { cleanPath = cleanPath.replacingOccurrences(of: "file://", with: "") }; cleanPath = cleanPath.removingPercentEncoding ?? cleanPath; targetFolderURL = URL(fileURLWithPath: cleanPath) }
        guard let folderURL = targetFolderURL else { return "搬运失败：无效路径" }
        isSecurelyAccessed = folderURL.startAccessingSecurityScopedResource()
        defer { if isSecurelyAccessed { folderURL.stopAccessingSecurityScopedResource() } }
        let destURL = folderURL.appendingPathComponent("\(title).pdf")
        do { if !FileManager.default.fileExists(atPath: folderURL.path) { try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true) }; if FileManager.default.fileExists(atPath: destURL.path) { try FileManager.default.removeItem(at: destURL) }; try FileManager.default.moveItem(at: tempURL, to: destURL); return nil } catch { return "物理搬运失败: \(error.localizedDescription)" }
    }
    
    private func calculatePhysicalIndent(type: LPNodeType, step: CGFloat) -> CGFloat {
        switch type {
        case .h1: return 0; case .h2: return step; case .h3: return step * 2; case .h4: return step * 3; case .h5: return step * 4; case .h6: return step * 5
        case .l1: return (step * 5) + (step * 2.0); case .l2: return (step * 7) + (step * 0.5); case .l3: return (step * 7) + (step * 1.0)
        case .l4: return (step * 7) + (step * 1.5); case .l5: return (step * 7) + (step * 2.0); case .quote: return (step * 9) + step
        }
    }
    
    private func getTargetStyleConfig(node: LPRowNode, style: LPGlobalStyle) -> LPGlobalStyle.TextStyle {
        switch node.type {
        case .h1: return style.h1; case .h2: return style.h2; case .h3: return style.h3; case .h4: return style.h4; case .h5: return style.h5; case .h6: return style.h6
        case .l1, .l2, .l3, .l4, .l5: return style.body; case .quote: return style.quote
        }
    }

    #if os(macOS)
    private final class MacPDFExportContainerView: NSView {
        let brandingText: String

        init(frame: CGRect, brandingText: String) {
            self.brandingText = brandingText
            super.init(frame: frame)
            wantsLayer = true
            layer?.backgroundColor = NSColor.white.cgColor
        }

        @available(*, unavailable)
        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        override var isFlipped: Bool { true }

        override func draw(_ dirtyRect: NSRect) {
            NSColor.white.setFill()
            dirtyRect.fill()

            let attrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: 9.6, weight: .black),
                .foregroundColor: NSColor.black,
                .kern: 0.5
            ]
            let branding = NSAttributedString(string: brandingText, attributes: attrs)
            let size = branding.size()
            let point = CGPoint(x: bounds.width - size.width, y: 0)
            branding.draw(at: point)
        }
    }

    private func generateMacPDFData(from attributedText: NSAttributedString) -> Data? {
        let pageSize = CGSize(width: 595.2, height: 841.8)
        let horizontalMargin: CGFloat = 40
        let verticalMargin: CGFloat = 40
        let contentWidth = pageSize.width - (horizontalMargin * 2)

        let textView = NSTextView(frame: CGRect(x: 0, y: 0, width: contentWidth, height: 10))
        textView.isEditable = false
        textView.isSelectable = false
        textView.drawsBackground = false
        textView.textContainerInset = .zero
        textView.textContainer?.containerSize = CGSize(width: contentWidth, height: .greatestFiniteMagnitude)
        textView.textContainer?.widthTracksTextView = false
        textView.textContainer?.heightTracksTextView = false
        textView.textContainer?.lineFragmentPadding = 0
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.maxSize = CGSize(width: contentWidth, height: .greatestFiniteMagnitude)
        textView.minSize = CGSize(width: contentWidth, height: 0)
        textView.textStorage?.setAttributedString(attributedText)
        textView.layoutManager?.ensureLayout(for: textView.textContainer!)

        let usedRect = textView.layoutManager?.usedRect(for: textView.textContainer!) ?? .zero
        let brandingHeight: CGFloat = 18
        let contentTopSpacing: CGFloat = 14
        let documentHeight = max(pageSize.height - verticalMargin * 2, ceil(usedRect.height) + brandingHeight + contentTopSpacing)

        textView.frame = CGRect(x: 0, y: brandingHeight + contentTopSpacing, width: contentWidth, height: ceil(usedRect.height))

        let containerView = MacPDFExportContainerView(
            frame: CGRect(x: 0, y: 0, width: contentWidth, height: documentHeight),
            brandingText: "Generated By 李知本·时间管理器"
        )
        containerView.addSubview(textView)

        let printInfo = NSPrintInfo()
        printInfo.paperSize = pageSize
        printInfo.topMargin = verticalMargin
        printInfo.bottomMargin = verticalMargin
        printInfo.leftMargin = horizontalMargin
        printInfo.rightMargin = horizontalMargin
        printInfo.horizontalPagination = .fit
        printInfo.verticalPagination = .automatic
        printInfo.isHorizontallyCentered = false
        printInfo.isVerticallyCentered = false

        let pdfData = NSMutableData()
        let operation = NSPrintOperation.pdfOperation(
            with: containerView,
            inside: containerView.bounds,
            to: pdfData,
            printInfo: printInfo
        )
        operation.showsPrintPanel = false
        operation.showsProgressPanel = false

        guard operation.run() else { return nil }
        return pdfData as Data
    }
    
    private func resolveExportFolderURL(folderPath: String, bookmarkData: Data?) -> (url: URL?, secure: Bool) {
        var targetFolderURL: URL?
        var isStale = false
        if let data = bookmarkData {
            do {
                targetFolderURL = try URL(
                    resolvingBookmarkData: data,
                    options: .withSecurityScope,
                    relativeTo: nil,
                    bookmarkDataIsStale: &isStale
                )
            } catch {
                print("[Export] 书签解析异常: \(error.localizedDescription)")
            }
        }
        if targetFolderURL == nil {
            var cleanPath = folderPath
            if cleanPath.hasPrefix("file://") {
                cleanPath = cleanPath.replacingOccurrences(of: "file://", with: "")
            }
            cleanPath = cleanPath.removingPercentEncoding ?? cleanPath
            targetFolderURL = URL(fileURLWithPath: cleanPath)
        }
        guard let folderURL = targetFolderURL else { return (nil, false) }
        let secure = folderURL.startAccessingSecurityScopedResource()
        return (folderURL, secure)
    }
    #endif

    func exportPDFToCustomPath(attributedText: NSAttributedString, title: String, folderPath: String, bookmarkData: Data?) -> String? {
        #if os(macOS)
        guard let pdfData = generateMacPDFData(from: attributedText) else {
            return "导出失败：无法生成 PDF 数据"
        }
        let resolved = resolveExportFolderURL(folderPath: folderPath, bookmarkData: bookmarkData)
        guard let folderURL = resolved.url else { return "导出失败：无效的保存路径" }
        defer { if resolved.secure { folderURL.stopAccessingSecurityScopedResource() } }
        let destURL = folderURL.appendingPathComponent("\(title).pdf")
        do {
            if !FileManager.default.fileExists(atPath: folderURL.path) {
                try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true)
            }
            if FileManager.default.fileExists(atPath: destURL.path) {
                try FileManager.default.removeItem(at: destURL)
            }
            try pdfData.write(to: destURL, options: .atomic)
            return nil
        } catch {
            return "物理写入失败: \(error.localizedDescription)"
        }
        #else
        var targetFolderURL: URL? = nil; var isStale = false; var isSecurelyAccessed = false
        if let data = bookmarkData { do {
            #if targetEnvironment(macCatalyst)
            let options = URL.BookmarkResolutionOptions.withSecurityScope
            #else
            let options = URL.BookmarkResolutionOptions([])
            #endif
            targetFolderURL = try URL(resolvingBookmarkData: data, options: options, relativeTo: nil, bookmarkDataIsStale: &isStale)
        } catch { print("[Export] 书签解析异常: \(error.localizedDescription)") } }
        if targetFolderURL == nil { var cleanPath = folderPath; if cleanPath.hasPrefix("file://") { cleanPath = cleanPath.replacingOccurrences(of: "file://", with: "") }; cleanPath = cleanPath.removingPercentEncoding ?? cleanPath; targetFolderURL = URL(fileURLWithPath: cleanPath) }
        guard let folderURL = targetFolderURL else { return "导出失败：无效的保存路径" }
        isSecurelyAccessed = folderURL.startAccessingSecurityScopedResource()
        defer { if isSecurelyAccessed { folderURL.stopAccessingSecurityScopedResource() } }
        let printFormatter = UISimpleTextPrintFormatter(attributedText: attributedText); let renderer = UIPrintPageRenderer(); renderer.addPrintFormatter(printFormatter, startingAtPageAt: 0)
        let pageSize = CGSize(width: 595.2, height: 841.8); let pageRect = CGRect(x: 0, y: 0, width: pageSize.width, height: pageSize.height); let printableRect = pageRect.insetBy(dx: 40, dy: 40); renderer.setValue(NSValue(cgRect: pageRect), forKey: "paperRect"); renderer.setValue(NSValue(cgRect: printableRect), forKey: "printableRect")
        let pdfData = NSMutableData(); UIGraphicsBeginPDFContextToData(pdfData, pageRect, nil); for i in 0..<renderer.numberOfPages { UIGraphicsBeginPDFPage(); renderer.drawPage(at: i, in: UIGraphicsGetPDFContextBounds()) }; UIGraphicsEndPDFContext()
        let destURL = folderURL.appendingPathComponent("\(title).pdf")
        do { if !FileManager.default.fileExists(atPath: folderURL.path) { try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true) }; if FileManager.default.fileExists(atPath: destURL.path) { try FileManager.default.removeItem(at: destURL) }; try pdfData.write(to: destURL, options: .atomic); return nil } catch { return "物理写入失败: \(error.localizedDescription)" }
        #endif
    }
    
    func generatePDFFromRichText(attributedText: NSAttributedString, title: String) -> URL? {
        #if os(macOS)
        guard let pdfData = generateMacPDFData(from: attributedText) else { return nil }
        let fileName = "\(title).pdf"
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName)
        try? pdfData.write(to: url, options: .atomic)
        return url
        #else
        let printFormatter = UISimpleTextPrintFormatter(attributedText: attributedText); let renderer = UIPrintPageRenderer(); renderer.addPrintFormatter(printFormatter, startingAtPageAt: 0)
        let pageSize = CGSize(width: 595.2, height: 841.8); let pageRect = CGRect(x: 0, y: 0, width: pageSize.width, height: pageSize.height); let printableRect = pageRect.insetBy(dx: 40, dy: 40); renderer.setValue(NSValue(cgRect: pageRect), forKey: "paperRect"); renderer.setValue(NSValue(cgRect: printableRect), forKey: "printableRect")
        let pdfData = NSMutableData(); UIGraphicsBeginPDFContextToData(pdfData, pageRect, nil); for i in 0..<renderer.numberOfPages { UIGraphicsBeginPDFPage(); renderer.drawPage(at: i, in: UIGraphicsGetPDFContextBounds()) }; UIGraphicsEndPDFContext()
        let fileName = "\(title).pdf"; let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName); try? pdfData.write(to: url); return url
        #endif
    }
    
    func generatePDF(text: String, title: String) -> URL? {
        let attributedString = renderMarkdownAttributedStringForExport(text: text, isDark: false)
        return generatePDFFromRichText(attributedText: attributedString, title: title)
    }
}

// MARK: - ArchiveStore Part 7-2 - v28 - Markdown解析与图像导出 (下) - 适配 macOS
//
// extension ArchiveStore
// (修改：
//  1. 承接 Part 7-1，保留样式加载、Markdown 语法解析及纯文本属性处理。
//  2. 对 generateImage 中依赖 UITextView 与 UIGraphicsImageRenderer 的部分施加 #if !os(macOS) 屏蔽。)

extension ArchiveStore {

    func loadMarkdownStyle() -> MarkdownGlobalStyle { if let data = UserDefaults.standard.data(forKey: "global_markdown_style"), let style = try? JSONDecoder().decode(MarkdownGlobalStyle.self, from: data) { return style }; return MarkdownGlobalStyle() }
    func saveMarkdownStyle(_ style: MarkdownGlobalStyle) { if let data = try? JSONEncoder().encode(style) { UserDefaults.standard.set(data, forKey: "global_markdown_style"); objectWillChange.send() } }
    func loadMarkdownSettings() -> MarkdownViewSettings { if let data = UserDefaults.standard.data(forKey: "global_markdown_view_settings"), let settings = try? JSONDecoder().decode(MarkdownViewSettings.self, from: data) { return settings }; return MarkdownViewSettings() }
    func saveMarkdownSettings(_ settings: MarkdownViewSettings) { if let data = try? JSONEncoder().encode(settings) { UserDefaults.standard.set(data, forKey: "global_markdown_view_settings") } }
    func parseMarkdownStructure(content: String) ->[MDNode] { let pattern = "^(#{1,6})\\s+(.*)$"; guard let regex = try? NSRegularExpression(pattern: pattern, options: .anchorsMatchLines) else { return[] }; let nsString = content as NSString; let range = NSRange(location: 0, length: nsString.length); let matches = regex.matches(in: content, options: [], range: range); var roots:[MDNode] = []; var stack: [MDNode] = []; for match in matches { let hashRange = match.range(at: 1); let level = hashRange.length; let titleRange = match.range(at: 2); let title = nsString.substring(with: titleRange); let newNode = MDNode(title: title, level: level, rangeLocation: match.range.location, rangeLength: match.range.length); if stack.isEmpty { stack.append(newNode) } else { while let last = stack.last, last.level >= level { stack.removeLast() }; stack.append(newNode) }; roots.append(newNode) }; return roots }
    func wrapMarkdownContent(_ content: String) -> String { return content }
    func unwrapMarkdownContent(_ json: String) -> String { if let d = json.data(using: .utf8), let data = try? JSONDecoder().decode(StandardRowData.self, from: d) { return data.content }; return json }
    
    private func renderMarkdownAttributedStringForExport(text: String, isDark: Bool) -> NSAttributedString {
        let style = loadMarkdownStyle()
        let lpStyle = LPGlobalStyle(
            h1: .init(size: style.h1.size, color: style.h1.color, isBold: style.h1.isBold, fontName: style.h1.fontName),
            h2: .init(size: style.h2.size, color: style.h2.color, isBold: style.h2.isBold, fontName: style.h2.fontName),
            h3: .init(size: style.h3.size, color: style.h3.color, isBold: style.h3.isBold, fontName: style.h3.fontName),
            h4: .init(size: style.h4.size, color: style.h4.color, isBold: style.h4.isBold, fontName: style.h4.fontName),
            h5: .init(size: style.h5.size, color: style.h5.color, isBold: style.h5.isBold, fontName: style.h5.fontName),
            h6: .init(size: style.h6.size, color: style.h6.color, isBold: style.h6.isBold, fontName: style.h6.fontName),
            body: .init(size: style.body.size, color: style.body.color, isBold: style.body.isBold, fontName: style.body.fontName),
            quote: .init(size: style.quote.size, color: style.quote.color, isBold: style.quote.isBold, fontName: style.quote.fontName)
        )
        return LPRenderer.renderFullDocumentForPDF(text: text, style: lpStyle, isDark: isDark)
    }
    
    @MainActor func generateImage(text: String, title: String) -> URL? {
        let isDark = loadMarkdownSettings().isDarkMode
        let attributedString = renderMarkdownAttributedStringForExport(text: text, isDark: isDark)
        #if os(macOS)
        let width: CGFloat = 600
        let horizontalInset: CGFloat = 20
        let verticalInset: CGFloat = 30
        let contentWidth = width - (horizontalInset * 2)

        let textStorage = NSTextStorage(attributedString: attributedString)
        let layoutManager = NSLayoutManager()
        let textContainer = NSTextContainer(size: CGSize(width: contentWidth, height: .greatestFiniteMagnitude))
        textContainer.widthTracksTextView = false
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 0
        layoutManager.addTextContainer(textContainer)
        textStorage.addLayoutManager(layoutManager)
        layoutManager.ensureLayout(for: textContainer)

        let usedRect = layoutManager.usedRect(for: textContainer)
        let height = max(ceil(usedRect.height) + verticalInset * 2, 120)

        let textView = NSTextView(frame: CGRect(x: horizontalInset, y: verticalInset, width: contentWidth, height: ceil(usedRect.height)), textContainer: textContainer)
        textView.isEditable = false
        textView.isSelectable = false
        textView.drawsBackground = false
        textView.textContainerInset = .zero
        textView.textContainer?.lineFragmentPadding = 0

        let containerView = NSView(frame: CGRect(x: 0, y: 0, width: width, height: height))
        containerView.wantsLayer = true
        containerView.layer?.backgroundColor = (isDark ? NSColor.black : NSColor.white).cgColor
        containerView.addSubview(textView)

        guard let rep = containerView.bitmapImageRepForCachingDisplay(in: containerView.bounds) else { return nil }
        containerView.cacheDisplay(in: containerView.bounds, to: rep)
        guard let data = rep.representation(using: .png, properties: [:]) else { return nil }

        let fileName = "\(title).png"
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName)
        try? data.write(to: url, options: .atomic)
        return url
        #else
        let textView = UITextView(); textView.attributedText = attributedString; textView.backgroundColor = isDark ? .black : .white; let width: CGFloat = 600; let size = textView.sizeThatFits(CGSize(width: width, height: .greatestFiniteMagnitude)); let height = size.height + 60; textView.frame = CGRect(x: 0, y: 0, width: width, height: height); textView.textContainerInset = UIEdgeInsets(top: 30, left: 20, bottom: 30, right: 20); let renderer = UIGraphicsImageRenderer(size: CGSize(width: width, height: height)); let image = renderer.image { context in textView.layer.render(in: context.cgContext) }; let fileName = "\(title).png"; let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName); if let data = image.pngData() { try? data.write(to: url); return url }; return nil
        #endif
    }
    
    private func getExportFont(style: MarkdownGlobalStyle.TextStyle) -> UIFont {
        let size = style.size
        let weight: UIFont.Weight = style.isBold ? .bold : .regular

        #if os(macOS)
        func fontFromDescriptor(_ descriptor: UIFontDescriptor) -> UIFont {
            UIFont(descriptor: descriptor, size: size) ?? UIFont.systemFont(ofSize: size, weight: weight)
        }

        switch style.fontName {
        case "system_default", "system":
            return UIFont.systemFont(ofSize: size, weight: weight)
        case "system_serif", "serif":
            return UIFont.systemFont(ofSize: size, weight: weight)
        case "system_mono", "mono":
            return UIFont.monospacedSystemFont(ofSize: size, weight: weight)
        case "system_rounded", "rounded":
            return UIFont.systemFont(ofSize: size, weight: weight)
        default:
            if let customFont = UIFont(name: style.fontName, size: size) {
                let descriptor = customFont.fontDescriptor
                if style.isBold {
                    let boldDesc = descriptor.withSymbolicTraits(.traitBold)
                    return fontFromDescriptor(boldDesc)
                }
                return customFont
            } else {
                let descriptor = UIFontDescriptor().withFamily(style.fontName)
                if style.isBold {
                    let boldDesc = descriptor.withSymbolicTraits(.traitBold)
                    return fontFromDescriptor(boldDesc)
                }
                return fontFromDescriptor(descriptor)
            }
        }
        #else
        switch style.fontName {
        case "system_default", "system":
            return UIFont.systemFont(ofSize: size, weight: weight)
        case "system_serif", "serif":
            return UIFont.systemFont(ofSize: size, weight: weight).with(design: .serif) ?? UIFont.systemFont(ofSize: size, weight: weight)
        case "system_mono", "mono":
            return UIFont.monospacedSystemFont(ofSize: size, weight: weight)
        case "system_rounded", "rounded":
            return UIFont.systemFont(ofSize: size, weight: weight).with(design: .rounded) ?? UIFont.systemFont(ofSize: size, weight: weight)
        default:
            if let customFont = UIFont(name: style.fontName, size: size) {
                let descriptor = customFont.fontDescriptor
                if style.isBold, let boldDesc = descriptor.withSymbolicTraits(.traitBold) {
                    return UIFont(descriptor: boldDesc, size: size)
                }
                return customFont
            } else {
                let descriptor = UIFontDescriptor().withFamily(style.fontName)
                if style.isBold, let boldDesc = descriptor.withSymbolicTraits(.traitBold) {
                    return UIFont(descriptor: boldDesc, size: size)
                }
                return UIFont(descriptor: descriptor, size: size)
            }
        }
        #endif
    }
    
    private func getExportColor(hex: String) -> UIColor { switch hex { case "black": return .black; case "white": return .white; case "gray": return .gray; case "red": return .systemRed; case "orange": return .systemOrange; case "yellow": return .systemYellow; case "green": return .systemGreen; case "blue": return .systemBlue; case "purple": return .systemPurple; case "cyan": return .systemCyan; default: return .black } }
}

// MARK: - ArchiveStore Part 9 - v47 - 物理加固开课日期强制注入逻辑

extension ArchiveStore {
    
    enum PrepareClassResult {
        case success(journal: ArchiveTable, focusID: UUID?)
        case feedbackSourceMissing
    }

    func reconcileStudentChecklists(studentName: String, studentCatID: UUID, planNames: [String]) {
        lock.lock(); defer { lock.unlock() }
        guard let catIdx = categories.firstIndex(where: { $0.id == studentCatID }) else { return }
        for plan in planNames {
            guard let templateIndex = lessonPlanTemplateIndex(for: plan) else { continue }
            let planTemplate = templates[templateIndex]
            let listName = "教案_\(plan)_完成情况_\(studentName)"
            if let tableIdx = categories[catIdx].tables.firstIndex(where: { $0.title == listName }) {
                var table = categories[catIdx].tables[tableIdx]
                table.templateID = planTemplate.id
                table.rows = castNewRowsFromTemplate(oldRows: table.rows, templateRows: planTemplate.taskRows)
                categories[catIdx].tables[tableIdx] = table
                saveTableToFile(table, categoryTitle: studentName)
            } else {
                var newTable = ArchiveTable(
                    id: UUID(),
                    title: listName,
                    rows: [],
                    templateID: planTemplate.id,
                    type: .taskList
                )
                newTable.rows = castNewRowsFromTemplate(oldRows: [], templateRows: planTemplate.taskRows)
                categories[catIdx].tables.insert(newTable, at: 0)
                saveTableToFile(newTable, categoryTitle: studentName)
            }
        }
        DispatchQueue.main.async { self.objectWillChange.send() }
    }

    func extractContentFromMaster(compositePath: String, sourceID: UUID) -> [LPRowNode] {
        let rootURL: URL = compositePath.contains("上课收集") ? CloudFileManager.shared.getCloudDir(.tables) : CloudFileManager.shared.getCloudDir(.lessonPlans)
        let fileURL = rootURL.appendingPathComponent(compositePath)
        guard fm.fileExists(atPath: fileURL.path) else { return [] }
        let nodes = loadLessonPlanNodes(from: fileURL)
        var packet: [LPRowNode] = []; var isExtracting = false
        for node in nodes {
            if node.id == sourceID && node.type == .h3 { isExtracting = true; var firstNode = node; firstNode.sourceNodeID = node.id; firstNode.sourceFileName = compositePath; packet.append(firstNode); continue }
            if isExtracting && [.h1, .h2, .h3].contains(node.type) { break }
            if isExtracting { var contentNode = node; contentNode.sourceNodeID = node.id; contentNode.sourceFileName = compositePath; packet.append(contentNode) }
        }
        return packet
    }
    
    private func resolveMasterPacketForTeachingSync(h3Node: LPRowNode, planNames: [String]) -> (packet: [LPRowNode], anchorKey: String)? {
        let candidateIDs = [h3Node.sourceNodeID, h3Node.id].compactMap { $0 }
        guard !candidateIDs.isEmpty else { return nil }
        
        if let compositePath = h3Node.sourceFileName,
           !compositePath.contains("上课收集"),
           let sourceID = h3Node.sourceNodeID {
            let directPacket = extractContentFromMaster(compositePath: compositePath, sourceID: sourceID)
            if !directPacket.isEmpty {
                return (directPacket, "\(sourceID.uuidString)|\(compositePath)")
            }
        }
        
        for item in getAllMasterFiles(planNames: planNames) {
            let compositePath = "\(item.planName)/\(item.fileURL.lastPathComponent)"
            let masterNodes = loadLessonPlanNodes(from: item.fileURL)
            for candidateID in candidateIDs {
                if let node = masterNodes.first(where: { $0.id == candidateID && $0.type == .h3 }) {
                    let packet = extractContentFromMaster(compositePath: compositePath, sourceID: node.id)
                    if !packet.isEmpty {
                        return (packet, "\(node.id.uuidString)|\(compositePath)")
                    }
                }
            }
        }
        
        return nil
    }

    func syncLessonPlanContent(folderName: String) {
        let folderURL = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(folderName)
        Task {
            guard let files = try? fm.contentsOfDirectory(at: folderURL, includingPropertiesForKeys: nil, options: .skipsHiddenFiles) else { return }
            let sortedFiles = files.filter { $0.pathExtension == "csv" }.sorted { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }
            var newTemplateRows: [ArchiveRow] = []
            for file in sortedFiles {
                let compositePath = "\(folderName)/\(file.lastPathComponent)"
                let masterNodes = loadLessonPlanNodes(from: file)
                for node in masterNodes {
                    let lvl: Int? = {
                        switch node.type {
                        case .h1: return 0; case .h2: return 1; case .h3: return 2; default: return nil
                        }
                    }()
                    if let l = lvl {
                        let data = TaskRowData(title: node.content, isCompleted: false, level: l, sourceID: node.id, sourceFile: compositePath)
                        if let enc = try? JSONEncoder().encode(data), let s = String(data: enc, encoding: .utf8) {
                            newTemplateRows.append(ArchiveRow(id: UUID(), key: node.id.uuidString, value: s))
                        }
                    }
                }
            }
            await MainActor.run {
                self.lock.lock()
                defer { self.lock.unlock() }
                let templateTitle = "教案_\(folderName)"
                if let idx = self.lessonPlanTemplateIndex(for: folderName) {
                    self.templates[idx].title = templateTitle
                    self.templates[idx].taskRows = newTemplateRows
                    let tid = self.templates[idx].id
                    self.saveTemplates()
                    self.syncAllInstancesToTemplate(templateID: tid)
                } else {
                    let nt = ArchiveTemplate(id: UUID(), title: templateTitle, keys: [], type: .taskList, taskRows: newTemplateRows)
                    self.templates.append(nt)
                    self.saveTemplates()
                }
                self.objectWillChange.send()
            }
        }
    }

    /// 仅准备随堂笔记。课反表改为首次打开课反时再生成。
    func prepareClassFiles(studentName: String, catID: UUID, feedbackSourceID: UUID?) -> PrepareClassResult {
        lock.lock(); defer { lock.unlock() }
        let jName = "随堂笔记_\(studentName).csv"
        let jURL = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName).appendingPathComponent(jName)
        guard var journal = getOrCreateLessonJournal(studentName: studentName, studentCategoryID: catID) else { return .feedbackSourceMissing }
        var nodes = loadLessonPlanNodes(from: jURL)
        let df = DateFormatter(); df.dateFormat = "yyMMdd"; let ds = df.string(from: Date())
        let lastH1 = nodes.last(where: { $0.type == .h1 })
        if lastH1?.content != ds {
            nodes.append(LPRowNode(id: UUID(), type: .h1, content: ds))
            let newCSV = generateLessonPlanCSV(from: nodes)
            try? newCSV.write(to: jURL, atomically: true, encoding: .utf8)
            if let firstRowIdx = journal.rows.firstIndex(where: { $0.key == "content" }) {
                journal.rows[firstRowIdx].value = wrapMarkdownContent(newCSV)
                if let ci = categories.firstIndex(where: { $0.id == catID }),
                   let ti = categories[ci].tables.firstIndex(where: { $0.id == journal.id }) { categories[ci].tables[ti] = journal }
            }
        }
        return .success(journal: journal, focusID: nil)
    }

    func ensureTodayFeedbackTable(studentName: String, catID: UUID, feedbackSourceID: UUID?) -> ArchiveTable? {
        lock.lock(); defer { lock.unlock() }
        let df = DateFormatter(); df.dateFormat = "yyMMdd"; let ds = df.string(from: Date())
        guard let sourceID = feedbackSourceID,
              let sourceTable = getTable(by: sourceID),
              let catIdx = categories.firstIndex(where: { $0.id == catID }) else { return nil }

        let targetTitle = "\(sourceTable.title)_\(ds)"
        if let existingIndex = categories[catIdx].tables.firstIndex(where: { $0.title == targetTitle && !$0.title.contains("_旧") }) {
            return categories[catIdx].tables[existingIndex]
        }

        var targetTable = sourceTable
        targetTable.id = UUID()
        targetTable.title = targetTitle
        targetTable.createdAt = Date()

        if let config = TeachingStore.shared.getStudentConfig(studentName),
           let dateKey = config.feedbackDateRowKey {
            for rowIndex in targetTable.rows.indices where targetTable.rows[rowIndex].key == dateKey {
                let currentVal = targetTable.rows[rowIndex].value
                var title = dateKey
                if let data = currentVal.data(using: .utf8),
                   let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) {
                    title = decoded.title
                }
                let newRowObj = StandardRowData(title: title, content: ds)
                if let encoded = try? JSONEncoder().encode(newRowObj),
                   let s = String(data: encoded, encoding: .utf8) {
                    targetTable.rows[rowIndex].value = s
                }
            }
        }

        categories[catIdx].tables.insert(targetTable, at: 0)
        saveTableToFile(targetTable, categoryTitle: studentName)
        clearSmartCache()
        return targetTable
    }

    func appendFeedbackText(studentName: String, studentCatID: UUID, keys: [String], textToAppend: String) { lock.lock(); defer { lock.unlock() }; let df = DateFormatter(); df.dateFormat = "yyMMdd"; let ds = df.string(from: Date()); guard let catIdx = categories.firstIndex(where: { $0.id == studentCatID }) else { return }; if let tableIdx = categories[catIdx].tables.firstIndex(where: { $0.title.hasSuffix("_\(ds)") && !$0.title.contains("_旧") }) { var table = categories[catIdx].tables[tableIdx]; var hasChanged = false; for key in keys { if let rowIndex = table.rows.firstIndex(where: { $0.key == key }) { let rowValue = table.rows[rowIndex].value; var content = ""; if let data = rowValue.data(using: .utf8), let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) { content = decoded.content; let separator = content.isEmpty ? "" : (content.hasSuffix("\n") ? "" : "\n"); let newContent = content + separator + textToAppend; let newRowObj = StandardRowData(title: decoded.title, content: newContent); if let encoded = try? JSONEncoder().encode(newRowObj), let s = String(data: encoded, encoding: .utf8) { table.rows[rowIndex].value = s; hasChanged = true } } } } ; if hasChanged { categories[catIdx].tables[tableIdx] = table; saveTableToFile(table, categoryTitle: categories[catIdx].title) } } }
    func importMarkdownToLessonPlan(url: URL, folderName: String) { guard url.startAccessingSecurityScopedResource() else { return }; defer { url.stopAccessingSecurityScopedResource() }; guard let content = try? String(contentsOf: url, encoding: .utf8) else { return }; let rawLines = content.components(separatedBy: .newlines); var nodes: [LPRowNode] = []; for line in rawLines { var proc = line.trimmingCharacters(in: .whitespaces); if proc.isEmpty { continue }; proc = proc.replacingOccurrences(of: #"\s*\[(.*?)\]\{.mark\}"#, with: "<mark>$1</mark>", options: .regularExpression); proc = proc.replacingOccurrences(of: #"\s*\[(.*?)\]\.?\{underline\}"#, with: "<u>$1</u>", options: .regularExpression); var nType: LPNodeType = .l1; var fCont = proc; if proc.hasPrefix("#######") { let hashCount = proc.prefix(while: { $0 == "#" }).count; let textPart = String(proc.dropFirst(hashCount)).trimmingCharacters(in: .whitespaces); switch hashCount { case 7: nType = .l1; case 8: nType = .l2; case 9: nType = .l3; case 10: nType = .l4; default: nType = .l5 }; fCont = textPart } else { let hPrefixes = ["###### ", "##### ", "#### ", "### ", "## ", "# ", "> "]; var foundH = false; for p in hPrefixes { if proc.hasPrefix(p) { nType = LPNodeType.from(prefix: p, content: ""); fCont = String(proc.dropFirst(p.count)); foundH = true; break } }; if !foundH { if proc.trimmingCharacters(in: CharacterSet(charactersIn: " ")).hasPrefix("- ") { let spaceCount = proc.prefix(while: { $0 == " " }).count; nType = (spaceCount >= 8 ? .l5 : (spaceCount >= 6 ? .l4 : (spaceCount >= 4 ? .l3 : (spaceCount >= 2 ? .l2 : .l1)))); fCont = proc.trimmingCharacters(in: .whitespaces).dropFirst(2).description } else { nType = .l1; fCont = proc } } }; if [LPNodeType.h1, .h2, .h3, .h4, .h5, .h6].contains(nType) && fCont.isEmpty { continue }; nodes.append(LPRowNode(id: UUID(), type: nType, content: fCont)) }; let csvString = generateLessonPlanCSV(from: nodes); let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(folderName); try? csvString.write(to: root.appendingPathComponent("\(url.lastPathComponent.replacingOccurrences(of: ".md", with: "")).csv"), atomically: true, encoding: .utf8); DispatchQueue.main.async { self.syncLessonPlanContent(folderName: folderName) } }
    func generateLessonPlanCSV(from nodes: [LPRowNode]) -> String { var csv = "\u{FEFF}UUID,Prefix,Content,SourceID,SourceFile\n"; for node in nodes { csv += "\(node.id.uuidString),\(node.type.csvPrefix),\(escapeCSVField(node.content)),\(node.sourceNodeID?.uuidString ?? ""),\(node.sourceFileName ?? "")\n" }; return csv }
    func parseLessonPlanCSV(_ csv: String) -> [LPRowNode] { var nodes: [LPRowNode] = []; let lines = csv.components(separatedBy: .newlines); for line in lines { let cols = parseCSVRow(line); if cols.count >= 3 { let uStr = cols[0].trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "\u{FEFF}", with: ""); if uStr == "UUID" || uStr.isEmpty { continue }; if let uid = UUID(uuidString: uStr) { let pref = cols[1]; let cont = cols[2].replacingOccurrences(of: "{{BR}}", with: "\n").replacingOccurrences(of: "{{TAB}}", with: "\t"); var sid: UUID? = nil; if cols.count >= 4 { let sidStr = cols[3].trimmingCharacters(in: .whitespacesAndNewlines); if !sidStr.isEmpty { sid = UUID(uuidString: sidStr) } }; var sfile: String? = nil; if cols.count >= 5 { let sfStr = cols[4].trimmingCharacters(in: .whitespacesAndNewlines); if !sfStr.isEmpty { sfile = sfStr } }; nodes.append(LPRowNode(id: uid, type: LPNodeType.from(prefix: pref, content: cont), content: cont, sourceNodeID: sid, sourceFileName: sfile)) } } }; return nodes }
    func saveLessonPlanCSVToFile(_ csv: String, categoryTitle: String, fileName: String) { if let d = csv.data(using: .utf8) { CloudSyncManager.shared.ignoreNextUpdate(relativePath: "表格/\(categoryTitle)/\(fileName)"); CloudFileManager.shared.saveDual(data: d, folder: .tables, fileName: "\(categoryTitle)/\(fileName)") } }
    func loadLessonPlanNodes(from url: URL) -> [LPRowNode] { if let content = try? String(contentsOf: url, encoding: .utf8) { return parseLessonPlanCSV(content) }; return [] }
    func getOrCreateLessonJournal(studentName: String, studentCategoryID: UUID) -> ArchiveTable? { lock.lock(); defer { lock.unlock() }; let studentFolder = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName); try? fm.createDirectory(at: studentFolder, withIntermediateDirectories: true); guard let catIdx = categories.firstIndex(where: { $0.id == studentCategoryID }) else { return nil }; let catTitle = categories[catIdx].title; let targetTitle = "随堂笔记_\(studentName)"; if let existingTable = categories[catIdx].tables.first(where: { $0.title == targetTitle }) { return existingTable }; let emptyCSV = generateLessonPlanCSV(from: []); let row = ArchiveRow(key: "content", value: wrapMarkdownContent(emptyCSV)); let newJournal = ArchiveTable(id: UUID(), title: targetTitle, rows: [row], templateID: nil, type: .markdown); categories[catIdx].tables.insert(newJournal, at: 0); saveLessonPlanCSVToFile(emptyCSV, categoryTitle: catTitle, fileName: "\(targetTitle).csv"); clearSmartCache(); DispatchQueue.main.async { self.objectWillChange.send() }; return newJournal }
}

// MARK: - ArchiveStore Part 10 - v21 - 内容晋升引擎：实现 ID 继承与收集站物理清理

extension ArchiveStore {
    
    func getAllMasterFiles(planNames: [String]) -> [(planName: String, fileURL: URL)] {
        var results: [(planName: String, fileURL: URL)] = []
        for plan in planNames {
            let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(plan)
            if !fm.fileExists(atPath: root.path) { try? fm.createDirectory(at: root, withIntermediateDirectories: true) }
            if let files = try? fm.contentsOfDirectory(at: root, includingPropertiesForKeys: nil, options: .skipsHiddenFiles) {
                for fileURL in files where fileURL.pathExtension == "csv" { results.append((planName: plan, fileURL: fileURL)) }
            }
        }
        return results.sorted(by: { $0.fileURL.lastPathComponent < $1.fileURL.lastPathComponent })
    }

    func updateMasterPacket(planNames: [String], newNodes: [LPRowNode]) -> [UUID: UUID]? {
        lock.lock(); defer { lock.unlock() }
        guard let firstNode = newNodes.first, let anchorMasterID = firstNode.sourceNodeID else { return nil }
        var targetFileURL: URL? = nil
        let compositePath = firstNode.sourceFileName ?? ""
        if compositePath.contains("上课收集") {
            let harvestURL = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(compositePath)
            if fm.fileExists(atPath: harvestURL.path) { targetFileURL = harvestURL }
        }
        if targetFileURL == nil && !compositePath.isEmpty {
            let potentialURL = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(compositePath)
            if fm.fileExists(atPath: potentialURL.path) { targetFileURL = potentialURL }
        }
        if targetFileURL == nil {
            let allFiles = getAllMasterFiles(planNames: planNames)
            for item in allFiles { let mNodes = loadLessonPlanNodes(from: item.fileURL); if mNodes.contains(where: { $0.id == anchorMasterID }) { targetFileURL = item.fileURL; break } }
        }
        guard let finalURL = targetFileURL else { return nil }
        var masterNodes = loadLessonPlanNodes(from: finalURL); var idMapping: [UUID: UUID] = [:]
        if let startIdx = masterNodes.firstIndex(where: { $0.id == anchorMasterID }) {
            var endIdx = startIdx; for i in (startIdx + 1)..<masterNodes.count { if [LPNodeType.h1, .h2, .h3].contains(masterNodes[i].type) { break }; endIdx = i }
            let nodesToInsertInMaster = newNodes.map { n -> LPRowNode in
                var updated = n; if n.type == .h3 { updated.id = anchorMasterID } else { updated.id = n.id }
                updated.sourceNodeID = nil; updated.sourceFileName = nil; idMapping[n.id] = updated.id; return updated
            }
            masterNodes.removeSubrange(startIdx...endIdx); masterNodes.insert(contentsOf: nodesToInsertInMaster, at: startIdx)
            let newCSV = generateLessonPlanCSV(from: masterNodes)
            do {
                try newCSV.write(to: finalURL, atomically: true, encoding: .utf8)
                let planFolderName = finalURL.deletingLastPathComponent().lastPathComponent
                if planFolderName != "教案" && planFolderName != "LessonPlans" && planFolderName != "Documents" { self.syncLessonPlanContent(folderName: planFolderName) }
                return idMapping
            } catch { return nil }
        }
        return nil
    }

    /// 【252号核心修改】：晋升收集站内容至母本（保持 ID，清理收集站）
    func promotePacketsToMasterFile(targetFileURL: URL, planName: String, packets: [[LPRowNode]]) -> (mapping: [UUID: UUID], path: String) {
        lock.lock(); defer { lock.unlock() }
        var masterNodes = loadLessonPlanNodes(from: targetFileURL); var idMapping: [UUID: UUID] = [:]
        
        let compositePath = "\(planName)/\(targetFileURL.lastPathComponent)"
        
        for packet in packets {
            // 判定来源是否为收集站
            let isFromHarvest = packet.first?.sourceFileName?.contains("上课收集") ?? false
            
            let nodesToInsert = packet.map { n -> LPRowNode in
                // 【核心要求】：保持 H3 包内所有节点的 UUID 不变
                let persistentID = n.id
                idMapping[n.id] = persistentID
                
                var updated = n
                updated.id = persistentID
                updated.sourceNodeID = nil
                updated.sourceFileName = nil
                return updated
            }
            masterNodes.append(contentsOf: nodesToInsert)
            
            // 【核心要求】：如果是从收集站晋升的，物理删除收集站中的原包
            if isFromHarvest {
                deleteFromHarvestFile(nodesToRemove: packet)
            }
        }
        
        let newCSV = generateLessonPlanCSV(from: masterNodes)
        try? newCSV.write(to: targetFileURL, atomically: true, encoding: .utf8)
        
        // 晋升完成后立即刷新母本清单模板
        self.syncLessonPlanContent(folderName: planName)
        
        return (idMapping, compositePath)
    }

    /// 【252号新增】：物理删除收集站内容
    private func deleteFromHarvestFile(nodesToRemove: [LPRowNode]) {
        let harvestDir = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent("上课收集")
        let harvestFile = harvestDir.appendingPathComponent("上课收集.csv")
        guard fm.fileExists(atPath: harvestFile.path) else { return }
        
        var currentHarvestNodes = loadLessonPlanNodes(from: harvestFile)
        let idsToRemove = Set(nodesToRemove.map { $0.id })
        
        // 物理过滤并写回
        currentHarvestNodes.removeAll { idsToRemove.contains($0.id) }
        let newHarvestCSV = generateLessonPlanCSV(from: currentHarvestNodes)
        try? newHarvestCSV.write(to: harvestFile, atomically: true, encoding: .utf8)
        print("[Harvest] 物理删除已晋升章节，收集站剩余节点: \(currentHarvestNodes.count)")
    }
}

// MARK: - ArchiveStore Part 11 - v38 - 移除下课冗余日期逻辑，优化同步收口流程

extension ArchiveStore {
    
    /// 【305号新增】：物理重置清单勾选状态
    func resetChecklistItem(sourceID: UUID, sourceFile: String, studentName: String) {
        lock.lock(); defer { lock.unlock() }
        guard let catIdx = categories.firstIndex(where: { $0.title == studentName }) else { return }
        for tableIdx in categories[catIdx].tables.indices {
            var table = categories[catIdx].tables[tableIdx]
            if table.title.contains("_完成情况_") {
                var tableChanged = false
                for rowIndex in table.rows.indices {
                    if let taskData = parseTaskData(table.rows[rowIndex].value),
                       taskData.sourceID == sourceID,
                       taskData.sourceFile == sourceFile {
                        var mod = taskData
                        mod.isCompleted = false
                        if let json = try? JSONEncoder().encode(mod), let s = String(data: json, encoding: .utf8) {
                            table.rows[rowIndex].value = s
                            tableChanged = true
                        }
                    }
                }
                if tableChanged {
                    categories[catIdx].tables[tableIdx] = table
                    saveTableToFile(table, categoryTitle: studentName)
                }
            }
        }
        DispatchQueue.main.async { self.objectWillChange.send() }
    }

    func analyzeSyncStats(package: TeachingStore.SyncPackage) -> TeachingStore.SyncDebugInfo {
        var info = TeachingStore.SyncDebugInfo(); guard let content = try? String(contentsOf: package.journalURL, encoding: .utf8) else { return info }; let currentJournalNodes = parseLessonPlanCSV(content)
        var affectedFiles = Set<String>(); for id in package.dirtyIDs { if let node = currentJournalNodes.first(where: { $0.id == id }), let fname = node.sourceFileName { affectedFiles.insert(fname) } }
        info.dirtyPacketCount = package.dirtyIDs.count; info.chapterFileCount = affectedFiles.count; info.preparedWriteCount = package.dirtyIDs.count; info.isWriteSuccessful = false; return info
    }

    /// 【360号物理修正】：执行下课同步，已移除 redundancy 的日期覆盖逻辑
    func performEndOfClassFinalSync(package: TeachingStore.SyncPackage, catID: UUID) -> String {
        lock.lock(); defer { lock.unlock() }
        let planNames = package.planNames; let journalURL = package.journalURL; let dirtyIDs = package.dirtyIDs; let affectedSourceIDs = package.affectedSourceIDs; let studentName = package.studentName
        
        // 【360号删除点】：此处不再调用 overwriteFeedbackDate，日期已在上课时筹备完毕
        
        guard let content = try? String(contentsOf: journalURL, encoding: .utf8) else { return "" }
        let currentJournalNodes = parseLessonPlanCSV(content)
        var finalNodes = currentJournalNodes.filter { n in let tr = n.content.trimmingCharacters(in: .whitespacesAndNewlines); return n.type == .h1 || tr == "---" || !tr.isEmpty }
        
        if !affectedSourceIDs.isEmpty { syncAffectedTitlesToAllStudentChecklists(affectedSourceIDs: affectedSourceIDs, planNames: planNames) }
        
        let aliveAnchors = Set(finalNodes.compactMap { n -> String? in guard n.type == .h3, let sid = n.sourceNodeID, let sfile = n.sourceFileName else { return nil }; return "\(sid.uuidString)|\(sfile)" })
        syncChecklistCompletion(studentName: studentName, catID: catID, aliveAnchors: aliveAnchors)
        
        harvestAndBackfillOriginalPackets(nodes: &finalNodes)
        let cleanedCSV = generateLessonPlanCSV(from: finalNodes); try? cleanedCSV.write(to: journalURL, atomically: true, encoding: .utf8)
        
        var needsFinalIdRewrite = false; var successCount = 0
        if package.isAutoMasterSyncEnabled && !dirtyIDs.isEmpty {
            for h3ID in dirtyIDs { if let packet = findPacketInNodes(nodes: finalNodes, h3ID: h3ID), packet.first?.sourceNodeID != nil { if let idMapping = self.updateMasterPacket(planNames: planNames, newNodes: packet) { successCount += 1; for k in finalNodes.indices { if let newMasterUUID = idMapping[finalNodes[k].id] { finalNodes[k].sourceNodeID = newMasterUUID; needsFinalIdRewrite = true } }; TeachingStore.shared.markPacketSynced(id: h3ID) } } }
        }
        
        DispatchQueue.main.async { var debugInfo = self.analyzeSyncStats(package: package); debugInfo.isWriteSuccessful = (package.isAutoMasterSyncEnabled ? (successCount == dirtyIDs.count) : false); TeachingStore.shared.lastSyncDebug = debugInfo }
        if needsFinalIdRewrite { let finalIdCSV = generateLessonPlanCSV(from: finalNodes); try? finalIdCSV.write(to: journalURL, atomically: true, encoding: .utf8) }
        DispatchQueue.main.async { self.loadDataFromFileSystem() }
        return finalNodes.map { "\($0.type.csvPrefix)\($0.content)" }.joined(separator: "\n")
    }

    private func syncChecklistCompletion(studentName: String, catID: UUID, aliveAnchors: Set<String>) { guard let catIdx = categories.firstIndex(where: { $0.id == catID }) else { return }; let tables = categories[catIdx].tables; for tableIdx in tables.indices { var table = tables[tableIdx]; if table.title.contains("_完成情况_") { var hasChanged = false; for rowIndex in table.rows.indices { let row = table.rows[rowIndex]; if let taskData = parseTaskData(row.value), let sID = taskData.sourceID, let sFile = taskData.sourceFile { let anchorKey = "\(sID.uuidString)|\(sFile)"; let shouldBeDone = aliveAnchors.contains(anchorKey); if taskData.isCompleted != shouldBeDone { var updatedData = taskData; updatedData.isCompleted = shouldBeDone; if let json = try? JSONEncoder().encode(updatedData), let s = String(data: json, encoding: .utf8) { table.rows[rowIndex].value = s; hasChanged = true } } } }; if hasChanged { categories[catIdx].tables[tableIdx] = table; saveTableToFile(table, categoryTitle: studentName) } } } }
    
    func performTeachingSync(studentName: String, catID: UUID, planNames: [String]) { lock.lock(); defer { lock.unlock() }; self.reconcileStudentChecklists(studentName: studentName, studentCatID: catID, planNames: planNames); let fileName = "随堂笔记_\(studentName).csv"; let journalURL = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName).appendingPathComponent(fileName); var aliveAnchors = Set<String>(); if let journalContent = try? String(contentsOf: journalURL, encoding: .utf8) { let journalNodes = parseLessonPlanCSV(journalContent); var refinedNodes: [LPRowNode] = []; var i = 0; while i < journalNodes.count { let node = journalNodes[i]; if node.type == .h3 { var eIdx = i; for j in (i + 1)..<journalNodes.count { if [.h1, .h2, .h3].contains(journalNodes[j].type) { break }; eIdx = j }; let currentPacketLength = eIdx - i + 1; if let resolved = resolveMasterPacketForTeachingSync(h3Node: node, planNames: planNames) { refinedNodes.append(contentsOf: resolved.packet); aliveAnchors.insert(resolved.anchorKey) } else if node.sourceNodeID != nil || node.sourceFileName != nil { for k in i...eIdx { var original = journalNodes[k]; original.sourceNodeID = nil; original.sourceFileName = nil; refinedNodes.append(original) } } else { for k in i...eIdx { refinedNodes.append(journalNodes[k]) } }; i += currentPacketLength } else { refinedNodes.append(node); i += 1 } }; let updatedCSV = generateLessonPlanCSV(from: refinedNodes); try? updatedCSV.write(to: journalURL, atomically: true, encoding: .utf8) }; syncChecklistCompletion(studentName: studentName, catID: catID, aliveAnchors: aliveAnchors); self.loadDataFromFileSystem(); NotificationCenter.default.post(name: NSNotification.Name("LPJournalPhysicallyUpdated"), object: nil) }
    func syncH3TitleToMasterAndTemplate(sourceNodeID: UUID, newTitle: String, planNames: [String]) { lock.lock(); defer { lock.unlock() }; for plan in planNames { let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(plan); guard let files = try? fm.contentsOfDirectory(at: root, includingPropertiesForKeys: nil, options: .skipsHiddenFiles) else { continue }; for fileURL in files where fileURL.pathExtension == "csv" { var masterNodes = loadLessonPlanNodes(from: fileURL); if let idx = masterNodes.firstIndex(where: { $0.id == sourceNodeID }) { masterNodes[idx].content = newTitle; let newCSV = generateLessonPlanCSV(from: masterNodes); try? newCSV.write(to: fileURL, atomically: true, encoding: .utf8); self.syncLessonPlanContent(folderName: plan) } } } }
    func harvestAndBackfillOriginalPackets(nodes: inout [LPRowNode]) { var packetsToHarvest: [LPRowNode] = []; let harvestCompositePath = "上课收集/上课收集.csv"; var i = 0; while i < nodes.count { let node = nodes[i]; let hasAnyAnchor = (node.sourceNodeID != nil || node.sourceFileName != nil); if node.type == .h3 && !hasAnyAnchor { var packet = [node]; var j = i + 1; while j < nodes.count { if [LPNodeType.h1, .h2, .h3].contains(nodes[j].type) { break }; packet.append(nodes[j]); j += 1 }; let cleanPacket = packet.map { n -> LPRowNode in var updated = n; updated.sourceNodeID = n.id; updated.sourceFileName = harvestCompositePath; return updated }; packetsToHarvest.append(contentsOf: cleanPacket); for k in i..<j { nodes[k].sourceNodeID = nodes[k].id; nodes[k].sourceFileName = harvestCompositePath }; i = j } else { i += 1 } }; guard !packetsToHarvest.isEmpty else { return }; let harvestDir = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent("上课收集"); let harvestFile = harvestDir.appendingPathComponent("上课收集.csv"); try? fm.createDirectory(at: harvestDir, withIntermediateDirectories: true); var existingNodes: [LPRowNode] = []; if fm.fileExists(atPath: harvestFile.path) { existingNodes = loadLessonPlanNodes(from: harvestFile) }; existingNodes.append(contentsOf: packetsToHarvest); let newHarvestCSV = generateLessonPlanCSV(from: existingNodes); try? newHarvestCSV.write(to: harvestFile, atomically: true, encoding: .utf8) }
    private func syncAffectedTitlesToAllStudentChecklists(affectedSourceIDs: Set<UUID>, planNames: [String]) { let affectedTemplateTitles = planNames.map { "教案_\($0)" }; let targetTemplates = templates.filter { t in affectedTemplateTitles.contains(where: { t.title.hasPrefix($0) }) }; for i in 0..<categories.count { for j in 0..<categories[i].tables.count { var table = categories[i].tables[j]; if let tID = table.templateID, targetTemplates.contains(where: { $0.id == tID }) { var tableChanged = false; for rowIndex in table.rows.indices { if let taskData = parseTaskData(table.rows[rowIndex].value), let sID = taskData.sourceID, affectedSourceIDs.contains(sID) { if let latestTitle = findTitleInMasters_Internal(planNames: planNames, sourceID: sID) { if taskData.title != latestTitle { var mod = taskData; mod.title = latestTitle; if let json = try? JSONEncoder().encode(mod), let s = String(data: json, encoding: .utf8) { table.rows[rowIndex].value = s; tableChanged = true } } } } }; if tableChanged { categories[i].tables[j] = table; saveTableToFile(table, categoryTitle: categories[i].title) } } } } }
    private func findTitleInMasters_Internal(planNames: [String], sourceID: UUID) -> String? { for plan in planNames { let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(plan); guard let files = try? fm.contentsOfDirectory(at: root, includingPropertiesForKeys: nil, options: .skipsHiddenFiles) else { continue }; for fileURL in files where fileURL.pathExtension == "csv" { let masterNodes = loadLessonPlanNodes(from: fileURL); if let node = masterNodes.first(where: { $0.id == sourceID }) { return node.content } } } ; return nil }
    private func findPacketInNodes(nodes: [LPRowNode], h3ID: UUID) -> [LPRowNode]? { guard let startIdx = nodes.firstIndex(where: { $0.id == h3ID }) else { return nil }; var packet = [nodes[startIdx]]; for j in (startIdx + 1)..<nodes.count { if [.h1, .h2, .h3].contains(nodes[j].type) { break }; packet.append(nodes[j]) }; return packet }
}

// MARK: - ArchiveStore Part 12 - v7 - 图片垃圾回收引擎适配震动反馈

extension ArchiveStore {
    
    /// 【260号修订】：图片垃圾回收引擎
    func performImageGarbageCollection() {
        lock.lock()
        defer { lock.unlock() }
        
        print("[GC] >>> 启动图片垃圾物理回收协议 <<<")
        
        let fm = FileManager.default
        let imageDir = CloudFileManager.shared.getCloudDir(.templates).appendingPathComponent("图片")
        let tablesDir = CloudFileManager.shared.getCloudDir(.tables)
        let lessonPlansDir = CloudFileManager.shared.getCloudDir(.lessonPlans)
        
        guard let allImageFiles = try? fm.contentsOfDirectory(at: imageDir, includingPropertiesForKeys: nil) else { return }
        
        var orphanedIDs = Set(allImageFiles.map { $0.lastPathComponent })
        var searchPaths:[URL] = []
        func collectCSV(in url: URL) {
            if let enumerator = fm.enumerator(at: url, includingPropertiesForKeys:[.isRegularFileKey], options:[.skipsHiddenFiles]) {
                for case let fileURL as URL in enumerator {
                    if fileURL.pathExtension.lowercased() == "csv" { searchPaths.append(fileURL) }
                }
            }
        }
        
        collectCSV(in: tablesDir)
        collectCSV(in: lessonPlansDir)
        
        var usedIDs = Set<String>()
        let pattern = #"(?i)asset:([\w\.-]+\.jpg)"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return }
        
        for path in searchPaths {
            if let content = try? String(contentsOf: path, encoding: .utf8) {
                let matches = regex.matches(in: content, range: NSRange(location: 0, length: content.utf16.count))
                for m in matches {
                    if let range = Range(m.range(at: 1), in: content) {
                        usedIDs.insert(String(content[range]))
                    }
                }
            }
        }
        
        orphanedIDs.subtract(usedIDs)
        
        var deletedCount = 0
        for id in orphanedIDs {
            MarkdownAssetManager.shared.deleteSingleAsset(assetID: id)
            deletedCount += 1
        }
        
        print("[GC] ✅ 回收完成。清理垃圾: \(deletedCount)")
        
        DispatchQueue.main.async {
            self.triggerHapticFeedback(style: 2) // Heavy
            self.triggerCollision("垃圾回收完成：清理 \(deletedCount) 张图片")
        }
    }

    func performImageMigration() {
        lock.lock(); defer { lock.unlock() }
        let oldSandboxDir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0].appendingPathComponent("MarkdownAssets")
        let targetDir = CloudFileManager.shared.getCloudDir(.templates).appendingPathComponent("图片")
        let targetMirrorDir = CloudFileManager.shared.getLocalMirrorDir(.templates).appendingPathComponent("图片")
        try? fm.createDirectory(at: targetDir, withIntermediateDirectories: true)
        try? fm.createDirectory(at: targetMirrorDir, withIntermediateDirectories: true)
        guard fm.fileExists(atPath: oldSandboxDir.path) else { return }
        do {
            let files = try fm.contentsOfDirectory(at: oldSandboxDir, includingPropertiesForKeys: nil)
            var count = 0
            for fileURL in files {
                let fileName = fileURL.lastPathComponent
                let destCloudURL = targetDir.appendingPathComponent(fileName)
                let destMirrorURL = targetMirrorDir.appendingPathComponent(fileName)
                if !fm.fileExists(atPath: destCloudURL.path) { try fm.copyItem(at: fileURL, to: destCloudURL) }
                if !fm.fileExists(atPath: destMirrorURL.path) { try fm.copyItem(at: fileURL, to: destMirrorURL) }
                count += 1
            }
            try fm.removeItem(at: oldSandboxDir)
            DispatchQueue.main.async {
                self.triggerHapticFeedback(style: 2) // Heavy
                self.triggerCollision("图片迁移完成：\(count) 项")
            }
        } catch { }
    }

    func performTemplateMigration() {
        lock.lock(); defer { lock.unlock() }
        let filesToMigrate = [templateFileName, smartViewFileName, unmatchedFileName, orderFileName]
        for fileName in filesToMigrate {
            if let data = CloudFileManager.shared.smartLoad(folder: .tables, fileName: fileName) {
                CloudFileManager.shared.saveDual(data: data, folder: .templates, fileName: fileName)
                let localOldURL = CloudFileManager.shared.getLocalMirrorDir(.tables).appendingPathComponent(fileName)
                let cloudOldURL = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(fileName)
                if fm.fileExists(atPath: localOldURL.path) { try? fm.removeItem(at: localOldURL) }
                CloudSyncManager.shared.ignoreNextUpdate(relativePath: "表格/\(fileName)")
                NSFileCoordinator(filePresenter: nil).coordinate(writingItemAt: cloudOldURL, options: .forDeleting, error: nil) { url in try? fm.removeItem(at: url) }
            }
        }
    }
}

// MARK: - ArchiveStore Part 13 - v2 - 全量教案物理清洗适配震动反馈

extension ArchiveStore {
    
    /// 【319号核心新增】：执行全球教案数据大清洗协议
    func performGlobalLessonPlanCleanup() {
        lock.lock()
        defer { lock.unlock() }
        
        print("[Cleanup] >>> 启动全量教案物理清洗程序 <<<")
        
        let fm = FileManager.default
        let lessonPlansRoot = CloudFileManager.shared.getCloudDir(.lessonPlans)
        
        // 1. 获取所有教案文件夹
        guard let folders = try? fm.contentsOfDirectory(at: lessonPlansRoot, includingPropertiesForKeys: [.isDirectoryKey], options: .skipsHiddenFiles) else { return }
        
        var fileCount = 0
        
        for folderURL in folders {
            let res = try? folderURL.resourceValues(forKeys: [.isDirectoryKey])
            guard res?.isDirectory == true else { continue }
            
            // 2. 扫描文件夹内的 CSV 文件
            if let files = try? fm.contentsOfDirectory(at: folderURL, includingPropertiesForKeys: nil, options: .skipsHiddenFiles) {
                for fileURL in files where fileURL.pathExtension.lowercased() == "csv" {
                    cleanSingleLessonPlanFile(url: fileURL)
                    fileCount += 1
                }
            }
        }
        
        print("[Cleanup] ✅ 清洗完成，共处理文件: \(fileCount)")
        
        DispatchQueue.main.async {
            self.triggerHapticFeedback(style: 2) // Heavy
            self.triggerCollision("全量清洗完成：已规范 \(fileCount) 个文件")
            // 重新同步模板，确保 UI 刷新
            self.loadDataFromFileSystem()
        }
    }
    
    private func cleanSingleLessonPlanFile(url: URL) {
        guard let content = try? String(contentsOf: url, encoding: .utf8) else { return }
        var nodes = parseLessonPlanCSV(content)
        guard !nodes.isEmpty else { return }
        
        // --- 阶段一：文本内容正则替换 ---
        for i in nodes.indices {
            var text = nodes[i].content
            
            // 1. [文字]{.underline} -> <u>文字</u>
            let underlinePattern = #"\[(.*?)\]\{.underline\}"#
            text = text.replacingOccurrences(of: underlinePattern, with: "<u>$1</u>", options: .regularExpression)
            
            // 2. A~B~ -> $A_B$ (处理下标)
            // 排除已经是 $ 包含的情况，匹配 字母~内容~
            let subPattern = #"(\w+)~([^~]+)~"#
            text = text.replacingOccurrences(of: subPattern, with: #"$$$1_$2$$"#, options: .regularExpression)
            
            // 3. A^B^ -> $A^B$ (处理上标)
            let supPattern = #"(\w+)\^([^^]+)\^"#
            text = text.replacingOccurrences(of: supPattern, with: #"$$$1^$2$$"#, options: .regularExpression)
            
            nodes[i].content = text
        }
        
        // --- 阶段二：层级结构规范化 ---
        var lastType: LPNodeType? = nil
        
        for i in nodes.indices {
            let currentType = nodes[i].type
            
            // 判定是否为正文类型 (L1-L5 或 Quote)
            let isCurrentBody = [.l1, .l2, .l3, .l4, .l5, .quote].contains(currentType)
            
            if isCurrentBody {
                if let last = lastType {
                    if[.h1, .h2, .h3, .h4, .h5, .h6].contains(last) {
                        // 规则：上层是 H1-H6，当前直接改为正文第一级 L1
                        nodes[i].type = .l1
                    } else {
                        // 规则：上层也是正文
                        let lastLevel = getLevelValue(last)
                        let currentLevel = getLevelValue(currentType)
                        
                        if currentLevel > lastLevel + 1 {
                            // 规则：如果比上一层深了超过1级，强制降1级（即 last + 1）
                            nodes[i].type = setLevelByValue(lastLevel + 1)
                        }
                        // “如果之前是同级，保持同级” 逻辑已隐含在不触发上述判断中
                    }
                } else {
                    // 孤立的正文（文件开头），设为 L1
                    nodes[i].type = .l1
                }
            }
            
            lastType = nodes[i].type
        }
        
        // --- 阶段三：物理回写 ---
        let cleanedCSV = generateLessonPlanCSV(from: nodes)
        try? cleanedCSV.write(to: url, atomically: true, encoding: .utf8)
    }
    
    // 辅助：获取物理层级数值
    private func getLevelValue(_ type: LPNodeType) -> Int {
        switch type {
        case .l1: return 1
        case .l2: return 2
        case .l3: return 3
        case .l4: return 4
        case .l5: return 5
        case .quote: return 6
        default: return 0
        }
    }
    
    // 辅助：根据数值设置类型
    private func setLevelByValue(_ val: Int) -> LPNodeType {
        switch val {
        case 1: return .l1
        case 2: return .l2
        case 3: return .l3
        case 4: return .l4
        case 5: return .l5
        case 6: return .quote
        default: return .l1
        }
    }
}

// MARK: - ArchiveStore Part 14 - v207 - 统一提取 macOS 环境安全的震动反馈扩展

extension ArchiveStore {
    
    // 我们定义一个安全的反馈辅助方法，用于替代所有之前的直接调用
    func triggerHapticFeedback(style: Int) {
        #if !os(macOS)
        // 0: light, 1: medium, 2: heavy
        let generator: UIImpactFeedbackGenerator
        switch style {
        case 0: generator = UIImpactFeedbackGenerator(style: .light)
        case 1: generator = UIImpactFeedbackGenerator(style: .medium)
        case 2: generator = UIImpactFeedbackGenerator(style: .heavy)
        default: generator = UIImpactFeedbackGenerator(style: .medium)
        }
        generator.impactOccurred()
        #endif
    }
}

// MARK: - 授课Tab枚举定义 - v4 - 重新物理排序适配 92 号需求

enum TeachingTab: Int, CaseIterable, Identifiable {
    // 0-4: 功能组件 | 6: 会话结束 | 5: 笔记入口 | 7: 系统重置
    case startClass = 0
    case journal = 1
    case update = 2
    case aids = 3
    case feedback = 4
    case endClass = 6
    case notes = 5   // 物理位置在“下课”之后
    case reset = 7
    
    var id: Int { self.rawValue }
    
    func displayTitle(isNotesMode: Bool) -> String {
        switch self {
        case .startClass: return "上课"
        case .journal: return "教案"
        case .update: return "更新"
        case .aids: return "教辅"
        case .feedback: return "课反"
        case .notes: return "笔记"
        case .endClass: return isNotesMode ? "关闭" : "下课"
        case .reset: return "初始"
        }
    }
    
    var title: String { displayTitle(isNotesMode: false) }
    
    var color: Color {
        switch self {
        case .startClass: return .red
        case .journal: return .orange
        case .update: return .yellow
        case .aids: return .green
        case .feedback: return .cyan
        case .notes: return .mint
        case .endClass: return .blue
        case .reset: return .purple
        }
    }
    
    var icon: String {
        switch self {
        case .startClass: return "play.fill"
        case .journal: return "book.fill"
        case .update: return "arrow.clockwise"
        case .aids: return "doc.on.clipboard.fill"
        case .feedback: return "text.bubble.fill"
        case .notes: return "pencil.and.list.clipboard"
        case .endClass: return "stop.fill"
        case .reset: return "arrow.counterclockwise.circle.fill"
        }
    }
}

// MARK: - ClassModeView - v178 - 实装视野锚点持久化，实现模块切换零跳变

struct ClassModeView: View {
    let studentName: String
    let studentCategoryID: UUID
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var settingsStore: GlobalSettingsStore
    @Environment(\.dismiss) var dismiss
    
    @State private var selectedTab: TeachingTab = .startClass
    @State private var journalURL: URL?
    @State private var isClassActive: Bool = false
    @State private var isNotesModeActive: Bool = false
    
    @State private var selectedPlanName: String? = nil
    @State private var showPlanSidebar: Bool = false
    @State private var planSidebarRefreshKey: Int = 0
    @State private var showFeedbackSidebar: Bool = false
    @State private var showUpdateSidebar: Bool = false
    @State private var showingReinitSheet = false
    @State private var currentFocusID: UUID? = nil
    @State private var showingUpdateSheet = false
    @State private var pendingSyncNodes: [LPRowNode]? = nil
    
    // 【358号新增】：视野顶端物理锚点，用于在 Tab 切换或 UI 重刷时锁定视野
    @State private var topAnchorID: UUID? = nil
    
    @State private var showFeedbackMissingAlert = false
    @AppStorage("lp_settings_isDarkMode_v1") private var isDarkMode: Bool = true
    @State private var capturedPackage: TeachingStore.SyncPackage? = nil

    var body: some View {
        GeometryReader { geo in
            let isLandscape = geo.size.width > geo.size.height
            ZStack(alignment: .topLeading) {
                mainHStack(isLandscape: isLandscape)
                floatingOverlayPanel(isLandscape: isLandscape)
                if settingsStore.config.isCursorDebugEnabled, let range = teachingStore.activeCursorRange {
                    Text("光标: { \(range.location), \(range.length) }").font(.system(size: 12, weight: .bold, design: .monospaced)).foregroundColor(.black).padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().fill(Color.orange)).shadow(radius: 5).padding(.top, isLandscape ? 10 : 60).zIndex(1000)
                }
            }
        }
        .navigationTitle(studentName).ttNavigationBarTitleDisplayMode(.inline).toolbar(.hidden, for: .tabBar).navigationBarBackButtonHidden(isClassActive || isNotesModeActive).interactiveDismissDisabled(isClassActive || isNotesModeActive)
        .overlay(alignment: .top) { if let error = teachingStore.pdfPathError { Text(error).font(.caption.bold()).foregroundColor(.white).padding(12).background(Capsule().fill(Color.red.opacity(0.9))).shadow(radius: 10).padding(.top, 60).onTapGesture { teachingStore.pdfPathError = nil } } }
        .sheet(isPresented: $showingReinitSheet) {
            TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                StudentInitializationSheet(studentName: studentName)
                    .environmentObject(asStore)
                    .environmentObject(teachingStore)
            }
        }
        .sheet(item: Binding(get: { pendingSyncNodes.map { _ in "sync" } }, set: { if $0 == nil { pendingSyncNodes = nil } })) { _ in
            if let nodes = pendingSyncNodes, let url = journalURL {
                let config = teachingStore.getStudentConfig(studentName)
                let block = LessonPlanUpdateView.LPContentBlock(id: nodes.first?.id ?? UUID(), title: nodes.first?.content ?? "未命名", nodes: nodes, isFromMaster: false, isDirty: true, sourceFileName: nil)
                TTModalSheetContainer(minWidth: 860, minHeight: 640) {
                    MasterDestinationPicker(planNames: config?.lessonPlanNames ?? [], blocks: [block], journalURL: url) {
                        pendingSyncNodes = nil
                        teachingStore.isUpdateAvailable = false
                    }
                    .environmentObject(asStore)
                }
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPSwitchToFullUpdateUI"))) { _ in
            openUpdatePanel()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPDirectSyncTrigger"))) { note in if let nodes = note.userInfo? ["nodes"] as? [LPRowNode] { self.pendingSyncNodes = nodes } }
        .onAppear {
            withAnimation { teachingStore.isAnyClassActive = true }
            let sessionPlans = teachingStore.config.currentSession?.lessonPlanNames ?? []
            if let activePlan = teachingStore.config.currentSession?.activePlanName ?? sessionPlans.first {
                self.selectedPlanName = activePlan
                if teachingStore.config.currentSession?.activePlanName == nil {
                    syncPlanSelection(activePlan, refreshTeachingSync: false)
                }
            } else {
                self.selectedPlanName = nil
            }
        }
        .onChange(of: teachingStore.config.currentSession?.activePlanName) { _, newPlan in
            guard let newPlan else {
                selectedPlanName = nil
                return
            }
            if selectedPlanName != newPlan {
                selectedPlanName = newPlan
            }
        }
        .onDisappear { if isClassActive || isNotesModeActive { performPhysicalTerminate_Safe() }; withAnimation { teachingStore.isAnyClassActive = false } }
    }

    private func handleJournalClick() {
        let sessionPlans = teachingStore.config.currentSession?.lessonPlanNames ?? []
        if let activePlan = teachingStore.config.currentSession?.activePlanName ?? sessionPlans.first {
            openPlanSidebar(for: activePlan, forceRefresh: false)
        }
        withAnimation {
            showFeedbackSidebar = false
            showUpdateSidebar = false
        }
        selectedTab = .journal
    }

    private func handleTabClick(_ tab: TeachingTab) {
        if tab != .journal && tab != .reset { NotificationCenter.default.post(name: NSNotification.Name("LPJournalExitAllEditing"), object: nil) }
        if tab == .startClass { startClassAction() }
        else if tab == .notes { openNotesAction() }
        else if tab == .journal {
            if isClassActive || isNotesModeActive {
                if showPlanSidebar {
                    withAnimation { showPlanSidebar = false }
                } else {
                    handleJournalClick()
                }
            }
        }
        else if tab == .update {
            if isClassActive || isNotesModeActive {
                if showUpdateSidebar {
                    withAnimation {
                        showUpdateSidebar = false
                        selectedTab = .journal
                    }
                } else {
                    openUpdatePanel()
                }
            }
        }
        else if tab == .feedback {
            if isClassActive {
                if showFeedbackSidebar {
                    withAnimation {
                        showFeedbackSidebar = false
                        selectedTab = .journal
                    }
                } else {
                    openFeedbackPanel()
                }
            }
        }
        else if tab == .endClass { handleEndClassClick() }
        else if tab == .reset { showingReinitSheet = true }
        else { selectedTab = tab }
    }

    private func handleEndClassClick() {
        guard isClassActive || isNotesModeActive else { return }
        NotificationCenter.default.post(name: NSNotification.Name("LPFinalSyncRequest"), object: nil)
        
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
            guard let pkg = teachingStore.captureSyncPackage() else {
                finalizeAndExit(); return
            }
            _ = asStore.performEndOfClassFinalSync(package: pkg, catID: studentCategoryID)
            
            if let exportPath = pkg.pdfConfig.path {
                let finalNodes = asStore.loadLessonPlanNodes(from: pkg.journalURL)
                Task {
                    if let tempPDFURL = await asStore.generateAdvancedPDF(nodes: finalNodes, title: "随堂笔记_\(studentName)", style: lpStyleFromStorage()) {
                        let result = asStore.saveAdvancedPDFToCustomPath(tempURL: tempPDFURL, title: "随堂笔记_\(studentName)", folderPath: exportPath, bookmarkData: pkg.pdfConfig.bookmark)
                        if let err = result { print("[Export] PDF 自动导出失败: \(err)") }
                        else { print("[Export] PDF 自动导出成功: \(exportPath)") }
                    }
                    await MainActor.run { finalizeAndExit() }
                }
            } else {
                finalizeAndExit()
            }
        }
    }
    
    private func lpStyleFromStorage() -> LPGlobalStyle { if let data = UserDefaults.standard.data(forKey: "lesson_plan_style_v1"), let saved = try? JSONDecoder().decode(LPGlobalStyle.self, from: data) { return saved }; return LPGlobalStyle.default }
    private func finalizeAndExit() { if isClassActive { withAnimation { timeStore.start(category: "生活") } }; isClassActive = false; isNotesModeActive = false; journalURL = nil; currentFocusID = nil; selectedTab = .startClass; capturedPackage = nil; teachingStore.endSession(); dismiss() }
    private func performPhysicalTerminate_Safe() { if let pkg = teachingStore.captureSyncPackage() { _ = asStore.performEndOfClassFinalSync(package: pkg, catID: studentCategoryID) }; teachingStore.endSession() }
    private func syncPlanSelection(_ planName: String, refreshTeachingSync: Bool) {
        if selectedPlanName != planName {
            selectedPlanName = planName
            planSidebarRefreshKey += 1
        } else if refreshTeachingSync {
            planSidebarRefreshKey += 1
        }
        teachingStore.updateActivePlan(planName: planName, studentCategoryID: studentCategoryID)
        if refreshTeachingSync {
            let plans = teachingStore.config.currentSession?.lessonPlanNames ?? []
            asStore.performTeachingSync(studentName: studentName, catID: studentCategoryID, planNames: plans)
        }
    }
    private func openPlanSidebar(for planName: String, forceRefresh: Bool) {
        if selectedPlanName != planName {
            selectedPlanName = planName
            planSidebarRefreshKey += 1
        } else if forceRefresh {
            planSidebarRefreshKey += 1
        }
        withAnimation {
            selectedTab = .journal
            showFeedbackSidebar = false
            showUpdateSidebar = false
            showPlanSidebar = true
        }
    }
    private func openFeedbackPanel() {
        let config = teachingStore.getStudentConfig(studentName)
        _ = asStore.ensureTodayFeedbackTable(
            studentName: studentName,
            catID: studentCategoryID,
            feedbackSourceID: config?.feedbackTableID
        )
        withAnimation {
            selectedTab = .feedback
            showPlanSidebar = false
            showFeedbackSidebar = true
            showUpdateSidebar = false
        }
    }
    private func openUpdatePanel() {
        withAnimation {
            selectedTab = .update
            showPlanSidebar = false
            showFeedbackSidebar = false
            showUpdateSidebar = true
        }
    }
    private func startClassAction() { guard !isClassActive else { return }; let config = teachingStore.getStudentConfig(studentName); teachingStore.startSession(studentName: studentName, studentCatID: studentCategoryID); let planNames = config?.lessonPlanNames ?? []; for plan in planNames { asStore.syncLessonPlanContent(folderName: plan) }; asStore.performTeachingSync(studentName: studentName, catID: studentCategoryID, planNames: planNames); let result = asStore.prepareClassFiles(studentName: studentName, catID: studentCategoryID, feedbackSourceID: nil); switch result { case .success(_, let focusID): let url = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName).appendingPathComponent("随堂笔记_\(studentName).csv"); self.journalURL = url; self.currentFocusID = focusID; let resolvedPlan = teachingStore.config.currentSession?.activePlanName ?? planNames.first; if let lp = resolvedPlan { syncPlanSelection(lp, refreshTeachingSync: false) } else { self.selectedPlanName = nil }; withAnimation(.spring()) { timeStore.start(category: "工作") }; withAnimation { isClassActive = true; selectedTab = .journal }; case .feedbackSourceMissing: showFeedbackMissingAlert = true; teachingStore.endSession() } }
    private func openNotesAction() { guard !isClassActive && !isNotesModeActive else { return }; let config = teachingStore.getStudentConfig(studentName); let planNames = config?.lessonPlanNames ?? []; teachingStore.startSession(studentName: studentName, studentCatID: studentCategoryID); for plan in planNames { asStore.syncLessonPlanContent(folderName: plan) }; asStore.performTeachingSync(studentName: studentName, catID: studentCategoryID, planNames: planNames); let url = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName).appendingPathComponent("随堂笔记_\(studentName).csv"); self.journalURL = url; self.currentFocusID = nil; if let resolvedPlan = teachingStore.config.currentSession?.activePlanName ?? planNames.first { syncPlanSelection(resolvedPlan, refreshTeachingSync: false) } else { self.selectedPlanName = nil }; withAnimation { isNotesModeActive = true; selectedTab = .journal } }
    @ViewBuilder private func mainHStack(isLandscape: Bool) -> some View { HStack(spacing: 0) { if isLandscape { teachingSidebar.frame(width: 80).background(isDarkMode ? Color(white: 0.02) : Color(white: 0.98)).overlay(Rectangle().fill(isDarkMode ? Color.white.opacity(0.1) : Color.black.opacity(0.1)).frame(width: 0.5), alignment: .trailing) }; VStack(spacing: 0) { if !isLandscape { teachingTopBar }; mainContentView } } }
    @ViewBuilder private func floatingOverlayPanel(isLandscape: Bool) -> some View {
        if showPlanSidebar, let planName = selectedPlanName {
            floatingPanelShell(isLandscape: isLandscape) {
                renderPlanSidebar(planName: planName)
            }
            .transition(.move(edge: .leading).combined(with: .opacity))
        } else if showFeedbackSidebar && isClassActive {
            floatingPanelShell(isLandscape: isLandscape) {
                TeachingFeedbackSidePanel(
                    studentName: studentName,
                    categoryID: studentCategoryID,
                    isDark: isDarkMode,
                    onExit: {
                        withAnimation {
                            showFeedbackSidebar = false
                            selectedTab = .journal
                        }
                    }
                )
                .environmentObject(asStore)
                .environmentObject(teachingStore)
            }
            .transition(.move(edge: .leading).combined(with: .opacity))
        } else if showUpdateSidebar && (isClassActive || isNotesModeActive) {
            floatingPanelShell(isLandscape: isLandscape, width: 460) {
                teachingUpdateView
            }
            .transition(.move(edge: .leading).combined(with: .opacity))
        }
    }
    private func floatingPanelShell<Content: View>(isLandscape: Bool, width: CGFloat = 360, @ViewBuilder content: () -> Content) -> some View {
        content()
            .frame(width: width)
            .background(
                RoundedRectangle(cornerRadius: 22, style: .continuous)
                    .fill(isDarkMode ? Color(white: 0.08).opacity(0.96) : Color.white.opacity(0.96))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 22, style: .continuous)
                    .stroke(isDarkMode ? Color.white.opacity(0.08) : Color.black.opacity(0.08), lineWidth: 1)
            )
            .clipShape(RoundedRectangle(cornerRadius: 22, style: .continuous))
            .shadow(color: .black.opacity(isDarkMode ? 0.35 : 0.12), radius: 30, x: 0, y: 16)
            .padding(.top, isLandscape ? 16 : 76)
            .padding(.leading, isLandscape ? 96 : 16)
            .zIndex(100)
    }
    private var teachingSidebar: some View {
        VStack(spacing: 24) {
            teachingSidebarButton(.startClass, isSelected: selectedTab == .startClass, isHighlighted: isClassActive, disabled: isClassActive || isNotesModeActive) { handleTabClick(.startClass) }
            teachingSidebarButton(.journal, isSelected: selectedTab == .journal && !showUpdateSidebar, isHighlighted: false, disabled: !isClassActive && !isNotesModeActive) { handleTabClick(.journal) }
            teachingSidebarButton(.update, isSelected: showUpdateSidebar || selectedTab == .update, isHighlighted: teachingStore.isUpdateAvailable, disabled: !isClassActive && !isNotesModeActive) { handleTabClick(.update) }
            teachingSidebarButton(.aids, isSelected: selectedTab == .aids, isHighlighted: false, disabled: false) { handleTabClick(.aids) }
            teachingSidebarButton(.feedback, isSelected: selectedTab == .feedback, isHighlighted: false, disabled: !isClassActive) { handleTabClick(.feedback) }
            Spacer()
            teachingSidebarButton(.endClass, isSelected: selectedTab == .endClass, isHighlighted: false, disabled: !isClassActive && !isNotesModeActive) { handleEndClassClick() }
            teachingSidebarButton(.notes, isSelected: selectedTab == .notes, isHighlighted: isNotesModeActive, disabled: isClassActive || isNotesModeActive) { handleTabClick(.notes) }
            teachingSidebarButton(.reset, isSelected: false, isHighlighted: false, disabled: isClassActive || isNotesModeActive) { handleTabClick(.reset) }
        }
        .padding(.vertical, 20)
    }
    private var teachingTopBar: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 12) {
                ForEach(TeachingTab.allCases) { tab in
                    teachingTopBarButton(for: tab)
                }
            }
            .padding(.horizontal)
            .padding(.vertical, 10)
        }
        .background(isDarkMode ? Color(white: 0.05).opacity(0.8) : Color(white: 0.95).opacity(0.8))
        .background(.ultraThinMaterial)
        .overlay(Rectangle().fill(isDarkMode ? Color.white.opacity(0.1) : Color.black.opacity(0.1)).frame(height: 0.5), alignment: .bottom)
    }
    @ViewBuilder private var mainContentView: some View {
        ZStack {
            (isDarkMode ? Color.black : Color.white).ignoresSafeArea()
            switch selectedTab {
            case .journal, .feedback, .update:
                journalHostView
            case .startClass:
                if isClassActive {
                    classActiveDashboard
                } else if isNotesModeActive {
                    notesActiveDashboard
                } else {
                    placeholderView(text: "点击按钮开始")
                }
            case .aids:
                teachingAidsView
            default:
                placeholderView(text: "\(selectedTab.title) 模块待实装")
            }
        }
    }
    @ViewBuilder private var journalHostView: some View {
        if let plan = selectedPlanName, let url = journalURL {
            LessonPlanEditorView(
                fileURL: url,
                initialFocusID: currentFocusID,
                feedbackOverlayActive: showFeedbackSidebar && isClassActive,
                externalTopAnchorID: $topAnchorID
            )
            .environmentObject(asStore)
            .id("\(url.path)_\(plan)_\(planSidebarRefreshKey)")
        } else {
            placeholderView(text: (isClassActive || isNotesModeActive) ? "载入中..." : "请选择上课或笔记模式")
        }
    }
    @ViewBuilder private var classActiveDashboard: some View { VStack(spacing: 20) { Image(systemName: "checkmark.seal.fill").font(.system(size: 80)).foregroundColor(.red); Text("课程正在进行中").font(.title2).bold().foregroundColor(isDarkMode ? .white : .black); Button("进入随堂笔记") { selectedTab = .journal }.buttonStyle(.bordered) } }
    @ViewBuilder private var notesActiveDashboard: some View { VStack(spacing: 20) { Image(systemName: "pencil.and.outline").font(.system(size: 80)).foregroundColor(.mint); Text("笔记编辑模式").font(.title2).bold().foregroundColor(isDarkMode ? .white : .black); Button("打开笔记") { selectedTab = .journal }.buttonStyle(.bordered) } }
    private func teachingSidebarButton(_ tab: TeachingTab, isSelected: Bool, isHighlighted: Bool, disabled: Bool, action: @escaping () -> Void) -> some View {
        TeachingSideBtn(tab: tab, isSelected: isSelected, isHighlighted: isHighlighted, isDark: isDarkMode, isNotesMode: isNotesModeActive, action: action)
            .disabled(disabled)
            .opacity(disabled ? 0.3 : 1.0)
    }
    private func isTopBarTabDisabled(_ tab: TeachingTab) -> Bool {
        let isOff = !isClassActive && !isNotesModeActive
        switch tab {
        case .startClass: return isClassActive || isNotesModeActive
        case .notes, .reset: return !isOff
        case .feedback: return isOff || isNotesModeActive
        case .endClass: return isOff
        default: return false
        }
    }
    private func isTopBarTabSelected(_ tab: TeachingTab) -> Bool {
        if tab == .update { return showUpdateSidebar || selectedTab == .update }
        if tab == .journal { return selectedTab == .journal && !showUpdateSidebar }
        return selectedTab == tab
    }
    private func isTopBarTabLit(_ tab: TeachingTab) -> Bool {
        (tab == .startClass && isClassActive) || (tab == .notes && isNotesModeActive) || (tab == .update && teachingStore.isUpdateAvailable)
    }
    private func teachingTopBarButton(for tab: TeachingTab) -> some View {
        let isDisabled = isTopBarTabDisabled(tab)
        let isSelected = isTopBarTabSelected(tab)
        let isLit = isTopBarTabLit(tab)
        return Button { handleTabClick(tab) } label: {
            HStack(spacing: 6) {
                Image(systemName: "tab.icon")
                Text(tab.displayTitle(isNotesMode: isNotesModeActive))
            }
            .font(.system(size: 14, weight: .bold))
            .foregroundColor(isSelected ? .white : (isLit ? tab.color : tab.color.opacity(0.6)))
            .padding(.horizontal, 16)
            .padding(.vertical, 8)
            .background(isSelected ? tab.color.opacity(1.0) : Color.white.opacity(0.05))
            .cornerRadius(12)
        }
        .buttonStyle(.plain)
        .disabled(isDisabled)
        .opacity(isDisabled ? 0.3 : 1.0)
    }
    @ViewBuilder private var teachingUpdateView: some View {
        if let url = journalURL {
            let config = teachingStore.getStudentConfig(studentName)
            LessonPlanUpdateView(
                studentName: studentName,
                journalURL: url,
                planNames: config?.lessonPlanNames ?? []
            )
            .environmentObject(asStore)
            .environmentObject(teachingStore)
        } else {
            placeholderView(text: "暂无可更新内容")
        }
    }
    @ViewBuilder private var teachingAidsView: some View {
        let aids = asStore.templates.filter { $0.type == .taskList && !$0.title.hasPrefix("教案_") }
        if aids.isEmpty {
            VStack(spacing: 18) {
                Image(systemName: "doc.on.clipboard.fill")
                    .font(.system(size: 68))
                    .foregroundColor(.green.opacity(0.65))
                Text("暂无可用教辅模板")
                    .font(.title3.bold())
                    .foregroundColor(isDarkMode ? .white : .black)
                Text("请先在档案页创建清单模板。")
                    .font(.subheadline)
                    .foregroundColor(isDarkMode ? .white.opacity(0.55) : .black.opacity(0.55))
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List {
                Section {
                    ForEach(aids) { tmpl in
                        HStack(spacing: 14) {
                            Image(systemName: "list.bullet.clipboard.fill")
                                .font(.title3)
                                .foregroundColor(.green)
                            VStack(alignment: .leading, spacing: 4) {
                                Text(tmpl.title)
                                    .font(.headline)
                                    .foregroundColor(isDarkMode ? .white : .black)
                                Text("\(tmpl.taskRows.count) 个条目")
                                    .font(.caption)
                                    .foregroundColor(isDarkMode ? .white.opacity(0.55) : .black.opacity(0.55))
                            }
                            Spacer()
                        }
                        .padding(.vertical, 6)
                        .listRowBackground(isDarkMode ? Color.white.opacity(0.03) : Color.black.opacity(0.02))
                    }
                } header: {
                    Text("当前可用教辅模板")
                } footer: {
                    Text("教辅关联在“学生初始化”中配置，这里用于课中查看。")
                }
            }
            .scrollContentBackground(.hidden)
            .background(isDarkMode ? Color.black : Color.white)
        }
    }
    @ViewBuilder private func renderPlanSidebar(planName: String) -> some View {
        TeachingLessonSidePanel(
            planName: planName,
            studentName: studentName,
            categoryID: studentCategoryID,
            isDark: isDarkMode,
            onSwitchPlan: { newPlan in
                syncPlanSelection(newPlan, refreshTeachingSync: true)
                openPlanSidebar(for: newPlan, forceRefresh: false)
            },
            onComplete: { nodes in insertSelectedLessons(nodes: nodes) },
            onExit: { withAnimation { showPlanSidebar = false } }
        )
        .id("\(planName)_\(planSidebarRefreshKey)")
    }
    private func insertSelectedLessons(nodes: [TeachingLessonNode]) { NotificationCenter.default.post(name: NSNotification.Name("LPRowInsertAction"), object: nil, userInfo: ["nodes": nodes]); withAnimation { showPlanSidebar = false } }
    private func placeholderView(text: String) -> some View { VStack(spacing: 15) { let plans = teachingStore.config.currentSession?.lessonPlanNames ?? []; if (selectedTab == .journal || selectedTab == .startClass) && plans.count > 0 && selectedPlanName == nil && (isClassActive || isNotesModeActive) { Text("请选择要开启的教案:").font(.headline).foregroundColor(isDarkMode ? .white : .black); ForEach(plans, id: \.self) { plan in Button(plan) { withAnimation { syncPlanSelection(plan, refreshTeachingSync: true); openPlanSidebar(for: plan, forceRefresh: false) } }.padding().frame(maxWidth: 240).background(Color.orange.opacity(0.2)).cornerRadius(12) } } else { Image(systemName: selectedTab.icon).font(.system(size: 60)).foregroundColor(selectedTab.color).opacity(0.2); Text(text).font(.headline).foregroundColor(isDarkMode ? .white.opacity(0.3) : .black.opacity(0.3)) } } }
}

// MARK: - 侧边按钮组件 - v4 - 适配动态标题逻辑

struct TeachingSideBtn: View {
    let tab: TeachingTab
    let isSelected: Bool
    let isHighlighted: Bool
    let isDark: Bool
    // 【65号新增】：感知模式
    var isNotesMode: Bool = false
    let action: () -> Void
    
    var body: some View {
        Button(action: action) {
            VStack(spacing: 6) {
                ZStack {
                    Circle()
                        .fill(tab.color.opacity(isHighlighted ? 0.6 : (isSelected ? 0.3 : 0.1)))
                        .frame(width: 54, height: 54)
                        .shadow(color: isHighlighted ? tab.color.opacity(0.5) : .clear, radius: 10)
                    
                    Image(systemName: tab.icon)
                        .font(.system(size: 20, weight: .bold))
                        .foregroundColor(isSelected || isHighlighted ? tab.color : tab.color.opacity(0.7))
                }
                
                // 【65号修改】：调用动态标题方法
                Text(tab.displayTitle(isNotesMode: isNotesMode))
                    .font(.system(size: 11, weight: .bold))
                    .foregroundColor(isDark ? .white : .black)
            }
        }.buttonStyle(.plain)
    }
}

// MARK: - 全局样式配置模型 - v4 - 支持H1-H6
//
// MarkdownGlobalStyle
// (修改：新增 h4, h5, h6 样式定义。)

struct MarkdownGlobalStyle: Codable, Equatable {
    var h1: TextStyle = .init(size: 24, color: "white", isBold: true)
    var h2: TextStyle = .init(size: 20, color: "white", isBold: true)
    var h3: TextStyle = .init(size: 18, color: "white", isBold: true)
    // 【新增】
    var h4: TextStyle = .init(size: 16, color: "white", isBold: true)
    var h5: TextStyle = .init(size: 15, color: "white", isBold: true)
    var h6: TextStyle = .init(size: 14, color: "gray", isBold: true)
    
    var body: TextStyle = .init(size: 15, color: "white", isBold: false)
    var quote: TextStyle = .init(size: 15, color: "gray", isBold: false)
    
    struct TextStyle: Codable, Equatable {
        var size: CGFloat
        var color: String
        var isBold: Bool
        var fontName: String = "system"
    }
}

// MARK: - Markdown 视图配置模型 - v5 - 增加深色模式开关
//
// MarkdownViewSettings
// (修改：新增 isDarkMode 字段，默认为 true)

struct MarkdownViewSettings: Codable, Equatable {
    var maxDisplayLevel: Int = 3
    var viewMode: ViewMode = .live
    var isDarkMode: Bool = true // 【新增】默认为深色模式
    
    enum ViewMode: String, Codable, CaseIterable {
        case live    // 即时渲染
        case code    // 源码模式
        case preview // Web 预览
        case split   // 分屏预览
    }
}

// 3. 目录树节点 (保持不变)
struct MDNode: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var title: String
    var level: Int
    var rangeLocation: Int
    var rangeLength: Int
    var children: [MDNode] = []
}

// MARK: - Markdown 图片资产管理器 - v11 - 实现零秒尺寸探测，支持布局高度锁定

#if canImport(UIKit)
    import UIKit
#endif
import ImageIO

class MarkdownAssetManager {
    static let shared = MarkdownAssetManager()
    private init() { ensureDirectoryExists() }
    
    private var baseDir: URL {
        return CloudFileManager.shared.getCloudDir(.templates).appendingPathComponent("图片")
    }
    
    private var mirrorDir: URL {
        return CloudFileManager.shared.getLocalMirrorDir(.templates).appendingPathComponent("图片")
    }
    
    private let thumbnailCache = NSCache<NSString, UIImage>()
    
    private func ensureDirectoryExists() {
        try? FileManager.default.createDirectory(at: baseDir, withIntermediateDirectories: true)
        try? FileManager.default.createDirectory(at: mirrorDir, withIntermediateDirectories: true)
    }
    
    func saveImage(_ image: UIImage, tableID: UUID) -> String? {
        guard let data = optimizedImageData(from: image) else { return nil }
        let fileName = "\(tableID.uuidString)_\(UUID().uuidString).jpg"
        let fileURL = baseDir.appendingPathComponent(fileName)
        let mirrorURL = mirrorDir.appendingPathComponent(fileName)
        do {
            try data.write(to: fileURL)
            try? data.write(to: mirrorURL)
            return fileName
        } catch { return nil }
    }
    
    func getFileURL(assetID: String) -> URL {
        let cleanID = assetID.trimmingCharacters(in: .whitespacesAndNewlines)
        let mirrorURL = mirrorDir.appendingPathComponent(cleanID)
        if FileManager.default.fileExists(atPath: mirrorURL.path) { return mirrorURL }
        return baseDir.appendingPathComponent(cleanID)
    }

    /// 【375号核心新增】：零解码获取图片原始尺寸
    /// 用于在渲染前锁定 UI 高度，防止 LazyVStack 布局死循环
    func getImageSize(assetID: String) -> CGSize? {
        let fileURL = getFileURL(assetID: assetID)
        guard let source = CGImageSourceCreateWithURL(fileURL as CFURL, nil) else { return nil }
        
        let options = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, options) as? [CFString: Any] else { return nil }
        
        if let width = properties[kCGImagePropertyPixelWidth] as? CGFloat,
           let height = properties[kCGImagePropertyPixelHeight] as? CGFloat {
            return CGSize(width: width, height: height)
        }
        return nil
    }

    func getThumbnail(assetID: String, targetWidth: CGFloat) -> UIImage? {
        let cacheKey = "\(assetID)_\(Int(targetWidth))" as NSString
        if let cached = thumbnailCache.object(forKey: cacheKey) { return cached }
        
        let fileURL = getFileURL(assetID: assetID)
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: targetWidth * UIScreen.mainSafe.scale
        ]
        
        guard let source = CGImageSourceCreateWithURL(fileURL as CFURL, nil),
              let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else {
            return nil
        }
        
        let thumbnail = UIImage(cgImage: cgImage)
        thumbnailCache.setObject(thumbnail, forKey: cacheKey)
        return thumbnail
    }
    
    func deleteSingleAsset(assetID: String) {
        let cleanID = assetID.trimmingCharacters(in: .whitespacesAndNewlines)
        let fileURL = baseDir.appendingPathComponent(cleanID)
        let mirrorURL = mirrorDir.appendingPathComponent(cleanID)
        try? FileManager.default.removeItem(at: fileURL)
        try? FileManager.default.removeItem(at: mirrorURL)
        thumbnailCache.removeAllObjects()
        CloudSyncManager.shared.ignoreNextUpdate(relativePath: "模板/图片/\(cleanID)")
    }
    
    func deleteAssets(for tableID: UUID) {
        let prefix = tableID.uuidString
        let fm = FileManager.default
        thumbnailCache.removeAllObjects()
        [baseDir, mirrorDir].forEach { dir in
            if let files = try? fm.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil) {
                for fileURL in files {
                    if fileURL.lastPathComponent.hasPrefix(prefix) { try? fm.removeItem(at: fileURL) }
                }
            }
        }
    }
    
    func getAssetsDir() -> URL { return baseDir }

    private func optimizedImageData(from image: UIImage) -> Data? {
        let maxSide: CGFloat = 1500
        let minQuality: CGFloat = 0.35
        let targetSize = scaledSize(for: image.size, maxSide: maxSide)
        guard targetSize.width > 0, targetSize.height > 0 else { return nil }

        let resizedImage: UIImage
        #if canImport(UIKit)
        if targetSize != image.size {
            let format = UIGraphicsImageRendererFormat()
            format.scale = 1
            let renderer = UIGraphicsImageRenderer(size: targetSize, format: format)
            resizedImage = renderer.image { context in
                image.draw(in: CGRect(origin: .zero, size: targetSize))
            }
        } else {
            resizedImage = image
        }
        #else
        resizedImage = image
        #endif

        var quality: CGFloat = 0.65
        var data = resizedImage.jpegData(compressionQuality: quality)
        while let current = data, current.count > 100_000 && quality > minQuality {
            quality = max(minQuality, quality - 0.1)
            data = resizedImage.jpegData(compressionQuality: quality)
        }
        if let finalData = data, finalData.count > 100_000 {
            // 仍然大于 100K 时再缩一层尺寸，飞机
            let scaledSize = CGSize(width: targetSize.width * 0.85, height: targetSize.height * 0.85)
            guard scaledSize.width > 0, scaledSize.height > 0 else { return finalData }
            #if canImport(UIKit)
            let format = UIGraphicsImageRendererFormat()
            format.scale = 1
            let renderer = UIGraphicsImageRenderer(size: scaledSize, format: format)
            let extraResized = renderer.image { context in
                resizedImage.draw(in: CGRect(origin: .zero, size: scaledSize))
            }
            data = extraResized.jpegData(compressionQuality: minQuality)
            #else
            data = resizedImage.jpegData(compressionQuality: minQuality)
            #endif
        }
        return data
    }

    private func scaledSize(for original: CGSize, maxSide: CGFloat) -> CGSize {
        let width = original.width
        let height = original.height
        let maxDimension = max(width, height)
        if maxDimension <= maxSide {
            return original
        }
        let scale = maxSide / maxDimension
        return CGSize(width: width * scale, height: height * scale)
    }
}

// MARK: - Markdown 调色板视图 - v7 - 支持 Hex 颜色代码输入
//
// MarkdownPaletteView
// (修改：
//  1. [交互] 在颜色选择区右侧增加 Hex 输入框。
//  2. [逻辑] 点击圆球设置预设名（如 "red"），输入框输入则保存代码（如 "#FF0000"）。)

struct MarkdownPaletteView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var style: MarkdownGlobalStyle = MarkdownGlobalStyle()
    
    // 字体选择弹窗控制
    @State private var showFontPicker = false
    @State private var activeConfigLabel: String = ""
    @State private var tempFontSelection: String = ""
    
    let colors: [String: Color] = [
        "white": .white, "gray": .gray, "red": .red, "orange": .orange,
        "yellow": .yellow, "green": .green, "blue": .blue, "purple": .purple, "cyan": .cyan
    ]
    let colorKeys = ["white", "gray", "red", "orange", "yellow", "green", "blue", "purple", "cyan"]
    
    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("高层标题 (H1-H3)")) {
                    styleRow(label: "H1 一级标题", key: "h1", config: $style.h1)
                    styleRow(label: "H2 二级标题", key: "h2", config: $style.h2)
                    styleRow(label: "H3 三级标题", key: "h3", config: $style.h3)
                }
                
                Section(header: Text("低层标题 (H4-H6)")) {
                    styleRow(label: "H4 四级标题", key: "h4", config: $style.h4)
                    styleRow(label: "H5 五级标题", key: "h5", config: $style.h5)
                    styleRow(label: "H6 六级标题", key: "h6", config: $style.h6)
                }
                
                Section(header: Text("正文与引用")) {
                    styleRow(label: "Body 正文", key: "body", config: $style.body)
                    styleRow(label: "Quote 引用", key: "quote", config: $style.quote)
                }
                
                Section(footer: Text("颜色支持预设点击，也支持输入十六进制代码（如 #FF5733）。")) {
                    Button("重置为默认") {
                        style = MarkdownGlobalStyle()
                    }
                }
            }
            .navigationTitle("文档样式配置")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("保存") {
                        asStore.saveMarkdownStyle(style)
                        dismiss()
                    }
                }
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { dismiss() }
                }
            }
            .onAppear {
                style = asStore.loadMarkdownStyle()
            }
            .sheet(isPresented: $showFontPicker) {
                TTModalSheetContainer(minWidth: 720, minHeight: 560) {
                    FontSelectionSheet(selection: $tempFontSelection)
                        .onDisappear {
                            updateFontBack(key: activeConfigLabel, fontName: tempFontSelection)
                        }
                }
            }
        }
        .presentationDetents([.medium, .large])
    }
    
    func updateFontBack(key: String, fontName: String) {
        switch key {
        case "h1": style.h1.fontName = fontName
        case "h2": style.h2.fontName = fontName
        case "h3": style.h3.fontName = fontName
        case "h4": style.h4.fontName = fontName
        case "h5": style.h5.fontName = fontName
        case "h6": style.h6.fontName = fontName
        case "body": style.body.fontName = fontName
        case "quote": style.quote.fontName = fontName
        default: break
        }
    }
    
    func getCurrentFontName(key: String) -> String {
        switch key {
        case "h1": return style.h1.fontName
        case "h2": return style.h2.fontName
        case "h3": return style.h3.fontName
        case "h4": return style.h4.fontName
        case "h5": return style.h5.fontName
        case "h6": return style.h6.fontName
        case "body": return style.body.fontName
        case "quote": return style.quote.fontName
        default: return "system_default"
        }
    }
    
    func styleRow(label: String, key: String, config: Binding<MarkdownGlobalStyle.TextStyle>) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text(label).font(.headline).foregroundColor(.white)
                Spacer()
                Button {
                    activeConfigLabel = key
                    tempFontSelection = getCurrentFontName(key: key)
                    showFontPicker = true
                } label: {
                    HStack(spacing: 4) {
                        Text(displayFontName(config.wrappedValue.fontName))
                            .font(.caption)
                            .foregroundColor(.gray)
                        Image(systemName: "chevron.right").font(.caption2).foregroundColor(.gray)
                    }
                    .padding(6)
                    .background(Color.white.opacity(0.1))
                    .cornerRadius(6)
                }
            }
            
            HStack {
                let sizeBinding = Binding<Double>(
                    get: { Double(config.wrappedValue.size) },
                    set: { config.wrappedValue.size = CGFloat($0) }
                )
                Stepper("字号 \(Int(config.wrappedValue.size))", value: sizeBinding, in: 10.0...80.0)
                Toggle("加粗", isOn: config.isBold).labelsHidden()
            }
            
            // 颜色选择区域
            HStack(spacing: 12) {
                // 1. 预设圆球
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack {
                        ForEach(colorKeys, id: \.self) { colorKey in
                            Circle()
                                .fill(colors[colorKey] ?? .white)
                                .frame(width: 24, height: 24)
                                .overlay(
                                    Circle().stroke(Color.white, lineWidth: config.wrappedValue.color == colorKey ? 2 : 0)
                                )
                                .onTapGesture {
                                    config.wrappedValue.color = colorKey
                                }
                        }
                    }
                }
                .layoutPriority(1)
                
                // 2. Hex 输入框
                HStack(spacing: 4) {
                    Text("#")
                        .foregroundColor(.gray)
                        .font(.caption)
                    TextField("Hex", text: config.color)
                        .font(.system(size: 12, design: .monospaced))
                        .frame(width: 60)
                        .padding(4)
                        .background(Color.white.opacity(0.1))
                        .cornerRadius(4)
                }
            }
        }
        .padding(.vertical, 4)
    }
    
    func displayFontName(_ raw: String) -> String {
        switch raw {
        case "system_default", "system": return "系统默认"
        case "system_serif", "serif": return "系统衬线"
        case "system_rounded", "rounded": return "系统圆体"
        case "system_mono", "mono": return "系统等宽"
        default: return raw
        }
    }
}

// MARK: - 字体选择器 - v2 - 支持中文名显示与中文字体过滤
//
// struct FontSelectionSheet
// (修改内容：
//  1. [NEW] 引入 FontInfo 结构，同时存储字体的技术名称（用于保存）和本地化中文名称（用于显示）。
//  2. [Feature] 增加 onlyChineseFonts 开关。通过 CoreText 接口识别字体是否支持中文语言包。
//  3. [Feature] 列表显示逻辑升级：优先显示字体的中文名称。
//  4. [Logic] 优化搜索逻辑，支持通过中文名或英文名进行双向搜索。)

struct FontSelectionSheet: View {
    @Binding var selection: String
    @Environment(\.dismiss) var dismiss
    
    @State private var searchText = ""
    @State private var onlyChineseFonts = true // 默认开启中文字体过滤
    @State private var allFonts: [FontModel] = []
    
    // 字体模型
    struct FontModel: Identifiable, Equatable {
        let id: String         // 技术名称，如 "PingFangSC-Regular"
        let displayName: String // 本地化名称，如 "萍方"
        let isChinese: Bool    // 是否支持中文
    }
    
    // 系统预设风格
    let systemStyles = [
        ("system", "系统默认 (San Francisco)"),
        ("serif", "系统衬线 (New York)"),
        ("rounded", "系统圆体 (SF Rounded)"),
        ("mono", "系统等宽 (SF Mono)")
    ]
    
    var filteredFonts: [FontModel] {
        var base = allFonts
        if onlyChineseFonts {
            base = base.filter { $0.isChinese }
        }
        if !searchText.isEmpty {
            base = base.filter {
                $0.displayName.localizedCaseInsensitiveContains(searchText) ||
                $0.id.localizedCaseInsensitiveContains(searchText)
            }
        }
        return base.sorted { $0.displayName.localizedStandardCompare($1.displayName) == .orderedAscending }
    }
    
    var body: some View {
        NavigationStack {
            List {
                Section {
                    Toggle("仅显示中文字体", isOn: $onlyChineseFonts)
                        .tint(.blue)
                }
                
                Section(header: Text("预设风格")) {
                    ForEach(systemStyles, id: \.0) { key, name in
                        HStack {
                            Text(name)
                                .font(getPreviewFont(name: key))
                            Spacer()
                            if selection == key {
                                Image(systemName: "checkmark").foregroundColor(.blue)
                            }
                        }
                        .contentShape(Rectangle())
                        .onTapGesture {
                            selection = key
                            dismiss()
                        }
                    }
                }
                
                Section(header: Text(onlyChineseFonts ? "已安装的中文字体" : "所有已安装字体")) {
                    if allFonts.isEmpty {
                        HStack {
                            Spacer()
                            ProgressView("正在扫描系统字体...")
                            Spacer()
                        }
                    } else {
                        ForEach(filteredFonts) { font in
                            HStack {
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(font.displayName) // 显示中文名
                                        .font(.custom(font.id, size: 17))
                                    Text(font.id) // 副标题显示英文 ID
                                        .font(.system(size: 10, design: .monospaced))
                                        .foregroundColor(.gray)
                                }
                                Spacer()
                                if selection == font.id {
                                    Image(systemName: "checkmark").foregroundColor(.blue)
                                }
                            }
                            .contentShape(Rectangle())
                            .onTapGesture {
                                selection = font.id
                                dismiss()
                            }
                        }
                    }
                }
            }
            .ttSearchable(text: $searchText, prompt: "搜索字体名称...")
            .navigationTitle("选择字体")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { dismiss() }
                }
            }
            .onAppear {
                if allFonts.isEmpty {
                    loadFonts()
                }
            }
        }
    }
    
    // 核心逻辑：扫描并识别字体属性
    private func loadFonts() {
        DispatchQueue.global(qos: .userInitiated).async {
            var loadedFonts: [FontModel] = []
            let families = UIFont.familyNames
            
            for family in families {
                // 获取该族下的第一个字体名（通常是 Regular）
                let fontNames = UIFont.fontNames(forFamilyName: family)
                guard let firstFontName = fontNames.first else { continue }
                
                // 使用 CoreText 获取本地化名称
                let ctFont = CTFontCreateWithName(firstFontName as CFString, 12, nil)
                let localizedName = CTFontCopyLocalizedName(ctFont, kCTFontFamilyNameKey, nil) as String? ?? family
                
                // 识别是否支持中文
                // 原理：检查字体的语言属性列表
                let descriptor = CTFontCopyFontDescriptor(ctFont)
                let languages = CTFontDescriptorCopyAttribute(descriptor, kCTFontLanguagesAttribute) as? [String] ?? []
                let isChinese = languages.contains { $0.starts(with: "zh") }
                
                // 补充判定：如果名称本身包含汉字，也判定为中文字体
                let hasChineseInName = localizedName.range(of: "\\p{Han}", options: .regularExpression) != nil
                
                loadedFonts.append(FontModel(
                    id: firstFontName,
                    displayName: localizedName,
                    isChinese: isChinese || hasChineseInName
                ))
            }
            
            DispatchQueue.main.async {
                self.allFonts = loadedFonts
            }
        }
    }
    
    func getPreviewFont(name: String) -> Font {
        switch name {
        case "serif": return .system(size: 16, design: .serif)
        case "rounded": return .system(size: 16, design: .rounded)
        case "mono": return .system(size: 16, design: .monospaced)
        default: return .system(size: 16)
        }
    }
}


// MARK: - Markdown 目录视图 - v2 - 筛选与跳转
//
// struct MarkdownTOCSheet
// (修改：支持层级过滤，点击触发 onJump 回调)

struct MarkdownTOCSheet: View {
    let content: String
    // 【核心新增】跳转回调
    var onJump: (NSRange) -> Void
    
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var nodes: [MDNode] = []
    // 【核心新增】筛选层级状态
    @State private var maxLevel: Int = 3
    
    var filteredNodes: [MDNode] {
        if maxLevel >= 6 { return nodes }
        return nodes.filter { $0.level <= maxLevel }
    }
    
    var body: some View {
        NavigationStack {
            VStack(spacing: 0) {
                // 筛选栏
                Picker("显示层级", selection: $maxLevel) {
                    Text("H1").tag(1)
                    Text("H2").tag(2)
                    Text("H3").tag(3)
                    Text("全部").tag(6)
                }
                .pickerStyle(.segmented)
                .padding()
                
                List {
                    if filteredNodes.isEmpty {
                        Text("无符合条件的标题").foregroundColor(.gray)
                    } else {
                        ForEach(filteredNodes) { node in
                            HStack {
                                // 缩进模拟树状结构
                                if node.level > 1 {
                                    Spacer().frame(width: CGFloat(node.level - 1) * 16)
                                }
                                
                                Text(node.title)
                                    .font(.system(size: 16 - CGFloat(node.level), weight: node.level == 1 ? .bold : .regular))
                                    .foregroundColor(node.level == 1 ? .white : .white.opacity(0.8))
                                    .lineLimit(1)
                                
                                Spacer()
                                
                                Text("H\(node.level)").font(.caption2).foregroundColor(.gray).padding(4).background(Color.white.opacity(0.1)).cornerRadius(4)
                            }
                            .listRowBackground(Color.clear)
                            .contentShape(Rectangle())
                            // 【核心新增】点击跳转
                            .onTapGesture {
                                let range = NSRange(location: node.rangeLocation, length: node.rangeLength)
                                onJump(range)
                                dismiss()
                            }
                        }
                    }
                }
                .listStyle(.plain)
            }
            .navigationTitle("目录结构")
            .ttNavigationBarTitleDisplayMode(.inline)
            .background(Color.black.ignoresSafeArea())
            .onAppear {
                DispatchQueue.global(qos: .userInitiated).async {
                    let result = asStore.parseMarkdownStructure(content: content)
                    DispatchQueue.main.async {
                        self.nodes = result
                    }
                }
            }
        }
        .presentationDetents([.medium, .large])
    }
}

// MARK: - Markdown 编辑器主视图 - v108 - 适配原生 macOS 大屏判定

struct MarkdownEditorView: View {
