        }
        .ttNavigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItemGroup(placement: .primaryAction) {
                Button {
                    withAnimation { viewSettings.isDarkMode.toggle() }
                } label: {
                    Image(systemName: viewSettings.isDarkMode ? "moon.fill" : "sun.max.fill")
                        .foregroundColor(viewSettings.isDarkMode ? .yellow : .orange)
                }
