                Button { showTOC = true } label: { Image(systemName: "list.bullet.rectangle") }
                Menu {
                    Button { viewSettings.viewMode = .live } label: { Label("即时渲染", systemImage: viewSettings.viewMode == .live ? "checkmark" : "wand.and.stars") }
                    Button { viewSettings.viewMode = .code } label: { Label("源码模式", systemImage: viewSettings.viewMode == .code ? "checkmark" : "doc.plaintext") }
