                    if isLargeScreen {
                        Divider()
                        Button { viewSettings.viewMode = .split } label: { Label("分屏预览", systemImage: viewSettings.viewMode == .split ? "checkmark" : "rectangle.split.2x1") }
                    }
                } label: { Image(systemName: currentModeIcon).foregroundColor(currentModeColor) }
                Button { showExportDialog = true } label: { Image(systemName: "square.and.arrow.up").font(.system(size: 16, weight: .bold)) }
            }
        }
        .confirmationDialog("导出为...", isPresented: $showExportDialog, titleVisibility: .visible) {
            Button("Markdown (.md)") { exportMarkdown() }
            Button("长图 (.png)") { exportImage() }
            Button("PDF (.pdf)") { exportPDF() }
            Button("取消", role: .cancel) { }
        }
        .sheet(isPresented: $showPalette) {
            TTModalSheetContainer(minWidth: 720, minHeight: 560) {
                MarkdownPaletteView()
                    .environmentObject(asStore)
                    .onDisappear { globalStyle = asStore.loadMarkdownStyle() }
            }
        }
        .sheet(isPresented: $showTOC) {
            TTModalSheetContainer(minWidth: 820, minHeight: 680) {
                MarkdownTOCSheet(content: text) { range in self.scrollTarget = range }
                    .environmentObject(asStore)
            }
        }
        .background(ShareSheet(isPresented: $showShareSheet, items: shareItems))
        .onAppear { loadContent() }
        .onDisappear { saveContent(isSessionEnd: true) }
        .onReceive(autoSaveTimer) { _ in saveContent(isSessionEnd: false) }
        .onChange(of: viewSettings) { _, _ in saveSettings() }
    }
    
    @ViewBuilder
    var contentView: some View {
        let bgColor = viewSettings.isDarkMode ? Color.black : Color.white
        let codeBgColor = viewSettings.isDarkMode ? Color(white: 0.1) : Color(white: 0.96)
        
        switch viewSettings.viewMode {
        case .live:
            // 使用专用的即时渲染编辑器
            LiveMarkdownEditor(text: $text, tableID: table.id, style: globalStyle, isDarkMode: viewSettings.isDarkMode, scrollTarget: $scrollTarget, syncProgress: .constant(0), initialState: currentState, onStateChange: updateState)
                .background(codeBgColor)
        case .code:
            // 使用专用的源码模式编辑器
            SourceCodeEditor(text: $text, tableID: table.id, style: globalStyle, isDarkMode: viewSettings.isDarkMode, scrollTarget: $scrollTarget, syncProgress: .constant(0), initialState: currentState, onStateChange: updateState)
                .background(bgColor)
        case .preview:
            MarkdownPreviewView(text: text, isDarkMode: viewSettings.isDarkMode, style: globalStyle, syncProgress: nil).background(bgColor)
        case .split:
            HStack(spacing: 0) {
                // 左侧源码
                SourceCodeEditor(text: $text, tableID: table.id, style: globalStyle, isDarkMode: viewSettings.isDarkMode, scrollTarget: $scrollTarget, syncProgress: $syncScrollProgress, initialState: currentState, onStateChange: updateState)
                    .background(bgColor)
                Rectangle().fill(Color.gray.opacity(0.2)).frame(width: 1)
                // 右侧预览
                MarkdownPreviewView(text: text, isDarkMode: viewSettings.isDarkMode, style: globalStyle, syncProgress: syncScrollProgress).background(bgColor)
            }
        }
    }
    
    private var eyeIcon: String { "eye" }
    var currentModeIcon: String {
        switch viewSettings.viewMode {
        case .live: return "wand.and.stars"; case .code: return "doc.plaintext"; case .preview: return "eye"; case .split: return "rectangle.split.2x1"
        }
    }
    var currentModeColor: Color {
        let baseWhite = viewSettings.isDarkMode ? Color.white : Color.black
        switch viewSettings.viewMode {
        case .live: return .yellow; case .code: return baseWhite; case .preview: return baseWhite; case .split: return .cyan
        }
    }
    func updateState(newState: EditorViewState) { self.currentState = newState; let key = "md_state_\(table.id.uuidString)"; if let data = try? JSONEncoder().encode(newState) { UserDefaults.standard.set(data, forKey: key) } }
    func loadContent() { viewSettings = asStore.loadMarkdownSettings(); if !isLargeScreen && viewSettings.viewMode == .split { viewSettings.viewMode = .live }; globalStyle = asStore.loadMarkdownStyle(); if let firstRow = table.rows.first { text = asStore.unwrapMarkdownContent(firstRow.value) } else { text = "" }; initialText = text; asStore.editingTableID = table.id; let key = "md_state_\(table.id.uuidString)"; if let data = UserDefaults.standard.data(forKey: key), let saved = try? JSONDecoder().decode(EditorViewState.self, from: data) { self.currentState = saved } }
    func saveContent(isSessionEnd: Bool) { if text != initialText { let jsonStr = asStore.wrapMarkdownContent(text); var newTable = table; let row = ArchiveRow(id: table.rows.first?.id ?? UUID(), key: "content", value: jsonStr); newTable.rows = [row]; asStore.persistTableChanges(table: newTable, categoryID: getCategoryID(), oldTitle: table.title) }; if isSessionEnd { asStore.isUserEditing = false; if text != initialText { var finalTable = table; let row = ArchiveRow(id: table.rows.first?.id ?? UUID(), key: "content", value: asStore.wrapMarkdownContent(text)); finalTable.rows = [row]; if let data = try? JSONEncoder().encode(finalTable) { BackupManager.shared.saveBackup(data: data, module: "Archives", subID: table.id.uuidString) } } } }
    func saveSettings() { asStore.saveMarkdownSettings(viewSettings) }
    func exportMarkdown() { let fileName = "\(table.title).md"; let url = FileManager.default.temporaryDirectory.appendingPathComponent(fileName); try? text.write(to: url, atomically: true, encoding: .utf8); shareItems = [url]; showShareSheet = true }
    func exportImage() { isExporting = true; Task { @MainActor in try? await Task.sleep(nanoseconds: 100_000_000); if let url = asStore.generateImage(text: text, title: table.title) { shareItems = [url]; showShareSheet = true }; isExporting = false } }
    func exportPDF() { isExporting = true; Task { try? await Task.sleep(nanoseconds: 100_000_000); await MainActor.run { if let url = asStore.generatePDF(text: text, title: table.title) { shareItems = [url]; showShareSheet = true }; isExporting = false } } }
    func getCategoryID() -> UUID { if let cat = asStore.categories.first(where: { $0.tables.contains(where: { $0.id == table.id }) }) { return cat.id }; return UUID() }
}

// MARK: - 高性能排版管理器 - v12 - 适配 macOS
#if canImport(UIKit)
import UIKit
class HighPerfLayoutManager: NSLayoutManager {
    
    private var isDrawing = false
    
    override func drawBackground(forGlyphRange glyphsToShow: NSRange, at origin: CGPoint) {
        guard let textStorage = textStorage,
              let container = textContainers.first,
              !isDrawing else { return }
        
        if glyphsToShow.length > 10000 { return }
        
        isDrawing = true
        defer { isDrawing = false }
        
        let charRange = self.characterRange(forGlyphRange: glyphsToShow, actualGlyphRange: nil)
        if charRange.location == NSNotFound || charRange.length == 0 { return }
        
        let textLength = textStorage.length
        guard charRange.location < textLength else { return }
        let safeCharRange = NSRange(
            location: charRange.location,
            length: min(charRange.length, textLength - charRange.location)
        )
        
        if safeCharRange.length <= 0 { return }
        
        textStorage.enumerateAttribute(.backgroundColor, in: safeCharRange, options: [.longestEffectiveRangeNotRequired]) { (value, range, stop) in
            guard let color = value as? UIColor else { return }
            let glyphRange = self.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
            let invalidRange = NSRange(location: NSNotFound, length: 0)
            
            self.enumerateEnclosingRects(forGlyphRange: glyphRange, withinSelectedGlyphRange: invalidRange, in: container) { (rect, _) in
                if rect.height <= 0 || rect.width <= 0 { return }
                let paintRect = CGRect(x: rect.origin.x + origin.x - 2, y: rect.origin.y + origin.y + 1, width: rect.width + 4, height: rect.height - 2)
                let path = UIBezierPath(roundedRect: paintRect, cornerRadius: 5.0)
                color.setFill(); path.fill()
            }
        }
    }
}
#elseif canImport(AppKit)
import AppKit
class HighPerfLayoutManager: NSLayoutManager {
    
    private var isDrawing = false
    
    override func drawBackground(forGlyphRange glyphsToShow: NSRange, at origin: NSPoint) {
        guard let textStorage = textStorage,
              let container = textContainers.first,
              !isDrawing else { return }
        
        if glyphsToShow.length > 10000 { return }
        
        isDrawing = true
        defer { isDrawing = false }
        
        let charRange = self.characterRange(forGlyphRange: glyphsToShow, actualGlyphRange: nil)
        if charRange.location == NSNotFound || charRange.length == 0 { return }
        
        let textLength = textStorage.length
        guard charRange.location < textLength else { return }
        let safeCharRange = NSRange(
            location: charRange.location,
            length: min(charRange.length, textLength - charRange.location)
        )
        
        if safeCharRange.length <= 0 { return }
        
        textStorage.enumerateAttribute(.backgroundColor, in: safeCharRange, options: [.longestEffectiveRangeNotRequired]) { (value, range, stop) in
            guard let color = value as? NSColor else { return }
            let glyphRange = self.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
            let invalidRange = NSRange(location: NSNotFound, length: 0)
            
            self.enumerateEnclosingRects(forGlyphRange: glyphRange, withinSelectedGlyphRange: invalidRange, in: container) { (rect, _) in
                if rect.height <= 0 || rect.width <= 0 { return }
                let paintRect = CGRect(x: rect.origin.x + origin.x - 2, y: rect.origin.y + origin.y + 1, width: rect.width + 4, height: rect.height - 2)
                let path = NSBezierPath(roundedRect: paintRect, xRadius: 5.0, yRadius: 5.0)
                color.setFill(); path.fill()
            }
        }
    }
}
#endif

#if os(macOS)
final class MacMarkdownNSTextView: NSTextView {}

struct MarkdownTextEditor: NSViewRepresentable {
    @Binding var text: String
    let style: MarkdownGlobalStyle
    let isWordMode: Bool
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    @Binding var syncProgress: Double
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)? = nil

    func makeNSView(context: Context) -> NSScrollView {
        let textView = MacMarkdownNSTextView()
        textView.delegate = context.coordinator
        textView.drawsBackground = false
        textView.isRichText = false
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        textView.isAutomaticSpellingCorrectionEnabled = false
        textView.isAutomaticDataDetectionEnabled = false
        textView.isContinuousSpellCheckingEnabled = false
        textView.isGrammarCheckingEnabled = false
        textView.isHorizontallyResizable = false
        textView.isVerticallyResizable = true
        textView.autoresizingMask = [.width]
        textView.textContainerInset = NSSize(width: 15, height: 15)
        textView.font = .monospacedSystemFont(ofSize: 14, weight: .regular)
        textView.textColor = isDarkMode ? .white : .black
        textView.insertionPointColor = isDarkMode ? .white : .black
        textView.string = text
        
        let scrollView = NSScrollView()
        scrollView.drawsBackground = false
        scrollView.borderType = .noBorder
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = false
        scrollView.documentView = textView
        scrollView.contentView.postsBoundsChangedNotifications = true
        
        context.coordinator.attach(textView: textView, scrollView: scrollView)
        return scrollView
    }
    
    func updateNSView(_ nsView: NSScrollView, context: Context) {
        context.coordinator.parent = self
        guard let textView = nsView.documentView as? MacMarkdownNSTextView else { return }
        textView.textColor = isDarkMode ? .white : .black
        textView.insertionPointColor = isDarkMode ? .white : .black
        
        if !context.coordinator.hasRestored, let state = initialState {
            context.coordinator.hasRestored = true
            DispatchQueue.main.async {
                context.coordinator.restoreState(view: textView, state: state)
            }
        }
        
        let isFirstResponder = textView.window.map { $0.firstResponder === textView } ?? false
        if !isFirstResponder, textView.string != text {
            context.coordinator.isInternallyUpdating = true
            textView.string = text
            context.coordinator.isInternallyUpdating = false
        }
        
        if let target = scrollTarget, target.location + target.length <= textView.string.utf16.count {
            textView.setSelectedRange(target)
            textView.scrollRangeToVisible(target)
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
    }
    
    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }
    
    final class Coordinator: NSObject, NSTextViewDelegate {
        var parent: MarkdownTextEditor
        var isInternallyUpdating = false
        var hasRestored = false
        weak var activeTextView: MacMarkdownNSTextView?
        weak var activeScrollView: NSScrollView?
        
        init(_ parent: MarkdownTextEditor) {
            self.parent = parent
        }
        
        deinit {
            if let clipView = activeScrollView?.contentView {
                NotificationCenter.default.removeObserver(self, name: NSView.boundsDidChangeNotification, object: clipView)
            }
        }
        
        func attach(textView: MacMarkdownNSTextView, scrollView: NSScrollView) {
            activeTextView = textView
            activeScrollView = scrollView
            NotificationCenter.default.removeObserver(self, name: NSView.boundsDidChangeNotification, object: scrollView.contentView)
            NotificationCenter.default.addObserver(self, selector: #selector(boundsDidChange(_:)), name: NSView.boundsDidChangeNotification, object: scrollView.contentView)
        }
        
        @objc private func boundsDidChange(_ note: Notification) {
            guard let textView = activeTextView else { return }
            reportState(for: textView)
        }
        
        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? MacMarkdownNSTextView, !isInternallyUpdating else { return }
            parent.text = textView.string
            reportState(for: textView)
        }
        
        func textViewDidChangeSelection(_ notification: Notification) {
            guard let textView = notification.object as? MacMarkdownNSTextView else { return }
            reportState(for: textView)
        }
        
        func restoreState(view: MacMarkdownNSTextView, state: EditorViewState) {
            let maxLen = view.string.utf16.count
            let safeLoc = min(state.selectedLocation, maxLen)
            let safeLen = min(state.selectedLength, max(0, maxLen - safeLoc))
            let range = NSRange(location: safeLoc, length: safeLen)
            view.setSelectedRange(range)
            view.scrollRangeToVisible(range)
            if let scrollView = activeScrollView {
                let maxOffset = max(0, view.bounds.height - scrollView.contentView.bounds.height)
                scrollView.contentView.scroll(to: CGPoint(x: 0, y: min(state.offsetY, maxOffset)))
                scrollView.reflectScrolledClipView(scrollView.contentView)
            }
            reportState(for: view)
        }
        
        private func reportState(for textView: NSTextView) {
            let range = textView.selectedRange()
            let offsetY = activeScrollView?.contentView.bounds.origin.y ?? 0
            parent.onStateChange?(EditorViewState(selectedLocation: range.location, selectedLength: range.length, offsetY: offsetY))
        }
    }
}
#endif

// MARK: - 即时渲染编辑器组件 - v3 - 适配 macOS 编译与原生渲染
#if canImport(UIKit) && !os(macOS)
import UIKit
import SwiftUI
import PhotosUI

struct LiveMarkdownEditor: UIViewRepresentable {
    @Binding var text: String
    let tableID: UUID
    let style: MarkdownGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    @Binding var syncProgress: Double
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?
    
    func makeUIView(context: Context) -> UITextView {
        let textStorage = NSTextStorage()
        let layoutManager = HighPerfLayoutManager()
        textStorage.addLayoutManager(layoutManager)
        let textContainer = NSTextContainer(size: .zero)
        textContainer.widthTracksTextView = true
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 5
        layoutManager.addTextContainer(textContainer)
        
        let textView = UITextView(frame: .zero, textContainer: textContainer)
        textView.backgroundColor = .clear
        textView.isScrollEnabled = true
        textView.keyboardDismissMode = .onDrag
        textView.textContainerInset = UIEdgeInsets(top: 15, left: 15, bottom: 300, right: 15)
        textView.delegate = context.coordinator
        
        textView.dataDetectorTypes = []
        textView.autocapitalizationType = .none
        textView.autocorrectionType = .no
        textView.smartQuotesType = .no
        textView.smartDashesType = .no
        
        let toolbar = UIToolbar(frame: CGRect(x: 0, y: 0, width: UIScreen.mainSafe.bounds.width, height: 44))
        let flex = UIBarButtonItem(barButtonSystemItem: .flexibleSpace, target: nil, action: nil)
        let done = UIBarButtonItem(title: "收起", style: .done, target: context.coordinator, action: #selector(context.coordinator.dismissKeyboard))
        toolbar.items = [flex, done]
        textView.inputAccessoryView = toolbar
        
        if !text.isEmpty {
            textView.text = text
            context.coordinator.applyLiveHighlightingSync(for: textView)
        }
        
        if let state = initialState { context.coordinator.pendingRestoreState = state }
        return textView
    }
    
    func updateUIView(_ uiView: UITextView, context: Context) {
        context.coordinator.parent = self
        
        if uiView.isFirstResponder {
            if context.coordinator.currentIsDarkMode != isDarkMode || context.coordinator.currentStyle != style {
                context.coordinator.currentStyle = style
                context.coordinator.currentIsDarkMode = isDarkMode
                context.coordinator.applyLiveHighlightingSync(for: uiView)
            }
            return
        }
        
        if text != uiView.text {
            context.coordinator.isInternallyUpdating = true
            uiView.text = text
            context.coordinator.applyLiveHighlightingSync(for: uiView)
            context.coordinator.isInternallyUpdating = false
        }
        
        if let target = scrollTarget {
            if target.location < uiView.text.utf16.count {
                DispatchQueue.main.async { uiView.scrollRangeToVisible(target) }
            }
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
        
        if let pendingState = context.coordinator.pendingRestoreState {
            context.coordinator.isInternallyUpdating = true
            context.coordinator.restoreState(view: uiView, state: pendingState)
            context.coordinator.pendingRestoreState = nil
            context.coordinator.isInternallyUpdating = false
        }
    }
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UITextViewDelegate, PHPickerViewControllerDelegate, UIDocumentPickerDelegate {
        var parent: LiveMarkdownEditor
        var pendingRestoreState: EditorViewState? = nil
        var isInternallyUpdating = false
        var currentStyle: MarkdownGlobalStyle
        var currentIsDarkMode: Bool
        
        private var stateReportWorkItem: DispatchWorkItem?
        private weak var activeTextView: UITextView?
        
        init(_ parent: LiveMarkdownEditor) {
            self.parent = parent
            self.currentStyle = parent.style
            self.currentIsDarkMode = parent.isDarkMode
        }
        
        @objc func dismissKeyboard() { UIApplication.shared.sendAction(#selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil) }
        
        private func findViewController() -> UIViewController? {
            return UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.flatMap { $0.windows }.first { $0.isKeyWindow }?.rootViewController
        }
        
        func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool {
            if isInternallyUpdating { return true }
            if text.isEmpty {
                let nsString = (textView.text ?? "") as NSString
                if range.location + range.length <= nsString.length {
                    let lineRange = nsString.lineRange(for: range)
                    let lineContent = nsString.substring(with: lineRange)
                    if let assetID = extractAssetID(from: lineContent) {
                        UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
                        MarkdownAssetManager.shared.deleteSingleAsset(assetID: assetID)
                        let originalDelegate = textView.delegate
                        textView.delegate = nil
                        textView.textStorage.replaceCharacters(in: lineRange, with: "")
                        textView.delegate = originalDelegate
                        self.parent.text = textView.text
                        return false
                    }
                }
            }
            return true
        }

        func textViewDidChange(_ textView: UITextView) {
            if textView.markedTextRange != nil { return }
            _ = applyMarkReplacement(textView: textView)
            parent.text = textView.text ?? ""
            applyLiveHighlightingSync(for: textView)
        }
        
        private func extractAssetID(from text: String) -> String? {
            let pattern = "!\\[.*?\\]\\(asset:([\\w\\.-]+\\.jpg)\\)"
            guard let regex = try? NSRegularExpression(pattern: pattern, options:[]) else { return nil }
            if let match = regex.firstMatch(in: text, options:[], range: NSRange(location: 0, length: text.utf16.count)) {
                return (text as NSString).substring(with: match.range(at: 1))
            }
            return nil
        }
        
        private func applyMarkReplacement(textView: UITextView) -> Bool {
            guard let selectedRange = textView.selectedTextRange else { return false }
            let cursorPosition = textView.offset(from: textView.beginningOfDocument, to: selectedRange.start)
            let fullText = textView.text ?? ""
            let nsString = fullText as NSString
            if cursorPosition < 2 { return false }
            let lastTwoRange = NSRange(location: cursorPosition - 2, length: 2)
            if lastTwoRange.location + lastTwoRange.length > nsString.length { return false }
            if nsString.substring(with: lastTwoRange) != "==" { return false }
            let searchStart = max(0, cursorPosition - 200)
            let searchLen = cursorPosition - searchStart
            let searchStr = nsString.substring(with: NSRange(location: searchStart, length: searchLen))
            guard let regex = try? NSRegularExpression(pattern: "==([^=]+)==$", options:[]) else { return false }
            if let match = regex.firstMatch(in: searchStr, options:[], range: NSRange(location: 0, length: searchStr.utf16.count)) {
                let matchRangeInFull = NSRange(location: searchStart + match.range.location, length: match.range.length)
                let contentRangeInSearch = match.range(at: 1)
                let content = (searchStr as NSString).substring(with: contentRangeInSearch)
                let replacement = "<mark>\(content)</mark>"
                isInternallyUpdating = true
                let originalDelegate = textView.delegate
                textView.delegate = nil
                textView.textStorage.replaceCharacters(in: matchRangeInFull, with: replacement)
                textView.delegate = originalDelegate
                isInternallyUpdating = false
                return true
            }
            return false
        }
        
        func textViewDidChangeSelection(_ textView: UITextView) {
            guard !isInternallyUpdating else { return }
            if textView.selectedRange.length < 3000 { scheduleStateReport(textView) }
        }
        
        func scrollViewDidEndDecelerating(_ scrollView: UIScrollView) { reportScrollProgress(scrollView); if let tv = scrollView as? UITextView { scheduleStateReport(tv) } }
        func scrollViewDidEndDragging(_ scrollView: UIScrollView, willDecelerate decelerate: Bool) { if !decelerate { reportScrollProgress(scrollView); if let tv = scrollView as? UITextView { scheduleStateReport(tv) } } }
        
        private func scheduleStateReport(_ textView: UITextView) {
            stateReportWorkItem?.cancel()
            let item = DispatchWorkItem { [weak self, weak textView] in
                guard let self = self, let tv = textView else { return }
                let state = EditorViewState(selectedLocation: tv.selectedRange.location, selectedLength: tv.selectedRange.length, offsetY: tv.contentOffset.y)
                DispatchQueue.main.async { self.parent.onStateChange?(state) }
            }
            stateReportWorkItem = item
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0, execute: item)
        }
        
        private func reportScrollProgress(_ scrollView: UIScrollView) {
            let total = scrollView.contentSize.height; let visible = scrollView.bounds.height
            guard total > visible else { parent.syncProgress = 0; return }
            let progress = max(0.0, min(1.0, scrollView.contentOffset.y / (total - visible)))
            DispatchQueue.main.async { self.parent.syncProgress = progress }
        }
        
        func applyLiveHighlightingSync(for textView: UITextView) {
            let storage = textView.textStorage
            let contentString = storage.string
            let fullRange = NSRange(location: 0, length: storage.length)
            if fullRange.length == 0 { return }

            storage.beginEditing()
            let baseFont = getUIFont(style: currentStyle.body)
            storage.setAttributes([.font: baseFont, .foregroundColor: getAdaptiveColor(hex: currentStyle.body.color, isDarkMode: currentIsDarkMode)], range: fullRange)
            
            let headerRules:[(String, MarkdownGlobalStyle.TextStyle)] = [
                ("^#\\s.*$", currentStyle.h1), ("^##\\s.*$", currentStyle.h2), ("^###\\s.*$", currentStyle.h3),
                ("^####\\s.*$", currentStyle.h4), ("^#####\\s.*$", currentStyle.h5), ("^######\\s.*$", currentStyle.h6)
            ]
            for (p, h) in headerRules {
                applyRegexToStorage(pattern: p, text: contentString, storage: storage) { _ in[.foregroundColor: self.getAdaptiveColor(hex: h.color, isDarkMode: self.currentIsDarkMode), .font: self.getUIFont(style: h)]
                }
            }
            
            let boldColor = currentIsDarkMode ? UIColor.systemOrange : UIColor.orange
            applyRegexToStorage(pattern: "\\*\\*.*?\\*\\*", text: contentString, storage: storage) { matchRange in
                let existingFont = storage.attribute(.font, at: matchRange.location, effectiveRange: nil) as? UIFont ?? baseFont
                let boldFont: UIFont
                if let descriptor = existingFont.fontDescriptor.withSymbolicTraits(.traitBold) { boldFont = UIFont(descriptor: descriptor, size: existingFont.pointSize) } else { boldFont = existingFont }
                return[.foregroundColor: boldColor, .font: boldFont]
            }
            
            applyRegexToStorage(pattern: "!\\[.*?\\]\\(asset:[\\w\\.-]+\\.jpg\\)", text: contentString, storage: storage) { _ in[.foregroundColor: self.currentIsDarkMode ? UIColor.systemCyan : UIColor.systemBlue] }
            applyRegexToStorage(pattern: "^>\\s.*$", text: contentString, storage: storage) { _ in[.foregroundColor: self.getRawColor(hex: self.currentStyle.quote.color)] }
            applyRegexToStorage(pattern: "<mark>.*?</mark>", text: contentString, storage: storage) { _ in[.backgroundColor: self.currentIsDarkMode ? UIColor.systemYellow.withAlphaComponent(0.3) : UIColor.systemYellow.withAlphaComponent(0.4)] }
            
            storage.endEditing()
        }
        
        private func applyRegexToStorage(pattern: String, text: String, storage: NSTextStorage, attrProvider: (NSRange) -> [NSAttributedString.Key: Any]) {
            guard let regex = try? NSRegularExpression(pattern: pattern, options: [.anchorsMatchLines]) else { return }
            let results = regex.matches(in: text, options:[], range: NSRange(location: 0, length: (text as NSString).length))
            for m in results { storage.addAttributes(attrProvider(m.range), range: m.range) }
        }

        func getAdaptiveColor(hex: String, isDarkMode: Bool) -> UIColor { if isDarkMode { return getRawColor(hex: hex) } else { if hex == "white" { return .black }; if hex == "gray" { return .darkGray }; if hex == "yellow" { return .systemOrange }; return getRawColor(hex: hex) } }
        func getRawColor(hex: String) -> UIColor { switch hex { case "white": return .white; case "gray": return .gray; case "red": return .systemRed; case "orange": return .systemOrange; case "yellow": return .systemYellow; case "green": return .systemGreen; case "blue": return .systemBlue; case "purple": return .systemPurple; case "cyan": return .systemCyan; default: return UIColor(hexString: hex) ?? .white } }
        func getUIFont(style: MarkdownGlobalStyle.TextStyle) -> UIFont { let size = style.size; let weight: UIFont.Weight = style.isBold ? .bold : .regular; switch style.fontName { case "system_serif", "serif": return UIFont.systemFont(ofSize: size, weight: weight).with(design: .serif) ?? .systemFont(ofSize: size, weight: weight); case "system_mono", "mono": return UIFont.monospacedSystemFont(ofSize: size, weight: weight); case "system_rounded", "rounded": return UIFont.systemFont(ofSize: size, weight: weight).with(design: .rounded) ?? .systemFont(ofSize: size, weight: weight); default: return UIFont.systemFont(ofSize: size, weight: weight) } }
        func restoreState(view: UITextView, state: EditorViewState) { let totalLen = view.text.utf16.count; let safeLoc = min(state.selectedLocation, totalLen); let safeLen = min(state.selectedLength, totalLen - safeLoc); view.selectedRange = NSRange(location: safeLoc, length: safeLen); if safeLoc > 0 || safeLen > 0 { view.scrollRangeToVisible(view.selectedRange) } else { let maxOffset = max(0, view.contentSize.height - view.bounds.height); view.setContentOffset(CGPoint(x: 0, y: min(state.offsetY, maxOffset)), animated: false) } }
        func picker(_ picker: PHPickerViewController, didFinishPicking results: [PHPickerResult]) { picker.dismiss(animated: true); guard let provider = results.first?.itemProvider, provider.canLoadObject(ofClass: UIImage.self) else { return }; provider.loadObject(ofClass: UIImage.self) { [weak self] image, _ in if let uiImage = image as? UIImage { DispatchQueue.main.async { self?.handleImageImport(uiImage) } } } }
        func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls:[URL]) { guard let url = urls.first, let data = try? Data(contentsOf: url), let image = UIImage(data: data) else { return }; handleImageImport(image) }
        private func handleImageImport(_ image: UIImage) { guard let assetID = MarkdownAssetManager.shared.saveImage(image, tableID: parent.tableID) else { return }; let tag = "\n![图片](asset:\(assetID))\n"; if let tv = activeTextView { self.isInternallyUpdating = true; if let range = tv.selectedTextRange { tv.replace(range, withText: tag) } else { tv.insertText(tag) }; parent.text = tv.text; self.isInternallyUpdating = false } else { parent.text.append(tag) }; UIImpactFeedbackGenerator(style: .medium).impactOccurred(); applyLiveHighlightingSync(for: activeTextView ?? UITextView()) }
        func textView(_ textView: UITextView, editMenuForTextIn range: NSRange, suggestedActions: [UIMenuElement]) -> UIMenu? { var actions = suggestedActions; let photoAction = UIAction(title: "插入相册图片", image: UIImage(systemName: "photo.on.rectangle")) { _ in self.activeTextView = textView; self.presentPhotoPicker() }; let fileAction = UIAction(title: "插入文件夹图片", image: UIImage(systemName: "folder")) { _ in self.activeTextView = textView; self.presentFilePicker() }; actions.append(UIMenu(title: "多媒体", image: UIImage(systemName: "plus.square"), children: [photoAction, fileAction])); return UIMenu(children: actions) }
        private func presentPhotoPicker() { var config = PHPickerConfiguration(); config.filter = .images; config.selectionLimit = 1; let picker = PHPickerViewController(configuration: config); picker.delegate = self; findViewController()?.present(picker, animated: true) }
        private func presentFilePicker() { let picker = UIDocumentPickerViewController(forOpeningContentTypes: [.image]); picker.delegate = self; findViewController()?.present(picker, animated: true) }
    }
}
#elseif canImport(AppKit)
import SwiftUI
import AppKit

struct LiveMarkdownEditor: NSViewRepresentable {
    @Binding var text: String
    let tableID: UUID
    let style: MarkdownGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    @Binding var syncProgress: Double
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?
    
    func makeNSView(context: Context) -> NSScrollView {
        let scrollView = NSScrollView()
        scrollView.hasVerticalScroller = true
        scrollView.autohidesScrollers = true
        scrollView.borderType = .noBorder
        scrollView.drawsBackground = false
        scrollView.backgroundColor = .clear
        
        let layoutManager = HighPerfLayoutManager()
        let textContainer = NSTextContainer(containerSize: NSSize(width: 0, height: CGFloat.greatestFiniteMagnitude))
        textContainer.widthTracksTextView = true
        textContainer.lineFragmentPadding = 5
        layoutManager.addTextContainer(textContainer)
        
        let textStorage = NSTextStorage()
        textStorage.addLayoutManager(layoutManager)
        
        let textView = NSTextView(frame: .zero, textContainer: textContainer)
        textView.autoresizingMask = [.width]
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.backgroundColor = .clear
        textView.isRichText = false
        textView.allowsUndo = true
        textView.textContainerInset = NSSize(width: 15, height: 15)
        textView.delegate = context.coordinator
        
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        
        scrollView.documentView = textView
        
        if !text.isEmpty {
            textView.string = text
            context.coordinator.applyLiveHighlightingSync(for: textView)
        }
        
        if let state = initialState {
            context.coordinator.pendingRestoreState = state
        }
        
        NotificationCenter.default.addObserver(context.coordinator, selector: #selector(Coordinator.boundsDidChange(_:)), name: NSView.boundsDidChangeNotification, object: scrollView.contentView)
        scrollView.contentView.postsBoundsChangedNotifications = true
        
        return scrollView
    }
    
    func updateNSView(_ scrollView: NSScrollView, context: Context) {
        guard let textView = scrollView.documentView as? NSTextView else { return }
        context.coordinator.parent = self
        
        let isFirstResponder = textView.window?.firstResponder == textView
        
        if isFirstResponder {
            if context.coordinator.currentIsDarkMode != isDarkMode || context.coordinator.currentStyle != style {
                context.coordinator.currentStyle = style
                context.coordinator.currentIsDarkMode = isDarkMode
                context.coordinator.applyLiveHighlightingSync(for: textView)
            }
            return
        }
        
        if text != textView.string {
            context.coordinator.isInternallyUpdating = true
            textView.string = text
            context.coordinator.applyLiveHighlightingSync(for: textView)
            context.coordinator.isInternallyUpdating = false
        }
        
        if let target = scrollTarget {
            if target.location < textView.string.utf16.count {
                DispatchQueue.main.async { textView.scrollRangeToVisible(target) }
            }
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
        
        if let pendingState = context.coordinator.pendingRestoreState {
            context.coordinator.isInternallyUpdating = true
            context.coordinator.restoreState(view: textView, state: pendingState)
            context.coordinator.pendingRestoreState = nil
            context.coordinator.isInternallyUpdating = false
        }
    }
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, NSTextViewDelegate {
        var parent: LiveMarkdownEditor
        var pendingRestoreState: EditorViewState? = nil
        var isInternallyUpdating = false
        var currentStyle: MarkdownGlobalStyle
        var currentIsDarkMode: Bool
        weak var activeTextView: NSTextView?
        
        private var stateReportWorkItem: DispatchWorkItem?
        
        init(_ parent: LiveMarkdownEditor) {
            self.parent = parent
            self.currentStyle = parent.style
            self.currentIsDarkMode = parent.isDarkMode
        }
        
        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            if isInternallyUpdating { return }
            _ = applyMarkReplacement(textView: textView)
            parent.text = textView.string
            applyLiveHighlightingSync(for: textView)
        }
        
        private func applyMarkReplacement(textView: NSTextView) -> Bool {
            let selectedRange = textView.selectedRange()
            let cursorPosition = selectedRange.location
            let fullText = textView.string
            let nsString = fullText as NSString
            if cursorPosition < 2 || cursorPosition > nsString.length { return false }
            let lastTwoRange = NSRange(location: cursorPosition - 2, length: 2)
            if nsString.substring(with: lastTwoRange) != "==" { return false }
            let searchStart = max(0, cursorPosition - 200)
            let searchLen = cursorPosition - searchStart
            let searchStr = nsString.substring(with: NSRange(location: searchStart, length: searchLen))
            guard let regex = try? NSRegularExpression(pattern: "==([^=]+)==$", options:[]) else { return false }
            if let match = regex.firstMatch(in: searchStr, options:[], range: NSRange(location: 0, length: searchStr.utf16.count)) {
                let matchRangeInFull = NSRange(location: searchStart + match.range.location, length: match.range.length)
                let contentRangeInSearch = match.range(at: 1)
                let content = (searchStr as NSString).substring(with: contentRangeInSearch)
                let replacement = "<mark>\(content)</mark>"
                isInternallyUpdating = true
                if let ts = textView.textStorage {
                    ts.replaceCharacters(in: matchRangeInFull, with: replacement)
                }
                isInternallyUpdating = false
                return true
            }
            return false
        }
        
        func textViewDidChangeSelection(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            guard !isInternallyUpdating else { return }
            if textView.selectedRange().length < 3000 { scheduleStateReport(textView) }
        }
        
        @objc func boundsDidChange(_ notification: Notification) {
            guard let clipView = notification.object as? NSClipView,
                  let scrollView = clipView.enclosingScrollView,
                  let textView = scrollView.documentView as? NSTextView else { return }
            reportScrollProgress(scrollView)
            scheduleStateReport(textView)
        }
        
        private func scheduleStateReport(_ textView: NSTextView) {
            stateReportWorkItem?.cancel()
            let item = DispatchWorkItem {[weak self, weak textView] in
                guard let self = self, let tv = textView, let scrollView = tv.enclosingScrollView else { return }
                let offsetY = scrollView.contentView.bounds.origin.y
                let state = EditorViewState(selectedLocation: tv.selectedRange().location, selectedLength: tv.selectedRange().length, offsetY: offsetY)
                DispatchQueue.main.async { self.parent.onStateChange?(state) }
            }
            stateReportWorkItem = item
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.0, execute: item)
        }
        
        private func reportScrollProgress(_ scrollView: NSScrollView) {
            guard let documentView = scrollView.documentView else { return }
            let total = documentView.bounds.height
            let visible = scrollView.contentView.bounds.height
            guard total > visible else { parent.syncProgress = 0; return }
            let progress = max(0.0, min(1.0, scrollView.contentView.bounds.origin.y / (total - visible)))
            DispatchQueue.main.async { self.parent.syncProgress = progress }
        }
        
        func applyLiveHighlightingSync(for textView: NSTextView) {
            guard let storage = textView.textStorage else { return }
            let contentString = storage.string
            let fullRange = NSRange(location: 0, length: storage.length)
            if fullRange.length == 0 { return }

            storage.beginEditing()
            let baseFont = getNSFont(style: currentStyle.body)
            storage.setAttributes([.font: baseFont, .foregroundColor: getAdaptiveColor(hex: currentStyle.body.color, isDarkMode: currentIsDarkMode)], range: fullRange)
            
            let headerRules: [(String, MarkdownGlobalStyle.TextStyle)] = [
                ("^#\\s.*$", currentStyle.h1), ("^##\\s.*$", currentStyle.h2), ("^###\\s.*$", currentStyle.h3),
                ("^####\\s.*$", currentStyle.h4), ("^#####\\s.*$", currentStyle.h5), ("^######\\s.*$", currentStyle.h6)
            ]
            for (p, h) in headerRules {
                applyRegexToStorage(pattern: p, text: contentString, storage: storage) { _ in[.foregroundColor: self.getAdaptiveColor(hex: h.color, isDarkMode: self.currentIsDarkMode), .font: self.getNSFont(style: h)]
                }
            }
            
            let boldColor = currentIsDarkMode ? NSColor.systemOrange : NSColor.orange
            applyRegexToStorage(pattern: "\\*\\*.*?\\*\\*", text: contentString, storage: storage) { matchRange in
                let existingFont = storage.attribute(.font, at: matchRange.location, effectiveRange: nil) as? NSFont ?? baseFont
                let boldFont = NSFontManager.shared.convert(existingFont, toHaveTrait: .boldFontMask)
                return[.foregroundColor: boldColor, .font: boldFont]
            }
            
            applyRegexToStorage(pattern: "!\\[.*?\\]\\(asset:[\\w\\.-]+\\.jpg\\)", text: contentString, storage: storage) { _ in[.foregroundColor: self.currentIsDarkMode ? NSColor.systemCyan : NSColor.systemBlue] }
            applyRegexToStorage(pattern: "^>\\s.*$", text: contentString, storage: storage) { _ in[.foregroundColor: self.getRawColor(hex: self.currentStyle.quote.color)] }
            applyRegexToStorage(pattern: "<mark>.*?</mark>", text: contentString, storage: storage) { _ in[.backgroundColor: self.currentIsDarkMode ? NSColor.systemYellow.withAlphaComponent(0.3) : NSColor.systemYellow.withAlphaComponent(0.4)] }
            
            storage.endEditing()
        }
        
        private func applyRegexToStorage(pattern: String, text: String, storage: NSTextStorage, attrProvider: (NSRange) ->[NSAttributedString.Key: Any]) {
            guard let regex = try? NSRegularExpression(pattern: pattern, options:[.anchorsMatchLines]) else { return }
            let results = regex.matches(in: text, options:[], range: NSRange(location: 0, length: (text as NSString).length))
            for m in results { storage.addAttributes(attrProvider(m.range), range: m.range) }
        }

        func getAdaptiveColor(hex: String, isDarkMode: Bool) -> NSColor { if isDarkMode { return getRawColor(hex: hex) } else { if hex == "white" { return .black }; if hex == "gray" { return .darkGray }; if hex == "yellow" { return .systemOrange }; return getRawColor(hex: hex) } }
        
        func getRawColor(hex: String) -> NSColor { switch hex { case "white": return .white; case "gray": return .gray; case "red": return .systemRed; case "orange": return .systemOrange; case "yellow": return .systemYellow; case "green": return .systemGreen; case "blue": return .systemBlue; case "purple": return .systemPurple; case "cyan": return .systemCyan; default: return NSColor(hexString: hex) ?? .white } }
        
        func getNSFont(style: MarkdownGlobalStyle.TextStyle) -> NSFont {
            let size = style.size
            let weight: NSFont.Weight = style.isBold ? .bold : .regular
            switch style.fontName {
            case "system_serif", "serif":
                let desc = NSFont.systemFont(ofSize: size, weight: weight).fontDescriptor.withDesign(.serif)
                return desc != nil ? NSFont(descriptor: desc!, size: size) ?? NSFont.systemFont(ofSize: size, weight: weight) : NSFont.systemFont(ofSize: size, weight: weight)
            case "system_mono", "mono":
                return NSFont.monospacedSystemFont(ofSize: size, weight: weight)
            case "system_rounded", "rounded":
                let desc = NSFont.systemFont(ofSize: size, weight: weight).fontDescriptor.withDesign(.rounded)
                return desc != nil ? NSFont(descriptor: desc!, size: size) ?? NSFont.systemFont(ofSize: size, weight: weight) : NSFont.systemFont(ofSize: size, weight: weight)
            default:
                return NSFont.systemFont(ofSize: size, weight: weight)
            }
        }
        
        func restoreState(view: NSTextView, state: EditorViewState) {
            let totalLen = view.string.utf16.count
            let safeLoc = min(state.selectedLocation, totalLen)
            let safeLen = min(state.selectedLength, totalLen - safeLoc)
            view.setSelectedRange(NSRange(location: safeLoc, length: safeLen))
            if safeLoc > 0 || safeLen > 0 {
                view.scrollRangeToVisible(NSRange(location: safeLoc, length: safeLen))
            } else if let scrollView = view.enclosingScrollView, let documentView = scrollView.documentView {
                let maxOffset = max(0, documentView.bounds.height - scrollView.contentView.bounds.height)
                let newOrigin = NSPoint(x: 0, y: min(state.offsetY, maxOffset))
                scrollView.contentView.scroll(to: newOrigin)
                scrollView.reflectScrolledClipView(scrollView.contentView)
            }
        }
        
        func textView(_ view: NSTextView, menu: NSMenu, for event: NSEvent, at charIndex: Int) -> NSMenu? {
            activeTextView = view
            let insertItem = NSMenuItem(title: "插入图片...", action: #selector(presentFilePicker), keyEquivalent: "")
            insertItem.target = self
            menu.addItem(NSMenuItem.separator())
            menu.addItem(insertItem)
            return menu
        }
        
        @objc private func presentFilePicker() {
            let panel = NSOpenPanel()
            panel.allowedContentTypes = [.image]
            panel.allowsMultipleSelection = false
            if panel.runModal() == .OK, let url = panel.url, let image = NSImage(contentsOf: url),
               let assetID = MarkdownAssetManager.shared.saveImage(image, tableID: parent.tableID) {
                let tag = "\n![图片](asset:\(assetID))\n"
                self.isInternallyUpdating = true
                if let tv = activeTextView ?? (NSApp.keyWindow?.firstResponder as? NSTextView) {
                    let range = tv.selectedRange()
                    tv.insertText(tag, replacementRange: range)
                    parent.text = tv.string
                    applyLiveHighlightingSync(for: tv)
                }
                self.isInternallyUpdating = false
            }
        }
    }
}
#endif

// MARK: - 源码模式编辑器组件 - v3 - 适配 macOS 编译与原生渲染
#if canImport(UIKit) && !os(macOS)
import UIKit
