// MARK: - 编辑器状态模型 - v1
struct EditorViewState: Codable, Equatable {
    var selectedLocation: Int
    var selectedLength: Int
    var offsetY: CGFloat
    
    // 默认初始状态
    static let zero = EditorViewState(selectedLocation: 0, selectedLength: 0, offsetY: 0)
}

// MARK: - Markdown 核心编辑器引擎 - v22 - 状态恢复与保持
//
// MarkdownTextEditor
// (修改：
//  1. [恢复] 增加 initialState 参数，在视图加载完成后尝试恢复光标和滚动位置。
//  2. [汇报] 增加 onStateChange 回调，当光标移动或滚动停止时汇报状态。
//  3. [逻辑] 优先 scrollRangeToVisible 光标，其次 setContentOffset。)

#if os(iOS)
struct MarkdownTextEditor: UIViewRepresentable {
    @Binding var text: String
    let style: MarkdownGlobalStyle
    let isWordMode: Bool
    let isDarkMode: Bool
    
    // 滚动同步 (分屏用)
    @Binding var scrollTarget: NSRange?
    @Binding var syncProgress: Double
    
    // 【新增】状态恢复与保存
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?
    
    func makeUIView(context: Context) -> UITextView {
        let textView = UITextView()
        textView.backgroundColor = .clear
        textView.textColor = isDarkMode ? .white : .black
        textView.font = UIFont.monospacedSystemFont(ofSize: 16, weight: .regular)
        textView.delegate = context.coordinator
        textView.isScrollEnabled = true
        textView.textContainerInset = UIEdgeInsets(top: 15, left: 15, bottom: 300, right: 15)
        
        let toolbar = UIToolbar(frame: CGRect(x: 0, y: 0, width: UIScreen.mainSafe.bounds.width, height: 44))
        let flex = UIBarButtonItem(barButtonSystemItem: .flexibleSpace, target: nil, action: nil)
        let done = UIBarButtonItem(title: "收起", style: .done, target: context.coordinator, action: #selector(context.coordinator.dismissKeyboard))
        toolbar.items = [flex, done]
        textView.inputAccessoryView = toolbar
        
        return textView
    }
    
    func updateUIView(_ uiView: UITextView, context: Context) {
        let textChanged = uiView.text != text
        let modeChanged = context.coordinator.lastIsWordMode != isWordMode
        let styleChanged = context.coordinator.lastStyle != style
        let themeChanged = context.coordinator.lastIsDarkMode != isDarkMode
        
        if textChanged || modeChanged || styleChanged || themeChanged {
            if textChanged { uiView.text = text }
            
            context.coordinator.lastIsWordMode = isWordMode
            context.coordinator.lastStyle = style
            context.coordinator.lastIsDarkMode = isDarkMode
            
            uiView.textColor = isDarkMode ? .white : .black
            
            // 如果是首次加载且有初始状态，进行恢复
            if !context.coordinator.hasRestoredState, let state = initialState, !text.isEmpty {
                context.coordinator.restoreState(view: uiView, state: state)
            }
            
            if !uiView.isFirstResponder || modeChanged || styleChanged || themeChanged {
                context.coordinator.updateStyle(uiView, style: style, isWordMode: isWordMode, isDarkMode: isDarkMode)
            }
        }
        
        if let target = scrollTarget {
            if target.location < uiView.text.utf16.count {
                DispatchQueue.main.async {
                    uiView.scrollRangeToVisible(target)
                    uiView.selectedRange = target
                }
            }
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
    }
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UITextViewDelegate {
        var parent: MarkdownTextEditor
        var isUpdating = false
        var lastIsWordMode: Bool = false
        var lastStyle: MarkdownGlobalStyle = MarkdownGlobalStyle()
        var lastIsDarkMode: Bool = true
        
        // 【新增】标记是否已恢复过状态，防止反复跳转
        var hasRestoredState: Bool = false
        
        init(_ parent: MarkdownTextEditor) { self.parent = parent }
        
        @objc func dismissKeyboard() { UIApplication.shared.sendAction(#selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil) }
        
        // MARK: - 状态恢复核心逻辑
        func restoreState(view: UITextView, state: EditorViewState) {
            hasRestoredState = true
            
            // 确保布局已完成，否则滚动可能不准确
            DispatchQueue.main.async {
                // 1. 恢复光标
                let totalLen = view.text.utf16.count
                let safeLoc = min(state.selectedLocation, totalLen)
                let safeLen = min(state.selectedLength, totalLen - safeLoc)
                let targetRange = NSRange(location: safeLoc, length: safeLen)
                
                view.selectedRange = targetRange
                
                // 2. 决定视野
                // 如果光标不在开头，或者有选区，优先展示光标
                if safeLoc > 0 || safeLen > 0 {
                    view.scrollRangeToVisible(targetRange)
                } else {
                    // 否则恢复上次的滚动位置
                    // 限制最大滚动范围防止越界
                    let maxOffset = max(0, view.contentSize.height - view.bounds.height)
                    let safeOffset = min(state.offsetY, maxOffset)
                    view.setContentOffset(CGPoint(x: 0, y: safeOffset), animated: false)
                }
            }
        }
        
        // MARK: - 状态汇报逻辑
        private func reportState(_ textView: UITextView) {
            let state = EditorViewState(
                selectedLocation: textView.selectedRange.location,
                selectedLength: textView.selectedRange.length,
                offsetY: textView.contentOffset.y
            )
            parent.onStateChange?(state)
        }
        
        func textViewDidChangeSelection(_ textView: UITextView) {
            // 光标移动时汇报
            if !isUpdating { reportState(textView) }
        }
        
        func scrollViewDidEndDecelerating(_ scrollView: UIScrollView) {
            if let tv = scrollView as? UITextView { reportState(tv) }
            calculateAndReportProgress(scrollView)
        }
        
        func scrollViewDidEndDragging(_ scrollView: UIScrollView, willDecelerate decelerate: Bool) {
            if !decelerate {
                if let tv = scrollView as? UITextView { reportState(tv) }
                calculateAndReportProgress(scrollView)
            }
        }
        
        // 兼容原有的滚动同步
        private func calculateAndReportProgress(_ scrollView: UIScrollView) {
            let total = scrollView.contentSize.height
            let visible = scrollView.bounds.height
            guard total > visible else { parent.syncProgress = 0; return }
            let progress = max(0.0, min(1.0, scrollView.contentOffset.y / (total - visible)))
            DispatchQueue.main.async { self.parent.syncProgress = progress }
        }
        
        func textViewDidChange(_ textView: UITextView) {
            if textView.markedTextRange != nil { return }
            guard !isUpdating else { return }
            
            _ = applyMarkReplacement(textView: textView)
            parent.text = textView.text
            updateStyle(textView, style: parent.style, isWordMode: parent.isWordMode, isDarkMode: parent.isDarkMode)
        }
        
        // ... (以下 applyMarkReplacement, handleEnterKey, updateStyle, applyRegex 等保持原样，未修改) ...
        
        private func applyMarkReplacement(textView: UITextView) -> Bool {
            guard let selectedRange = textView.selectedTextRange else { return false }
            let cursorPosition = textView.offset(from: textView.beginningOfDocument, to: selectedRange.start)
            let text = textView.text ?? ""
            let nsString = text as NSString
            if cursorPosition < 2 { return false }
            let lastTwoCharsRange = NSRange(location: cursorPosition - 2, length: 2)
            if lastTwoCharsRange.location + lastTwoCharsRange.length > nsString.length { return false }
            if nsString.substring(with: lastTwoCharsRange) != "==" { return false }
            let searchStart = max(0, cursorPosition - 100)
            let searchLength = cursorPosition - searchStart
            let searchString = nsString.substring(with: NSRange(location: searchStart, length: searchLength))
            guard let regex = try? NSRegularExpression(pattern: "==([^=]+)==$", options: []) else { return false }
            if let match = regex.firstMatch(in: searchString, options: [], range: NSRange(location: 0, length: searchString.utf16.count)) {
                let matchRangeInText = NSRange(location: searchStart + match.range.location, length: match.range.length)
                let contentRangeInSearch = match.range(at: 1)
                let contentRangeInText = NSRange(location: searchStart + contentRangeInSearch.location, length: contentRangeInSearch.length)
                let content = nsString.substring(with: contentRangeInText)
                let replacement = "<mark>\(content)</mark>"
                isUpdating = true
                if let replaceStart = textView.position(from: textView.beginningOfDocument, offset: matchRangeInText.location),
                   let replaceEnd = textView.position(from: replaceStart, offset: matchRangeInText.length),
                   let replaceRange = textView.textRange(from: replaceStart, to: replaceEnd) {
                    textView.replace(replaceRange, withText: replacement)
                }
                isUpdating = false
                return true
            }
            return false
        }
        
        func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool {
            if text == "\n" { return handleEnterKey(textView) }
            return true
        }
        
        private func handleEnterKey(_ textView: UITextView) -> Bool {
            guard let currentRange = textView.selectedTextRange else { return true }
            let cursorPosition = textView.offset(from: textView.beginningOfDocument, to: currentRange.start)
            let fullText = textView.text ?? ""
            let nsString = fullText as NSString
            let lineRange = nsString.lineRange(for: NSRange(location: cursorPosition, length: 0))
            let currentLine = nsString.substring(with: lineRange)
            let patterns = ["^(\\s*[-*])\\s+(.*)$", "^(\\s*\\d+\\.)\\s+(.*)$", "^(\\s*>)\\s+(.*)$", "^(\\s*#{1,6})\\s+(.*)$"]
            for pattern in patterns {
                if let regex = try? NSRegularExpression(pattern: pattern, options: []) {
                    let matches = regex.matches(in: currentLine, options: [], range: NSRange(location: 0, length: currentLine.utf16.count))
                    if let match = matches.first {
                        let prefixRange = match.range(at: 1)
                        let contentRange = match.range(at: 2)
                        let prefix = (currentLine as NSString).substring(with: prefixRange)
                        let content = (currentLine as NSString).substring(with: contentRange).trimmingCharacters(in: .whitespacesAndNewlines)
                        if content.isEmpty {
                            let newText = fullText.replacingOccurrences(of: prefix, with: "", options: [], range: Range(lineRange, in: fullText)!)
                            textView.text = newText
                            let newCursorPos = lineRange.location
                            if let newPos = textView.position(from: textView.beginningOfDocument, offset: newCursorPos) {
                                textView.selectedTextRange = textView.textRange(from: newPos, to: newPos)
                            }
                            parent.text = newText
                            return false
                        }
                        var nextPrefix = prefix
                        if prefix.contains(".") {
                            let numberPart = prefix.trimmingCharacters(in: .whitespaces).dropLast()
                            if let num = Int(numberPart) { nextPrefix = "\(num + 1). " }
                        } else {
                            if !nextPrefix.hasSuffix(" ") { nextPrefix += " " }
                        }
                        textView.insertText("\n" + nextPrefix)
                        return false
                    }
                }
            }
            return true
        }
        
        func updateStyle(_ textView: UITextView, style: MarkdownGlobalStyle, isWordMode: Bool, isDarkMode: Bool) {
            isUpdating = true
            defer { isUpdating = false }
            let originalContentOffset = textView.contentOffset
            let selectedRange = textView.selectedRange
            let text = textView.text ?? ""
            let fullRange = NSRange(location: 0, length: (text as NSString).length)
            let attributedString = NSMutableAttributedString(string: text)
            let bodyFont: UIFont
            if isWordMode { bodyFont = getUIFont(style: style.body) }
            else { bodyFont = UIFont.monospacedSystemFont(ofSize: style.body.size, weight: .regular) }
            let baseColor = getAdaptiveColor(hex: style.body.color, isDarkMode: isDarkMode)
            attributedString.addAttribute(.font, value: bodyFont, range: fullRange)
            attributedString.addAttribute(.foregroundColor, value: baseColor, range: fullRange)
            let blockRules: [(regex: String, config: MarkdownGlobalStyle.TextStyle, isHeader: Bool)] = [
                ("^#\\s.*$", style.h1, true), ("^##\\s.*$", style.h2, true), ("^###\\s.*$", style.h3, true),
                ("^####\\s.*$", style.h4, true), ("^#####\\s.*$", style.h5, true), ("^######\\s.*$", style.h6, true),
                ("^>\\s.*$", style.quote, false)
            ]
            for rule in blockRules {
                guard let regex = try? NSRegularExpression(pattern: rule.regex, options: .anchorsMatchLines) else { continue }
                let matches = regex.matches(in: text, options: [], range: fullRange)
                for match in matches {
                    let range = match.range
                    if isWordMode {
                        attributedString.addAttribute(.font, value: getUIFont(style: rule.config), range: range)
                        attributedString.addAttribute(.foregroundColor, value: getAdaptiveColor(hex: rule.config.color, isDarkMode: isDarkMode), range: range)
                    } else {
                        if rule.isHeader {
                            let headerFont = UIFont.monospacedSystemFont(ofSize: rule.config.size, weight: rule.config.isBold ? .bold : .regular)
                            attributedString.addAttribute(.font, value: headerFont, range: range)
                            attributedString.addAttribute(.foregroundColor, value: getAdaptiveColor(hex: rule.config.color, isDarkMode: isDarkMode), range: range)
                        } else {
                            attributedString.addAttribute(.foregroundColor, value: getAdaptiveColor(hex: rule.config.color, isDarkMode: isDarkMode), range: range)
                        }
                    }
                }
            }
            applyRegex(pattern: "\\$(.+?)\\$", text: text, attrString: attributedString) { range in
                attributedString.addAttribute(.foregroundColor, value: isDarkMode ? UIColor.cyan : UIColor.systemBlue, range: range)
                if isWordMode { attributedString.addAttribute(.font, value: UIFont.monospacedSystemFont(ofSize: bodyFont.pointSize, weight: .medium), range: range) }
            }
            applyRegex(pattern: "`(.+?)`", text: text, attrString: attributedString) { range in
                attributedString.addAttribute(.foregroundColor, value: isDarkMode ? UIColor.systemPink : UIColor.systemPurple, range: range)
                attributedString.addAttribute(.backgroundColor, value: isDarkMode ? UIColor.white.withAlphaComponent(0.1) : UIColor.black.withAlphaComponent(0.05), range: range)
                if isWordMode { attributedString.addAttribute(.font, value: UIFont.monospacedSystemFont(ofSize: bodyFont.pointSize, weight: .regular), range: range) }
            }
            applyRegex(pattern: "\\*\\*(.+?)\\*\\*", text: text, attrString: attributedString) { range in
                applyBold(to: attributedString, range: range, baseFont: bodyFont)
                attributedString.addAttribute(.foregroundColor, value: isDarkMode ? UIColor.yellow : UIColor.orange, range: range)
            }
            applyRegex(pattern: "(?<!\\*)\\*(?!\\*)(.+?)(?<!\\*)\\*(?!\\*)", text: text, attrString: attributedString) { range in
                applyItalic(to: attributedString, range: range, baseFont: bodyFont)
                attributedString.addAttribute(.foregroundColor, value: isDarkMode ? UIColor.lightGray : UIColor.darkGray, range: range)
            }
            let highlightBg = isDarkMode ? UIColor.systemYellow.withAlphaComponent(0.3) : UIColor.systemYellow.withAlphaComponent(0.4)
            let highlightText = isDarkMode ? UIColor.systemYellow : UIColor.black
            applyRegex(pattern: "<mark>(.*?)</mark>", text: text, attrString: attributedString) { range in
                attributedString.addAttribute(.backgroundColor, value: highlightBg, range: range)
                attributedString.addAttribute(.foregroundColor, value: highlightText, range: range)
                applyBold(to: attributedString, range: range, baseFont: bodyFont)
            }
            applyRegex(pattern: "==(.*?)==", text: text, attrString: attributedString) { range in
                attributedString.addAttribute(.backgroundColor, value: highlightBg, range: range)
                attributedString.addAttribute(.foregroundColor, value: highlightText, range: range)
            }
            if let linkRegex = try? NSRegularExpression(pattern: "\\[(.+?)\\]\\((.+?)\\)", options: []) {
                let linkMatches = linkRegex.matches(in: text, options: [], range: fullRange)
                for match in linkMatches {
                    if match.numberOfRanges > 1 {
                        let textRange = match.range(at: 1)
                        attributedString.addAttribute(.foregroundColor, value: UIColor.systemBlue, range: textRange)
                        attributedString.addAttribute(.underlineStyle, value: NSUnderlineStyle.single.rawValue, range: textRange)
                    }
                    if match.numberOfRanges > 2 {
                        let urlRange = match.range(at: 2)
                        attributedString.addAttribute(.foregroundColor, value: UIColor.gray, range: urlRange)
                        if isWordMode { attributedString.addAttribute(.font, value: UIFont.systemFont(ofSize: bodyFont.pointSize * 0.8), range: urlRange) }
                    }
                }
            }
            textView.attributedText = attributedString
            textView.selectedRange = selectedRange
            let caretRect = textView.caretRect(for: textView.selectedTextRange?.start ?? textView.endOfDocument)
            let visibleRect = CGRect(origin: originalContentOffset, size: textView.bounds.size)
            if visibleRect.contains(caretRect) { textView.setContentOffset(originalContentOffset, animated: false) }
            else { textView.scrollRangeToVisible(selectedRange) }
        }
        
        private func applyRegex(pattern: String, text: String, attrString: NSMutableAttributedString, styleBlock: (NSRange) -> Void) {
            guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return }
            let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: text.utf16.count))
            for match in matches { styleBlock(match.range) }
        }
        private func applyBold(to attrString: NSMutableAttributedString, range: NSRange, baseFont: UIFont) {
            let currentFont = attrString.attribute(.font, at: range.location, effectiveRange: nil) as? UIFont ?? baseFont
            if let descriptor = currentFont.fontDescriptor.withSymbolicTraits(.traitBold) { attrString.addAttribute(.font, value: UIFont(descriptor: descriptor, size: currentFont.pointSize), range: range) }
        }
        private func applyItalic(to attrString: NSMutableAttributedString, range: NSRange, baseFont: UIFont) {
            let currentFont = attrString.attribute(.font, at: range.location, effectiveRange: nil) as? UIFont ?? baseFont
            if let descriptor = currentFont.fontDescriptor.withSymbolicTraits(.traitItalic) { attrString.addAttribute(.font, value: UIFont(descriptor: descriptor, size: currentFont.pointSize), range: range) }
        }
        func getUIFont(style: MarkdownGlobalStyle.TextStyle) -> UIFont {
            let size = style.size; let weight: UIFont.Weight = style.isBold ? .bold : .regular
            switch style.fontName {
            case "system_default", "system": return UIFont.systemFont(ofSize: size, weight: weight)
            case "system_serif", "serif": return UIFont.systemFont(ofSize: size, weight: weight).with(design: .serif) ?? UIFont.systemFont(ofSize: size, weight: weight)
            case "system_mono", "mono": return UIFont.monospacedSystemFont(ofSize: size, weight: weight)
            case "system_rounded", "rounded": return UIFont.systemFont(ofSize: size, weight: weight).with(design: .rounded) ?? UIFont.systemFont(ofSize: size, weight: weight)
            default: if let customFont = UIFont(name: style.fontName, size: size) { if style.isBold, let descriptor = customFont.fontDescriptor.withSymbolicTraits(.traitBold) { return UIFont(descriptor: descriptor, size: size) }; return customFont } else { let descriptor = UIFontDescriptor().withFamily(style.fontName); if style.isBold, let descriptor = descriptor.withSymbolicTraits(.traitBold) { return UIFont(descriptor: descriptor, size: size) }; return UIFont(descriptor: descriptor, size: size) }
            }
        }
        func getAdaptiveColor(hex: String, isDarkMode: Bool) -> UIColor {
            if isDarkMode { return getRawColor(hex: hex) }
            else { if hex == "white" { return .black }; if hex == "gray" { return .darkGray }; if hex == "yellow" { return .orange }; if hex == "cyan" { return UIColor(red: 0, green: 0.5, blue: 0.5, alpha: 1) }; return getRawColor(hex: hex) }
        }
        func getRawColor(hex: String) -> UIColor {
            switch hex { case "white": return .white; case "gray": return .gray; case "red": return .systemRed; case "orange": return .systemOrange; case "yellow": return .systemYellow; case "green": return .systemGreen; case "blue": return .systemBlue; case "purple": return .systemPurple; case "cyan": return .systemCyan; default: return UIColor(hexString: hex) ?? .white }
        }
    }
}

#endif

// 【新增】辅助扩展：Hex String 转 UIColor
extension UIColor {
    convenience init?(hexString: String) {
        var cString: String = hexString.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        if (cString.hasPrefix("#")) { cString.remove(at: cString.startIndex) }
        
        if ((cString.count) != 6) { return nil }
        
        var rgbValue: UInt64 = 0
        Scanner(string: cString).scanHexInt64(&rgbValue)
        
        self.init(
            red: CGFloat((rgbValue & 0xFF0000) >> 16) / 255.0,
            green: CGFloat((rgbValue & 0x00FF00) >> 8) / 255.0,
            blue: CGFloat(rgbValue & 0x0000FF) / 255.0,
            alpha: CGFloat(1.0)
        )
    }
}

// 辅助扩展：UIFont Design
extension UIFont {
    func with(design: UIFontDescriptor.SystemDesign) -> UIFont? {
        guard let descriptor = fontDescriptor.withDesign(design) else { return nil }
        return UIFont(descriptor: descriptor, size: pointSize)
    }
}

// MARK: - 清单层级样式编辑器 - v3 - 支持6层配置
//
// TaskListLevelStyleView
// (修改：增加 L5 (Level 6) 的配置选项)

struct TaskListLevelStyleView: View {
    let templateID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var selectedLevel: Int = 0
    @State private var oldLevel: Int = 0
    @State private var config = KeyStyleConfig()
    
    private let fontOptions: [(label: String, name: String?, design: String)] = [
        ("系统默认 (Default)", nil, "default"), ("圆体 (Rounded)", nil, "rounded"),
        ("衬线 (Serif)", nil, "serif"), ("等宽 (Monospaced)", nil, "monospaced")
    ]
    
    private let colorOptions: [(hex: String, name: String)] = [
        ("white", "白"), ("red", "红"), ("orange", "橙"), ("yellow", "黄"),
        ("green", "绿"), ("blue", "蓝"), ("purple", "紫"), ("cyan", "青")
    ]

    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("选择编辑层级")) {
                    // 【核心修改】增加 L5
                    Picker("层级", selection: $selectedLevel) {
                        Text("L0 (1.)").tag(0)
                        Text("L1 (a.)").tag(1)
                        Text("L2 (i.)").tag(2)
                        Text("L3 (括号)").tag(3)
                        Text("L4 (尖括号)").tag(4)
                        Text("L5 (项目符号)").tag(5)
                    }
                    .pickerStyle(.menu) // 选项太多改用 Menu 样式，或者 segmented 也可以挤一挤，这里用 menu 更清晰
                    .padding(.vertical, 4)
                }
                
                Section(header: Text("预览效果")) {
                    HStack {
                        if selectedLevel > 0 { Spacer().frame(width: CGFloat(selectedLevel * 20)) }
                        Text("这是第 \(selectedLevel) 层样式示例")
                            .font(getFont(config))
                            .foregroundColor(colorFromStr(config.color))
                    }
                    .frame(maxWidth: .infinity, minHeight: 60, alignment: .leading)
                    .listRowBackground(Color.white.opacity(0.05))
                }
                
                Section(header: Text("外观设置")) {
                    Picker("字体", selection: Binding<String>(
                        get: {
                            if let name = config.customFontName { return name }
                            return "sys_\(config.fontDesign)"
                        },
                        set: { val in
                            if val.starts(with: "sys_") {
                                config.fontDesign = String(val.dropFirst(4))
                                config.customFontName = nil
                            } else {
                                config.customFontName = val
                                config.fontDesign = "default"
                            }
                        }
                    )) {
                        ForEach(fontOptions, id: \.label) { opt in
                            Text(opt.label).tag(opt.name ?? "sys_\(opt.design)")
                        }
                    }
                    
                    Stepper("字号: \(Int(config.fontSize))", value: $config.fontSize, in: 10...50)
                    Toggle("文字加粗", isOn: $config.isBold)
                }
                
                Section(header: Text("文字颜色")) {
                    LazyVGrid(columns: [GridItem(.adaptive(minimum: 40))], spacing: 15) {
                        ForEach(colorOptions, id: \.hex) { opt in
                            ZStack {
                                Circle().fill(colorFromStr(opt.hex)).frame(width: 35, height: 35)
                                    .overlay(Circle().stroke(Color.white.opacity(0.3), lineWidth: 1))
                                if config.color == opt.hex {
                                    Image(systemName: "checkmark").font(.caption2.bold()).foregroundColor(opt.hex == "white" ? .black : .white)
                                }
                            }
                            .onTapGesture { config.color = opt.hex }
                        }
                    }.padding(.vertical, 8)
                }
            }
            .navigationTitle("清单层级样式")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }
                ToolbarItem(placement: .confirmationAction) {
                    Button("完成") {
                        saveConfig(for: selectedLevel)
                        dismiss()
                    }.fontWeight(.bold)
                }
            }
            .onAppear { loadLevelConfig(0) }
            .onChange(of: selectedLevel) { oldVal, newVal in
                saveConfig(for: oldVal)
                loadLevelConfig(newVal)
            }
        }
    }
    
    func loadLevelConfig(_ lvl: Int) {
        config = asStore.getLevelStyleObj(templateID: templateID, level: lvl)
        if config.fontSize == 24 && lvl > 0 { config.fontSize = CGFloat(max(12, 24 - lvl * 2)) }
    }
    
    func saveConfig(for lvl: Int) {
        asStore.saveLevelStyleObj(templateID: templateID, level: lvl, config: config)
    }
    
    func getFont(_ cfg: KeyStyleConfig) -> Font {
        let weight: Font.Weight = cfg.isBold ? .bold : .regular
        if let name = cfg.customFontName { return .custom(name, size: cfg.fontSize).weight(weight) }
        switch cfg.fontDesign {
        case "rounded": return .system(size: cfg.fontSize, weight: weight, design: .rounded)
        case "monospaced": return .system(size: cfg.fontSize, weight: weight, design: .monospaced)
        case "serif": return .system(size: cfg.fontSize, weight: weight, design: .serif)
        default: return .system(size: cfg.fontSize, weight: weight, design: .default)
        }
    }
    
    func colorFromStr(_ s: String) -> Color {
        switch s {
        case "red": return .red; case "blue": return .blue; case "green": return .green
        case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan
        case "white": return .white; default: return .white
        }
    }
}

// MARK: - 教案全局样式配置 - v9 - 调整默认正文垂直间距

struct LPGlobalStyle: Codable, Equatable {
    var h1 = TextStyle(size: 28, color: "white", isBold: true, fontName: "system", letterSpacing: 1.0, showBackground: true, spaceAbove: 15, spaceBelow: 15, lineSpacing: 5)
    var h2 = TextStyle(size: 24, color: "white", isBold: true, fontName: "system", letterSpacing: 0.8, showBackground: false, spaceAbove: 12, spaceBelow: 12, lineSpacing: 4)
    var h3 = TextStyle(size: 20, color: "white", isBold: true, fontName: "system", letterSpacing: 0.5, showBackground: false, spaceAbove: 10, spaceBelow: 10, lineSpacing: 3)
    var h4 = TextStyle(size: 18, color: "white", isBold: true, fontName: "system", letterSpacing: 0.2, showBackground: false, spaceAbove: 8, spaceBelow: 8, lineSpacing: 3)
    var h5 = TextStyle(size: 16, color: "white", isBold: true, fontName: "system", letterSpacing: 0.0, showBackground: false, spaceAbove: 6, spaceBelow: 6, lineSpacing: 2)
    var h6 = TextStyle(size: 14, color: "gray", isBold: true, fontName: "system", letterSpacing: 0.0, showBackground: false, spaceAbove: 6, spaceBelow: 6, lineSpacing: 2)
    
    // 【159号修改】：正文默认间距改为 2 (合计 4px)
    var body = TextStyle(size: 16, color: "white", isBold: false, fontName: "system", letterSpacing: 0.0, showBackground: false, spaceAbove: 2, spaceBelow: 2, lineSpacing: 2)
    var quote = TextStyle(size: 16, color: "gray", isBold: false, fontName: "system", letterSpacing: 0.0, showBackground: false, spaceAbove: 2, spaceBelow: 2, lineSpacing: 2)
    
    var numberingConfigs: [NumberingConfig] = [
        NumberingConfig(level: "h1", prefix: "第", suffix: "章", format: .chinese),
        NumberingConfig(level: "h2", prefix: "第", suffix: "节", format: .chinese),
        NumberingConfig(level: "h3", prefix: "", suffix: "", format: .numeric01),
        NumberingConfig(level: "h4", prefix: "", suffix: "", format: .heavenlyStems),
        NumberingConfig(level: "h5", prefix: "", suffix: "", format: .numeric),
        NumberingConfig(level: "h6", prefix: "(", suffix: ")", format: .numeric)
    ]
    
    struct TextStyle: Codable, Equatable {
        var size: CGFloat
        var color: String
        var isBold: Bool
        var fontName: String = "system"
        var letterSpacing: CGFloat = 0.0
        var showBackground: Bool = false
        var spaceAbove: CGFloat = 0.0
        var spaceBelow: CGFloat = 0.0
        var lineSpacing: CGFloat = 0.0
    }
    
    struct NumberingConfig: Codable, Equatable, Identifiable {
        var id: String { level }; let level: String; var prefix: String; var suffix: String; var format: NumberFormat
    }
    
    enum NumberFormat: String, Codable, CaseIterable {
        case chinese = "一, 二, 三", heavenlyStems = "甲, 乙, 丙", numeric = "1, 2, 3", numeric01 = "01, 02, 03", romanSmall = "i, ii, iii", alphaSmall = "a, b, c"
    }
    
    static var `default`: LPGlobalStyle { LPGlobalStyle() }
}

// MARK: - 授课主页 - v8 - 视觉统一与标题固定优化

struct TeachingView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    
    @State private var showingStudentPicker = false
    @State private var showingAidPicker = false
    @State private var targetStudentForInit: String?
    @State private var activeStudentForClass: String?

    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }

    var body: some View {
        NavigationStack {
            ZStack {
                // 【163号修复】：引入与档案页一致的动态渐变背景
                MainBackgroundView(themeColor: themeColor).ignoresSafeArea()
                
                VStack(spacing: 0) {
                    // 1. 顶部固定工具栏
                    VStack(alignment: .leading, spacing: 12) {
                        // 【163号核心修改】：自定义小尺寸标题，与按钮对齐，且不随滚动消失
                        HStack(alignment: .firstTextBaseline) {
                            Text(I18n.t(.tab_teaching))
                                .font(.system(size: 17, weight: .black, design: .rounded))
                                .foregroundColor(.white.opacity(0.9))
                            
                            Spacer()
                        }
                        .padding(.horizontal, 24)

                        HStack(spacing: 12) {
                            NavigationLink(destination: LessonPlanManagerView()) {
                                TeachingMenuIcon(title: "教案", icon: "book.closed.fill", color: .orange)
                            }.buttonStyle(.plain)
                            
                            TeachingMenuBtn(title: "教辅", icon: "doc.on.clipboard.fill", color: .green) {
                                showingAidPicker = true
                            }
                            
                            TeachingMenuBtn(title: "学生", icon: "person.2.fill", color: .blue) {
                                showingStudentPicker = true
                            }
                        }
                        .padding(.horizontal, 20)
                    }
                    .padding(.top, 10).padding(.bottom, 20)
                    .background(Color.black.opacity(0.1)) // 顶部轻微阴影区分

                    // 2. 学生列表 (可滚动)
                    ScrollView {
                        let activatedNames = teachingStore.getActivatedNames()
                        let studentFolders = asStore.userCategories.filter { activatedNames.contains($0.title) }
                        
                        if studentFolders.isEmpty {
                            VStack(spacing: 20) {
                                Spacer().frame(height: 100)
                                Image(systemName: "person.crop.circle.badge.plus").font(.system(size: 60)).opacity(0.2)
                                Text("点击上方“学生”按钮，激活学生目录").font(.subheadline).foregroundColor(.gray)
                            }
                        } else {
                            LazyVGrid(columns: [GridItem(.adaptive(minimum: 160), spacing: 20)], spacing: 20) {
                                ForEach(studentFolders) { folder in
                                    StudentStartButton(name: folder.title) { handleStudentClick(name: folder.title) }
                                }
                            }
                            .padding(.horizontal, 24)
                            .padding(.top, 10)
                        }
                        Spacer().frame(height: 100)
                    }
                }
            }
            // 禁用系统标题，使用自定义固定标题
            .navigationTitle("")
            .ttToolbarHidden(for: .navigationBar)
            .sheet(isPresented: $showingStudentPicker) {
                TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                    TeachingStudentPickerView()
                        .environmentObject(teachingStore)
                        .environmentObject(asStore)
                }
            }
            .sheet(isPresented: $showingAidPicker) {
                TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                    TeachingAidPickerView()
                        .environmentObject(teachingStore)
                        .environmentObject(asStore)
                }
            }
            .sheet(item: $targetStudentForInit) { name in
                TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                    StudentInitializationSheet(studentName: name)
                        .environmentObject(asStore)
                        .environmentObject(teachingStore)
                }
            }
            .navigationDestination(item: $activeStudentForClass) { name in
                if let cat = asStore.userCategories.first(where: { $0.title == name }) {
                    ClassModeView(studentName: name, studentCategoryID: cat.id).environmentObject(asStore).environmentObject(teachingStore)
                }
            }
        }
    }
    
    func handleStudentClick(name: String) {
        if teachingStore.isStudentInitialized(name) { activeStudentForClass = name }
        else { targetStudentForInit = name }
    }
}

// MARK: - 课反侧边栏编辑器 - v2 - 修复反馈表匹配 Bug
//
// TeachingFeedbackSidePanel
// (修改内容：
//  1. [FIX] 寻表逻辑修正：不再使用 Template 标题，改为直接从 config.feedbackTableID 获取“源表格”对象并读取其标题。
//  2. [Logic] 对齐命名规则：确保 targetTitle 的生成方式与 ArchiveStore.prepareClassFiles 完全一致（源表名_日期）。
