struct TeachingFeedbackSidePanel: View {
    let studentName: String
    let categoryID: UUID
    let isDark: Bool
    var onExit: () -> Void
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @State private var showShareSheet = false
    @State private var shareItems: [Any] = []
    @State private var activeTableID: UUID? = nil

    var body: some View {
        let feedbackTable = currentFeedbackTable
        VStack(spacing: 0) {
            // 1. 顶部标题栏
            HStack {
                Button(action: onExit) { Image(systemName: "chevron.left").bold() }
                    .padding()
                Text("课堂反馈表").font(.headline)
                Spacer()
                HStack(spacing: 2) {
                    Button {
                        showPreviousTable()
                    } label: {
                        Image(systemName: "chevron.left")
                            .padding(10)
                    }
                    .buttonStyle(.plain)
                    .disabled(previousTable == nil)
                    .opacity(previousTable == nil ? 0.35 : 1)

                    Button {
                        showNextTable()
                    } label: {
                        Image(systemName: "chevron.right")
                            .padding(10)
                    }
                    .buttonStyle(.plain)
                    .disabled(nextTable == nil)
                    .opacity(nextTable == nil ? 0.35 : 1)
                }
                Menu {
                    Button {
                        exportFeedbackCSV(feedbackTable)
                    } label: {
                        Label("导出 CSV", systemImage: "doc.text")
                    }
                    Button {
                        exportFeedbackImage(feedbackTable)
                    } label: {
                        Label("导出图片", systemImage: "photo")
                    }
                } label: {
                    Image(systemName: "square.and.arrow.up")
                        .padding()
                }
                .disabled(feedbackTable == nil)
                .opacity(feedbackTable == nil ? 0.35 : 1)
                Image(systemName: "text.bubble.fill").padding().foregroundColor(.cyan)
            }
            .foregroundColor(isDark ? .white : .black)
            .background(isDark ? Color.white.opacity(0.04) : Color.black.opacity(0.04))

            // 2. 查找并加载表格
            if let feedbackTable {
                NavigationStack {
                    // 内嵌档案模块的原生编辑器
                    ArchiveDetailTableView(categoryID: categoryID, table: feedbackTable)
                        .environmentObject(asStore)
                }
                .id(feedbackTable.id)
            } else {
                VStack(spacing: 20) {
                    Spacer()
                    Image(systemName: "doc.text.magnifyingglass").font(.largeTitle).opacity(0.2)
                    Text("未找到今日反馈表\n请检查学生初始化配置")
                        .font(.caption)
                        .multilineTextAlignment(.center)
                        .foregroundColor(.gray)
                    
                    // 调试辅助信息（可选，如果还找不到可以看这里）
                    if let config = teachingStore.getStudentConfig(studentName), config.feedbackTableID == nil {
                        Text("提示：该学生未关联反馈模板").font(.system(size: 10)).foregroundColor(.red.opacity(0.6))
                    }
                    Spacer()
                }
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .background(Color.clear)
        .background(ShareSheet(isPresented: $showShareSheet, items: shareItems))
        .onAppear {
            if activeTableID == nil {
                activeTableID = findCurrentFeedbackTable()?.id
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("TTFeedbackShowPrevious"))) { _ in
            showPreviousTable()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("TTFeedbackShowNext"))) { _ in
            showNextTable()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("TTFeedbackExportCSV"))) { _ in
            exportFeedbackCSV(currentFeedbackTable)
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("TTFeedbackExportImage"))) { _ in
            exportFeedbackImage(currentFeedbackTable)
        }
    }
    
    /// 辅助：精准寻找今日生成的反馈表实例
    private func findCurrentFeedbackTable() -> ArchiveTable? {
        let df = DateFormatter(); df.dateFormat = "yyMMdd"; let ds = df.string(from: Date())
        
        // 1. 获取该学生的初始化配置
        guard let config = teachingStore.getStudentConfig(studentName),
              let sourceTableID = config.feedbackTableID else { return nil }
        
        // 2. 【核心修复】：先获取“自动填写”文件夹里的那个源表对象
        guard let sourceTable = asStore.getTable(by: sourceTableID) else {
            print("[Teaching] 找不到关联的源反馈表对象")
            return nil
        }
        
        // 3. 构造今日文件的逻辑标题：源表名_yyMMdd
        let targetTitle = "\(sourceTable.title)_\(ds)"
        
        // 4. 在该学生的分类目录下查找匹配此标题的表
        if let cat = asStore.categories.first(where: { $0.id == categoryID }) {
            return cat.tables.first(where: {
                // 排除重命名后的“旧”文件，只找活跃的那张
                $0.title == targetTitle && !$0.title.contains("_旧")
            })
        }
        return nil
    }

    private var currentFeedbackTable: ArchiveTable? {
        if let activeTableID, let table = asStore.getTable(by: activeTableID) {
            return table
        }
        return findCurrentFeedbackTable()
    }

    private var orderedCategoryTables: [ArchiveTable] {
        guard let category = asStore.categories.first(where: { $0.id == categoryID }) else { return [] }
        return category.tables
            .filter {
                $0.type != .markdown
                && !$0.title.contains("_旧")
                && !$0.title.hasPrefix("随堂笔记_")
                && !$0.title.hasPrefix("教案_")
            }
            .sorted {
            let result = $0.title.localizedStandardCompare($1.title)
            if result == .orderedSame {
                return $0.createdAt < $1.createdAt
            }
            return result == .orderedAscending
        }
    }

    private var currentTableIndex: Int? {
        guard let currentID = currentFeedbackTable?.id else { return nil }
        return orderedCategoryTables.firstIndex(where: { $0.id == currentID })
    }

    private var previousTable: ArchiveTable? {
        guard let index = currentTableIndex, index > 0 else { return nil }
        return orderedCategoryTables[index - 1]
    }

    private var nextTable: ArchiveTable? {
        guard let index = currentTableIndex, index < orderedCategoryTables.count - 1 else { return nil }
        return orderedCategoryTables[index + 1]
    }

    private func showPreviousTable() {
        guard let previousTable else { return }
        activeTableID = previousTable.id
    }

    private func showNextTable() {
        guard let nextTable else { return }
        activeTableID = nextTable.id
    }

    private func exportFeedbackCSV(_ feedbackTable: ArchiveTable?) {
        guard let feedbackTable, let url = asStore.exportCSVFile(for: feedbackTable) else { return }
        shareItems = [url]
        showShareSheet = true
    }

    @MainActor
    private func exportFeedbackImage(_ feedbackTable: ArchiveTable?) {
        guard let feedbackTable else { return }
        let renderer = ImageRenderer(content: TableExportView(table: feedbackTable, asStore: asStore))
        #if os(macOS)
        if let image = renderer.nsImage,
           let tiffData = image.tiffRepresentation,
           let rep = NSBitmapImageRep(data: tiffData),
           let pngData = rep.representation(using: .png, properties: [:]) {
            let url = FileManager.default.temporaryDirectory.appendingPathComponent("\(feedbackTable.title).png")
            try? pngData.write(to: url)
            shareItems = [url]
            showShareSheet = true
        }
        #else
        if let image = renderer.uiImage, let pngData = image.pngData() {
            let url = FileManager.default.temporaryDirectory.appendingPathComponent("\(feedbackTable.title).png")
            try? pngData.write(to: url)
            shareItems = [url]
            showShareSheet = true
        }
        #endif
    }
}

// MARK: - LessonPlanUpdateView - v19 - 脏包蓝色视觉标记与手动回传

struct LessonPlanUpdateView: View {
    let studentName: String
    let journalURL: URL
    let planNames: [String]
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @Environment(\.dismiss) var dismiss
    
    @State private var blocks: [LPContentBlock] = []
    @State private var selectedOriginalIDs = Set<UUID>()
    @State private var selectedModifiedIDs = Set<UUID>()
    @State private var showingPromotionPicker = false
    
    struct LPContentBlock: Identifiable {
        let id: UUID; let title: String; let nodes: [LPRowNode]; let isFromMaster: Bool; let isDirty: Bool; let sourceFileName: String?
        var isFromHarvest: Bool { sourceFileName == "上课收集.csv" }
        var isTrulyOriginal: Bool { sourceFileName == nil }
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            List {
                Section(header: Text("自动更新策略")) {
                    Toggle(isOn: $teachingStore.config.isAutoMasterSyncEnabled) {
                        VStack(alignment: .leading, spacing: 4) {
                            Text("下课自动写回母本").font(.headline)
                            Text("开启后，带有蓝色标记的修改项将在下课时自动同步到教案源文件。").font(.caption2).foregroundColor(.gray)
                        }
                    }.padding(.vertical, 4).tint(.blue)
                    .onChange(of: teachingStore.config.isAutoMasterSyncEnabled) { _, _ in teachingStore.save() }
                }

                let promotables = blocks.filter { !$0.isFromMaster || $0.isFromHarvest }
                if !promotables.isEmpty {
                    Section(header: Text("待晋升章节 (存入母本库)").foregroundColor(.orange).bold()) {
                        ForEach(promotables) { block in
                            Button {
                                if selectedOriginalIDs.contains(block.id) { selectedOriginalIDs.remove(block.id) }
                                else { selectedOriginalIDs.insert(block.id) }
                            } label: {
                                HStack(spacing: 12) {
                                    Image(systemName: selectedOriginalIDs.contains(block.id) ? "checkmark.circle.fill" : "circle")
                                        .foregroundColor(block.isTrulyOriginal ? .red : .orange)
                                    blockRow(block, isDirty: false)
                                }
                            }.buttonStyle(.plain)
                        }
                    }
                }
                
                let modifieds = blocks.filter { $0.isFromMaster && !$0.isFromHarvest && $0.isDirty }
                if !modifieds.isEmpty {
                    Section(header: Text("已改动母本章节 (蓝色标记)").foregroundColor(.blue).bold()) {
                        ForEach(modifieds) { block in
                            Button {
                                if selectedModifiedIDs.contains(block.id) { selectedModifiedIDs.remove(block.id) }
                                else { selectedModifiedIDs.insert(block.id) }
                            } label: {
                                HStack(spacing: 12) {
                                    Image(systemName: selectedModifiedIDs.contains(block.id) ? "checkmark.circle.fill" : "circle")
                                        .foregroundColor(.blue)
                                    blockRow(block, isDirty: true)
                                }
                            }.buttonStyle(.plain)
                        }
                    }
                }

                if blocks.isEmpty {
                    VStack(spacing: 20) { Spacer().frame(height: 100); Image(systemName: "checkmark.seal.fill").font(.largeTitle).foregroundColor(.green).opacity(0.5); Text("暂无需要同步的改动").foregroundColor(.gray) }.frame(maxWidth: .infinity)
                }
                Section { Color.clear.frame(height: 120) }.listRowBackground(Color.clear)
            }
            
            VStack(spacing: 0) {
                Divider().background(Color.white.opacity(0.1))
                HStack(spacing: 15) {
                    if !selectedModifiedIDs.isEmpty {
                        Button { performManualSyncModified() } label: {
                            HStack {
                                Image(systemName: "arrow.up.doc.fill")
                                Text("手动回传 (\(selectedModifiedIDs.count))")
                            }
                            .font(.system(size: 14, weight: .bold)).foregroundColor(.white)
                            .padding(.vertical, 12).padding(.horizontal, 16).background(RoundedRectangle(cornerRadius: 12).fill(Color.blue))
                        }
                    }
                    Spacer()
                    if !selectedOriginalIDs.isEmpty {
                        Button { showingPromotionPicker = true } label: {
                            HStack { Text("晋升入库 (\(selectedOriginalIDs.count))").bold(); Image(systemName: "folder.badge.plus") }
                            .font(.system(size: 15)).padding(.horizontal, 20).padding(.vertical, 12).background(Color.orange).foregroundColor(.black).cornerRadius(12)
                        }
                    }
                }.padding(20).background(.ultraThinMaterial)
            }.opacity((!selectedOriginalIDs.isEmpty || !selectedModifiedIDs.isEmpty) ? 1 : 0)
            .animation(.spring(), value: selectedOriginalIDs.isEmpty)
        }
        .navigationTitle("同步更新中心")
        .ttNavigationBarTitleDisplayMode(.inline)
        .toolbar { ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } }
        .sheet(isPresented: $showingPromotionPicker) {
            let selectedBlocks = blocks.filter { selectedOriginalIDs.contains($0.id) }
            TTModalSheetContainer(minWidth: 860, minHeight: 640) {
                MasterDestinationPicker(planNames: planNames, blocks: selectedBlocks, journalURL: journalURL) {
                    selectedOriginalIDs.removeAll()
                    scanJournal()
                }
                .environmentObject(asStore)
            }
        }
        .onAppear { scanJournal() }
    }
    
    func scanJournal() {
        if let content = try? String(contentsOf: journalURL, encoding: .utf8) {
            let allNodes = asStore.parseLessonPlanCSV(content)
            var foundBlocks: [LPContentBlock] = []; var i = 0
            while i < allNodes.count {
                if allNodes[i].type == .h3 {
                    var packet = [allNodes[i]]; let isFromMaster = allNodes[i].sourceNodeID != nil; let sFile = allNodes[i].sourceFileName; let isDirty = teachingStore.dirtyPacketIDs.contains(allNodes[i].id); let title = allNodes[i].content; var j = i + 1
                    while j < allNodes.count { if [.h1, .h2, .h3].contains(allNodes[j].type) { break }; packet.append(allNodes[j]); j += 1 }
                    
                    if !isFromMaster || sFile == "上课收集.csv" || isDirty {
                        foundBlocks.append(LPContentBlock(id: allNodes[i].id, title: title, nodes: packet, isFromMaster: isFromMaster, isDirty: isDirty, sourceFileName: sFile))
                    }
                    i = j
                } else { i += 1 }
            }
            withAnimation {
                self.blocks = foundBlocks
                self.selectedModifiedIDs = Set(foundBlocks.filter { $0.isFromMaster && $0.sourceFileName != "上课收集.csv" && $0.isDirty }.map { $0.id })
            }
            teachingStore.isUpdateAvailable = !foundBlocks.isEmpty
        }
    }
    
    func blockRow(_ block: LPContentBlock, isDirty: Bool) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(block.title.isEmpty ? "未命名章节" : block.title)
                .font(.system(size: 15, weight: .bold))
                .foregroundColor(isDirty ? .blue : .white)
            
            let displaySource: String = {
                guard let fullPath = block.sourceFileName else { return "纯原创章节" }
                if fullPath.contains("上课收集") { return "来自收集站" }
                return "来自母本: \(fullPath.components(separatedBy: "/").first ?? "未知")"
            }()
            
            Text("\(block.nodes.count) 个节点 • \(displaySource)").font(.system(size: 11)).foregroundColor(.gray)
        }.padding(.vertical, 6)
    }
    
    func performManualSyncModified() {
        let toUpdate = blocks.filter { selectedModifiedIDs.contains($0.id) }
        for block in toUpdate {
            if let idMapping = asStore.updateMasterPacket(planNames: self.planNames, newNodes: block.nodes) {
                NotificationCenter.default.post(name: NSNotification.Name("LPJournalSyncIDBackfill"), object: nil, userInfo: ["mapping": idMapping])
                teachingStore.markPacketSynced(id: block.id)
            }
        }
        UIImpactFeedbackGenerator(style: .heavy).impactOccurred(); scanJournal()
    }
}

// MARK: - MasterDestinationPicker - v11 - 物理对齐回填逻辑

struct MasterDestinationPicker: View {
    let planNames: [String]
    let blocks: [LessonPlanUpdateView.LPContentBlock]
    let journalURL: URL
    var onSelect: () -> Void
    
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var availableFiles: [(planName: String, fileURL: URL)] = []
    
    var body: some View {
        NavigationStack {
            List {
                if availableFiles.isEmpty {
                    VStack(spacing: 20) {
                        Image(systemName: "folder.badge.questionmark").font(.largeTitle).opacity(0.2)
                        Text("未在选定教案中找到 CSV 章文件").foregroundColor(.gray)
                    }.padding()
                } else {
                    Section(header: Text("请选择要存入的章文件").foregroundColor(.gray)) {
                        ForEach(availableFiles, id: \.fileURL) { item in
                            Button {
                                performBulkPromotion(to: item.fileURL, planName: item.planName)
                            } label: {
                                HStack(spacing: 16) {
                                    ZStack {
                                        Circle().fill(Color.orange.opacity(0.15)).frame(width: 36, height: 36)
                                        Image(systemName: "doc.text.fill").font(.system(size: 14)).foregroundColor(.orange)
                                    }
                                    VStack(alignment: .leading, spacing: 2) {
                                        Text(item.fileURL.deletingPathExtension().lastPathComponent)
                                            .font(.headline).foregroundColor(.white)
                                        Text(item.planName).font(.caption2).foregroundColor(.gray)
                                    }
                                    Spacer()
                                    Image(systemName: "arrow.right.circle.fill").foregroundColor(.blue.opacity(0.8))
                                }
                                .padding(.vertical, 8)
                            }
                        }
                    }
                }
            }
            .navigationTitle("选择具体章节")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } } }
            .onAppear {
                self.availableFiles = asStore.getAllMasterFiles(planNames: planNames)
            }
        }
        .presentationDetents([.medium, .large])
    }
    
    private func performBulkPromotion(to targetURL: URL, planName: String) {
        let packetsToPromote = blocks.map { $0.nodes }
        
        // 1. 在母本中生成新节点，获取 ID 映射和新分配的物理路径
        let result = asStore.promotePacketsToMasterFile(
            targetFileURL: targetURL,
            planName: planName,
            packets: packetsToPromote
        )
        
        // 2. 将 ID 映射和物理复合路径回填至随堂笔记
        updateJournalPhysicalSourceIDs(mapping: result.mapping, newPath: result.path)
        
        UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
        NotificationCenter.default.post(name: NSNotification.Name("LPJournalPhysicallyUpdated"), object: nil)
        onSelect()
        dismiss()
    }
    
    private func updateJournalPhysicalSourceIDs(mapping: [UUID: UUID], newPath: String) {
        guard let content = try? String(contentsOf: journalURL, encoding: .utf8) else { return }
        var journalNodes = asStore.parseLessonPlanCSV(content)
        var hasChanged = false
        
        // 遍历笔记所有节点，根据映射表回填 SourceID 和全新的物理路径
        for i in journalNodes.indices {
            let journalID = journalNodes[i].id
            if let masterUUID = mapping[journalID] {
                journalNodes[i].sourceNodeID = masterUUID
                journalNodes[i].sourceFileName = newPath // 注入全新的复合路径
                hasChanged = true
            }
        }
        
        if hasChanged {
            let updatedCSV = asStore.generateLessonPlanCSV(from: journalNodes)
            try? updatedCSV.write(to: journalURL, atomically: true, encoding: .utf8)
            print("[Promotion] 物理复合路径回填成功: \(newPath)")
        }
    }
}

