// MARK: - 授课管理中心 - v31 - 维持日期自动填写配置字段

class TeachingStore: ObservableObject {
    static let shared = TeachingStore()
    
    struct LPQuickInputRule: Codable, Identifiable, Equatable {
        var id = UUID()
        var trigger: String
        var endTrigger: String?
        var replacementPrefix: String
        var replacementSuffix: String?
        var isPair: Bool
        var effectiveEndTrigger: String { if isPair { return endTrigger ?? trigger }; return "" }
    }

    struct ClassSession: Codable, Equatable {
        var studentName: String; var studentFolderURL: URL; var journalURL: URL; var pdfExportPath: String?; var pdfExportBookmark: Data?
        var lessonPlanNames: [String] = []; var activePlanName: String?; var activeChecklistURL: URL?
    }
    
    struct StudentConfig: Codable, Equatable {
        var feedbackTableID: UUID?
        var feedbackRowKeys: [String] = []
        var feedbackDateRowKey: String? = nil
        var lessonPlanNames: [String] = []; var teachingAidTemplateIDs: [UUID] = []
        var macPdfExportPath: String?; var macPdfExportBookmark: Data?; var iosPdfExportPath: String?; var iosPdfExportBookmark: Data?
        var lastPlanName: String? = nil
    }
    
    struct SyncPackage {
        let studentName: String; let journalURL: URL; let dirtyIDs: Set<UUID>; let affectedSourceIDs: Set<UUID>; let planNames: [String]; let pdfConfig: (path: String?, bookmark: Data?)
        let isAutoMasterSyncEnabled: Bool
    }
    
    struct SyncDebugInfo { var dirtyPacketCount: Int = 0; var chapterFileCount: Int = 0; var preparedWriteCount: Int = 0; var isWriteSuccessful: Bool = false }
    
    struct GlobalConfig: Codable {
        var activatedStudentNames: [String] = []; var studentConfigs: [String: StudentConfig] = [:]; var currentSession: ClassSession?
        var numberingConfigs: [LPGlobalStyle.NumberingConfig] = []; var quickInputRules: [LPQuickInputRule] = []
        var isAutoMasterSyncEnabled: Bool = true
    }
    
    @Published var config = GlobalConfig(); @Published var sessionFeedbackCounter: Int = 1; @Published var isAnyClassActive: Bool = false
    @Published var focusedH3PacketID: UUID? = nil; @Published var isFocusedPacketFromMaster: Bool = false; @Published var isUpdateAvailable: Bool = false
    @Published var dirtyPacketIDs: Set<UUID> = []; @Published var affectedSourceIDs: Set<UUID> = []; @Published var pdfPathError: String? = nil
    @Published var lastSyncDebug: SyncDebugInfo = SyncDebugInfo(); @Published var clipboardPacket: [LPRowNode]? = nil; @Published var activeCursorRange: NSRange? = nil

    private let fileName = "teaching_global_config.json"; private let relativePath: String; private let fm = FileManager.default

    init() { self.relativePath = "记录/\(fileName)"; load(); NotificationCenter.default.addObserver(self, selector: #selector(handleCloudFileChange), name: .CloudFileDidChange, object: nil) }
    @objc private func handleCloudFileChange(_ notification: Notification) { guard let userInfo = notification.userInfo, let path = userInfo["path"] as? String, path == relativePath else { return }; load() }

    func save() { if let data = try? JSONEncoder().encode(config) { CloudSyncManager.shared.ignoreNextUpdate(relativePath: relativePath); CloudFileManager.shared.saveDual(data: data, folder: .records, fileName: fileName) } }
    func load() { DispatchQueue.main.async { [weak self] in guard let self = self else { return }; if let data = CloudFileManager.shared.smartLoad(folder: .records, fileName: self.fileName), let decoded = try? JSONDecoder().decode(GlobalConfig.self, from: data) { self.config = decoded; self.ensureDefaultRules() } else { self.ensureDefaultRules() } } }
    private func ensureDefaultRules() { if config.numberingConfigs.isEmpty { config.numberingConfigs = LPGlobalStyle.default.numberingConfigs }; if config.quickInputRules.isEmpty { config.quickInputRules = [LPQuickInputRule(trigger: "==", endTrigger: "==", replacementPrefix: "<mark>", replacementSuffix: "</mark>", isPair: true), LPQuickInputRule(trigger: "\\1", replacementPrefix: "①", replacementSuffix: nil, isPair: false)] } }

    func captureSyncPackage() -> SyncPackage? { guard let session = config.currentSession else { return nil }; return SyncPackage(studentName: session.studentName, journalURL: session.journalURL, dirtyIDs: self.dirtyPacketIDs, affectedSourceIDs: self.affectedSourceIDs, planNames: session.lessonPlanNames, pdfConfig: (session.pdfExportPath, session.pdfExportBookmark), isAutoMasterSyncEnabled: config.isAutoMasterSyncEnabled) }
    func startSession(studentName: String, studentCatID: UUID) {
        let studentFolder = CloudFileManager.shared.getCloudDir(.tables).appendingPathComponent(studentName)
        let journalFile = studentFolder.appendingPathComponent("随堂笔记_\(studentName).csv")
        let studentCfg = getStudentConfig(studentName)
        let pPath: String?
        let pBook: Data?
        #if targetEnvironment(macCatalyst)
        pPath = studentCfg?.macPdfExportPath
        pBook = studentCfg?.macPdfExportBookmark
        #else
        pPath = studentCfg?.iosPdfExportPath
        pBook = studentCfg?.iosPdfExportBookmark
        #endif
        self.config.currentSession = ClassSession(
            studentName: studentName,
            studentFolderURL: studentFolder,
            journalURL: journalFile,
            pdfExportPath: pPath,
            pdfExportBookmark: pBook,
            lessonPlanNames: studentCfg?.lessonPlanNames ?? [],
            activePlanName: studentCfg?.lastPlanName
        )
        self.isAnyClassActive = true
        self.dirtyPacketIDs.removeAll()
        self.affectedSourceIDs.removeAll()
        self.sessionFeedbackCounter = 1
        self.pdfPathError = nil
        save()
    }
    func endSession() { self.config.currentSession = nil; self.isAnyClassActive = false; self.activeCursorRange = nil; save() }
    func markPacketDirty(id: UUID) { if !dirtyPacketIDs.contains(id) { dirtyPacketIDs.insert(id) } }
    func markSourceAffected(sourceID: UUID) { if !affectedSourceIDs.contains(sourceID) { affectedSourceIDs.insert(sourceID) } }
    func markPacketSynced(id: UUID) { dirtyPacketIDs.remove(id) }
    func getStudentConfig(_ name: String) -> StudentConfig? { config.studentConfigs[name] }
    func saveStudentConfig(name: String, studentConfig: StudentConfig) { self.config.studentConfigs[name] = studentConfig; if !self.config.activatedStudentNames.contains(name) { self.config.activatedStudentNames.append(name); self.config.activatedStudentNames.sort() }; save() }
    func updateActivePlan(planName: String, studentCategoryID: UUID) { guard var s = config.currentSession else { return }; s.activePlanName = planName; s.activeChecklistURL = s.studentFolderURL.appendingPathComponent("教案_\(planName)_完成情况_\(s.studentName).csv"); self.config.currentSession = s; if var sc = config.studentConfigs[s.studentName] { sc.lastPlanName = planName; config.studentConfigs[s.studentName] = sc }; save() }
    func getActivatedNames() -> [String] { config.activatedStudentNames }; func setActivatedNames(_ names: [String]) { config.activatedStudentNames = names; save() }
    func isStudentInitialized(_ name: String) -> Bool { if let cfg = config.studentConfigs[name] { return !cfg.lessonPlanNames.isEmpty }; return false }
}

private func applyLPQuickInputRules(
    text: String,
    cursorIndex: Int,
    rules: [TeachingStore.LPQuickInputRule]
) -> (String, Int?) {
    let nsText = text as NSString
    let safeCursor = max(0, min(cursorIndex, nsText.length))
    
    for rule in rules {
        if rule.isPair {
            let endTrigger = rule.effectiveEndTrigger
            guard !endTrigger.isEmpty, safeCursor >= endTrigger.count else { continue }
            let tailRange = NSRange(location: safeCursor - endTrigger.count, length: endTrigger.count)
            guard nsText.substring(with: tailRange) == endTrigger else { continue }

            let prefixSearch = String(text[..<text.index(text.startIndex, offsetBy: safeCursor - endTrigger.count)])
            guard let triggerRange = prefixSearch.range(
                of: rule.trigger,
                options: [.backwards, .literal]
            ) else { continue }

            let content = String(prefixSearch[triggerRange.upperBound...])
            let replacedStart = prefixSearch.distance(from: prefixSearch.startIndex, to: triggerRange.lowerBound)
            let replacedLength = safeCursor - replacedStart
            let replacement = rule.replacementPrefix + content + (rule.replacementSuffix ?? "")
            let updated = nsText.replacingCharacters(
                in: NSRange(location: replacedStart, length: replacedLength),
                with: replacement
            )
            let newCursor = replacedStart + replacement.utf16.count
            return (updated, newCursor)
        } else {
            guard !rule.trigger.isEmpty else { continue }

            let directMatchRange: NSRange? = {
                guard safeCursor >= rule.trigger.count else { return nil }
                let range = NSRange(location: safeCursor - rule.trigger.count, length: rule.trigger.count)
                return nsText.substring(with: range) == rule.trigger ? range : nil
            }()

            let delayedMatchRange: NSRange? = {
                guard safeCursor >= rule.trigger.count + 1 else { return nil }
                let trailingChar = nsText.substring(with: NSRange(location: safeCursor - 1, length: 1))
                guard trailingChar.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
                let range = NSRange(location: safeCursor - 1 - rule.trigger.count, length: rule.trigger.count)
                return nsText.substring(with: range) == rule.trigger ? range : nil
            }()

            guard let targetRange = directMatchRange ?? delayedMatchRange else { continue }

            let updated = nsText.replacingCharacters(in: targetRange, with: rule.replacementPrefix)
            let newCursor = targetRange.location + rule.replacementPrefix.utf16.count
            return (updated, newCursor)
        }
    }
    
    return (text, nil)
}

private func applyLPQuickInputRulesForEdit(
    originalText: String,
    affectedRange: NSRange,
    replacement: String,
    rules: [TeachingStore.LPQuickInputRule]
) -> (String, Int?)? {
    let nsText = originalText as NSString
    guard affectedRange.location >= 0,
          affectedRange.length >= 0,
          affectedRange.location + affectedRange.length <= nsText.length else {
        return nil
    }

    let draft = nsText.replacingCharacters(in: affectedRange, with: replacement)
    let cursor = affectedRange.location + (replacement as NSString).length
    let (processed, newCursor) = applyLPQuickInputRules(
        text: draft,
        cursorIndex: cursor,
        rules: rules
    )
    guard processed != draft else { return nil }
    return (processed, newCursor)
}

private func applySmartEditorTransformForEdit(
    originalText: String,
    affectedRange: NSRange,
    replacement: String,
    transform: (String, String, Int) -> (String, Int?)
) -> (String, Int?)? {
    let nsText = originalText as NSString
    guard affectedRange.location >= 0,
          affectedRange.length >= 0,
          affectedRange.location + affectedRange.length <= nsText.length else {
        return nil
    }

    let draft = nsText.replacingCharacters(in: affectedRange, with: replacement)
    let cursor = affectedRange.location + (replacement as NSString).length
    let (processed, newCursor) = transform(originalText, draft, cursor)
    guard processed != draft else { return nil }
    return (processed, newCursor)
}

struct TTModalSheetContainer<Content: View>: View {
    let minWidth: CGFloat
    let minHeight: CGFloat
    let showsDismissButton: Bool
    @Environment(\.dismiss) private var dismiss
    @ViewBuilder var content: () -> Content
    
    init(
        minWidth: CGFloat = 760,
        minHeight: CGFloat = 620,
        showsDismissButton: Bool = true,
        @ViewBuilder content: @escaping () -> Content
    ) {
        self.minWidth = minWidth
        self.minHeight = minHeight
        self.showsDismissButton = showsDismissButton
        self.content = content
    }
    
    var body: some View {
        NavigationStack {
            content()
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
                .toolbar {
                    if showsDismissButton {
                        ToolbarItem(placement: .topBarLeading) {
                            Button {
                                dismiss()
                            } label: {
                                Image(systemName: "chevron.left")
                                    .font(.system(size: 14, weight: .semibold))
                            }
                        }
                    }
                }
        }
        #if os(macOS)
        .frame(width: minWidth, height: minHeight)
        #endif
    }
}

