// MARK: - 快捷输入编辑弹窗 - v4 - 适配非对称成对触发符设置

struct LPQuickInputEditSheet: View {
    let isPair: Bool
    var editingRule: TeachingStore.LPQuickInputRule? = nil
    
    @EnvironmentObject var teachingStore: TeachingStore
    @Environment(\.dismiss) var dismiss
    
    @State private var trigger = ""
    @State private var endTrigger = "" // 【222号新增】
    @State private var prefix = ""
    @State private var suffix = ""
    @State private var showConflictAlert = false
    
    @FocusState private var isTriggerFocused: Bool

    var body: some View {
        Form {
            Section(header: Text("规则定义"), footer: Text(isPair ? "输入开头触发符后输入内容，再输入结束触发符，系统将自动包裹。" : "输入触发符后空格或继续输入会自动替换。")) {
                HStack {
                    Text(isPair ? "开始符" : "触发符").font(.subheadline).foregroundColor(.gray).frame(width: 60, alignment: .leading)
                    TextField(isPair ? "如: ==" : "如: \\1", text: $trigger)
                        .textInputAutocapitalization(.never)
                        .disableAutocorrection(true)
                        .focused($isTriggerFocused)
                }
                
                if isPair {
                    HStack {
                        Text("结束符").font(.subheadline).foregroundColor(.gray).frame(width: 60, alignment: .leading)
                        TextField("如: ==", text: $endTrigger)
                            .textInputAutocapitalization(.never)
                            .disableAutocorrection(true)
                    }
                }
                
                HStack {
                    Text(isPair ? "替换前缀" : "替换目标").font(.subheadline).foregroundColor(.gray).frame(width: 60, alignment: .leading)
                    TextField(isPair ? "如: <mark>" : "如: ①", text: $prefix)
                }
                
                if isPair {
                    HStack {
                        Text("替换后缀").font(.subheadline).foregroundColor(.gray).frame(width: 60, alignment: .leading)
                        TextField("如: </mark>", text: $suffix)
                    }
                }
            }
            
            if editingRule != nil {
                Section {
                    Button(role: .destructive) {
                        teachingStore.config.quickInputRules.removeAll { $0.id == editingRule?.id }
                        teachingStore.save()
                        dismiss()
                    } label: {
                        HStack { Spacer(); Text("删除此规则"); Spacer() }
                    }
                }
            }
        }
        .navigationTitle(editingRule == nil ? "新建规则" : "修改规则")
        .ttNavigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } }
            ToolbarItem(placement: .confirmationAction) {
                Button(editingRule == nil ? "继续" : "保存") { saveWithValidation() }
                .disabled(trigger.isEmpty || prefix.isEmpty || (isPair && endTrigger.isEmpty))
                .fontWeight(.bold)
            }
        }
        .alert("冲突提示", isPresented: $showConflictAlert) { Button("确定", role: .cancel) { } }
        .onAppear {
            if let rule = editingRule {
                trigger = rule.trigger
                endTrigger = rule.endTrigger ?? rule.trigger
                prefix = rule.replacementPrefix
                suffix = rule.replacementSuffix ?? ""
            } else {
                isTriggerFocused = true
            }
        }
    }
    
    private func saveWithValidation() {
        let trimmedTrigger = trigger.trimmingCharacters(in: .whitespacesAndNewlines)
        if teachingStore.config.quickInputRules.contains(where: { $0.trigger == trimmedTrigger && $0.id != editingRule?.id }) {
            showConflictAlert = true; return
        }
        
        if let rule = editingRule {
            if let idx = teachingStore.config.quickInputRules.firstIndex(where: { $0.id == rule.id }) {
                var updated = rule
                updated.trigger = trimmedTrigger
                updated.endTrigger = isPair ? endTrigger : nil
                updated.replacementPrefix = prefix
                updated.replacementSuffix = isPair ? suffix : nil
                teachingStore.config.quickInputRules[idx] = updated
            }
            teachingStore.save(); dismiss()
        } else {
            let newRule = TeachingStore.LPQuickInputRule(
                trigger: trimmedTrigger,
                endTrigger: isPair ? endTrigger : nil,
                replacementPrefix: prefix,
                replacementSuffix: isPair ? suffix : nil,
                isPair: isPair
            )
            teachingStore.config.quickInputRules.append(newRule)
            teachingStore.save()
            trigger = ""; endTrigger = ""; prefix = ""; suffix = ""; isTriggerFocused = true
        }
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
    }
}

// MARK: - 学生目录选择器 - v2 - 过滤系统文件夹

struct TeachingStudentPickerView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @Environment(\.dismiss) var dismiss
    
    @State private var tempSelectedNames: Set<String> = []

    var body: some View {
        NavigationStack {
            List {
                Section(header: Text("从“我的文件夹”中选择学生")) {
                    ForEach(asStore.userCategories) { cat in
                        // 【159号核心】：过滤掉“上课收集”以及其他系统内置文件夹
                        if !isForbiddenFolder(cat.title) {
                            Button {
                                if tempSelectedNames.contains(cat.title) {
                                    tempSelectedNames.remove(cat.title)
                                } else {
                                    tempSelectedNames.insert(cat.title)
                                }
                                UIImpactFeedbackGenerator(style: .light).impactOccurred()
                            } label: {
                                HStack {
                                    Image(systemName: "folder.fill")
                                        .foregroundColor(.indigo)
                                    Text(cat.title)
                                        .foregroundColor(.white)
                                    Spacer()
                                    if tempSelectedNames.contains(cat.title) {
                                        Image(systemName: "checkmark.circle.fill")
                                            .foregroundColor(.blue)
                                            .font(.title3)
                                    } else {
                                        Image(systemName: "circle")
                                            .foregroundColor(.white.opacity(0.2))
                                            .font(.title3)
                                    }
                                }
                            }
                            .buttonStyle(.plain)
                        }
                    }
                }
            }
            .onAppear {
                tempSelectedNames = Set(teachingStore.getActivatedNames())
            }
            .navigationTitle("选择学生")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }
                ToolbarItem(placement: .confirmationAction) {
                    Button("完成") {
                        teachingStore.setActivatedNames(Array(tempSelectedNames).sorted())
                        dismiss()
                    }
                    .fontWeight(.bold)
                }
            }
        }
    }
    
    private func isForbiddenFolder(_ name: String) -> Bool {
        // 【159号】：正式排除上课收集
        let forbidden = ["导入", "自动填写", "删除回收", "测试", "上课收集"]
        return forbidden.contains(name)
    }
}

