// MARK: - 文件夹选择器组件 - v5 - 适配 macOS 原生
//
// struct FolderPicker
// (修改：使用 #if !os(macOS) 隔离 UIKit 的 UIViewControllerRepresentable，并在 macOS 环境下提供基于 NSOpenPanel 的原生 View 实现，确保双端完美编译。)

#if !os(macOS)
import UIKit
import SwiftUI

struct FolderPicker: UIViewControllerRepresentable {
    @Binding var folderPath: String
    @Binding var bookmarkData: Data?
    
    func makeUIViewController(context: Context) -> UIDocumentPickerViewController {
        let picker = UIDocumentPickerViewController(forOpeningContentTypes:[.folder])
        picker.delegate = context.coordinator
        picker.allowsMultipleSelection = false
        return picker
    }
    
    func updateUIViewController(_ uiViewController: UIDocumentPickerViewController, context: Context) {}
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UIDocumentPickerDelegate {
        var parent: FolderPicker
        init(_ parent: FolderPicker) { self.parent = parent }
        
        func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) {
            guard let url = urls.first else { return }
            
            guard url.startAccessingSecurityScopedResource() else { return }
            defer { url.stopAccessingSecurityScopedResource() }
            
            do {
                #if targetEnvironment(macCatalyst)
                let options = URL.BookmarkCreationOptions.withSecurityScope
                #else
                let options = URL.BookmarkCreationOptions([])
                #endif
                
                let bookmark = try url.bookmarkData(
                    options: options,
                    includingResourceValuesForKeys: nil,
                    relativeTo: nil
                )
                parent.bookmarkData = bookmark
                parent.folderPath = url.path
                print("[Picker] 长期访问钥匙已生成")
            } catch {
                print("[Picker] 生成钥匙失败: \(error)")
            }
        }
    }
}
#else
import SwiftUI
import AppKit

struct FolderPicker: View {
    @Binding var folderPath: String
    @Binding var bookmarkData: Data?
    @Environment(\.dismiss) var dismiss
    
    var body: some View {
        VStack(spacing: 20) {
            Text("选择文件夹").font(.headline)
            
            Button("打开系统选择面板") {
                let panel = NSOpenPanel()
                panel.canChooseDirectories = true
                panel.canChooseFiles = false
                panel.allowsMultipleSelection = false
                
                if panel.runModal() == .OK, let url = panel.url {
                    guard url.startAccessingSecurityScopedResource() else { return }
                    defer { url.stopAccessingSecurityScopedResource() }
                    do {
                        let bookmark = try url.bookmarkData(options: .withSecurityScope, includingResourceValuesForKeys: nil, relativeTo: nil)
                        self.bookmarkData = bookmark
                        self.folderPath = url.path
                        print("[Picker] macOS 长期访问钥匙已生成")
                    } catch {
                        print("[Picker] macOS 生成钥匙失败: \(error)")
                    }
                    dismiss()
                }
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)
            
            Button("取消") { dismiss() }
        }
        .padding(40)
        .frame(minWidth: 350, minHeight: 200)
    }
}
#endif

// MARK: - 学生初始化向导 - v9 - 修复选择日期后步骤丢失的 Bug

struct StudentInitializationSheet: View {
    let studentName: String
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @Environment(\.dismiss) var dismiss
    
    @State private var step = 1
    
    // 【257号关键修复】：增加初始化锁，防止在编辑过程中数据被重置
    @State private var isDataLoaded = false
    
    @State private var selectedFeedbackTableID: UUID?
    @State private var feedbackTable: ArchiveTable?
    @State private var selectedRowKey: String? = nil
    @State private var selectedDateRowKey: String? = nil
    
    @State private var selectedPlanNames: Set<String> = []
    @State private var lessonPlans: [String] = []
    
    @State private var selectedAidIDs: Set<UUID> = []
    @State private var pdfPath: String = ""
    @State private var pdfBookmark: Data? = nil
    @State private var showFolderPicker = false
    
    var body: some View {
        NavigationStack {
            VStack {
                HStack(spacing: 4) {
                    ForEach(1...5, id: \.self) { i in
                        Capsule().fill(i <= step ? Color.blue : Color.gray.opacity(0.3)).frame(height: 4)
                    }
                }.padding()
                
                ScrollView {
                    VStack(alignment: .leading, spacing: 20) {
                        if step == 1 { step1View }
                        else if step == 2 { step2View }
                        else if step == 3 { step3View }
                        else if step == 4 { step4View }
                        else if step == 5 { step5View }
                    }
                    .padding()
                }
                
                Spacer()
                
                HStack {
                    if step > 1 {
                        Button("上一步") { withAnimation { step -= 1 } }.buttonStyle(.plain).foregroundColor(.gray)
                    }
                    Spacer()
                    Button(step == 5 ? "完成初始化" : "下一步") {
                        if step < 5 { withAnimation { step += 1 } }
                        else { finishInitialization() }
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(!canProceed())
                }
                .padding()
                .background(Color(white: 0.1))
            }
            .navigationTitle("初始化: \(studentName)")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } } }
            .sheet(isPresented: $showFolderPicker) {
                TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                    FolderPicker(folderPath: $pdfPath, bookmarkData: $pdfBookmark)
                }
            }
        }
        .onAppear { loadInitialData() }
    }
    
    func canProceed() -> Bool {
        switch step {
        case 1: return selectedFeedbackTableID != nil
        case 2: return selectedRowKey != nil
        case 3: return !selectedPlanNames.isEmpty
        case 5: return !pdfPath.isEmpty
        default: return true
        }
    }
    
    func loadInitialData() {
        // 【核心修复点】：如果已经加载过，严禁重复加载，否则步骤 2 的点击会触发重刷，导致 3/4/5 的数据归零
        if isDataLoaded { return }
        
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        if let folders = try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: [.isDirectoryKey], options: .skipsHiddenFiles) {
            lessonPlans = folders.filter { (try? $0.resourceValues(forKeys: [.isDirectoryKey]))?.isDirectory == true }.map { $0.lastPathComponent }.sorted()
        }
        
        if let existing = teachingStore.getStudentConfig(studentName) {
            selectedFeedbackTableID = existing.feedbackTableID
            if let tid = existing.feedbackTableID { feedbackTable = asStore.getTable(by: tid) }
            selectedRowKey = existing.feedbackRowKeys.first
            selectedDateRowKey = existing.feedbackDateRowKey
            selectedPlanNames = Set(existing.lessonPlanNames)
            selectedAidIDs = Set(existing.teachingAidTemplateIDs)
            
            #if targetEnvironment(macCatalyst)
            pdfPath = existing.macPdfExportPath ?? ""
            pdfBookmark = existing.macPdfExportBookmark
            #else
            pdfPath = existing.iosPdfExportPath ?? ""
            pdfBookmark = existing.iosPdfExportBookmark
            #endif
        }
        
        isDataLoaded = true
    }
    
    var step1View: some View {
        VStack(alignment: .leading) {
            Text("1. 选择课堂反馈表").font(.headline)
            let autoFillTables = asStore.getTablesInAutoFillFolder()
            if autoFillTables.isEmpty {
                Text("暂无自动填写表格，请先在档案中创建。").foregroundColor(.red).padding()
            } else {
                ForEach(autoFillTables) { table in
                    HStack {
                        Image(systemName: "tablecells").foregroundColor(.purple)
                        Text(table.title)
                        Spacer()
                        if selectedFeedbackTableID == table.id { Image(systemName: "checkmark.circle.fill").foregroundColor(.blue) }
                    }
                    .padding().background(Color(white: 0.12)).cornerRadius(10)
                    .onTapGesture {
                        selectedFeedbackTableID = table.id
                        feedbackTable = table
                        selectedRowKey = nil; selectedDateRowKey = nil
                    }
                }
            }
        }
    }
    
    var step2View: some View {
        VStack(alignment: .leading, spacing: 24) {
            VStack(alignment: .leading, spacing: 10) {
                Text("2.1 选择反馈内容填入项").font(.headline)
                if let table = feedbackTable {
                    renderRowPicker(table: table, selection: $selectedRowKey)
                }
            }
            
            Divider().background(Color.white.opacity(0.1))
            
            VStack(alignment: .leading, spacing: 10) {
                Text("2.2 选择日期自动填写项 (可选)").font(.headline)
                Text("下课时将自动清空并填入日期 (格式: 260101)。").font(.caption).foregroundColor(.orange)
                if let table = feedbackTable {
                    renderRowPicker(table: table, selection: $selectedDateRowKey, isOptional: true)
                }
            }
        }
    }

    @ViewBuilder
    private func renderRowPicker(table: ArchiveTable, selection: Binding<String?>, isOptional: Bool = false) -> some View {
        ForEach(table.rows, id: \.key) { row in
            let title = (try? JSONDecoder().decode(StandardRowData.self, from: row.value.data(using: .utf8) ?? Data()))?.title ?? row.key
            HStack {
                Text(title)
                Spacer()
                if selection.wrappedValue == row.key {
                    Image(systemName: "checkmark.circle.fill").foregroundColor(.blue)
                } else {
                    Image(systemName: "circle").foregroundColor(.gray)
                }
            }
            .padding().background(Color(white: 0.12)).cornerRadius(10)
            .onTapGesture {
                if isOptional && selection.wrappedValue == row.key {
                    selection.wrappedValue = nil
                } else {
                    selection.wrappedValue = row.key
                }
            }
        }
    }
    
    var step3View: some View {
        VStack(alignment: .leading) {
            Text("3. 选择教案母本").font(.headline)
            if lessonPlans.isEmpty {
                Text("未找到教案母本，请在教案页创建。").foregroundColor(.red).padding()
            } else {
                ForEach(lessonPlans, id: \.self) { plan in
                    Button {
                        if selectedPlanNames.contains(plan) { selectedPlanNames.remove(plan) }
                        else { selectedPlanNames.insert(plan) }
                    } label: {
                        HStack {
                            Image(systemName: "book.closed.fill").foregroundColor(.orange)
                            Text(plan).foregroundColor(.white)
                            Spacer()
                            Image(systemName: selectedPlanNames.contains(plan) ? "checkmark.square.fill" : "square")
                                .foregroundColor(selectedPlanNames.contains(plan) ? .blue : .gray)
                        }
                        .padding().background(Color(white: 0.12)).cornerRadius(10)
                    }.buttonStyle(.plain)
                }
            }
        }
    }
    
    var step4View: some View {
        VStack(alignment: .leading) {
            Text("4. 选择教辅 (可选)").font(.headline)
            let aids = asStore.templates.filter { $0.type == .taskList && !$0.title.hasPrefix("教案_") }
            if aids.isEmpty {
                Text("暂无可用的清单模板。").foregroundColor(.gray).padding()
            } else {
                ForEach(aids) { tmpl in
                    HStack {
                        Image(systemName: "list.bullet.clipboard").foregroundColor(.green)
                        Text(tmpl.title)
                        Spacer()
                        if selectedAidIDs.contains(tmpl.id) { Image(systemName: "checkmark.square.fill").foregroundColor(.blue) }
                        else { Image(systemName: "square").foregroundColor(.gray) }
                    }
                    .padding().background(Color(white: 0.12)).cornerRadius(10)
                    .onTapGesture {
                        if selectedAidIDs.contains(tmpl.id) { selectedAidIDs.remove(tmpl.id) }
                        else { selectedAidIDs.insert(tmpl.id) }
                    }
                }
            }
        }
    }
    
    var step5View: some View {
        VStack(alignment: .leading) {
            Text("5. 设置 PDF 导出路径").font(.headline)
            HStack {
                Text(pdfPath.isEmpty ? "未选择路径" : pdfPath).lineLimit(1).truncationMode(.middle).foregroundColor(.gray)
                Spacer()
                Button(pdfBookmark == nil ? "选择文件夹" : "更改文件夹") { showFolderPicker = true }.buttonStyle(.bordered)
            }
            .padding().background(Color(white: 0.12)).cornerRadius(10)
            if pdfBookmark != nil {
                Text("✅ 已获得长期访问授权").font(.caption2).foregroundColor(.green).padding(.leading, 4)
            }
        }
    }
    
    func finishInitialization() {
        let feedbackKeys = selectedRowKey.map { [$0] } ?? []
        var configToSave = teachingStore.getStudentConfig(studentName) ?? TeachingStore.StudentConfig()
        
        configToSave.feedbackTableID = selectedFeedbackTableID
        configToSave.feedbackRowKeys = feedbackKeys
        configToSave.feedbackDateRowKey = selectedDateRowKey
        configToSave.lessonPlanNames = Array(selectedPlanNames)
        configToSave.teachingAidTemplateIDs = Array(selectedAidIDs)
        
        #if targetEnvironment(macCatalyst)
        configToSave.macPdfExportPath = pdfPath
        configToSave.macPdfExportBookmark = pdfBookmark
        #else
        configToSave.iosPdfExportPath = pdfPath
        configToSave.iosPdfExportBookmark = pdfBookmark
        #endif
        
        teachingStore.saveStudentConfig(name: studentName, studentConfig: configToSave)
        asStore.initializeStudentArchives(studentName: studentName, planNames: Array(selectedPlanNames), aidTemplateIDs: Array(selectedAidIDs))
        dismiss()
    }
}

// MARK: - 教案管理视图 - v5 - 移除创建时的自动分发
//
// struct LessonPlanManagerView
// (修改内容：
//  1. [Logic] createNewLessonPlan 调用 createLessonPlanResources 时不再传递学生参数（参数已在 ArchiveStore v203 中移除）。)

struct LessonPlanManagerView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @EnvironmentObject var teachingStore: TeachingStore
    
    @State private var showingAddAlert = false
    @State private var newPlanName = ""
    @State private var lessonPlanFolders: [String] = []
    
    // 重命名相关状态
    @State private var showRenameAlert = false
    @State private var renamingFolder: String? = nil
    @State private var renameText = ""

    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }

    var body: some View {
        ZStack {
            MainBackgroundView(themeColor: themeColor).ignoresSafeArea()
            
            VStack(spacing: 0) {
                List {
                    Section(header: Text("教案母本目录").foregroundColor(.gray)) {
                        if lessonPlanFolders.isEmpty {
                            Text("点击右上角图标，新建教案文件夹").foregroundColor(.gray).font(.caption).padding(.vertical, 10)
                        } else {
                            ForEach(lessonPlanFolders, id: \.self) { folderName in
                                NavigationLink(destination: LessonPlanFileListView(folderName: folderName)) {
                                    HStack(spacing: 16) {
                                        Image(systemName: "folder.fill.badge.person.crop").foregroundColor(.orange)
                                        VStack(alignment: .leading) {
                                            Text(folderName).font(.headline).foregroundColor(.white)
                                            Text("教案母本").font(.caption2).foregroundColor(.gray)
                                        }
                                    }
                                    .padding(.vertical, 4)
                                }
                                .listRowBackground(Color.white.opacity(0.05))
                                .contextMenu {
                                    Button {
                                        renamingFolder = folderName
                                        renameText = folderName
                                        showRenameAlert = true
                                    } label: { Label("重命名", systemImage: "pencil") }
                                    
                                    Button(role: .destructive) {
                                        deleteFolder(name: folderName)
                                    } label: { Label("删除", systemImage: "trash") }
                                }
                            }
                            .onDelete(perform: deleteFolders)
                        }
                    }
                }
                .ttListStyleInsetGrouped()
                .scrollContentBackground(.hidden)
            }
        }
        .navigationTitle("教案管理")
        .toolbar {
            ToolbarItem(placement: .primaryAction) {
                Button { showingAddAlert = true } label: { Image(systemName: "folder.badge.plus") }
            }
        }
        .onAppear { refreshFolderList() }
        .alert("新建教案母本", isPresented: $showingAddAlert) {
            TextField("教案名称 (如: 初中数学精讲)", text: $newPlanName)
            Button("取消", role: .cancel) { newPlanName = "" }
            Button("创建") { createNewLessonPlan() }
        }
        .alert("重命名教案", isPresented: $showRenameAlert) {
            TextField("新名称", text: $renameText)
            Button("取消", role: .cancel) { }
            Button("保存") { renameFolder() }
        }
    }
    
    func refreshFolderList() {
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        let fm = FileManager.default
        do {
            let folders = try fm.contentsOfDirectory(at: root, includingPropertiesForKeys: [.isDirectoryKey], options: .skipsHiddenFiles)
            self.lessonPlanFolders = folders
                .filter { (try? $0.resourceValues(forKeys: [.isDirectoryKey]))?.isDirectory == true }
                .map { $0.lastPathComponent }
                .sorted()
        } catch {
            print("[Teaching] 获取教案列表失败: \(error)")
        }
    }
    
    func createNewLessonPlan() {
        guard !newPlanName.isEmpty else { return }
        
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        let newURL = root.appendingPathComponent(newPlanName)
        try? FileManager.default.createDirectory(at: newURL, withIntermediateDirectories: true)
        
        // 【修改】仅创建模板，不分发学生
        asStore.createLessonPlanResources(planName: newPlanName)
        
        newPlanName = ""
        refreshFolderList()
    }
    
    func renameFolder() {
        guard let oldName = renamingFolder, !renameText.isEmpty, oldName != renameText else { return }
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        let oldURL = root.appendingPathComponent(oldName)
        let newURL = root.appendingPathComponent(renameText)
        
        do {
            try FileManager.default.moveItem(at: oldURL, to: newURL)
            asStore.renameLessonPlanResources(oldPlanName: oldName, newPlanName: renameText)
            refreshFolderList()
        } catch {
            print("[Teaching] Rename failed: \(error)")
        }
    }
    
    func deleteFolders(at offsets: IndexSet) {
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        for index in offsets {
            let name = lessonPlanFolders[index]
            let target = root.appendingPathComponent(name)
            try? FileManager.default.removeItem(at: target)
        }
        refreshFolderList()
    }
    
    func deleteFolder(name: String) {
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans)
        let target = root.appendingPathComponent(name)
        try? FileManager.default.removeItem(at: target)
        refreshFolderList()
    }
}

// MARK: - LessonPlanFileListView - v8 - 物理简化布局结构，解决编译器超时

struct LessonPlanFileListView: View {
    let folderName: String
    @EnvironmentObject var asStore: ArchiveStore
    @State private var files: [URL] = []
    @State private var showingAddFile = false
    @State private var newFileName = ""
    @State private var historyTargetFile: URL? = nil
    @State private var showHistorySheet = false
    @State private var fileToDelete: URL? = nil
    @State private var showDeleteConfirmation = false
    @State private var showImporter = false

    var body: some View {
        List {
            if files.isEmpty {
                Text("暂无教案文件，点击右上角添加或导入")
                    .foregroundColor(.gray).font(.caption)
            } else {
                // 【核心修复】：通过分块渲染降低 body 复杂度
                ForEach(files, id: \.self) { fileURL in
                    fileRow(for: fileURL)
                }
            }
        }
        .navigationTitle(folderName)
        .toolbar {
            ToolbarItemGroup(placement: .primaryAction) {
                Button { showImporter = true } label: { Image(systemName: "square.and.arrow.down") }
                Button { showingAddFile = true } label: { Image(systemName: "plus.circle") }
            }
        }
        .fileImporter(isPresented: $showImporter, allowedContentTypes: [.plainText, .init(filenameExtension: "md")!]) { result in
            switch result {
            case .success(let url):
                asStore.importMarkdownToLessonPlan(url: url, folderName: folderName)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { refreshFileList() }
            case .failure(let error):
                print("[Import] 失败: \(error)")
            }
        }
        .onAppear { refreshFileList() }
        .sheet(isPresented: $showHistorySheet) {
            if let target = historyTargetFile {
                TTModalSheetContainer(minWidth: 900, minHeight: 680) {
                    LessonPlanHistoryView(fileURL: target) { refreshFileList() }
                }
            }
        }
        .alert("新建教案章节", isPresented: $showingAddFile) {
            TextField("文件名", text: $newFileName); Button("取消", role: .cancel) { }; Button("创建") { createFile() }
        }
        .alert("确认删除章节？", isPresented: $showDeleteConfirmation, presenting: fileToDelete) { file in
            Button("取消", role: .cancel) { }; Button("确认删除", role: .destructive) { performDelete(file) }
        } message: { file in Text("删除“\(file.lastPathComponent)”后，对应的清单模板将更新。") }
    }
    
    // 【物理分块】：抽离行视图逻辑
    @ViewBuilder
    private func fileRow(for fileURL: URL) -> some View {
        NavigationLink(destination: LessonPlanEditorView(fileURL: fileURL, externalTopAnchorID: .constant(nil))) {
            HStack {
                Image(systemName: "tablecells.fill").foregroundColor(.orange)
                Text(fileURL.deletingPathExtension().lastPathComponent).foregroundColor(.white)
            }
        }
        .contextMenu {
            Button { historyTargetFile = fileURL; showHistorySheet = true } label: { Label("查看历史版本", systemImage: "clock.arrow.circlepath") }
            Divider()
            Button(role: .destructive) { fileToDelete = fileURL; showDeleteConfirmation = true } label: { Label("删除文件", systemImage: "trash") }
        }
    }
    
    func refreshFileList() {
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(folderName)
        self.files = (try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: nil, options: .skipsHiddenFiles))?
            .filter({ $0.pathExtension == "csv" })
            .sorted(by: { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }) ?? []
    }
    
    func createFile() {
        guard !newFileName.isEmpty else { return }
        let root = CloudFileManager.shared.getCloudDir(.lessonPlans).appendingPathComponent(folderName)
        let fileURL = root.appendingPathComponent("\(newFileName).csv")
        let csv = asStore.generateLessonPlanCSV(from: [LPRowNode(type: .h1, content: newFileName)])
        try? csv.write(to: fileURL, atomically: true, encoding: .utf8)
        newFileName = ""; refreshFileList()
        asStore.syncLessonPlanContent(folderName: folderName)
    }
    
    func performDelete(_ file: URL) {
        try? FileManager.default.removeItem(at: file)
        refreshFileList(); asStore.syncLessonPlanContent(folderName: folderName)
    }
}

// MARK: - 教案全局样式配置 - v1 - 独立于档案的样式体系
//
// LessonPlanGlobalStyle
// (逻辑说明：
//  1. 结构参照 MarkdownGlobalStyle，但数据完全隔离。
//  2. 新增 numberingPrefixes 字典，为后续 H1-H6 的自动编号设置留好接口。)

struct LessonPlanGlobalStyle: Codable, Equatable {
    var h1: TextStyle = .init(size: 24, color: "white", isBold: true)
    var h2: TextStyle = .init(size: 20, color: "white", isBold: true)
    var h3: TextStyle = .init(size: 18, color: "white", isBold: true)
    var h4: TextStyle = .init(size: 16, color: "white", isBold: true)
    var h5: TextStyle = .init(size: 15, color: "white", isBold: true)
    var h6: TextStyle = .init(size: 14, color: "gray", isBold: true)
    
    var body: TextStyle = .init(size: 15, color: "white", isBold: false)
    var quote: TextStyle = .init(size: 15, color: "gray", isBold: false)
    
    // 【预留】编号设置：Key 为 "h1", "h2" 等，Value 为 "第一章", "第一节" 等
    var numberingPrefixes: [String: String] = [
        "h1": "第一章", "h2": "第一节", "h3": "01", "h4": "甲", "h5": "1", "h6": "(1)"
    ]
    
    struct TextStyle: Codable, Equatable {
        var size: CGFloat
        var color: String
        var isBold: Bool
        var fontName: String = "system"
    }
}

// MARK: - 教案源码模式编辑器 - v2 - 适配浅色模式颜色翻转
//
// LessonPlanSourceEditor
// (修改内容：
//  1. [FIX] 引入 getAdaptiveColor 逻辑，确保浅色模式下配置为 "white" 的文字自动呈现为黑色。
//  2. [渲染] 优化基础属性设置，默认前景色不再硬编码，而是通过样式配置动态计算。
//  3. [稳定] 维持等宽字体渲染、正则着色以及 == 物理替换逻辑。)

#if os(iOS)
struct LessonPlanSourceEditor: UIViewRepresentable {
    @Binding var text: String
    let style: LessonPlanGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?
    
    func makeUIView(context: Context) -> UITextView {
        let textStorage = NSTextStorage()
        let layoutManager = HighPerfLayoutManager()
        textStorage.addLayoutManager(layoutManager)
        let textContainer = NSTextContainer(size: .zero)
        textContainer.widthTracksTextView = true
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 5
        layoutManager.addTextContainer(textContainer)
        
        let textView = UITextView(frame: .zero, textContainer: textContainer)
        textView.backgroundColor = .clear
        textView.isScrollEnabled = true
        textView.keyboardDismissMode = .onDrag
        textView.textContainerInset = UIEdgeInsets(top: 15, left: 15, bottom: 300, right: 15)
        textView.delegate = context.coordinator
        
        textView.dataDetectorTypes = []
        textView.autocapitalizationType = .none
        textView.autocorrectionType = .no
        
        if !text.isEmpty {
            textView.text = text
            context.coordinator.applyHighlighting(for: textView)
        }
        return textView
    }
    
    func updateUIView(_ uiView: UITextView, context: Context) {
        context.coordinator.parent = self
        if uiView.isFirstResponder {
            // 实时响应样式或深浅色切换
            context.coordinator.applyHighlighting(for: uiView)
            return
        }
        if text != uiView.text {
            context.coordinator.isUpdating = true
            uiView.text = text
            context.coordinator.applyHighlighting(for: uiView)
            context.coordinator.isUpdating = false
        }
        if let target = scrollTarget {
            if target.location < uiView.text.utf16.count { uiView.scrollRangeToVisible(target) }
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
    }
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UITextViewDelegate {
        var parent: LessonPlanSourceEditor
        var isUpdating = false
        init(_ parent: LessonPlanSourceEditor) { self.parent = parent }
        
        func textViewDidChange(_ textView: UITextView) {
            if textView.markedTextRange != nil { return }
            _ = applyMarkReplacement(textView: textView)
            parent.text = textView.text ?? ""
            applyHighlighting(for: textView)
        }

        private func applyMarkReplacement(textView: UITextView) -> Bool {
            guard let selectedRange = textView.selectedTextRange else { return false }
            let cursorPosition = textView.offset(from: textView.beginningOfDocument, to: selectedRange.start)
            let nsString = (textView.text ?? "") as NSString
            if cursorPosition < 2 { return false }
            if nsString.substring(with: NSRange(location: cursorPosition-2, length: 2)) == "==" {
                let searchStr = nsString.substring(with: NSRange(location: max(0, cursorPosition-200), length: cursorPosition - max(0, cursorPosition-200)))
                if let regex = try? NSRegularExpression(pattern: "==([^=]+)==$", options: []),
                   let match = regex.firstMatch(in: searchStr, options: [], range: NSRange(location: 0, length: searchStr.utf16.count)) {
                    let matchIdx = max(0, cursorPosition-200) + match.range.location
                    isUpdating = true
                    textView.textStorage.replaceCharacters(in: NSRange(location: matchIdx, length: match.range.length), with: "<mark>\((searchStr as NSString).substring(with: match.range(at: 1)))</mark>")
                    isUpdating = false
                    return true
                }
            }
            return false
        }

        func applyHighlighting(for textView: UITextView) {
            let storage = textView.textStorage
            let content = storage.string
            let fullRange = NSRange(location: 0, length: storage.length)
            if fullRange.length == 0 { return }
            
            storage.beginEditing()
            let baseSize = parent.style.body.size
            let codeFont = UIFont.monospacedSystemFont(ofSize: baseSize, weight: .regular)
            
            // 【核心修改】使用自适应颜色
            let baseColor = getAdaptiveColor(hex: parent.style.body.color, isDarkMode: parent.isDarkMode)
            storage.setAttributes([.font: codeFont, .foregroundColor: baseColor], range: fullRange)
            
            // 标题高亮 (H1-H6)
            applyRegex(pattern: "^#{1,6}\\s.*$", text: content, storage: storage) { _ in
                [.foregroundColor: UIColor.systemBlue, .font: UIFont.monospacedSystemFont(ofSize: baseSize, weight: .bold)]
            }
            
            // 粗体渲染
            let boldColor = parent.isDarkMode ? UIColor.systemOrange : UIColor.orange
            applyRegex(pattern: "\\*\\*.*?\\*\\*", text: content, storage: storage) { _ in
                [.foregroundColor: boldColor, .font: UIFont.monospacedSystemFont(ofSize: baseSize, weight: .bold)]
            }
            
            // 代码块
            let codeColor = parent.isDarkMode ? UIColor.systemPink : UIColor.systemPurple
            applyRegex(pattern: "(`.*?`|(?ms)^```.*?^```)", text: content, storage: storage) { _ in
                [.foregroundColor: codeColor]
            }
            
            // 公式
            applyRegex(pattern: "\\${1,2}.*?\\${1,2}", text: content, storage: storage) { _ in
                [.foregroundColor: UIColor.systemCyan]
            }
            
            // Mark 标签
            let markBg = parent.isDarkMode ? UIColor.systemYellow.withAlphaComponent(0.3) : UIColor.systemYellow.withAlphaComponent(0.4)
            applyRegex(pattern: "<mark>.*?</mark>", text: content, storage: storage) { _ in
                [.backgroundColor: markBg]
            }
            
            storage.endEditing()
        }
        
        private func applyRegex(pattern: String, text: String, storage: NSTextStorage, attrs: (NSRange) -> [NSAttributedString.Key: Any]) {
            let options: NSRegularExpression.Options = pattern.contains("^") ? [.anchorsMatchLines] : (pattern.hasPrefix("(?ms)") ? [] : [])
            if let regex = try? NSRegularExpression(pattern: pattern, options: options) {
                let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: (text as NSString).length))
                for m in matches { storage.addAttributes(attrs(m.range), range: m.range) }
            }
        }
        
        // 颜色适配辅助方法
        func getAdaptiveColor(hex: String, isDarkMode: Bool) -> UIColor {
            if isDarkMode {
                return getRawColor(hex: hex)
            } else {
                // 浅色模式转换逻辑：白色->黑色，灰色->深灰
                if hex == "white" { return .black }
                if hex == "gray" { return .darkGray }
                if hex == "yellow" { return .systemOrange }
                return getRawColor(hex: hex)
            }
        }
        
        func getRawColor(hex: String) -> UIColor {
            switch hex {
            case "white": return .white
            case "gray": return .gray
            case "red": return .systemRed
            case "orange": return .systemOrange
            case "yellow": return .systemYellow
            case "green": return .systemGreen
            case "blue": return .systemBlue
            case "purple": return .systemPurple
            case "cyan": return .systemCyan
            default: return UIColor(hexString: hex) ?? .white
            }
        }
        
        func scrollViewDidEndDecelerating(_ scrollView: UIScrollView) { reportState(scrollView) }
        func scrollViewDidEndDragging(_ scrollView: UIScrollView, willDecelerate decelerate: Bool) { if !decelerate { reportState(scrollView) } }
        private func reportState(_ sv: UIScrollView) { if let tv = sv as? UITextView { parent.onStateChange?(EditorViewState(selectedLocation: tv.selectedRange.location, selectedLength: tv.selectedRange.length, offsetY: tv.contentOffset.y)) } }
    }
}

