// MARK: - LessonPlanEditorView - v57 - 适配 macOS UIDevice 与震动反馈

struct LessonPlanEditorView: View {
    let fileURL: URL
    var initialFocusID: UUID? = nil
    var feedbackOverlayActive: Bool = false
    
    @State private var text: String = ""
    @State private var nodes: [LPRowNode] = []
    
    @Binding var externalTopAnchorID: UUID?
    
    @AppStorage("lp_settings_isDarkMode_v1") private var isDarkMode: Bool = true
    @AppStorage("lp_settings_viewMode_v1") private var viewModeRaw: String = LPViewMode.live.rawValue
    enum LPViewMode: String, Codable, CaseIterable { case live, code, preview, split }
    private var currentMode: LPViewMode { LPViewMode(rawValue: viewModeRaw) ?? .live }
    
    @State private var lpStyle = LPGlobalStyle.default
    @State private var scrollTarget: NSRange? = nil
    @State private var currentState: EditorViewState = .zero
    @State private var initialCSVSource: String = ""
    @State private var showTOC = false
    @State private var showPalette = false
    @State private var forcedFocusedID: UUID? = nil
    @State private var showShareSheet = false
    @State private var shareItems: [Any] = []
    
    @State private var showSearchBar = false
    @State private var searchText = ""
    @State private var matchedNodeIDs: [UUID] = []
    @State private var currentMatchIndex = 0
    @FocusState private var isSearchFieldFocused: Bool
    @State private var editorReloadKey: Int = 0
    @State private var previewHeight: CGFloat = 0

    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore

    @State private var saveTask: Task<Void, Never>? = nil
    private var fileStateKey: String { "lp_state_" + fileURL.lastPathComponent.addingPercentEncoding(withAllowedCharacters: .alphanumerics)! }
    private func editorStateKey(for mode: LPViewMode) -> String { "\(fileStateKey)_\(mode.rawValue)" }
    private var currentModeIcon: String {
        switch currentMode {
        case .live: return "text.alignleft"
        case .code: return "chevron.left.forwardslash.chevron.right"
        case .preview: return "eye"
        case .split: return "square.split.2x1"
        }
    }
    
    // 【核心修改】：适配 macOS 原生判定
    private var isIPhone: Bool {
        #if os(macOS)
        return false
        #else
        return UIDevice.current.userInterfaceIdiom == .phone
        #endif
    }
    
    var body: some View {
        ZStack(alignment: .top) {
            (isDarkMode ? Color.black : Color(white: 0.98)).ignoresSafeArea()
            VStack(spacing: 0) {
                if showSearchBar { searchBarOverlay }
                #if os(macOS)
                lessonPlanTopBar
                #endif
                switch currentMode {
                case .live:
                    LPLiveEditor(
                        text: $text,
                        nodes: $nodes,
                        style: lpStyle,
                        isDarkMode: isDarkMode,
                        scrollTarget: $scrollTarget,
                        initialState: currentState,
                        onStateChange: { currentState = $0 },
                        externalFocusID: $forcedFocusedID,
                        externalTopAnchorID: $externalTopAnchorID
                    )
                    .id("live_\(editorReloadKey)")
                case .code:
                    LPSourceEditor(text: $text, style: lpStyle, isDarkMode: isDarkMode, scrollTarget: $scrollTarget, initialState: currentState, onStateChange: { currentState = $0 })
                        .id("code_\(editorReloadKey)")
                case .preview:
                    previewContentView
                case .split:
                    HStack(spacing: 0) {
                        LPSourceEditor(text: $text, style: lpStyle, isDarkMode: isDarkMode, scrollTarget: $scrollTarget, initialState: currentState, onStateChange: { currentState = $0 })
                            .id("split_code_\(editorReloadKey)")
                        Rectangle()
                            .fill(isDarkMode ? Color.white.opacity(0.08) : Color.black.opacity(0.08))
                            .frame(width: 1)
                        previewContentView
                    }
                }
                
                Button("") { performQuickMasterSync() }
                    .keyboardShortcut("s", modifiers: .command)
                    .frame(width: 0, height: 0)
                    .opacity(0)
            }
        }
        .ttToolbarColorScheme(isDarkMode ? .dark : .light, for: .navigationBar)
        #if !os(macOS)
        .toolbar {
            ToolbarItemGroup(placement: .primaryAction) {
                Button {
                    withAnimation(.spring(response: 0.3)) {
                        showSearchBar.toggle()
                        if showSearchBar { isSearchFieldFocused = true }
                        else { searchText = ""; matchedNodeIDs = [] }
                    }
                } label: { Image(systemName: "magnifyingglass") }
                
                HStack(spacing: 4) {
                    Button { NotificationCenter.default.post(name: NSNotification.Name("LPIndentAction"), object: nil, userInfo: ["delta": -1]) } label: { Image(systemName: "arrow.left.to.line.compact") }
                    Button { NotificationCenter.default.post(name: NSNotification.Name("LPIndentAction"), object: nil, userInfo:["delta": 1]) } label: { Image(systemName: "arrow.right.to.line.compact") }
                }
                Menu {
                    ForEach(LPViewMode.allCases, id: \.self) { mode in
                        Button {
                            switchEditorMode(to: mode)
                        } label: {
                            Label(modeTitle(mode), systemImage: modeIcon(mode))
                        }
                    }
                } label: { Image(systemName: currentModeIcon) }

                if feedbackOverlayActive {
                    Button {
                        NotificationCenter.default.post(name: NSNotification.Name("TTFeedbackShowPrevious"), object: nil)
                    } label: {
                        Image(systemName: "chevron.left")
                    }

                    Button {
                        NotificationCenter.default.post(name: NSNotification.Name("TTFeedbackShowNext"), object: nil)
                    } label: {
                        Image(systemName: "chevron.right")
                    }

                    Menu {
                        Button {
                            NotificationCenter.default.post(name: NSNotification.Name("TTFeedbackExportCSV"), object: nil)
                        } label: {
                            Label("导出 CSV", systemImage: "doc.text")
                        }
                        Button {
                            NotificationCenter.default.post(name: NSNotification.Name("TTFeedbackExportImage"), object: nil)
                        } label: {
                            Label("导出图片", systemImage: "photo")
                        }
                    } label: {
                        Image(systemName: "square.and.arrow.up")
                    }
                }

                Button { isDarkMode.toggle() } label: { Image(systemName: isDarkMode ? "moon.fill" : "sun.max.fill").foregroundColor(isDarkMode ? .yellow : .orange) }
                Button { showPalette = true } label: { Image(systemName: "paintpalette") }
                Button { showTOC = true } label: { Image(systemName: "list.bullet.rectangle") }
                Menu {
                    Button { prepareExport(isPDF: false, isShare: true) } label: { Label("分享 Markdown", systemImage: "shareplay") }
                    Button { prepareExport(isPDF: true, isShare: true) } label: { Label("分享 PDF", systemImage: "square.and.arrow.up") }
                } label: { Image(systemName: "square.and.arrow.up") }
            }
        }
        #endif
        .sheet(isPresented: $showPalette) {
            TTModalSheetContainer(minWidth: 1120, minHeight: 860) {
                LessonPlanPaletteView(style: $lpStyle)
            }
        }
        .sheet(isPresented: $showTOC) {
            TTModalSheetContainer(minWidth: 820, minHeight: 680) {
                MarkdownTOCSheet(content: text) { range in self.scrollTarget = range }
                    .environmentObject(asStore)
            }
        }
        .background(ShareSheet(isPresented: $showShareSheet, items: shareItems))
        .onAppear {
            asStore.editingTableID = UUID()
            lpLoadContent()
            if let fid = initialFocusID { self.forcedFocusedID = fid }
        }
        .onDisappear {
            lpSaveContentImmediately()
            triggerTemplateSync()
            asStore.editingTableID = nil
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPJournalPhysicallyUpdated"))) { _ in
            DispatchQueue.main.async {
                self.saveTask?.cancel()
                self.lpLoadContent(forceEditorReload: true)
            }
        }
        .onChange(of: viewModeRaw) { oldRaw, newRaw in
            guard let oldMode = LPViewMode(rawValue: oldRaw),
                  let newMode = LPViewMode(rawValue: newRaw),
                  oldMode != newMode else { return }
            persistEditorState(currentState, for: oldMode)
            loadEditorState(for: newMode)
            editorReloadKey += 1
        }
        .onChange(of: nodes) { _, _ in debouncedSave() }
        .onChange(of: text) { _, _ in if currentMode == .code { debouncedSave() } }
        .onChange(of: searchText) { _, nv in if nv.isEmpty { matchedNodeIDs = [] } }
    }

