    #if os(macOS)
    private struct GlassEffectBar: NSViewRepresentable {
        var cornerRadius: CGFloat

        func makeNSView(context: Context) -> NSView {
            if #available(macOS 26.0, *) {
                let glass = NSGlassEffectView()
                glass.style = .regular
                glass.cornerRadius = cornerRadius
                glass.tintColor = NSColor(calibratedWhite: 1.0, alpha: 0.12)
                return glass
            } else {
                let v = NSVisualEffectView()
                v.material = .hudWindow
                v.blendingMode = .withinWindow
                v.state = .active
                v.wantsLayer = true
                v.layer?.cornerRadius = cornerRadius
                v.layer?.masksToBounds = true
                return v
            }
        }

        func updateNSView(_ nsView: NSView, context: Context) {
            if #available(macOS 26.0, *) {
                if let glass = nsView as? NSGlassEffectView {
                    glass.cornerRadius = cornerRadius
                }
            } else if let v = nsView as? NSVisualEffectView {
                v.layer?.cornerRadius = cornerRadius
            }
        }
    }
    #endif

    private func performQuickMasterSync() {
        lpSaveContentImmediately()
        let planNames = teachingStore.config.currentSession?.lessonPlanNames ?? []
        guard !planNames.isEmpty else { return }
        let dirtyIDs = teachingStore.dirtyPacketIDs
        guard !dirtyIDs.isEmpty else { return }

        var syncedAny = false
        var i = 0
        while i < nodes.count {
            if nodes[i].type == .h3 && nodes[i].sourceNodeID != nil && dirtyIDs.contains(nodes[i].id) {
                var packet = [nodes[i]]; var j = i + 1
                while j < nodes.count { if [.h1, .h2, .h3].contains(nodes[j].type) { break }; packet.append(nodes[j]); j += 1 }
                
                if let idMapping = asStore.updateMasterPacket(planNames: planNames, newNodes: packet) {
                    syncedAny = true
                    for k in nodes.indices { if let newMasterUUID = idMapping[nodes[k].id] { nodes[k].sourceNodeID = newMasterUUID } }
                    teachingStore.markPacketSynced(id: nodes[i].id)
                }
                i = j
            } else { i += 1 }
        }

        if syncedAny {
            #if !os(macOS)
            UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
            #endif
            lpSaveContentImmediately()
            scanJournal()
            print("[Sync] Command+S 快捷回传成功，更新灯已熄灭")
        }
    }

    func scanJournal() {
        if let content = try? String(contentsOf: fileURL, encoding: .utf8) {
            let allNodes = asStore.parseLessonPlanCSV(content)
            var foundBlocks:[LessonPlanUpdateView.LPContentBlock] = []; var i = 0
            while i < allNodes.count {
                if allNodes[i].type == .h3 {
                    var packet = [allNodes[i]]; let isFromMaster = allNodes[i].sourceNodeID != nil; let sFile = allNodes[i].sourceFileName; let isDirty = teachingStore.dirtyPacketIDs.contains(allNodes[i].id); var j = i + 1
                    while j < allNodes.count { if[.h1, .h2, .h3].contains(allNodes[j].type) { break }; packet.append(allNodes[j]); j += 1 }
                    if !isFromMaster || sFile == "上课收集.csv" || isDirty {
                        foundBlocks.append(LessonPlanUpdateView.LPContentBlock(id: allNodes[i].id, title: allNodes[i].content, nodes: packet, isFromMaster: isFromMaster, isDirty: isDirty, sourceFileName: sFile))
                    }
                    i = j
                } else { i += 1 }
            }
            teachingStore.isUpdateAvailable = !foundBlocks.isEmpty
        }
    }

    private func performNodeSearch() {
        guard !searchText.isEmpty else { matchedNodeIDs = []; return }
        let matches = nodes.filter { $0.content.localizedCaseInsensitiveContains(searchText) }
        self.matchedNodeIDs = matches.map { $0.id }
        self.currentMatchIndex = 0
        if let firstMatch = matchedNodeIDs.first { jumpToMatch(id: firstMatch) }
    }

    private func navigateSearch(delta: Int) {
        guard !matchedNodeIDs.isEmpty else { return }
        currentMatchIndex = (currentMatchIndex + delta + matchedNodeIDs.count) % matchedNodeIDs.count
        jumpToMatch(id: matchedNodeIDs[currentMatchIndex])
    }

    private func jumpToMatch(id: UUID) { NotificationCenter.default.post(name: NSNotification.Name("LPSetSearchFocus"), object: nil, userInfo: ["nodeID": id]) }

    private func debouncedSave() {
        saveTask?.cancel()
        saveTask = Task {
            try? await Task.sleep(nanoseconds: 500_000_000)
            if Task.isCancelled { return }
            await MainActor.run { lpSaveContentImmediately() }
        }
    }

    private func lpSaveContentImmediately() {
        let newCSV = asStore.generateLessonPlanCSV(from: nodes)
        if newCSV != initialCSVSource {
            try? newCSV.write(to: fileURL, atomically: true, encoding: .utf8)
            self.initialCSVSource = newCSV
        }
        if let data = try? JSONEncoder().encode(lpStyle) { UserDefaults.standard.set(data, forKey: "lesson_plan_style_v1") }
        persistEditorState(currentState, for: currentMode)
    }

    func lpLoadContent(forceEditorReload: Bool = false) {
        if let csv = try? String(contentsOf: fileURL, encoding: .utf8) {
            self.initialCSVSource = csv
            let loadedNodes = asStore.parseLessonPlanCSV(csv)
            self.nodes = loadedNodes
            self.text = loadedNodes.map { "\($0.type.csvPrefix)\($0.content)" }.joined(separator: "\n")
        }
        if let data = UserDefaults.standard.data(forKey: "lesson_plan_style_v1"), let saved = try? JSONDecoder().decode(LPGlobalStyle.self, from: data) { self.lpStyle = saved }
        if forceEditorReload {
            self.currentState = .zero
        } else {
            loadEditorState(for: currentMode)
        }
        if forceEditorReload {
            self.scrollTarget = nil
            self.forcedFocusedID = nil
            self.editorReloadKey += 1
        }
    }

    private func persistEditorState(_ state: EditorViewState, for mode: LPViewMode) {
        if let data = try? JSONEncoder().encode(state) {
            UserDefaults.standard.set(data, forKey: editorStateKey(for: mode))
        }
    }

    private func loadEditorState(for mode: LPViewMode) {
        if let data = UserDefaults.standard.data(forKey: editorStateKey(for: mode)),
           let saved = try? JSONDecoder().decode(EditorViewState.self, from: data) {
            self.currentState = saved
        } else {
            self.currentState = .zero
        }
        self.scrollTarget = nil
    }

    private func switchEditorMode(to mode: LPViewMode) {
        guard currentMode != mode else { return }
        persistEditorState(currentState, for: currentMode)
        viewModeRaw = mode.rawValue
    }

    private func modeTitle(_ mode: LPViewMode) -> String {
        switch mode {
        case .live: return "即时"
        case .code: return "源码"
        case .preview: return "预览"
        case .split: return "分屏"
        }
    }

    private func modeIcon(_ mode: LPViewMode) -> String {
        switch mode {
        case .live: return "text.alignleft"
        case .code: return "chevron.left.forwardslash.chevron.right"
        case .preview: return "eye"
        case .split: return "square.split.2x1"
        }
    }

    func prepareExport(isPDF: Bool, isShare: Bool) {
        let currentTitle = fileURL.lastPathComponent.replacingOccurrences(of: ".csv", with: "")
        if isPDF {
            Task {
                if let pdfURL = await asStore.generateAdvancedPDF(nodes: nodes, title: currentTitle, style: lpStyle) {
                    await MainActor.run {
                        self.shareItems = [pdfURL]
                        self.showShareSheet = true
                    }
                }
            }
        }
        else { let fileName = currentTitle + ".md"; let tempURL = FileManager.default.temporaryDirectory.appendingPathComponent(fileName); let cleaned = nodes.map { "\($0.type.csvPrefix)\($0.content)" }.joined(separator: "\n"); try? cleaned.write(to: tempURL, atomically: true, encoding: .utf8); self.shareItems = [tempURL]; self.showShareSheet = true }
    }

    private func triggerTemplateSync() { let folderName = fileURL.deletingLastPathComponent().lastPathComponent; if folderName != "教案" && folderName != "LessonPlans" { asStore.syncLessonPlanContent(folderName: folderName) } }
}

// MARK: - 教案导出文档包装器 - v1 - 支持 MD 与 PDF 物理导出
//
// struct LPDocument
// (逻辑：作为桥接层，将编辑器内的文本或生成的 PDF 数据包装成系统可识别的文档对象，以便触发“另存为”对话框。)

struct LPDocument: FileDocument {
    static var readableContentTypes: [UTType] = [.plainText, .pdf]
    
    var text: String = ""
    var pdfData: Data? = nil
    var isPDF: Bool = false
    
    // 初始化空文档
    init(text: String = "", pdfData: Data? = nil, isPDF: Bool = false) {
        self.text = text
        self.pdfData = pdfData
        self.isPDF = isPDF
    }
    
    // 协议要求：从数据读取（此处主要用于导出，暂不处理复杂的读取逻辑）
    init(configuration: ReadConfiguration) throws {
        if let data = configuration.file.regularFileContents {
            self.text = String(data: data, encoding: .utf8) ?? ""
        }
    }
    
    // 协议要求：写出到文件
    func fileWrapper(configuration: WriteConfiguration) throws -> FileWrapper {
        if isPDF, let data = pdfData {
            return FileWrapper(regularFileWithContents: data)
        } else {
            return FileWrapper(regularFileWithContents: text.data(using: .utf8) ?? Data())
        }
    }
}

// MARK: - 教案时光机视图 - v1 - 独立于档案的恢复逻辑
//
// LessonPlanHistoryView
// (逻辑：
//  1. 物理隔离：专门处理 module 为 "LessonPlans" 的备份文件。
//  2. 交互：列出所有历史版本，点击后将备份内容物理写回当前 fileURL，实现回滚。)
struct LessonPlanHistoryView: View {
    let fileURL: URL
    var onRestored: () -> Void
    @Environment(\.dismiss) var dismiss
    
    @State private var backups: [BackupFile] = []
    
    var body: some View {
        NavigationStack {
            ZStack {
                Color.black.ignoresSafeArea()
                
                if backups.isEmpty {
                    VStack(spacing: 20) {
                        Image(systemName: "clock.arrow.circlepath").font(.system(size: 60)).foregroundColor(.gray.opacity(0.3))
                        Text("暂无历史存档").font(.headline).foregroundColor(.gray)
                        Text("在教案编辑器中修改内容并退出后\n系统会自动生成历史快照").font(.caption).foregroundColor(.gray.opacity(0.5)).multilineTextAlignment(.center)
                    }.padding()
                } else {
                    List {
                        Section(header: Text("备份记录 (点击恢复)")) {
                            ForEach(backups) { backup in
                                Button {
                                    restore(backup)
                                } label: {
                                    HStack {
                                        VStack(alignment: .leading, spacing: 4) {
                                            Text(getTimeAgo(backup.date)).font(.headline).foregroundColor(.white)
                                            Text(backup.date.formatted(date: .numeric, time: .standard)).font(.caption2).foregroundColor(.gray)
                                        }
                                        Spacer()
                                        Image(systemName: "arrow.uturn.backward.circle").font(.title2).foregroundColor(.orange)
                                    }
                                    .padding(.vertical, 4)
                                }
                                .listRowBackground(Color(white: 0.12))
                            }
                        }
                    }
                    .scrollContentBackground(.hidden)
                }
            }
            .navigationTitle("教案历史版本")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } }
            .onAppear { loadBackups() }
        }
    }
    
    private func loadBackups() {
        let subID = fileURL.lastPathComponent.replacingOccurrences(of: ".", with: "_")
        backups = BackupManager.shared.getHistory(module: "LessonPlans", subID: subID)
    }
    
    private func restore(_ backup: BackupFile) {
        do {
            let data = try Data(contentsOf: backup.url)
            try data.write(to: fileURL, options: .atomic)
            UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
            onRestored()
            dismiss()
        } catch {
            print("[History] 恢复失败: \(error)")
        }
    }
    
    func getTimeAgo(_ date: Date) -> String {
        let diff = Int(Date().timeIntervalSince(date))
        if diff < 60 { return "刚刚" }
        if diff < 3600 { return "\(diff / 60)分钟前" }
        if diff < 86400 { return "\(diff / 3600)小时前" }
        return "\(diff / 86400)天前"
    }
}

// MARK: - 授课专用教案节点模型 - v4 - 补充物理溯源字段

struct TeachingLessonNode: Identifiable, Equatable {
    let id: UUID = UUID()
    let title: String
    let level: Int
    var content: [LPRowNode]
    var isCompleted: Bool
    let originalKey: String
    
    // 【141号新增】：物理溯源双锚点
    var sourceID: UUID?
    var sourceFile: String?
    
    var isSelected: Bool = false
    var selectionOrder: Int = 0
}

// MARK: - TeachingLessonSidePanel - v17 - 305号多选排序与过滤逻辑

struct TeachingLessonSidePanel: View {
    let planName: String
    let studentName: String
    let categoryID: UUID
    let isDark: Bool
    var onSwitchPlan: (String) -> Void
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    var onComplete: ([TeachingLessonNode]) -> Void
    var onExit: () -> Void
    
    @State private var displayNodes: [TeachingLessonNode] = []
    @State private var activeTable: ArchiveTable? = nil
    @State private var selectedNodeIDs: [UUID] = [] // 数组维护选择顺序
    @State private var searchText: String = ""
    @State private var foldedIDs = Set<UUID>()
    
    @AppStorage("teaching_filter_level_v3") private var filterLevelIndex: Int = 2
    
    var body: some View {
        VStack(spacing: 0) {
            headerView
            actionHeaderBar
            searchBar
            
            List {
                ForEach(Array(displayNodes.enumerated()), id: \.element.id) { index, node in
                    if !isRowHidden(node: node) {
                        renderNodeRow(node)
                            .listRowBackground(Color.clear)
                            .listRowSeparatorTint(isDark ? Color.white.opacity(0.1) : Color.black.opacity(0.1))
                    }
                }
            }
            .listStyle(.plain)
            .scrollContentBackground(.hidden)
            
            if !selectedNodeIDs.isEmpty {
                submitButton
            } else {
                Button(action: onExit) {
                    Text("关闭教案").font(.subheadline.bold()).foregroundColor(.gray).padding(.vertical, 12).frame(maxWidth: .infinity).background(RoundedRectangle(cornerRadius: 12).stroke(Color.gray.opacity(0.3), lineWidth: 1))
                }.padding()
            }
        }
        .background(isDark ? Color(white: 0.05) : Color(white: 0.95))
        .task(id: planName) {
            reloadForPlan(planName)
        }
    }
    
    private var actionHeaderBar: some View {
        HStack {
            Menu {
                let plans = teachingStore.config.currentSession?.lessonPlanNames ?? []
                ForEach(plans, id: \.self) { p in
                    Button {
                        onSwitchPlan(p)
                    } label: {
                        HStack {
                            Text(p).foregroundColor(.orange)
                            if p == planName { Image(systemName: "checkmark").foregroundColor(.orange) }
                        }
                    }
                }
            } label: {
                HStack(spacing: 4) {
                    Image(systemName: "book.fill").foregroundColor(.orange)
                    Text("更换教案").font(.caption.bold()).foregroundColor(.orange)
                }
                .padding(.horizontal, 10).padding(.vertical, 6)
                .background(Capsule().fill(Color.orange.opacity(0.15)))
                .foregroundStyle(Color.orange)
            }
            .tint(.orange)
            .buttonStyle(.plain)
            Spacer()
            Button {
                let studentName = teachingStore.config.currentSession?.studentName ?? ""
                let plans = teachingStore.config.currentSession?.lessonPlanNames ?? []
                asStore.performTeachingSync(studentName: studentName, catID: categoryID, planNames: plans)
                withAnimation { reloadForPlan(planName) }
                UIImpactFeedbackGenerator(style: .medium).impactOccurred()
            } label: {
                HStack(spacing: 4) { Image(systemName: "arrow.triangle.2.circlepath"); Text("重新梳理").font(.caption.bold()) }
                .padding(.horizontal, 10).padding(.vertical, 6).background(Capsule().fill(Color.orange.opacity(0.15))).foregroundColor(.orange)
            }
        }
        .padding(.horizontal).padding(.vertical, 8)
        .background(isDark ? Color.white.opacity(0.02) : Color.black.opacity(0.02))
    }

    private func loadData(for plan: String) {
        activeTable = nil
        displayNodes = []
        let listName = "教案_\(plan)_完成情况_\(studentName)"
        let checklistURL = CloudFileManager.shared.getCloudDir(.tables)
            .appendingPathComponent(studentName)
            .appendingPathComponent("\(listName).csv")
        let latestTable: ArchiveTable? = {
            if let table = asStore.loadTableFromCSV(url: checklistURL) { return table }
            if let cat = asStore.categories.first(where: { $0.id == categoryID }),
               let table = cat.tables.first(where: { $0.title == listName }) { return table }
            return nil
        }()
        guard let resolved = latestTable else { return }
        activeTable = resolved
        var nodes: [TeachingLessonNode] = []
        for row in resolved.rows {
            if let data = asStore.parseTaskData(row.value) {
                // 【305号】：只显示未完成的项
                if !data.isCompleted {
                    let resolvedContent: [LPRowNode]
                    if let sourceID = data.sourceID, let sourceFile = data.sourceFile {
                        resolvedContent = asStore.extractContentFromMaster(compositePath: sourceFile, sourceID: sourceID)
                    } else {
                        resolvedContent = []
                    }
                    nodes.append(TeachingLessonNode(
                        title: data.title,
                        level: data.level,
                        content: resolvedContent,
                        isCompleted: data.isCompleted,
                        originalKey: row.key,
                        sourceID: data.sourceID,
                        sourceFile: data.sourceFile
                    ))
                }
            }
        }
        self.displayNodes = nodes
    }

    private func reloadForPlan(_ plan: String) {
        selectedNodeIDs.removeAll()
        foldedIDs.removeAll()
        loadData(for: plan)
        applyInitialFoldingByMode()
    }

    private var submitButton: some View {
        Button {
            var finalNodes: [TeachingLessonNode] = []
            guard var latestTable = activeTable else { return }
            let config = teachingStore.getStudentConfig(studentName); let feedbackKeys = config?.feedbackRowKeys ?? []
            
            // 按选择顺序处理
            for id in selectedNodeIDs {
                if var baseNode = displayNodes.first(where: { $0.id == id }) {
                    if let sID = baseNode.sourceID, let sFile = baseNode.sourceFile {
                        let refreshedContent = asStore.extractContentFromMaster(compositePath: sFile, sourceID: sID)
                        if !refreshedContent.isEmpty {
                            baseNode.content = refreshedContent
                        }
                        finalNodes.append(baseNode)
                    } else if !baseNode.content.isEmpty {
                        finalNodes.append(baseNode)
                    }
                    
                    let feedbackText = "\(teachingStore.sessionFeedbackCounter). \(baseNode.title); "; asStore.appendFeedbackText(studentName: studentName, studentCatID: categoryID, keys: feedbackKeys, textToAppend: feedbackText); teachingStore.sessionFeedbackCounter += 1
                    if let rowIndex = latestTable.rows.firstIndex(where: { $0.key == baseNode.originalKey }) {
                        if var taskData = asStore.parseTaskData(latestTable.rows[rowIndex].value) {
                            taskData.isCompleted = true
                            if let json = try? JSONEncoder().encode(taskData), let str = String(data: json, encoding: .utf8) {
                                latestTable.rows[rowIndex].value = str
                            }
                        }
                    }
                }
            }
            asStore.persistTableChanges(table: latestTable, categoryID: categoryID, oldTitle: latestTable.title)
            onComplete(finalNodes)
        } label: {
            HStack {
                Text("完成并插入内容").bold();
                Text("(\(selectedNodeIDs.count))").font(.caption.monospacedDigit())
            }.frame(maxWidth: .infinity).padding().background(Color.orange).foregroundColor(.black).cornerRadius(15)
        }.padding()
    }

    @ViewBuilder private func renderNodeRow(_ node: TeachingLessonNode) -> some View {
        let isH3 = node.level >= 2
        let hasChildren = checkHasChildren(node: node)
        let isFolded = foldedIDs.contains(node.id)
        let isSelected = selectedNodeIDs.contains(node.id)
        let selectionIndex = (selectedNodeIDs.firstIndex(of: node.id) ?? -1) + 1
        
        HStack(spacing: 12) {
            if node.level > 0 { Spacer().frame(width: CGFloat(node.level) * 16) }
            
            ZStack {
                if !isH3 && hasChildren {
                    Image(systemName: isFolded ? "chevron.right" : "chevron.down").font(.caption2.bold()).foregroundColor(.orange)
                } else if isH3 {
                    ZStack {
                        Circle().stroke(isSelected ? Color.orange : Color.gray, lineWidth: 2).frame(width: 24, height: 24)
                        if isSelected {
                            Circle().fill(Color.orange).frame(width: 16, height: 16)
                            Text("\(selectionIndex)").font(.system(size: 10, weight: .black)).foregroundColor(.black)
                        }
                    }
                } else {
                    Color.clear.frame(width: 24, height: 24)
                }
            }.frame(width: 24, height: 24)
            
            Text(node.title)
                .font(.system(size: node.level == 0 ? 16 : 14, weight: node.level == 0 ? .black : (isH3 ? .medium : .bold)))
                .foregroundColor(isSelected ? .orange : (isDark ? .white : .black))
            
            Spacer()
        }
        .padding(.vertical, 8).padding(.horizontal, 12)
        .background(isSelected ? Color.orange.opacity(0.1) : Color.clear)
        .contentShape(Rectangle())
        .onTapGesture {
            if !isH3 {
                if hasChildren {
                    withAnimation(.spring(response: 0.3)) {
                        if isFolded { foldedIDs.remove(node.id) } else { foldedIDs.insert(node.id) }
                    }
                }
            } else {
                if let idx = selectedNodeIDs.firstIndex(of: node.id) {
                    selectedNodeIDs.remove(at: idx)
                } else {
                    selectedNodeIDs.append(node.id)
                }
                UIImpactFeedbackGenerator(style: .light).impactOccurred()
            }
        }
    }

    private func isRowHidden(node: TeachingLessonNode) -> Bool {
        if !searchText.isEmpty { return !node.title.localizedCaseInsensitiveContains(searchText) }
        if foldedIDs.isEmpty { return false }
        if let idx = displayNodes.firstIndex(where: { $0.id == node.id }) {
            let parentIndices = findParentIndices(in: displayNodes, for: idx)
            return parentIndices.contains { foldedIDs.contains(displayNodes[$0].id) }
        }
        return false
    }

    private func applyInitialFoldingByMode() {
        withAnimation(.spring(response: 0.35)) {
            foldedIDs.removeAll()
            switch filterLevelIndex {
            case 0: for node in displayNodes where node.level == 0 { if checkHasChildren(node: node) { foldedIDs.insert(node.id) } }
            case 1: for node in displayNodes where node.level == 1 { if checkHasChildren(node: node) { foldedIDs.insert(node.id) } }
            default: break
            }
        }
    }

    private func findParentIndices(in nodes: [TeachingLessonNode], for targetIndex: Int) -> [Int] {
        var parents = [Int](); let targetLevel = nodes[targetIndex].level; var currentLevel = targetLevel
        for i in (0..<targetIndex).reversed() { if nodes[i].level < currentLevel { parents.append(i); currentLevel = nodes[i].level; if currentLevel == 0 { break } } }
        return parents
    }
    
    private func checkHasChildren(node: TeachingLessonNode) -> Bool { guard let idx = displayNodes.firstIndex(where: { $0.id == node.id }) else { return false }; if idx + 1 < displayNodes.count { return displayNodes[idx+1].level > node.level }; return false }
    
    private var headerView: some View {
        HStack {
            Button(action: onExit) { Image(systemName: "chevron.left").bold() }.padding().foregroundColor(isDark ? .white : .black)
            Text(planName).font(.headline).lineLimit(1).foregroundColor(isDark ? .white : .black)
            Spacer()
            Button { withAnimation(.spring(response: 0.3)) { filterLevelIndex = (filterLevelIndex + 1) % 3; applyInitialFoldingByMode(); UIImpactFeedbackGenerator(style: .light).impactOccurred() }
            } label: { HStack(spacing: 4) { Text("H\(min(3, filterLevelIndex + 1))"); Image(systemName: "line.3.horizontal.decrease.circle") }.font(.system(size: 13, weight: .bold)).foregroundColor(filterLevelIndex < 2 ? .orange : .gray).padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().fill(filterLevelIndex < 2 ? Color.orange.opacity(0.15) : Color.white.opacity(0.05))) }.padding(.trailing, 10)
        }
    }
    private var searchBar: some View { HStack { Image(systemName: "magnifyingglass").foregroundColor(.gray); TextField("搜索教案项...", text: $searchText).foregroundColor(isDark ? .white : .black) }.padding(8).background(isDark ? Color.white.opacity(0.05) : Color.black.opacity(0.05)).cornerRadius(10).padding(.horizontal) }
}

// MARK: - 教案源码模式编辑器 - v13 - 极大化增强滚动条宽度与对比度

#if os(iOS)
struct LPSourceEditor: UIViewRepresentable {
    @Binding var text: String
    let style: LPGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?
    
    func makeUIView(context: Context) -> UITextView {
        let textStorage = NSTextStorage(); let layoutManager = HighPerfLayoutManager()
        textStorage.addLayoutManager(layoutManager)
        let textContainer = NSTextContainer(size: .zero); textContainer.widthTracksTextView = true; layoutManager.addTextContainer(textContainer)
        
        let textView = UITextView(frame: .zero, textContainer: textContainer)
        textView.backgroundColor = .clear
        textView.textContainerInset = UIEdgeInsets(top: 15, left: 15, bottom: 300, right: 15)
        textView.delegate = context.coordinator
        textView.autocapitalizationType = .none
        textView.autocorrectionType = .no
        textView.showsVerticalScrollIndicator = false
        
        if !text.isEmpty { textView.text = text; context.coordinator.applyLPSyntaxHighlighting(for: textView) }
        return textView
    }
    
    func updateUIView(_ uiView: UITextView, context: Context) {
        context.coordinator.parent = self
        
        if !context.coordinator.hasRestored, let state = initialState {
            context.coordinator.hasRestored = true
            DispatchQueue.main.async {
                let maxOffset = max(0, uiView.contentSize.height - uiView.bounds.height)
                uiView.setContentOffset(CGPoint(x: 0, y: min(state.offsetY, maxOffset)), animated: false)
                context.coordinator.updateCustomIndicator(for: uiView)
            }
        }
        
        if !uiView.isFirstResponder && text != uiView.text {
            context.coordinator.isInternallyUpdating = true
            uiView.text = text
            context.coordinator.isInternallyUpdating = false
        }
        
        if let target = scrollTarget {
            if target.location + target.length <= uiView.text.utf16.count {
                uiView.scrollRangeToVisible(target)
                uiView.selectedRange = target
            }
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
        
        context.coordinator.applyLPSyntaxHighlighting(for: uiView)
        context.coordinator.updateCustomIndicator(for: uiView)
    }
    
    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UITextViewDelegate {
        var parent: LPSourceEditor; var isInternallyUpdating = false; var hasRestored = false
        private var customIndicator: UIView?
        
        init(_ parent: LPSourceEditor) { self.parent = parent }
        
        // 【111号核心修改】：滚动条宽度与颜色极致强化
        func updateCustomIndicator(for textView: UITextView) {
            if customIndicator == nil {
                // 圆角随宽度同步调整 (32/2 = 16)
                let v = UIView(); v.layer.cornerRadius = 16; v.isUserInteractionEnabled = false
                textView.addSubview(v); self.customIndicator = v
            }
            guard let indicator = customIndicator else { return }
            let contentHeight = textView.contentSize.height; let visibleHeight = textView.bounds.height
            if contentHeight <= visibleHeight { indicator.alpha = 0; return }
            
            let scrollProgress = textView.contentOffset.y / (contentHeight - visibleHeight)
            let indicatorHeight = max(60, (visibleHeight / contentHeight) * visibleHeight)
            let indicatorY = textView.contentOffset.y + (visibleHeight - indicatorHeight) * scrollProgress
            
            // 颜色极化
            let indicatorColor: UIColor = parent.isDarkMode ? .white : .black
            
            indicator.backgroundColor = indicatorColor
            // 宽度再次翻倍 (16 -> 32)，并调整距离右边缘的间距 (36)
            indicator.frame = CGRect(x: textView.bounds.width - 36, y: indicatorY, width: 32, height: indicatorHeight)
            indicator.alpha = 1.0; textView.bringSubviewToFront(indicator)
        }
        
        func scrollViewDidScroll(_ scrollView: UIScrollView) { if let tv = scrollView as? UITextView { updateCustomIndicator(for: tv) } }
        func textViewDidChange(_ textView: UITextView) { _ = performLPMarkReplacement(textView: textView); parent.text = textView.text ?? ""; applyLPSyntaxHighlighting(for: textView); updateCustomIndicator(for: textView) }
        func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool { if text == "\n" { let content = (textView.text ?? "") as NSString; let lineRange = content.lineRange(for: NSRange(location: range.location, length: 0)); if let nextPrefix = calculateNextPrefix(content.substring(with: lineRange)) { textView.insertText("\n" + nextPrefix); return false } }; return true }
        
        func applyLPSyntaxHighlighting(for textView: UITextView) {
            let storage = textView.textStorage
            let content = storage.string
            let fullRange = NSRange(location: 0, length: storage.length)
            if fullRange.length == 0 { return }
            
            storage.beginEditing()
            let baseFontSize = parent.style.body.size
            let codeFont = UIFont.monospacedSystemFont(ofSize: baseFontSize, weight: .regular)
            let boldCodeFont = UIFont.monospacedSystemFont(ofSize: baseFontSize, weight: .bold)
            let baseColor = lpAdaptiveColor(hex: parent.style.body.color, dark: parent.isDarkMode)
            
            storage.setAttributes([.font: codeFont, .foregroundColor: baseColor], range: fullRange)
            
            let h1Color = lpAdaptiveColor(hex: parent.style.h1.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^#\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h1Color, .font: boldCodeFont] }
            let h2Color = lpAdaptiveColor(hex: parent.style.h2.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^##\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h2Color, .font: boldCodeFont] }
            let h3Color = lpAdaptiveColor(hex: parent.style.h3.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^###\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h3Color, .font: boldCodeFont] }
            
            applyLPRegex(pattern: "^#{4,6}\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: baseColor, .font: boldCodeFont] }
            let listMarkerColor = parent.isDarkMode ? UIColor.systemCyan : UIColor.systemBlue
            applyLPRegex(pattern: #"^(\s{0,10})-\s+"#, text: content, storage: storage) { _ in [.foregroundColor: listMarkerColor] }
            let boldColor = parent.isDarkMode ? UIColor.systemOrange : UIColor.orange
            applyLPRegex(pattern: "\\*\\*.*?\\*\\*", text: content, storage: storage) { _ in [.foregroundColor: boldColor, .font: boldCodeFont] }
            let accentColor = parent.isDarkMode ? UIColor.systemPink : UIColor.systemPurple
            applyLPRegex(pattern: "(`.*?`|(?ms)^```.*?^```)", text: content, storage: storage) { _ in [.foregroundColor: accentColor] }
            let mathColor = parent.isDarkMode ? UIColor.systemCyan : UIColor(red: 0, green: 0.5, blue: 0.6, alpha: 1)
            applyLPRegex(pattern: "(?s)\\$\\$.*?\\$\\$|\\$.*?\\$", text: content, storage: storage) { _ in [.foregroundColor: mathColor] }
            let markBg = parent.isDarkMode ? UIColor.systemYellow.withAlphaComponent(0.3) : UIColor.systemYellow.withAlphaComponent(0.4)
            applyLPRegex(pattern: "<mark>.*?</mark>", text: content, storage: storage) { _ in [.backgroundColor: markBg] }
            
            storage.endEditing()
        }
        
        private func calculateNextPrefix(_ line: String) -> String? { let pattern = #"^(\s{0,10})-\s+"#; if let regex = try? NSRegularExpression(pattern: pattern, options: []), let match = regex.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) { return (line as NSString).substring(with: match.range) }; if let range = line.range(of: #"^\s*-\s+"#, options: .regularExpression) { return String(line[range]) }; let bp = #"^(\s*)\((\d+)\)(\.?)\s+"#; if let rx = try? NSRegularExpression(pattern: bp, options: []), let m = rx.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) { let s = (line as NSString).substring(with: m.range(at: 1)); let n = Int((line as NSString).substring(with: m.range(at: 2))) ?? 0; return "\(s)(\(n + 1))\( (line as NSString).substring(with: m.range(at: 3)) ) " }; let np = #"^(\s*)(\d+)(\.|\))(\.?)\s+"#; if let rx = try? NSRegularExpression(pattern: np, options: []), let m = rx.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) { let s = (line as NSString).substring(with: m.range(at: 1)); let n = Int((line as NSString).substring(with: m.range(at: 2))) ?? 0; let su = (line as NSString).substring(with: m.range(at: 3)); let d = (line as NSString).substring(with: m.range(at: 4)); return "\(s)\(n + 1)\(su)\(d) " }; return nil }
        private func performLPMarkReplacement(textView: UITextView) -> Bool { guard let selectedRange = textView.selectedTextRange else { return false }; let pos = textView.offset(from: textView.beginningOfDocument, to: selectedRange.start); let nsText = (textView.text ?? "") as NSString; if pos < 2 { return false }; if nsText.substring(with: NSRange(location: pos-2, length: 2)) == "==" { let searchRange = NSRange(location: max(0, pos-200), length: pos - max(0, pos-200)); let searchStr = nsText.substring(with: searchRange); if let regex = try? NSRegularExpression(pattern: "==([^=]+)==$", options: []), let match = regex.firstMatch(in: searchStr, options: [], range: NSRange(location: 0, length: searchStr.utf16.count)) { isInternallyUpdating = true; textView.textStorage.replaceCharacters(in: NSRange(location: searchRange.location + match.range.location, length: match.range.length), with: "<mark>\((searchStr as NSString).substring(with: match.range(at: 1)))</mark>"); isInternallyUpdating = false; return true } }; return false }
        private func applyLPRegex(pattern: String, text: String, storage: NSTextStorage, attrs: (NSRange) -> [NSAttributedString.Key: Any]) { var finalPattern = pattern; var options: NSRegularExpression.Options = []; if pattern.contains("^") { options.insert(.anchorsMatchLines) }; if pattern.hasPrefix("(?s)") { options.insert(.dotMatchesLineSeparators); finalPattern = pattern.replacingOccurrences(of: "(?s)", with: "") }; if pattern.hasPrefix("(?ms)") { options.insert(.anchorsMatchLines); options.insert(.dotMatchesLineSeparators); finalPattern = pattern.replacingOccurrences(of: "(?ms)", with: "") }; if let regex = try? NSRegularExpression(pattern: finalPattern, options: options) { let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: (text as NSString).length)); for m in matches { storage.addAttributes(attrs(m.range), range: m.range) } } }
        private func lpAdaptiveColor(hex: String, dark: Bool) -> UIColor { switch hex { case "white": return dark ? .white : .black; case "gray": return dark ? .gray : .darkGray; case "yellow": return dark ? .systemYellow : .systemOrange; default: return UIColor(hexString: hex) ?? (dark ? .white : .black) } }
        func scrollViewDidEndDecelerating(_ scrollView: UIScrollView) { reportState(scrollView) }
        func scrollViewDidEndDragging(_ scrollView: UIScrollView, willDecelerate decelerate: Bool) { if !decelerate { reportState(scrollView) } }
        private func reportState(_ sv: UIScrollView) { if let tv = sv as? UITextView { parent.onStateChange?(EditorViewState(selectedLocation: tv.selectedRange.location, selectedLength: tv.selectedRange.length, offsetY: tv.contentOffset.y)) } }
    }
}

// MARK: - LPLiveEditor - v148 - 物理修复 View 成员访问错误，维持像素整数锁定逻辑

struct LPLiveEditor: View {
    @Binding var text: String
    @Binding var nodes: [LPRowNode]
    let style: LPGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    let initialState: EditorViewState
    var onStateChange: (EditorViewState) -> Void
    @Binding var externalFocusID: UUID?
    @Binding var externalTopAnchorID: UUID?

    @State private var activeEditingNodeID: UUID? = nil
    @State private var focusedEditorNodeID: UUID? = nil
    @State private var anchorNodeID: UUID? = nil
    @State private var targetScrollID: UUID? = nil
    @State private var targetSnapID: UUID? = nil
    
    @State private var editSession = LPActiveEditSession()
    
    // UI 驱动的高度缓存池
    @State private var heightCache: [UUID: CGFloat] = [:]
    
    @State private var focusedPacketIDs: Set<UUID> = []
    @State private var lastSearchHitNodeID: UUID? = nil
    @State private var numberingCache: [UUID: String] = [:]
    
    @State private var visibleNodeIDs: Set<UUID> = []
    @State private var renderedFormulaCache: [String: LPFormulaRenderAsset] = [:]
    @State private var hasInitialJumped: Bool = false
    @State private var pendingCursorOffset: Int? = nil
    @State private var focusRequestToken: Int = 0
    
    @State private var precomputedLayoutMap: [UUID: LPNodeRowView.LayoutData] = [:]
    @State private var precomputeTask: Task<Void, Never>? = nil
    @State private var currentParentWidth: CGFloat = 0
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @EnvironmentObject var settingsStore: GlobalSettingsStore

    var body: some View {
        GeometryReader { screenGeo in
            let parentWidth = screenGeo.size.width
            ZStack(alignment: .bottom) {
                nodesListView(screenGeo: screenGeo, parentWidth: parentWidth)
                
                if settingsStore.config.isDirtyPacketDebugEnabled {
                    debugOverlay
                }
            }
        }
        .task(id: nodes) {
            updateNumberingCache()
            schedulePrecomputeLayouts()
            await ensureFormulasRendered()
        }
        .task(id: style) {
            updateNumberingCache()
            precomputedLayoutMap.removeAll()
            schedulePrecomputeLayouts()
            renderedFormulaCache.removeAll()
            await ensureFormulasRendered()
        }
        .onAppear {
            checkUpdateAvailability()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPRowInsertAction"))) { note in
            if let insertNodes = note.userInfo? ["nodes"] as? [TeachingLessonNode] { insertExternalLessonNodes(insertNodes) }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPJournalSidebarAnchorRequest"))) { _ in
            if let aid = activeEditingNodeID { commitCurrentEdit(nodeID: aid); self.anchorNodeID = aid }
            withAnimation { activeEditingNodeID = nil }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPJournalExitAllEditing"))) { _ in
            exitEditingAction()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPSetSearchFocus"))) { note in
            if let userInfo = note.userInfo, let tid = userInfo["nodeID"] as? UUID {
                self.lastSearchHitNodeID = tid; self.targetScrollID = tid
            }
        }
    }

    private func handleHeightUpdate(id: UUID, newH: CGFloat) {
        let roundedH = ceil(newH)
        if heightCache[id] == roundedH { return }
        heightCache[id] = roundedH
    }

    private var debugOverlay: some View {
        VStack(spacing: 4) {
            Text("活跃节点: \(visibleNodeIDs.count) | 缓存公式: \(renderedFormulaCache.count)")
            if let topID = topmostVisibleNodeID {
                if let node = nodes.first(where: { $0.id == topID }) {
                    Text("视野锚点内容: \(node.content.prefix(15))...")
                }
                Text("锚点 UUID: \(topID.uuidString)").font(.system(size: 8, design: .monospaced)).foregroundColor(.yellow)
            }
        }
        .font(.system(size: 10, weight: .bold))
        .padding(10)
        .background(RoundedRectangle(cornerRadius: 12).fill(Color.black.opacity(0.75)))
        .foregroundColor(.green)
        .padding(.bottom, 25)
        .allowsHitTesting(false)
    }

    private var topmostVisibleNodeID: UUID? {
        for node in nodes { if visibleNodeIDs.contains(node.id) { return node.id } }; return nil
    }

    private func handleVisibilityChange(id: UUID, isVisible: Bool) {
        if isVisible { visibleNodeIDs.insert(id) }
        else { visibleNodeIDs.remove(id) }
        if let top = topmostVisibleNodeID, externalTopAnchorID != top {
            externalTopAnchorID = top
        }
    }

    private func schedulePrecomputeLayouts() {
        guard currentParentWidth > 10, !nodes.isEmpty else { return }
        precomputeTask?.cancel()
        let snapshotNodes = nodes
        let visible = visibleNodeIDs
        let width = currentParentWidth
        let styleSnapshot = style
        let numbering = numberingCache
        let activeID = activeEditingNodeID
        precomputeTask = Task {
            try? await Task.sleep(nanoseconds: 120_000_000)
            if Task.isCancelled { return }
            var minIdx = Int.max
            var maxIdx = Int.min
            for (idx, node) in snapshotNodes.enumerated() {
                if visible.contains(node.id) {
                    minIdx = min(minIdx, idx)
                    maxIdx = max(maxIdx, idx)
                }
            }
            if minIdx == Int.max {
                if let aid = activeID, let idx = snapshotNodes.firstIndex(where: { $0.id == aid }) {
                    minIdx = idx
                    maxIdx = idx
                } else if !snapshotNodes.isEmpty {
                    minIdx = 0
                    maxIdx = 0
                }
            }
            if minIdx == Int.max { return }
            let start = max(0, minIdx - 50)
            let end = min(snapshotNodes.count - 1, maxIdx + 50)
            if start > end { return }
            var layouts: [UUID: LPNodeRowView.LayoutData] = [:]
            for i in start...end {
                let node = snapshotNodes[i]
                let config = resolveStyle(for: node.type, style: styleSnapshot)
                let contentWidth = max(50, width - staggerIndent(for: node.type) - 40)
                let number = numbering[node.id] ?? ""
                let imgTagPattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>|!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
                let stripped = node.content.replacingOccurrences(of: imgTagPattern, with: "", options: .regularExpression)
                let isImageOnly = stripped.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && (node.content.contains("<img") || node.content.contains("!["))
                let pTextH: CGFloat = {
                    if isImageOnly { return 0 }
                    return LPRerender.estimateNodeTextHeight(
                        text: node.content,
                        styleConfig: config,
                        width: contentWidth,
                        number: number,
                        isDark: isDarkMode
                    )
                }()
                let info = LPRerender.extractImageInfo(from: node.content)
                var pImgH: CGFloat = 0
                if let aid = info?.assetID, let size = MarkdownAssetManager.shared.getImageSize(assetID: aid) {
                    let ratio = size.height / size.width
                    let targetW = (info?.widthCm ?? 15.0) * LPRerender.pointsPerCm
                    let finalW = min(targetW, contentWidth)
                    pImgH = (finalW * ratio) + 10
                    await MainActor.run {
                        _ = MarkdownAssetManager.shared.getThumbnail(assetID: aid, targetWidth: finalW)
                    }
                }
                layouts[node.id] = LPNodeRowView.LayoutData(
                    assetID: info?.assetID,
                    widthCm: info?.widthCm,
                    predictedImgH: pImgH,
                    predictedTextH: pTextH,
                    isReady: true
                )
            }
            await MainActor.run {
                for (id, layout) in layouts {
                    self.precomputedLayoutMap[id] = layout
                    if self.heightCache[id] == nil, self.activeEditingNodeID != id {
                        self.heightCache[id] = layout.predictedTextH + layout.predictedImgH
                    }
                }
            }
        }
    }

    private func resolveStyle(for type: LPNodeType, style: LPGlobalStyle) -> LPGlobalStyle.TextStyle {
        switch type {
        case .h1: return style.h1
        case .h2: return style.h2
        case .h3: return style.h3
        case .h4: return style.h4
        case .h5: return style.h5
        case .h6: return style.h6
        case .l1, .l2, .l3, .l4, .l5: return style.body
        case .quote: return style.quote
        }
    }

    private func staggerIndent(for type: LPNodeType) -> CGFloat {
        let step: CGFloat = 42.0
        switch type {
        case .h1: return 0
        case .h2: return step
        case .h3: return step * 2
        case .h4: return step * 3
        case .h5: return step * 4
        case .h6: return step * 5
        case .l1: return (step * 5) + (step * 2.0)
        case .l2: return (step * 7) + (step * 0.5)
        case .l3: return (step * 7) + (step * 1.0)
        case .l4: return (step * 7) + (step * 1.5)
        case .l5: return (step * 7) + (step * 2.0)
        case .quote: return (step * 9) + step
        }
    }

    private func editingBinding(for node: LPRowNode) -> Binding<String> {
        Binding(
            get: {
                if editSession.nodeID == node.id {
                    return editSession.draftText
                }
                return node.content
            },
            set: { newValue in
                guard editSession.nodeID == node.id else { return }
                editSession.draftText = newValue
            }
        )
    }

    private func rowItem(node: LPRowNode, parentWidth: CGFloat) -> LPLiveRowContainer {
        LPLiveRowContainer(
            node: node,
            number: numberingCache[node.id] ?? "",
            style: style,
            isDark: isDarkMode,
            parentWidth: parentWidth,
            editingText: editingBinding(for: node),
            isSearchTarget: lastSearchHitNodeID == node.id,
            isInFocusedPacket: focusedPacketIDs.contains(node.id),
            isBeingEdited: activeEditingNodeID == node.id,
            isEditorFocused: focusedEditorNodeID == node.id,
            isAnchorNode: anchorNodeID == node.id,
            isDirtyMaster: teachingStore.dirtyPacketIDs.contains(node.id),
            canPaste: teachingStore.clipboardPacket != nil,
            cachedHeight: heightCache[node.id],
            initialCursorOffset: (activeEditingNodeID == node.id) ? pendingCursorOffset : nil,
            reportVisibility: { isVisible in handleVisibilityChange(id: node.id, isVisible: isVisible) },
            formulaMap: renderedFormulaCache,
            precomputedLayout: precomputedLayoutMap[node.id],
            onHeightCalculated: { newH in handleHeightUpdate(id: node.id, newH: newH) },
            onDeleteH3Packet: { deleteH3Packet(h3ID: node.id) },
            onCutH3Packet: { cutH3Packet(h3ID: node.id) },
            onPasteH3Packet: { pasteH3Packet(targetID: node.id) },
            onBeginEditing: { id in beginEditingAction(id: id) },
            onSplit: { left, right, pref in splitNode(id: node.id, left: left, right: right, prefix: pref) },
            onIndent: { delta in applyIndent(to: node.id, delta: delta) },
            onTabRequest: { delta in handlePhysicalTab(to: node.id, delta: delta) },
            onDeleteEmpty: { deleteNodeAction(id: node.id) },
            onMergeToPrevious: { content in mergeToPrevAction(id: node.id, contentToMerge: content) },
            onExitEditing: { exitEditingAction() },
            focusRequestToken: focusRequestToken,
            onFocusStateChanged: { id, isFocused, token in handleEditorFocusChange(id: id, isFocused: isFocused, token: token) }
        )
    }

    @ViewBuilder private func nodesListView(screenGeo: GeometryProxy, parentWidth: CGFloat) -> some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: true) {
                LazyVStack(alignment: .leading, spacing: 0) {
                    ForEach(nodes) { node in
                        rowItem(node: node, parentWidth: parentWidth).equatable()
                    }
                    Color.clear.frame(height: screenGeo.size.height * 0.6)
                }
            }
            .onChange(of: nodes) { _, newNodes in
                if !hasInitialJumped && !newNodes.isEmpty {
                    if let anchorID = externalTopAnchorID { proxy.scrollTo(anchorID, anchor: .top); self.hasInitialJumped = true }
                    else if let lastID = newNodes.last?.id { proxy.scrollTo(lastID, anchor: .bottom); self.hasInitialJumped = true }
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPRequestScroll"))) { note in
                if let id = note.userInfo? ["id"] as? UUID { withAnimation { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) } }
            }
            .onChange(of: targetSnapID) { _, newID in
                if let id = newID { proxy.scrollTo(id, anchor: .top); DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { self.targetSnapID = nil } }
            }
            .onChange(of: targetScrollID) { _, newID in
                if let id = newID { withAnimation(.easeOut(duration: 0.25)) { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) }; DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { self.targetScrollID = nil } }
            }
            .onChange(of: activeEditingNodeID) { _, newID in
                if let id = newID { withAnimation { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) } }
            }
        }
    }

    private func updateNumberingCache() {
        let newMap = LPNumberingEngine.generateNumbers(for: nodes, style: style)
        DispatchQueue.main.async { self.numberingCache = newMap }
    }

    private func beginEditingAction(id: UUID) {
        if activeEditingNodeID == id {
            focusedEditorNodeID = nil
            focusRequestToken += 1
            if editSession.nodeID == id {
                editSession.token = focusRequestToken
            }
            return
        }
        if let oid = activeEditingNodeID, oid != id { commitCurrentEdit(nodeID: oid) }
        anchorNodeID = nil
        lastSearchHitNodeID = nil
        focusedEditorNodeID = nil
        if let node = nodes.first(where: { $0.id == id }) {
            activeEditingNodeID = id
            focusRequestToken += 1
            editSession = LPActiveEditSession(nodeID: id, draftText: node.content, originalText: node.content, token: focusRequestToken)
            handleFocusIDChange(id)
        }
    }

    private func exitEditingAction() {
        if let aid = activeEditingNodeID { commitCurrentEdit(nodeID: aid) }
        withAnimation {
            self.activeEditingNodeID = nil
            self.focusedEditorNodeID = nil
            self.anchorNodeID = nil
            self.lastSearchHitNodeID = nil
            self.pendingCursorOffset = nil
            self.editSession = LPActiveEditSession()
        }
    }

    private func handleEditorFocusChange(id: UUID, isFocused: Bool, token: Int) {
        DispatchQueue.main.async {
            guard token == focusRequestToken else { return }
            if isFocused {
                focusedEditorNodeID = id
                if activeEditingNodeID != id {
                    activeEditingNodeID = id
                    handleFocusIDChange(id)
                }
            } else if focusedEditorNodeID == id {
                focusedEditorNodeID = nil
            }
        }
    }

    private func commitCurrentEdit(nodeID: UUID) {
        guard let idx = nodes.firstIndex(where: { $0.id == nodeID }) else { return }
        let draftText = (editSession.nodeID == nodeID) ? editSession.draftText : nodes[idx].content
        if nodes[idx].content != draftText {
            nodes[idx].content = draftText
            heightCache.removeValue(forKey: nodeID)
            let headIdx = findH3Head(at: idx, in: nodes)
            if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) }

            // 公式内容提交后，主动触发一次异步公式渲染，不依赖外层 task 被动感知。
            updateNumberingCache()
            schedulePrecomputeLayouts()
            Task { @MainActor in
                await ensureFormulasRendered()
            }
        }
        checkUpdateAvailability()
    }

    private func splitNode(id: UUID, left: String, right: String, prefix: String?) {
        guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }
        nodes[idx].content = left; heightCache.removeValue(forKey: id)
        let newContent = (prefix ?? "") + right.trimmingCharacters(in: .newlines)
        let newNode = LPRowNode(id: UUID(), type: nodes[idx].type, content: newContent)
        nodes.insert(newNode, at: idx + 1)
        let headIdx = findH3Head(at: idx, in: nodes)
        if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) }
        focusedEditorNodeID = nil
        activeEditingNodeID = newNode.id
        focusRequestToken += 1
        self.editSession = LPActiveEditSession(nodeID: newNode.id, draftText: newContent, originalText: newContent, token: focusRequestToken)
        self.pendingCursorOffset = 0
        handleFocusIDChange(newNode.id)
    }

    private func insertExternalLessonNodes(_ insertNodes: [TeachingLessonNode]) {
        guard !insertNodes.isEmpty else { return }
        withAnimation {
            var currentNodes = self.nodes
            let normalizedPackets = insertNodes.compactMap { node -> [LPRowNode]? in
                if !node.content.isEmpty { return node.content }
                return [
                    LPRowNode(
                        id: node.sourceID ?? UUID(),
                        type: .h3,
                        content: node.title,
                        sourceNodeID: node.sourceID,
                        sourceFileName: node.sourceFile
                    )
                ]
            }
            let allNewNodes = normalizedPackets.flatMap { $0 }
            guard !allNewNodes.isEmpty else { return }
            let firstNewH3ID = allNewNodes.first?.id
            let insertionIndex: Int
            if let targetID = anchorNodeID ?? activeEditingNodeID, let idx = currentNodes.firstIndex(where: { $0.id == targetID }) {
                let nodeType = currentNodes[idx].type
                if nodeType == .h1 || nodeType == .h2 { insertionIndex = idx + 1 }
                else {
                    let head = findH3Head(at: idx, in: currentNodes)
                    let range = findH3PacketRange(at: head, in: currentNodes)
                    insertionIndex = range.upperBound + 1
                }
            } else { insertionIndex = currentNodes.count }
            currentNodes.insert(contentsOf: allNewNodes, at: insertionIndex)
            self.nodes = currentNodes; self.anchorNodeID = nil
            if let snapID = firstNewH3ID { DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { self.targetSnapID = snapID } }
            checkUpdateAvailability()
        }
    }

    private func handleFocusIDChange(_ newID: UUID?) { if let fid = newID { if let packet = getCurrentH3Packet(from: fid), let h3 = packet.first { self.focusedPacketIDs = Set(packet.map { $0.id }); teachingStore.focusedH3PacketID = h3.id; teachingStore.isFocusedPacketFromMaster = (h3.sourceNodeID != nil) } } else { focusedPacketIDs.removeAll(); teachingStore.focusedH3PacketID = nil } }
    private func checkUpdateAvailability() { let hasOriginal = nodes.contains { $0.type == .h3 && $0.sourceNodeID == nil }; let hasDirty = nodes.contains { $0.type == .h3 && $0.sourceNodeID != nil && teachingStore.dirtyPacketIDs.contains($0.id) }; teachingStore.isUpdateAvailable = hasOriginal || hasDirty }
    private func findH3PacketRange(at h3Idx: Int, in list: [LPRowNode]) -> ClosedRange<Int> { var endIdx = h3Idx; for j in (h3Idx + 1)..<list.count { if [.h1, .h2, .h3].contains(list[j].type) { break }; endIdx = j }; return h3Idx...endIdx }
    private func findH3Head(at curIdx: Int, in list: [LPRowNode]) -> Int { var head = curIdx; for i in (0...curIdx).reversed() { if list[i].type == .h3 { head = i; break }; if [.h1, .h2].contains(list[i].type) { break } }; return head }
    private func deleteH3Packet(h3ID: UUID) { activeEditingNodeID = nil; anchorNodeID = nil; DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { guard let idx = self.nodes.firstIndex(where: { $0.id == h3ID }) else { return }; let h3Node = self.nodes[idx]; if let sid = h3Node.sourceNodeID, let sfile = h3Node.sourceFileName { self.asStore.resetChecklistItem(sourceID: sid, sourceFile: sfile, studentName: self.teachingStore.config.currentSession?.studentName ?? "") }; var updatedNodes = self.nodes; let range = self.findH3PacketRange(at: idx, in: updatedNodes); withAnimation { updatedNodes.removeSubrange(range); self.nodes = updatedNodes }; UIImpactFeedbackGenerator(style: .heavy).impactOccurred() } }
    private func getCurrentH3Packet(from id: UUID) -> [LPRowNode]? { guard let curIdx = nodes.firstIndex(where: { $0.id == id }) else { return nil }; let head = findH3Head(at: curIdx, in: nodes); if nodes[head].type != .h3 { return nil }; let range = findH3PacketRange(at: head, in: nodes); return Array(nodes[range]) }
    private func deleteNodeAction(id: UUID) { guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }; withAnimation { nodes.remove(at: idx); activeEditingNodeID = nil; focusedEditorNodeID = nil; editSession = LPActiveEditSession() } }
    private func mergeToPrevAction(id: UUID, contentToMerge: String) {
        guard let idx = nodes.firstIndex(where: { $0.id == id }), idx > 0 else { return }
        let prevIdx = idx - 1; let prevNodeID = nodes[prevIdx].id; let prevNodeNumber = numberingCache[prevNodeID] ?? ""
        let prefixLen = prevNodeNumber.isEmpty ? 0 : "\(prevNodeNumber)  ".utf16.count
        let oldContentLen = nodes[prevIdx].content.utf16.count
        self.pendingCursorOffset = prefixLen + oldContentLen
        withAnimation {
            nodes[prevIdx].content += contentToMerge
            heightCache.removeValue(forKey: prevNodeID)
            nodes.remove(at: idx)
            let headIdx = findH3Head(at: prevIdx, in: nodes)
            if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) }
        }
        focusedEditorNodeID = nil
        activeEditingNodeID = prevNodeID
        focusRequestToken += 1
        editSession = LPActiveEditSession(nodeID: prevNodeID, draftText: nodes[prevIdx].content, originalText: nodes[prevIdx].content, token: focusRequestToken)
        handleFocusIDChange(prevNodeID)
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
    }
    private func applyIndent(to id: UUID, delta: Int) { handlePhysicalTab(to: id, delta: delta) }
    private func handlePhysicalTab(to id: UUID, delta: Int) { commitCurrentEdit(nodeID: id); guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }; var node = nodes[idx]; node.type = (delta > 0) ? node.type.next : node.type.prev; heightCache.removeValue(forKey: id); nodes[idx] = node; self.editSession = LPActiveEditSession(nodeID: id, draftText: node.content, originalText: node.content); commitCurrentEdit(nodeID: id) }
    private func cutH3Packet(h3ID: UUID) {
        activeEditingNodeID = nil;
        guard let idx = nodes.firstIndex(where: { $0.id == h3ID }) else { return }
        let range = findH3PacketRange(at: idx, in: nodes)
        teachingStore.clipboardPacket = Array(nodes[range])
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
    }
    private func pasteH3Packet(targetID: UUID) { activeEditingNodeID = nil; DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { guard let clipboard = self.teachingStore.clipboardPacket, self.nodes.contains(where: { $0.id == targetID }) else { return }; var updatedNodes = self.nodes; guard let targetIdx = updatedNodes.firstIndex(where: { $0.id == targetID }) else { return }; let insIdx = self.findH3PacketRange(at: targetIdx, in: updatedNodes).upperBound + 1; updatedNodes.insert(contentsOf: clipboard, at: insIdx); self.nodes = updatedNodes; self.teachingStore.clipboardPacket = nil } }

    @MainActor
    private func ensureFormulasRendered() async {
        let allFormulas = Set(collectFormulas())
        let missingFormulas = allFormulas.filter { renderedFormulaCache[$0] == nil }
        guard !missingFormulas.isEmpty else { return }
        let results = await renderFormulas(missingFormulas)
        if results.isEmpty { return }
        for (formula, asset) in results {
            renderedFormulaCache[formula] = asset
        }
    }

    @MainActor
    private func renderFormulas(_ formulas: Set<String>) async -> [String: LPFormulaRenderAsset] {
        await withCheckedContinuation { continuation in
            ArchiveStore.headlessMathRenderer.render(formulas: formulas, style: style.body, dark: isDarkMode) { results in
                continuation.resume(returning: results)
            }
        }
    }

    private func collectFormulas() -> [String] {
        var list: [String] = []
        for node in nodes {
            for request in LPRerender.extractFormulaRequests(from: node.content) {
                list.append(request.formulaText)
            }
        }
        return list
    }
}

extension Animation { static func spring(bottomUnit: Double) -> Animation { .spring(response: bottomUnit, dampingFraction: 0.8) } }

