// MARK: - LPNodeRowView - v151 - 物理锁定内容剪裁，强制预测高度优先级解决重叠

struct LPNodeRowView: View, Equatable {
    let node: LPRowNode
    let number: String
    let style: LPGlobalStyle
    let isDark: Bool
    let parentWidth: CGFloat
    let renderNonce: Int
    @Binding var editingText: String
    
    var isSearchTarget: Bool = false
    var isInFocusedPacket: Bool = false
    var isBeingEdited: Bool = false
    var isEditorFocused: Bool = false
    var isAnchorNode: Bool = false
    let isDirtyMaster: Bool
    let canPaste: Bool
    
    let cachedHeight: CGFloat?
    var initialCursorOffset: Int? = nil
    
    let reportVisibility: (Bool) -> Void
    let formulaMap: [String: LPFormulaRenderAsset]
    let precomputedLayout: LPNodeRowView.LayoutData?
    
    var onHeightCalculated: (CGFloat) -> Void
    var onBeginEditing: (UUID) -> Void
    var onDeleteH3Packet: () -> Void
    var onCutH3Packet: () -> Void
    var onPasteH3Packet: () -> Void
    
    var onSplit: (String, String, String?) -> Void
    var onIndent: (Int) -> Void
    var onTabRequest: (Int) -> Void
    var onDeleteEmpty: () -> Void
    var onMergeToPrevious: (String) -> Void
    var onExitEditing: () -> Void
    var focusRequestToken: Int = 0
    var onFocusStateChanged: (UUID, Bool, Int) -> Void = { _, _, _ in }

    @State private var liveEditingHeight: CGFloat = 40
    @State private var textPartHeight: CGFloat = 0
    
    struct LayoutData: Equatable {
        let assetID: String?
        let widthCm: Double?
        let predictedImgH: CGFloat
        let predictedTextH: CGFloat
        let isReady: Bool
    }
    @State private var layoutData: LayoutData? = nil
    @State private var updateTask: Task<Void, Never>? = nil

    static func == (lhs: LPNodeRowView, rhs: LPNodeRowView) -> Bool {
        return lhs.node.id == rhs.node.id &&
               lhs.node.content == rhs.node.content &&
               lhs.node.type == rhs.node.type &&
               lhs.number == rhs.number &&
               lhs.isDark == rhs.isDark &&
               lhs.renderNonce == rhs.renderNonce &&
               lhs.isBeingEdited == rhs.isBeingEdited &&
               lhs.isEditorFocused == rhs.isEditorFocused &&
               lhs.isAnchorNode == rhs.isAnchorNode &&
               lhs.isDirtyMaster == rhs.isDirtyMaster &&
               lhs.canPaste == rhs.canPaste &&
               lhs.parentWidth == rhs.parentWidth &&
               lhs.style == rhs.style &&
               lhs.cachedHeight == rhs.cachedHeight &&
               lhs.formulaMap.count == rhs.formulaMap.count
    }

    private var staggerIndent: CGFloat {
        let step: CGFloat = 42.0
        switch node.type {
        case .h1: return 0; case .h2: return step; case .h3: return step * 2; case .h4: return step * 3; case .h5: return step * 4; case .h6: return step * 5
        case .l1: return (step * 5) + (step * 2.0); case .l2: return (step * 7) + (step * 0.5); case .l3: return (step * 7) + (step * 1.0)
        case .l4: return (step * 7) + (step * 1.5); case .l5: return (step * 7) + (step * 2.0); case .quote: return (step * 9) + step
        }
    }

    var body: some View {
        let contentWidth = max(50, parentWidth - staggerIndent - 40)
        let currentConfig = getTargetStyle()
        
        VStack(alignment: .leading, spacing: 0) {
            Color.clear.frame(height: currentConfig.spaceAbove)

            Group {
                if isBeingEdited {
                    renderEditor(config: currentConfig, width: contentWidth)
                } else {
                    renderStaticContent(config: currentConfig, width: contentWidth)
                }
            }
            .padding(.leading, staggerIndent + 20)
            .padding(.trailing, 20)
            .background {
                backgroundDecorations(currentConfig: currentConfig)
            }
            .overlay { selectionOverlay }
            .overlay(alignment: .leading) {
                if node.type == .quote { quoteDecoration(config: currentConfig).offset(x: staggerIndent + 12) }
            }
            
            Color.clear.frame(height: currentConfig.spaceBelow)
        }
        // 【383号核心修复】：强制开启物理剪裁，彻底杜绝内容溢出到下一行
        .clipped()
        .contentShape(Rectangle())
        .onTapGesture { onBeginEditing(node.id) }
        .onAppear {
            if layoutData == nil, let pre = precomputedLayout {
                DispatchQueue.main.async { self.layoutData = pre }
            }
            reportVisibility(true)
        }
        .onDisappear { reportVisibility(false) }
        .onChange(of: precomputedLayout) { _, newValue in
            if let pre = newValue {
                DispatchQueue.main.async {
                    if self.layoutData == nil || self.layoutData?.isReady == false {
                        self.layoutData = pre
                    }
                }
            }
        }
        .task {
            if precomputedLayout == nil {
                await performLayoutUpdate(width: contentWidth, config: currentConfig)
            }
        }
        .onChange(of: node.content) { _, newValue in
            let containsImage = newValue.contains("<img") || newValue.contains("![" )
            if precomputedLayout == nil || containsImage {
                scheduleLayoutUpdate(width: contentWidth, config: currentConfig)
            }
        }
        // 【383号核心修复】：数据就绪后立即同步高度缓存，防止滞后重叠
        .onChange(of: layoutData) { _, newData in
            if let data = newData, data.isReady {
                let h = data.predictedTextH + data.predictedImgH
                onHeightCalculated(h)
            }
        }
        .frame(width: parentWidth)
        .frame(height: calculateTotalCellHeight(currentConfig: currentConfig))
        .contextMenu { contextMenuContent }
    }

    @ViewBuilder
    private func renderStaticContent(config: LPGlobalStyle.TextStyle, width: CGFloat) -> some View {
        let imgTagPattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>|!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
        let stripped = node.content.replacingOccurrences(of: imgTagPattern, with: "", options: .regularExpression)
        let isImageOnly = stripped.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && (node.content.contains("<img") || node.content.contains("!["))
        let mathPattern = #"(?s)\$\$.*?\$\$|\$.*?\$|\\\(.*?\\\)|\\\[.*?\\\]"#
        let hasFormula = node.content.range(of: mathPattern, options: .regularExpression) != nil
        let showsSeparateNumber = !number.isEmpty
        let prefixWidth = showsSeparateNumber ? numberPrefixWidth(config: config) : 0
        let renderWidth = showsSeparateNumber ? max(20, width - prefixWidth) : width
        VStack(alignment: .leading, spacing: 10) {
            let staticAttrText = LPRerender.renderNS(
                node.content.isEmpty ? " " : node.content,
                styleConfig: config,
                scale: 1.0,
                isDark: isDark,
                hierarchicalIndent: 0,
                formulaImages: formulaMap,
                number: nil,
                isEditing: false,
                availableWidth: renderWidth,
                includeImages: false,
                renderNonce: renderNonce
            )
            let adjustedAttrText: NSAttributedString = {
                guard hasFormula else { return staticAttrText }
                let mutable = NSMutableAttributedString(attributedString: staticAttrText)
                let fullRange = NSRange(location: 0, length: mutable.length)
                // 不再对整行文字施加基线偏移，避免整体下沉
                mutable.enumerateAttribute(.attachment, in: fullRange, options: []) { value, range, _ in
                    if value != nil {
                        // 保留附件原始位置
                    }
                }
                return mutable
            }()
            
            Group {
                if !isImageOnly {
                    if showsSeparateNumber {
                        ZStack(alignment: .topLeading) {
                            if !number.isEmpty {
                                Text(numberAttributedString(config: config))
                                    .frame(width: prefixWidth, alignment: .leading)
                                    .padding(.top, numberVerticalNudge(config: config))
                            }
                            LPRenderedTextView(
                                attributedText: adjustedAttrText,
                                fixedWidth: renderWidth,
                                onHeightCalculated: { h in
                                    DispatchQueue.main.async {
                                        self.textPartHeight = h
                                        let imgH = layoutData?.predictedImgH ?? 0
                                        let totalH = h + imgH
                                        // 预计算已就绪时，只有“偏差足够大”才允许校正，避免进入视野后反复跳动
                                        if let pre = precomputedLayout, pre.isReady {
                                            let preTotal = pre.predictedTextH + pre.predictedImgH
                                            if abs(totalH - preTotal) < 6.0 { return }
                                        }
                                        // 仅在真实测量偏差较大时更新缓存
                                        if let current = cachedHeight, abs(totalH - current) < 5.0 { return }
                                        onHeightCalculated(totalH)
                                    }
                                }
                            )
                            .id("rendered_text_\(node.id.uuidString)_\(renderNonce)_numbered")
                            .padding(.leading, prefixWidth)
                        }
                    } else {
                        LPRenderedTextView(
                            attributedText: staticAttrText,
                            fixedWidth: renderWidth,
                            onHeightCalculated: { h in
                                DispatchQueue.main.async {
                                    self.textPartHeight = h
                                    let imgH = layoutData?.predictedImgH ?? 0
                                    let totalH = h + imgH
                                    // 预计算已就绪时，只有“偏差足够大”才允许校正，避免进入视野后反复跳动
                                    if let pre = precomputedLayout, pre.isReady {
                                        let preTotal = pre.predictedTextH + pre.predictedImgH
                                        if abs(totalH - preTotal) < 6.0 { return }
                                    }
                                    // 仅在真实测量偏差较大时更新缓存
                                    if let current = cachedHeight, abs(totalH - current) < 5.0 { return }
                                    onHeightCalculated(totalH)
                                }
                            }
                        )
                        .id("rendered_text_\(node.id.uuidString)_\(renderNonce)_plain")
                    }
                } else {
                    Color.clear.frame(height: 0)
                }
            }
            .frame(height: isImageOnly ? 0 : max(textPartHeight > 0 ? textPartHeight : (layoutData?.predictedTextH ?? 0), minimumRowContentHeight(config: config, text: node.content)))
            #if os(macOS)
            .allowsHitTesting(false)
            #endif

            if let aid = layoutData?.assetID {
                Group {
                    if isImageOnly {
                        let prefixWidth = numberPrefixWidth(config: config)
                        ZStack(alignment: .topLeading) {
                            if !number.isEmpty {
                                Text(numberAttributedString(config: config))
                                    .frame(width: prefixWidth, alignment: .leading)
                                    .padding(.top, numberVerticalNudge(config: config))
                            }

                            LPImageNodeView(assetID: aid, widthCm: layoutData?.widthCm, availableWidth: width, lockedHeight: max(0, (layoutData?.predictedImgH ?? 10)))
                                .padding(.leading, prefixWidth)
                        }
                    } else {
                        LPImageNodeView(assetID: aid, widthCm: layoutData?.widthCm, availableWidth: width, lockedHeight: max(0, (layoutData?.predictedImgH ?? 10)))
                    }
                }
                #if os(macOS)
                .allowsHitTesting(false)
                #endif
            }
        }
        .padding(.top, contentTopPadding(config: config))
    }

    // 【383号关键修正】：重构高度判定优先级
    private func calculateTotalCellHeight(currentConfig: LPGlobalStyle.TextStyle) -> CGFloat? {
        let contentH: CGFloat
        if isBeingEdited {
            contentH = liveEditingHeight
        } else {
            let imgTagPattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>|!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
            let stripped = node.content.replacingOccurrences(of: imgTagPattern, with: "", options: .regularExpression)
            let isImageOnly = stripped.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && (node.content.contains("<img") || node.content.contains("!["))
            let measuredTextH: CGFloat = {
                if isImageOnly { return 0 }
                if textPartHeight > 0 { return textPartHeight }
                if let data = layoutData { return data.predictedTextH }
                if let cache = cachedHeight { return cache }
                return 60
            }()
            let imgH = layoutData?.predictedImgH ?? 0
            if imgH > 0 {
                if isImageOnly {
                    contentH = measuredTextH + imgH
                } else {
                    contentH = max(measuredTextH + imgH, cachedHeight ?? 0)
                }
            } else {
                contentH = max(measuredTextH, cachedHeight ?? 0)
            }
        }
        return contentH + LPRerender.nodeOuterHeight(styleConfig: currentConfig)
    }

    private func numberPrefixWidth(config: LPGlobalStyle.TextStyle) -> CGFloat {
        numberLayoutMetrics(config: config)?.prefixWidth ?? 0
    }

    private func numberUIFont(config: LPGlobalStyle.TextStyle) -> UIFont {
        numberLayoutMetrics(config: config)?.font
            ?? LPRerender.resolveUIFont(name: config.fontName, size: config.size, isBold: config.isBold)
    }

    private func numberColor(config: LPGlobalStyle.TextStyle) -> Color {
        Color(numberLayoutMetrics(config: config)?.color ?? UIColor(LPRerender.lpAdaptiveColor(hex: config.color, dark: isDark)))
    }

    private func numberAttributedString(config: LPGlobalStyle.TextStyle) -> AttributedString {
        let metrics = numberLayoutMetrics(config: config)
        let attributed = NSAttributedString(
            string: number,
            attributes: [
                .font: metrics?.font ?? numberUIFont(config: config),
                .foregroundColor: metrics?.color ?? UIColor(numberColor(config: config))
            ]
        )
        return AttributedString(attributed)
    }

    private func numberVerticalNudge(config: LPGlobalStyle.TextStyle) -> CGFloat {
        max(0, config.lineSpacing * 0.12)
    }

    private func numberLayoutMetrics(config: LPGlobalStyle.TextStyle) -> LPRerender.NumberLayoutMetrics? {
        LPRerender.numberLayoutMetrics(number: number, styleConfig: config, isDark: isDark)
    }

    private func editingParagraphStyle(config: LPGlobalStyle.TextStyle) -> NSParagraphStyle {
        LPRerender.makeEditorParagraphStyle(
            styleConfig: config,
            number: number,
            isDark: isDark,
            embedsNumber: false
        )
    }

    private func contentTopPadding(config: LPGlobalStyle.TextStyle) -> CGFloat {
        4
    }

    private func minimumRowContentHeight(config: LPGlobalStyle.TextStyle, text: String) -> CGFloat {
        let hasDisplayFormula = text.range(of: #"(?s)\$\$.*?\$\$|\\\[.*?\\\]"#, options: .regularExpression) != nil
        return hasDisplayFormula ? (config.size * 1.6) : max(config.size * 1.6, config.size + config.lineSpacing)
    }

    @ViewBuilder
    private func renderEditor(config: LPGlobalStyle.TextStyle, width: CGFloat) -> some View {
        #if os(macOS)
        let editorWidth = max(40, width)
        let prefixWidth = numberPrefixWidth(config: config)
        let editorContentWidth = max(40, editorWidth - prefixWidth)
        LPRenderedTextView(
            attributedText: LPRerender.renderNS(
                editingText.isEmpty ? " " : editingText,
                styleConfig: config,
                scale: 1.0,
                isDark: isDark,
                hierarchicalIndent: 0,
                formulaImages: formulaMap,
                number: nil,
                isEditing: false,
                availableWidth: editorContentWidth,
                includeImages: false,
                renderNonce: renderNonce
            ),
            fixedWidth: editorContentWidth
        )
        .frame(height: liveEditingHeight)
        .opacity(0)
        .allowsHitTesting(false)
        .overlay(alignment: .topLeading) {
            let editorMinHeight = max(textPartHeight, cachedHeight ?? 0, minimumRowContentHeight(config: config, text: editingText))
            LPRowEditor(
                text: $editingText,
                style: config,
                isDark: isDark,
                dynamicHeight: $liveEditingHeight,
                scopeID: node.id,
                number: number,
                fixedWidth: editorContentWidth,
                isH3: node.type == .h3,
                initialCursorOffset: initialCursorOffset,
                isFocused: true,
                focusRequestToken: focusRequestToken,
                onManualTap: {},
                onFocusChanged: { isFocused, token in onFocusStateChanged(node.id, isFocused, token) },
                onEsc: { onExitEditing() },
                onMoveFocus: { _, _ in },
                onSplit: { l, r, p in onSplit(l, r, p) },
                onIndent: { d in onIndent(d) },
                onTabRequest: { d in onTabRequest(d) },
                onDeleteEmpty: { onDeleteEmpty() },
                onMergeToPrevious: { mergedText in onMergeToPrevious(mergedText) },
                minimumHeight: editorMinHeight
            )
            .id("row_editor_\(node.id)")
            .frame(width: editorContentWidth, height: liveEditingHeight, alignment: .topLeading)
            .padding(.leading, prefixWidth)
            .onChange(of: liveEditingHeight) { _, newH in onHeightCalculated(newH) }
            .background(Color.clear)
            .contentShape(Rectangle())
        }
            .overlay(alignment: .topLeading) {
                if !number.isEmpty {
                    Text(numberAttributedString(config: config))
                        .frame(width: numberPrefixWidth(config: config), alignment: .leading)
                        .padding(.top, numberVerticalNudge(config: config))
                }
            }
        .padding(.top, contentTopPadding(config: config))
        #else
        LPRowEditor(text: $editingText, style: config, isDark: isDark, dynamicHeight: $liveEditingHeight, scopeID: node.id, number: number, fixedWidth: width, isH3: node.type == .h3, initialCursorOffset: initialCursorOffset, isFocused: true, focusRequestToken: focusRequestToken, onManualTap: {}, onFocusChanged: { isFocused, token in onFocusStateChanged(node.id, isFocused, token) }, onEsc: { onExitEditing() }, minimumHeight: minimumRowContentHeight(config: config, text: editingText), onMoveFocus: { _, _ in }, onSplit: { l, r, p in onSplit(l, r, p) }, onIndent: { d in onIndent(d) }, onTabRequest: { d in onTabRequest(d) }, onDeleteEmpty: { onDeleteEmpty() }, onMergeToPrevious: { mergedText in onMergeToPrevious(mergedText) })
            .id("row_editor_\(node.id)")
            .frame(height: liveEditingHeight)
            .onChange(of: liveEditingHeight) { _, newH in onHeightCalculated(newH) }
        #endif
    }

    private func scheduleLayoutUpdate(width: CGFloat, config: LPGlobalStyle.TextStyle) {
        updateTask?.cancel()
        updateTask = Task {
            try? await Task.sleep(nanoseconds: 500_000_000)
            if Task.isCancelled { return }
            await performLayoutUpdate(width: width, config: config)
        }
    }

    private func performLayoutUpdate(width: CGFloat, config: LPGlobalStyle.TextStyle) async {
        let info = LPRerender.extractImageInfo(from: node.content)
        let imgTagPattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>|!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
        let stripped = node.content.replacingOccurrences(of: imgTagPattern, with: "", options: .regularExpression)
        let isImageOnly = stripped.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && (node.content.contains("<img") || node.content.contains("!["))
        let pTextH: CGFloat = {
            if isImageOnly { return 0 }
            let charCount = CGFloat(node.content.count + number.count); let charsPerLine = max(1, width / (config.size * 0.8)); let lines = ceil(charCount / charsPerLine)
            return max(config.size + 4, lines * (config.size + config.lineSpacing))
        }()
        let pImgH: CGFloat = {
            if let aid = info?.assetID, let size = MarkdownAssetManager.shared.getImageSize(assetID: aid) {
                let ratio = size.height / size.width; let targetW = (info?.widthCm ?? 15.0) * LPRerender.pointsPerCm
                return (min(targetW, width) * ratio) + 10
            }
            return 0
        }()
        await MainActor.run { self.layoutData = LayoutData(assetID: info?.assetID, widthCm: info?.widthCm, predictedImgH: pImgH, predictedTextH: pTextH, isReady: true) }
    }

    @ViewBuilder private func backgroundDecorations(currentConfig: LPGlobalStyle.TextStyle) -> some View {
        ZStack {
            if isBeingEdited || isEditorFocused { RoundedRectangle(cornerRadius: 15).fill(Color.blue.opacity(0.12)).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
            else if isAnchorNode { RoundedRectangle(cornerRadius: 15).fill(Color.purple.opacity(0.15)).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
            else if currentConfig.showBackground { RoundedRectangle(cornerRadius: 12).fill(LPRerender.lpAdaptiveColor(hex: currentConfig.color, dark: isDark).opacity(isDark ? 0.12 : 0.08)).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
            if node.type == .h3 {
                let isTrulyOriginal = (node.sourceNodeID == nil); let isFromHarvest = (node.sourceFileName?.contains("上课收集") ?? false)
                if isTrulyOriginal { RoundedRectangle(cornerRadius: 15).stroke(Color.red.opacity(0.8), lineWidth: 2).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
                else if isFromHarvest { RoundedRectangle(cornerRadius: 15).stroke(Color.orange.opacity(0.8), lineWidth: 2).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
                else if isDirtyMaster { RoundedRectangle(cornerRadius: 15).stroke(Color.blue.opacity(0.8), lineWidth: 2).padding(.leading, staggerIndent + 10).padding(.trailing, 18) }
            }
        }
    }
    
    @ViewBuilder private var selectionOverlay: some View {
        if isBeingEdited || isEditorFocused {
            RoundedRectangle(cornerRadius: 15).stroke(Color.blue, lineWidth: 2.5).padding(.leading, staggerIndent + 10).padding(.trailing, 18)
        } else if isAnchorNode {
            RoundedRectangle(cornerRadius: 15).stroke(Color.purple, lineWidth: 2.5).padding(.leading, staggerIndent + 10).padding(.trailing, 18)
        } else if isSearchTarget {
            RoundedRectangle(cornerRadius: 12).stroke(Color.orange, lineWidth: 2.5).padding(.leading, staggerIndent + 10).padding(.trailing, 18)
        }
    }
    
    @ViewBuilder private var contextMenuContent: some View {
        if node.type == .h3 { Button(action: onCutH3Packet) { Label("剪切 H3 内容包", systemImage: "scissors") }; Button(role: .destructive, action: onDeleteH3Packet) { Label("物理删除 H3 包", systemImage: "trash") } }
        if canPaste { if [.h1, .h2, .h3].contains(node.type) { Button(action: onPasteH3Packet) { Label("在此节点后粘贴内容包", systemImage: "doc.on.clipboard") } } }
    }

    private func getTargetStyle() -> LPGlobalStyle.TextStyle {
        switch node.type {
        case .h1: return style.h1; case .h2: return style.h2; case .h3: return style.h3; case .h4: return style.h4; case .h5: return style.h5; case .h6: return style.h6
        case .l1, .l2, .l3, .l4, .l5: return style.body; case .quote: return style.quote
        }
    }
    
    @ViewBuilder private func quoteDecoration(config: LPGlobalStyle.TextStyle) -> some View {
        Rectangle().fill(LPRerender.lpAdaptiveColor(hex: config.color, dark: isDark).opacity(0.4)).frame(width: 4).padding(.vertical, 2)
    }
}

// MARK: - 教案图像渲染组件 - v2 - 物理接收锁定高度，彻底消除布局抖动

struct LPImageNodeView: View {
    let assetID: String
    let widthCm: Double?
    let availableWidth: CGFloat
    let lockedHeight: CGFloat // 【378号新增】：由父容器预测并锁定的物理高度
    
    var body: some View {
        let targetWidthPoints = (widthCm ?? 15.0) * LPRerender.pointsPerCm
        let finalDisplayWidth = min(targetWidthPoints, availableWidth)
        
        ZStack {
            // 使用传入的锁定高度撑开容器，确保 LazyVStack 看到的布局永远稳定
            Color.clear.frame(width: finalDisplayWidth, height: lockedHeight)
            
            if let uiImg = MarkdownAssetManager.shared.getThumbnail(assetID: assetID, targetWidth: finalDisplayWidth) {
                Image(uiImage: uiImg)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: finalDisplayWidth, height: lockedHeight)
                    .cornerRadius(8)
            } else {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.white.opacity(0.05))
                    .frame(width: finalDisplayWidth, height: lockedHeight)
            }
        }
    }
}

extension Animation { static let fast = Animation.spring(response: 0.2, dampingFraction: 0.8) }
// MARK: - LPLiveRowContainer - v29 - 物理对齐合并协议签名，支持纯净内容向上传递

struct LPLiveRowContainer: View, Equatable {
    let node: LPRowNode
    let number: String
    let style: LPGlobalStyle
    let isDark: Bool
    let parentWidth: CGFloat
    let renderNonce: Int
    @Binding var editingText: String
    
    let isSearchTarget: Bool
    let isInFocusedPacket: Bool
    var isBeingEdited: Bool = false
    var isEditorFocused: Bool = false
    var isAnchorNode: Bool = false
    let isDirtyMaster: Bool
    let canPaste: Bool
    
    let cachedHeight: CGFloat?
    var initialCursorOffset: Int? = nil
    let reportVisibility: (Bool) -> Void
    let formulaMap: [String: LPFormulaRenderAsset]
    let precomputedLayout: LPNodeRowView.LayoutData?
    
    var onHeightCalculated: (CGFloat) -> Void
    var onDeleteH3Packet: () -> Void
    var onCutH3Packet: () -> Void
    var onPasteH3Packet: () -> Void
    var onBeginEditing: (UUID) -> Void

    var onSplit: (String, String, String?) -> Void
    var onIndent: (Int) -> Void
    var onTabRequest: (Int) -> Void
    var onDeleteEmpty: () -> Void
    // 【367号重构】：闭包签名升级，接收剥离编号后的纯内容
    var onMergeToPrevious: (String) -> Void
    var onExitEditing: () -> Void
    var focusRequestToken: Int = 0
    var onFocusStateChanged: (UUID, Bool, Int) -> Void = { _, _, _ in }

    static func == (lhs: LPLiveRowContainer, rhs: LPLiveRowContainer) -> Bool {
        return lhs.node.id == rhs.node.id &&
               lhs.node.content == rhs.node.content &&
               lhs.node.type == rhs.node.type &&
               lhs.number == rhs.number &&
               lhs.isDark == rhs.isDark &&
               lhs.renderNonce == rhs.renderNonce &&
               lhs.isBeingEdited == rhs.isBeingEdited &&
               lhs.isEditorFocused == rhs.isEditorFocused &&
               lhs.isAnchorNode == rhs.isAnchorNode &&
               lhs.isDirtyMaster == rhs.isDirtyMaster &&
               lhs.canPaste == rhs.canPaste &&
               lhs.parentWidth == rhs.parentWidth &&
               lhs.style == rhs.style &&
               lhs.cachedHeight == rhs.cachedHeight &&
               lhs.initialCursorOffset == rhs.initialCursorOffset &&
               lhs.formulaMap.count == rhs.formulaMap.count &&
               lhs.precomputedLayout == rhs.precomputedLayout
    }

    var body: some View {
        // 【核心修复】：物理调用底层 v143 视图，闭合参数链路
        LPNodeRowView(
            node: node,
            number: number,
            style: style,
            isDark: isDark,
            parentWidth: parentWidth,
            renderNonce: renderNonce,
            editingText: $editingText,
            isSearchTarget: isSearchTarget,
            isInFocusedPacket: isInFocusedPacket,
            isBeingEdited: isBeingEdited,
            isAnchorNode: isAnchorNode,
            isDirtyMaster: isDirtyMaster,
            canPaste: canPaste,
            cachedHeight: cachedHeight,
            initialCursorOffset: initialCursorOffset,
            reportVisibility: reportVisibility,
            formulaMap: formulaMap,
            precomputedLayout: precomputedLayout,
            onHeightCalculated: onHeightCalculated,
            onBeginEditing: onBeginEditing,
            onDeleteH3Packet: onDeleteH3Packet,
            onCutH3Packet: onCutH3Packet,
            onPasteH3Packet: onPasteH3Packet,
            onSplit: onSplit,
            onIndent: onIndent,
            onTabRequest: onTabRequest,
            onDeleteEmpty: onDeleteEmpty,
            onMergeToPrevious: onMergeToPrevious, // 转发新版闭包
            onExitEditing: onExitEditing,
            focusRequestToken: focusRequestToken,
            onFocusStateChanged: onFocusStateChanged
        )
    }
}
// MARK: - 教案富文本渲染引擎 - v62 - 增加图文分离渲染模式，物理规避 TextKit 布局死循环

struct LPFormulaRenderAsset: Equatable {
    let image: UIImage?
    let svgMarkup: String?
    let logicalSize: CGSize?
}

struct LPFormulaRenderRequest: Hashable {
    let rawToken: String
    let formulaText: String
    let isMarked: Bool
    let isDisplay: Bool
}

extension NSAttributedString.Key {
    static let lpFormulaMarked = NSAttributedString.Key("lpFormulaMarked")
}

struct LPRerender {
    static let pointsPerCm: CGFloat = 72.0 / 2.54
    private static let mathCorePattern = #"\$\$.*?\$\$|\$.*?\$|\\\(.*?\\\)|\\\[.*?\\\]"#
    private static let formulaTokenPattern = #"(?s)<mark>\s*(\$\$.*?\$\$|\$.*?\$|\\\(.*?\\\)|\\\[.*?\\\])\s*</mark>|\$\$.*?\$\$|\$.*?\$|\\\(.*?\\\)|\\\[.*?\\\]"#
    private static let inlineImagePattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>|!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
    private static let displayFormulaPattern = #"(?s)\$\$.*?\$\$|\\\[.*?\\\]"#
    private static let repeatedBlankLinesPattern = #"\n{3,}"#
    private static let leadingBlankLinesPattern = #"^\n+"#
    private static let trailingBlankLinesPattern = #"\n+$"#
    private static let formulaPlaceholderPrefix = "\u{F8FF}"
    private static let formulaPlaceholderSuffix = "\u{F8FE}"
    @MainActor private static var regexCache: [String: NSRegularExpression] = [:]
    @MainActor private static var fontCache: [FontCacheKey: UIFont] = [:]
    @MainActor private static var fontVariantCache: [FontVariantCacheKey: UIFont] = [:]
    @MainActor private static var renderCache: [RenderCacheKey: NSAttributedString] = [:]

    private struct FontCacheKey: Hashable {
        let name: String
        let sizeKey: Int
        let isBold: Bool
    }

    private struct FontVariantCacheKey: Hashable {
        let postScriptName: String
        let sizeKey: Int
        let traitsRawValue: UInt32
    }

    private struct RenderCacheKey: Hashable {
        let text: String
        let fontName: String
        let color: String
        let sizeKey: Int
        let isBold: Bool
        let letterSpacingKey: Int
        let spaceAboveKey: Int
        let spaceBelowKey: Int
        let lineSpacingKey: Int
        let scaleKey: Int
        let isDark: Bool
        let indentKey: Int
        let number: String?
        let isEditing: Bool
        let availableWidthKey: Int
        let includeImages: Bool
        let formulaSignature: String
        let renderNonce: Int
    }

    @MainActor
    private static func cachedRegex(pattern: String, options: NSRegularExpression.Options = []) -> NSRegularExpression? {
        let cacheKey = "\(options.rawValue)||\(pattern)"
        if let cached = regexCache[cacheKey] {
            return cached
        }
        guard let regex = try? NSRegularExpression(pattern: pattern, options: options) else {
            return nil
        }
        regexCache[cacheKey] = regex
        return regex
    }

    @MainActor
    private static func cachedFontVariant(_ font: UIFont, traits: UIFontDescriptor.SymbolicTraits) -> UIFont? {
        let descriptor = font.fontDescriptor
        let rawPostScriptName: String? = descriptor.postscriptName
        let postScriptName: String
        if let name = rawPostScriptName, !name.isEmpty {
            postScriptName = name
        } else if let family = descriptor.object(forKey: .family) as? String, !family.isEmpty {
            postScriptName = family
        } else {
            postScriptName = "UnknownFont"
        }
        let cacheKey = FontVariantCacheKey(
            postScriptName: postScriptName,
            sizeKey: Int((font.pointSize * 100).rounded()),
            traitsRawValue: traits.rawValue
        )
        if let cached = fontVariantCache[cacheKey] {
            return cached
        }
        #if os(macOS)
        let variantDescriptor = descriptor.withSymbolicTraits(traits)
        if let variant = UIFont(descriptor: variantDescriptor, size: font.pointSize) {
            fontVariantCache[cacheKey] = variant
            return variant
        }
        #else
        if let variantDescriptor = descriptor.withSymbolicTraits(traits) {
            let variant = UIFont(descriptor: variantDescriptor, size: font.pointSize)
            fontVariantCache[cacheKey] = variant
            return variant
        }
        #endif
        return nil
    }

    private static func makeRenderCacheKey(
        text: String,
        styleConfig: LPGlobalStyle.TextStyle,
        scale: CGFloat,
        isDark: Bool,
        hierarchicalIndent: CGFloat,
        highlightRange: NSRange?,
        formulaImages: [String: LPFormulaRenderAsset]?,
        number: String?,
        isEditing: Bool,
        availableWidth: CGFloat?,
        includeImages: Bool,
        renderNonce: Int
    ) -> RenderCacheKey? {
        guard highlightRange == nil else { return nil }
        let formulaSignature: String
        if let formulaImages, !formulaImages.isEmpty {
            formulaSignature = formulaImages.keys.sorted().joined(separator: "|")
        } else {
            formulaSignature = ""
        }
        return RenderCacheKey(
            text: text,
            fontName: styleConfig.fontName,
            color: styleConfig.color,
            sizeKey: Int((styleConfig.size * 100).rounded()),
            isBold: styleConfig.isBold,
            letterSpacingKey: Int((styleConfig.letterSpacing * 100).rounded()),
            spaceAboveKey: Int((styleConfig.spaceAbove * 100).rounded()),
            spaceBelowKey: Int((styleConfig.spaceBelow * 100).rounded()),
            lineSpacingKey: Int((styleConfig.lineSpacing * 100).rounded()),
            scaleKey: Int((scale * 1000).rounded()),
            isDark: isDark,
            indentKey: Int((hierarchicalIndent * 100).rounded()),
            number: number,
            isEditing: isEditing,
            availableWidthKey: Int(((availableWidth ?? -1) * 10).rounded()),
            includeImages: includeImages,
            formulaSignature: formulaSignature,
            renderNonce: renderNonce
        )
    }

    static func extractFormulaRequests(from text: String) -> [LPFormulaRenderRequest] {
        guard let regex = cachedRegex(pattern: formulaTokenPattern) else { return [] }
        let nsText = text as NSString
        let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: nsText.length))
        return matches.compactMap { match in
            let rawToken = nsText.substring(with: match.range)
            let isMarked = rawToken.hasPrefix("<mark>")
            let formulaText: String
            if isMarked, match.numberOfRanges > 1, match.range(at: 1).location != NSNotFound {
                formulaText = nsText.substring(with: match.range(at: 1))
            } else {
                formulaText = rawToken
            }
            let isDisplay = formulaText.hasPrefix("$$") || formulaText.hasPrefix("\\[")
            return LPFormulaRenderRequest(rawToken: rawToken, formulaText: formulaText, isMarked: isMarked, isDisplay: isDisplay)
        }
    }

    struct NumberLayoutMetrics {
        let prefixText: String
        let prefixWidth: CGFloat
        let font: UIFont
        let color: UIColor
    }

    @MainActor
    static func numberLayoutMetrics(
        number: String?,
        styleConfig: LPGlobalStyle.TextStyle,
        scale: CGFloat = 1.0,
        isDark: Bool
    ) -> NumberLayoutMetrics? {
        guard let number, !number.isEmpty else { return nil }
        let font = resolveUIFont(
            name: styleConfig.fontName,
            size: styleConfig.size * scale,
            isBold: styleConfig.isBold
        )
        let prefixText = "\(number)  "
        let prefixWidth = ceil((prefixText as NSString).size(withAttributes: [.font: font]).width)
        return NumberLayoutMetrics(
            prefixText: prefixText,
            prefixWidth: prefixWidth,
            font: font,
            color: UIColor(lpAdaptiveColor(hex: styleConfig.color, dark: isDark))
        )
    }

    static func makeParagraphStyle(
        styleConfig: LPGlobalStyle.TextStyle,
        scale: CGFloat,
        hierarchicalIndent: CGFloat = 0,
        prefixWidth: CGFloat = 0
    ) -> NSMutableParagraphStyle {
        let paragraph = NSMutableParagraphStyle()
        paragraph.lineSpacing = styleConfig.lineSpacing * scale
        paragraph.paragraphSpacing = styleConfig.spaceBelow * scale
        paragraph.paragraphSpacingBefore = styleConfig.spaceAbove * scale
        paragraph.firstLineHeadIndent = hierarchicalIndent
        paragraph.headIndent = hierarchicalIndent + prefixWidth
        paragraph.minimumLineHeight = 0
        paragraph.maximumLineHeight = 0
        return paragraph
    }

    @MainActor
    static func makeEditorParagraphStyle(
        styleConfig: LPGlobalStyle.TextStyle,
        number: String? = nil,
        scale: CGFloat = 1.0,
        isDark: Bool,
        embedsNumber: Bool
    ) -> NSMutableParagraphStyle {
        let prefixWidth = embedsNumber
            ? (numberLayoutMetrics(number: number, styleConfig: styleConfig, scale: scale, isDark: isDark)?.prefixWidth ?? 0)
            : 0
        return makeParagraphStyle(
            styleConfig: styleConfig,
            scale: scale,
            hierarchicalIndent: 0,
            prefixWidth: prefixWidth
        )
    }

    @MainActor
    static func estimateNodeTextHeight(
        text: String,
        styleConfig: LPGlobalStyle.TextStyle,
        width: CGFloat,
        number: String = "",
        isDark: Bool
    ) -> CGFloat {
        let safeWidth = max(40, width)
        let rendered = renderNS(
            text.isEmpty ? " " : text,
            styleConfig: styleConfig,
            scale: 1.0,
            isDark: isDark,
            hierarchicalIndent: 0,
            formulaImages: nil,
            number: number.isEmpty ? nil : number,
            isEditing: false,
            availableWidth: safeWidth,
            includeImages: false
        )
        let rect = rendered.boundingRect(
            with: CGSize(width: safeWidth, height: .greatestFiniteMagnitude),
            options: [.usesLineFragmentOrigin, .usesFontLeading],
            context: nil
        )
        return ceil(max(styleConfig.size + 4, rect.height))
    }

    static func nodeOuterHeight(styleConfig: LPGlobalStyle.TextStyle) -> CGFloat {
        8 + styleConfig.spaceAbove + styleConfig.spaceBelow
    }

    static func formulaAttachmentScale(renderScale: CGFloat, isDisplay: Bool) -> CGFloat {
        if renderScale < 1.0 {
            return isDisplay ? 0.99 : 0.996
        } else {
            return isDisplay ? 1.90 : 2.004
        }
    }

    private static func inlineFormulaBaselineShift(font: UIFont, attachmentHeight: CGFloat) -> CGFloat {
        let lineHeight = font.ascender - font.descender + font.leading
        let centered = font.descender - ((attachmentHeight - lineHeight) / 2)
        return centered - (lineHeight * 0.11)
    }

    private static func formulaHighlightColor(isDark: Bool) -> UIColor {
        isDark ? UIColor.systemYellow.withAlphaComponent(0.58) : UIColor.systemYellow.withAlphaComponent(0.46)
    }

    private static func makeFormulaAttachment(from asset: LPFormulaRenderAsset) -> NSTextAttachment? {
        let attachment = NSTextAttachment()
        attachment.allowsTextAttachmentView = true
        if let svgMarkup = asset.svgMarkup,
           let svgData = svgMarkup.data(using: .utf8) {
            attachment.contents = svgData
            attachment.fileType = UTType(filenameExtension: "svg")?.identifier ?? "public.svg-image"
        }
        if let image = asset.image {
            attachment.image = image
        }
        return (attachment.contents != nil || attachment.image != nil) ? attachment : nil
    }

    private static func makeMarkedFormulaAttachment(
        from asset: LPFormulaRenderAsset,
        targetFormulaSize: CGSize,
        isDisplay: Bool,
        isDark: Bool
    ) -> (attachment: NSTextAttachment, attachmentSize: CGSize)? {
        guard let baseImage = asset.image else {
            guard let attachment = makeFormulaAttachment(from: asset) else { return nil }
            return (attachment, targetFormulaSize)
        }

        let horizontalPadding = isDisplay
            ? max(8, targetFormulaSize.width * 0.05)
            : max(4, targetFormulaSize.height * 0.16)
        let verticalPadding = isDisplay
            ? max(6, targetFormulaSize.height * 0.10)
            : max(3, targetFormulaSize.height * 0.10)
        let attachmentSize = CGSize(
            width: targetFormulaSize.width + horizontalPadding * 2,
            height: targetFormulaSize.height + verticalPadding * 2
        )
        let formulaRect = CGRect(
            x: horizontalPadding,
            y: verticalPadding,
            width: targetFormulaSize.width,
            height: targetFormulaSize.height
        )
        let highlightColor = formulaHighlightColor(isDark: isDark)
        let highlightedImage: UIImage

        #if os(macOS)
        let image = NSImage(size: attachmentSize)
        image.lockFocus()
        NSGraphicsContext.current?.imageInterpolation = .high
        highlightColor.setFill()
        NSBezierPath(roundedRect: CGRect(origin: .zero, size: attachmentSize), cornerRadius: isDisplay ? 8 : 6).fill()
        baseImage.draw(in: formulaRect, from: .zero, operation: .sourceOver, fraction: 1.0)
        image.unlockFocus()
        highlightedImage = image
        #else
        let renderer = UIGraphicsImageRenderer(size: attachmentSize)
        highlightedImage = renderer.image { _ in
            let path = UIBezierPath(roundedRect: CGRect(origin: .zero, size: attachmentSize), cornerRadius: isDisplay ? 8 : 6)
            highlightColor.setFill()
            path.fill()
            baseImage.draw(in: formulaRect)
        }
        #endif

        let attachment = NSTextAttachment()
        attachment.allowsTextAttachmentView = true
        attachment.image = highlightedImage
        return (attachment, attachmentSize)
    }

    @MainActor
    static func render(_ text: String, styleConfig: LPGlobalStyle.TextStyle, isDark: Bool, highlightRange: NSRange? = nil) -> AttributedString {
        let ns = renderNS(text, styleConfig: styleConfig, scale: 1.0, isDark: isDark, hierarchicalIndent: 0, highlightRange: highlightRange)
        return AttributedString(ns)
    }
    
    @MainActor
    static func renderNS(_ text: String, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool, hierarchicalIndent: CGFloat, highlightRange: NSRange? = nil, formulaImages: [String: LPFormulaRenderAsset]? = nil, number: String? = nil, isEditing: Bool = false, availableWidth: CGFloat? = nil, includeImages: Bool = true, renderNonce: Int = 0) -> NSAttributedString {
        if let cacheKey = makeRenderCacheKey(
            text: text,
            styleConfig: styleConfig,
            scale: scale,
            isDark: isDark,
            hierarchicalIndent: hierarchicalIndent,
            highlightRange: highlightRange,
            formulaImages: formulaImages,
            number: number,
            isEditing: isEditing,
            availableWidth: availableWidth,
            includeImages: includeImages,
            renderNonce: renderNonce
        ), let cached = renderCache[cacheKey] {
            return cached.copy() as? NSAttributedString ?? cached
        }

        let scaledSize = styleConfig.size * scale
        let uiFont = resolveUIFont(name: styleConfig.fontName, size: scaledSize, isBold: styleConfig.isBold)
        
        // --- 375号核心逻辑：图文分离预处理 ---
        var contentToRender = text
        if !includeImages && !isEditing {
            // 如果不包含图片且非编辑态，物理抹除图片标签，防止 TextKit 介入图片渲染
            contentToRender = text.replacingOccurrences(of: inlineImagePattern, with: "", options: .regularExpression)
        }
        
        // display 公式强制独占一行，避免影响同一行文字基线
        if !isEditing {
            if let regex = cachedRegex(pattern: displayFormulaPattern) {
                let range = NSRange(location: 0, length: (contentToRender as NSString).length)
                contentToRender = regex.stringByReplacingMatches(in: contentToRender, options: [], range: range, withTemplate: "\n$0\n")
            }
            // 避免块级公式导致首行空行或过多空行
            contentToRender = contentToRender.replacingOccurrences(of: repeatedBlankLinesPattern, with: "\n\n", options: .regularExpression)
            contentToRender = contentToRender.replacingOccurrences(of: leadingBlankLinesPattern, with: "", options: .regularExpression)
            contentToRender = contentToRender.replacingOccurrences(of: trailingBlankLinesPattern, with: "", options: .regularExpression)
        }
        
        // 1. 编号嵌入逻辑
        var fullText = contentToRender
        let numberMetrics = numberLayoutMetrics(number: number, styleConfig: styleConfig, scale: scale, isDark: isDark)
        let prefixWidth = numberMetrics?.prefixWidth ?? 0
        if let numberMetrics {
            fullText = numberMetrics.prefixText + contentToRender
        }

        let nsAttr = NSMutableAttributedString(string: fullText)
        let fullRange = NSRange(location: 0, length: nsAttr.length)
        
        // 2. 段落样式
        let paragraph = makeParagraphStyle(
            styleConfig: styleConfig,
            scale: scale,
            hierarchicalIndent: hierarchicalIndent,
            prefixWidth: prefixWidth
        )
        
        let baseColor = lpAdaptiveColor(hex: styleConfig.color, dark: isDark)
        nsAttr.addAttributes([
            .paragraphStyle: paragraph,
            .font: uiFont,
            .foregroundColor: UIColor(baseColor),
            .kern: Double(styleConfig.letterSpacing * scale)
        ], range: fullRange)
        
        // 3. 搜索高亮
        if let hRange = highlightRange {
            let offset = number.map { "\($0)  ".utf16.count } ?? 0
            let adjustedRange = NSRange(location: hRange.location + offset, length: hRange.length)
            if adjustedRange.location + adjustedRange.length <= nsAttr.length {
                let highlightBg = isDark ? UIColor.systemYellow.withAlphaComponent(0.4) : UIColor.systemYellow.withAlphaComponent(0.3)
                nsAttr.addAttribute(.backgroundColor, value: highlightBg, range: adjustedRange)
                nsAttr.addAttribute(.foregroundColor, value: UIColor.black, range: adjustedRange)
            }
        }

        // --- 执行语法转码 ---
        applyMarkdownStyles(to: nsAttr, sourceText: fullText, styleConfig: styleConfig, scale: scale, isDark: isDark, formulaImages: formulaImages, isEditing: isEditing, availableWidth: availableWidth, includeImages: includeImages)

        let rendered = nsAttr.copy() as? NSAttributedString ?? nsAttr
        if let cacheKey = makeRenderCacheKey(
            text: text,
            styleConfig: styleConfig,
            scale: scale,
            isDark: isDark,
            hierarchicalIndent: hierarchicalIndent,
            highlightRange: highlightRange,
            formulaImages: formulaImages,
            number: number,
            isEditing: isEditing,
            availableWidth: availableWidth,
            includeImages: includeImages,
            renderNonce: renderNonce
        ) {
            renderCache[cacheKey] = rendered
        }

        return rendered
    }

    @MainActor
    private static func applyMarkdownStyles(to nsAttr: NSMutableAttributedString, sourceText: String, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool, formulaImages: [String: LPFormulaRenderAsset]?, isEditing: Bool, availableWidth: CGFloat?, includeImages: Bool) {
        let scaledSize = styleConfig.size * scale
        let baseFont = resolveUIFont(name: styleConfig.fontName, size: scaledSize, isBold: styleConfig.isBold)
        let italicFont = cachedFontVariant(baseFont, traits: .traitItalic) ?? baseFont
        let boldFont = resolveUIFont(name: styleConfig.fontName, size: scaledSize, isBold: true)
        let boldItalicTraits: UIFontDescriptor.SymbolicTraits = [.traitBold, .traitItalic]
        let boldItalicFont = cachedFontVariant(boldFont, traits: boldItalicTraits) ?? boldFont

        if isEditing {
            // 编辑态保持源码高亮（不处理图片，由用户编辑标签）
            let tagColor = isDark ? UIColor.systemGray : UIColor.lightGray
            let accentColor = isDark ? UIColor.systemCyan : UIColor.systemBlue
            applyRegexOnlyStyle(pattern: #"\*\*\*(.*?)\*\*\*"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldItalicFont, color: accentColor) }
            applyRegexOnlyStyle(pattern: #"___(.*?)___"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldItalicFont, color: accentColor) }
            applyRegexOnlyStyle(pattern: #"\*\*(.*?)\*\*"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldFont, color: accentColor) }
            applyRegexOnlyStyle(pattern: #"__(.*?)__"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldFont, color: accentColor) }
            applyRegexOnlyStyle(pattern: #"(?<!\*)\*(?!\*)([^*\n]+?)(?<!\*)\*(?!\*)"#, to: nsAttr) { nsAttr.addAttribute(.font, value: italicFont, range: $0) }
            applyRegexOnlyStyle(pattern: #"(?<!_)_(?!_)([^_\n]+?)(?<!_)_(?!_)"#, to: nsAttr) { nsAttr.addAttribute(.font, value: italicFont, range: $0) }
            applyRegexOnlyStyle(pattern: #"~~(.*?)~~"#, to: nsAttr) { nsAttr.addAttributes([.strikethroughStyle: NSUnderlineStyle.single.rawValue, .strikethroughColor: accentColor], range: $0) }
            applyRegexOnlyStyle(pattern: #"<u>(.*?)</u>"#, to: nsAttr) { nsAttr.addAttributes([.underlineStyle: NSUnderlineStyle.single.rawValue, .underlineColor: accentColor], range: $0) }
            applyRegexOnlyStyle(pattern: #"<mark>(.*?)</mark>"#, to: nsAttr) { nsAttr.addAttribute(.backgroundColor, value: isDark ? UIColor.systemYellow.withAlphaComponent(0.42) : UIColor.systemYellow.withAlphaComponent(0.34), range: $0) }
            applyRegexOnlyStyle(pattern: #"<sub>(.*?)</sub>"#, to: nsAttr) { nsAttr.addAttributes([.font: resolveUIFont(name: styleConfig.fontName, size: scaledSize * 0.8, isBold: styleConfig.isBold), .baselineOffset: -scaledSize * 0.1], range: $0) }
            applyRegexOnlyStyle(pattern: #"<sup>(.*?)</sup>"#, to: nsAttr) { nsAttr.addAttributes([.font: resolveUIFont(name: styleConfig.fontName, size: scaledSize * 0.8, isBold: styleConfig.isBold), .baselineOffset: scaledSize * 0.2], range: $0) }
            applyRegexOnlyStyle(pattern: #"\[[^\]]+\]\(#[^)]+\)"#, to: nsAttr) { nsAttr.addAttributes([.underlineStyle: NSUnderlineStyle.single.rawValue, .foregroundColor: accentColor], range: $0) }
            applyRegexOnlyStyle(pattern: #"\[\^[^\]]+\]"#, to: nsAttr) { nsAttr.addAttributes([.font: resolveUIFont(name: styleConfig.fontName, size: scaledSize * 0.75, isBold: false), .baselineOffset: scaledSize * 0.25], range: $0) }
            applyRegexOnlyStyle(pattern: #"(?s)\$\$.*?\$\$|\$.*?\$|\\\(.*?\\\)|\\\[.*?\\\]"#, to: nsAttr) { nsAttr.addAttribute(.foregroundColor, value: accentColor, range: $0) }
            applyRegexOnlyStyle(pattern: #"(?m)^- \[(?: |x|X)\]\s+.*$|(?m)^(?:---|\*\*\*|___)\s*$|(?im)^\[\[?toc\]?\]\s*$"#, to: nsAttr) { nsAttr.addAttribute(.foregroundColor, value: tagColor, range: $0) }
            applyRegexOnlyStyle(pattern: #"<[^>]+>|\*\*\*|___|\*\*|__|\*|_|~~|\{#[A-Za-z0-9_-]+\}"#, to: nsAttr) { nsAttr.addAttribute(.foregroundColor, value: tagColor, range: $0) }
        } else {
            // 静态态处理
            let accentColor = isDark ? UIColor.systemCyan : UIColor.systemBlue
            let baseColor = lpAdaptiveColor(hex: styleConfig.color, dark: isDark)
            let maskedFormulaPlaceholders = maskFormulaTokens(in: nsAttr)
            applyRegexAndStrip(pattern: #"\*\*\*(.*?)\*\*\*"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldItalicFont, color: UIColor(baseColor)) }
            applyRegexAndStrip(pattern: #"___(.*?)___"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldItalicFont, color: UIColor(baseColor)) }
            applyRegexAndStrip(pattern: #"\*\*(.*?)\*\*"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldFont, color: UIColor(baseColor)) }
            applyRegexAndStrip(pattern: #"__(.*?)__"#, to: nsAttr) { applyBoldLikeAttributes(to: nsAttr, range: $0, font: boldFont, color: UIColor(baseColor)) }
            applyRegexAndStrip(pattern: #"(?<!\*)\*(?!\*)([^*\n]+?)(?<!\*)\*(?!\*)"#, to: nsAttr) { nsAttr.addAttribute(.font, value: italicFont, range: $0) }
            applyRegexAndStrip(pattern: #"(?<!_)_(?!_)([^_\n]+?)(?<!_)_(?!_)"#, to: nsAttr) { nsAttr.addAttribute(.font, value: italicFont, range: $0) }
            applyRegexAndStrip(pattern: #"~~(.*?)~~"#, to: nsAttr) { nsAttr.addAttributes([.strikethroughStyle: NSUnderlineStyle.single.rawValue, .strikethroughColor: UIColor(baseColor)], range: $0) }
            applyRegexAndStrip(pattern: #"<u>(.*?)</u>"#, to: nsAttr) { nsAttr.addAttributes([.underlineStyle: NSUnderlineStyle.single.rawValue, .underlineColor: UIColor.systemBlue], range: $0) }
            applyRegexAndStrip(pattern: #"<mark>(.*?)</mark>"#, to: nsAttr) { nsAttr.addAttributes([.backgroundColor: isDark ? UIColor.yellow.withAlphaComponent(0.58) : UIColor.yellow.withAlphaComponent(0.46), .foregroundColor: UIColor.black], range: $0) }
            applyRegexAndStrip(pattern: #"<sub>(.*?)</sub>"#, to: nsAttr) { nsAttr.addAttributes([.font: resolveUIFont(name: styleConfig.fontName, size: scaledSize * 0.7, isBold: styleConfig.isBold), .baselineOffset: -scaledSize * 0.15], range: $0) }
            applyRegexAndStrip(pattern: #"<sup>(.*?)</sup>"#, to: nsAttr) { nsAttr.addAttributes([.font: resolveUIFont(name: styleConfig.fontName, size: scaledSize * 0.7, isBold: styleConfig.isBold), .baselineOffset: scaledSize * 0.3], range: $0) }
            applyRegexAndStrip(pattern: #"\[([^\]]+)\]\(#[^)]+\)"#, to: nsAttr) { nsAttr.addAttributes([.foregroundColor: accentColor, .underlineStyle: NSUnderlineStyle.single.rawValue], range: $0) }
            applyMarkdownTocPlaceholder(to: nsAttr, color: isDark ? UIColor.systemGray : UIColor.systemGray)
            stripSimpleMarkdownToken(pattern: #"\s*\{#[A-Za-z0-9_-]+\}"#, to: nsAttr)
            applyTaskListMarkdown(to: nsAttr, styleConfig: styleConfig, scale: scale, isDark: isDark)
            applyHorizontalRuleMarkdown(to: nsAttr, color: isDark ? UIColor.white.withAlphaComponent(0.28) : UIColor.black.withAlphaComponent(0.18))
            applyFootnoteDefinitionMarkdown(to: nsAttr, styleConfig: styleConfig, scale: scale, isDark: isDark)
            applyFootnoteReferenceMarkdown(to: nsAttr, styleConfig: styleConfig, scale: scale, isDark: isDark)
            applyDefinitionListMarkdown(to: nsAttr, styleConfig: styleConfig, scale: scale, isDark: isDark)

            // 图像处理
            if includeImages {
                renderImagesAsAttachments(to: nsAttr, availableWidth: availableWidth)
            }

            restoreFormulaPlaceholders(maskedFormulaPlaceholders, in: nsAttr)

            // 公式处理
            var remainingFormulaRequests = extractFormulaRequests(from: sourceText)[...]
            while let request = extractFormulaRequests(from: nsAttr.string).first {
                let rawRange = (nsAttr.string as NSString).range(of: request.rawToken)
                guard rawRange.location != NSNotFound else { break }
                let sourceRequest: LPFormulaRenderRequest = {
                    guard let first = remainingFormulaRequests.first else { return request }
                    remainingFormulaRequests.removeFirst()
                    return first
                }()
                let shouldHighlightFormula = sourceRequest.isMarked || request.isMarked
                if let images = formulaImages,
                   let asset = images[request.formulaText],
                   let img = asset.image,
                   let attachment = makeFormulaAttachment(from: asset) {
                    let logicalSize = asset.logicalSize ?? img.size
                    let scaleFactor = formulaAttachmentScale(renderScale: scale, isDisplay: request.isDisplay)
                    let displayHeight = logicalSize.height * scaleFactor
                    let widthTrim = request.isDisplay ? 0 : min(scaledSize * 0.24, logicalSize.width * scaleFactor * 0.12)
                    let displayWidth = max(scaledSize * 0.6, logicalSize.width * scaleFactor - widthTrim)
                    let targetFormulaSize = CGSize(width: displayWidth, height: displayHeight)
                    let replacementAttachment: NSTextAttachment
                    let replacementSize: CGSize
                    if shouldHighlightFormula,
                       let marked = makeMarkedFormulaAttachment(
                        from: asset,
                        targetFormulaSize: targetFormulaSize,
                        isDisplay: request.isDisplay,
                        isDark: isDark
                       ) {
                        replacementAttachment = marked.attachment
                        replacementSize = marked.attachmentSize
                    } else {
                        replacementAttachment = attachment
                        replacementSize = targetFormulaSize
                    }
                    let baselineShift = request.isDisplay
                        ? -replacementSize.height * 0.18
                        : inlineFormulaBaselineShift(font: baseFont, attachmentHeight: replacementSize.height)
                    replacementAttachment.bounds = CGRect(x: 0, y: baselineShift, width: replacementSize.width, height: replacementSize.height)
                    let replacement = NSMutableAttributedString(attachment: replacementAttachment)
                    if shouldHighlightFormula {
                        replacement.addAttribute(.lpFormulaMarked, value: true, range: NSRange(location: 0, length: replacement.length))
                    }
                    nsAttr.replaceCharacters(in: rawRange, with: replacement)
                    if request.isDisplay {
                        let paragraphRange = (nsAttr.string as NSString).paragraphRange(for: NSRange(location: rawRange.location, length: 1))
                        if let currentParagraph = nsAttr.attribute(.paragraphStyle, at: rawRange.location, effectiveRange: nil) as? NSParagraphStyle {
                            let centeredParagraph = currentParagraph.mutableCopy() as? NSMutableParagraphStyle ?? NSMutableParagraphStyle()
                            centeredParagraph.alignment = .center
                            nsAttr.addAttribute(.paragraphStyle, value: centeredParagraph, range: paragraphRange)
                        }
                    }
                } else {
                    let mathColor = isDark ? UIColor.systemCyan : UIColor(red: 0, green: 0.5, blue: 0.6, alpha: 1)
                    let mathFont = UIFont.systemFont(ofSize: scaledSize, weight: .medium).with(design: .serif)?.with(traits: .traitItalic) ?? UIFont.monospacedSystemFont(ofSize: scaledSize, weight: .medium)
                    nsAttr.addAttributes([.font: mathFont, .foregroundColor: mathColor], range: rawRange)
                    break
                }
            }
        }

        applyRegexAndStrip(pattern: #"`([^`]+)`"#, to: nsAttr) { range in
            let codeFont = UIFont.monospacedSystemFont(ofSize: (styleConfig.size - 1) * scale, weight: .regular)
            let bgColor = isDark ? UIColor.white.withAlphaComponent(0.12) : UIColor.black.withAlphaComponent(0.06)
            nsAttr.addAttributes([.font: codeFont, .backgroundColor: bgColor, .foregroundColor: UIColor.systemPink], range: range)
        }
    }

    @MainActor
    private static func renderImagesAsAttachments(to nsAttr: NSMutableAttributedString, availableWidth: CGFloat?) {
        guard let regex = cachedRegex(pattern: inlineImagePattern) else { return }
        var hasMatch = true
        while hasMatch {
            let plainString = nsAttr.string
            let fullRange = NSRange(location: 0, length: (plainString as NSString).length)
            if let match = regex.firstMatch(in: plainString, options: [], range: fullRange) {
                var assetID: String? = nil
                var widthCm: Double? = nil
                if match.range(at: 1).location != NSNotFound {
                    assetID = (plainString as NSString).substring(with: match.range(at: 1))
                    if match.range(at: 2).location != NSNotFound {
                        let widthStr = (plainString as NSString).substring(with: match.range(at: 2))
                        let unit = match.range(at: 3).location != NSNotFound
                            ? (plainString as NSString).substring(with: match.range(at: 3)).lowercased()
                            : "cm"
                        if let widthVal = Double(widthStr) {
                            if unit == "px" {
                                widthCm = widthVal / pointsPerCm
                            } else if unit == "cm" || unit.isEmpty {
                                widthCm = widthVal
                            }
                        }
                    }
                } else if match.range(at: 4).location != NSNotFound {
                    assetID = (plainString as NSString).substring(with: match.range(at: 4))
                }
                if let aid = assetID {
                    let containerWidth = availableWidth ?? 800
                    let targetWidth = (widthCm ?? 15.0) * pointsPerCm
                    let finalWidth = min(targetWidth, containerWidth)
                    if let image = MarkdownAssetManager.shared.getThumbnail(assetID: aid, targetWidth: finalWidth) {
                        let attachment = NSTextAttachment(); attachment.image = image
                        let ratio = image.size.height / image.size.width
                        attachment.bounds = CGRect(x: 0, y: 0, width: finalWidth, height: finalWidth * ratio)
                        nsAttr.replaceCharacters(in: match.range, with: NSAttributedString(attachment: attachment))
                    } else { nsAttr.replaceCharacters(in: match.range, with: NSAttributedString(string: "[图片加载中...]")) }
                }
            } else { hasMatch = false }
        }
    }

    @MainActor
    private static func applyRegexOnlyStyle(pattern: String, to nsAttr: NSMutableAttributedString, styler: (NSRange) -> Void) {
        guard let regex = cachedRegex(pattern: pattern) else { return }
        let matches = regex.matches(in: nsAttr.string, options: [], range: NSRange(location: 0, length: nsAttr.length))
        for m in matches { styler(m.range) }
    }

    @MainActor
    private static func applyRegexAndStrip(pattern: String, to nsAttr: NSMutableAttributedString, styler: (NSRange) -> Void) {
        guard let regex = cachedRegex(pattern: pattern) else { return }
        var hasMatch = true
        while hasMatch {
            let plainString = nsAttr.string
            let fullRange = NSRange(location: 0, length: (plainString as NSString).length)
            if let match = regex.firstMatch(in: plainString, options: [], range: fullRange), match.numberOfRanges > 1 {
                let outerRange = match.range(at: 0); let innerRange = match.range(at: match.numberOfRanges - 1)
                let contentString = (plainString as NSString).substring(with: innerRange)
                nsAttr.replaceCharacters(in: outerRange, with: contentString)
                let newStyledRange = NSRange(location: outerRange.location, length: contentString.utf16.count)
                styler(newStyledRange)
            } else { hasMatch = false }
        }
    }

    @MainActor
    private static func maskFormulaTokens(in nsAttr: NSMutableAttributedString) -> [(placeholder: String, rawToken: String)] {
        guard let regex = cachedRegex(pattern: formulaTokenPattern) else { return [] }
        let source = nsAttr.string
        let sourceNSString = source as NSString
        let matches = regex.matches(in: source, options: [], range: NSRange(location: 0, length: sourceNSString.length))
        guard !matches.isEmpty else { return [] }
        var placeholders: [(placeholder: String, rawToken: String)] = []
        var counter = 0
        for match in matches.reversed() {
            let rawToken = sourceNSString.substring(with: match.range)
            let placeholder = "\(formulaPlaceholderPrefix)\(counter)\(formulaPlaceholderSuffix)"
            counter += 1
            placeholders.append((placeholder: placeholder, rawToken: rawToken))
            nsAttr.replaceCharacters(in: match.range, with: placeholder)
        }
        return placeholders
    }

    @MainActor
    private static func restoreFormulaPlaceholders(_ placeholders: [(placeholder: String, rawToken: String)], in nsAttr: NSMutableAttributedString) {
        guard !placeholders.isEmpty else { return }
        for (placeholder, rawToken) in placeholders {
            let currentString = nsAttr.string as NSString
            let range = currentString.range(of: placeholder)
            guard range.location != NSNotFound else { continue }
            nsAttr.replaceCharacters(in: range, with: rawToken)
        }
    }

    @MainActor
    private static func applyBoldLikeAttributes(to nsAttr: NSMutableAttributedString, range: NSRange, font: UIFont, color: UIColor? = nil) {
        var attrs: [NSAttributedString.Key: Any] = [
            .font: font,
            .strokeWidth: -2.5
        ]
        if let color {
            attrs[.strokeColor] = color
            attrs[.foregroundColor] = color
        }
        nsAttr.addAttributes(attrs, range: range)
    }

    @MainActor
    private static func stripSimpleMarkdownToken(pattern: String, to nsAttr: NSMutableAttributedString) {
        guard let regex = cachedRegex(pattern: pattern) else { return }
        var hasMatch = true
        while hasMatch {
            let plainString = nsAttr.string
            let fullRange = NSRange(location: 0, length: (plainString as NSString).length)
            if let match = regex.firstMatch(in: plainString, options: [], range: fullRange) {
                nsAttr.replaceCharacters(in: match.range, with: "")
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyMarkdownTocPlaceholder(to nsAttr: NSMutableAttributedString, color: UIColor) {
        guard let regex = cachedRegex(pattern: #"(?im)^\[\[?toc\]?\]\s*$"#) else { return }
        var hasMatch = true
        while hasMatch {
            let plainString = nsAttr.string
            let fullRange = NSRange(location: 0, length: (plainString as NSString).length)
            if let match = regex.firstMatch(in: plainString, options: [], range: fullRange) {
                nsAttr.replaceCharacters(in: match.range, with: "目录")
                nsAttr.addAttribute(.foregroundColor, value: color, range: NSRange(location: match.range.location, length: 2))
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyTaskListMarkdown(to nsAttr: NSMutableAttributedString, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool) {
        guard let regex = cachedRegex(pattern: #"(?m)^- \[( |x|X)\]\s+(.*)$"#) else { return }
        let baseFont = resolveUIFont(name: styleConfig.fontName, size: styleConfig.size * scale, isBold: styleConfig.isBold)
        var hasMatch = true
        while hasMatch {
            let plainNSString = nsAttr.string as NSString
            let fullRange = NSRange(location: 0, length: plainNSString.length)
            if let match = regex.firstMatch(in: plainNSString as String, options: [], range: fullRange), match.numberOfRanges >= 3 {
                let marker = plainNSString.substring(with: match.range(at: 1))
                let content = plainNSString.substring(with: match.range(at: 2))
                let replacement = "\(marker == " " ? "☐" : "☑") \(content)"
                nsAttr.replaceCharacters(in: match.range(at: 0), with: replacement)
                let newRange = NSRange(location: match.range.location, length: (replacement as NSString).length)
                if marker == " " {
                    nsAttr.addAttribute(.font, value: baseFont, range: newRange)
                } else {
                    let doneColor = isDark ? UIColor.systemGray : UIColor.systemGray
                    nsAttr.addAttributes([.foregroundColor: doneColor, .strikethroughStyle: NSUnderlineStyle.single.rawValue, .strikethroughColor: doneColor], range: newRange)
                }
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyHorizontalRuleMarkdown(to nsAttr: NSMutableAttributedString, color: UIColor) {
        guard let regex = cachedRegex(pattern: #"(?m)^(?:---|\*\*\*|___)\s*$"#) else { return }
        var hasMatch = true
        while hasMatch {
            let plainString = nsAttr.string
            let fullRange = NSRange(location: 0, length: (plainString as NSString).length)
            if let match = regex.firstMatch(in: plainString, options: [], range: fullRange) {
                let replacement = "────────────"
                nsAttr.replaceCharacters(in: match.range, with: replacement)
                let newRange = NSRange(location: match.range.location, length: replacement.count)
                let paragraph = NSMutableParagraphStyle()
                paragraph.alignment = .center
                nsAttr.addAttributes([.foregroundColor: color, .paragraphStyle: paragraph], range: newRange)
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyFootnoteDefinitionMarkdown(to nsAttr: NSMutableAttributedString, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool) {
        guard let regex = cachedRegex(pattern: #"(?m)^\[\^([^\]]+)\]:\s*(.+)$"#) else { return }
        let footnoteFont = resolveUIFont(name: styleConfig.fontName, size: styleConfig.size * scale * 0.8, isBold: false)
        let footnoteColor = isDark ? UIColor.systemGray : UIColor.systemGray
        var hasMatch = true
        while hasMatch {
            let plainNSString = nsAttr.string as NSString
            let fullRange = NSRange(location: 0, length: plainNSString.length)
            if let match = regex.firstMatch(in: plainNSString as String, options: [], range: fullRange), match.numberOfRanges >= 3 {
                let noteID = plainNSString.substring(with: match.range(at: 1))
                let content = plainNSString.substring(with: match.range(at: 2))
                let replacement = "[\(noteID)] \(content)"
                nsAttr.replaceCharacters(in: match.range, with: replacement)
                let newRange = NSRange(location: match.range.location, length: (replacement as NSString).length)
                let paragraph = NSMutableParagraphStyle()
                paragraph.headIndent = footnoteFont.pointSize * 1.6
                nsAttr.addAttributes([.font: footnoteFont, .foregroundColor: footnoteColor, .paragraphStyle: paragraph], range: newRange)
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyFootnoteReferenceMarkdown(to nsAttr: NSMutableAttributedString, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool) {
        guard let regex = cachedRegex(pattern: #"\[\^([^\]]+)\]"#) else { return }
        let refFont = resolveUIFont(name: styleConfig.fontName, size: styleConfig.size * scale * 0.72, isBold: false)
        let refColor = isDark ? UIColor.systemTeal : UIColor.systemBlue
        var hasMatch = true
        while hasMatch {
            let plainNSString = nsAttr.string as NSString
            let fullRange = NSRange(location: 0, length: plainNSString.length)
            if let match = regex.firstMatch(in: plainNSString as String, options: [], range: fullRange), match.numberOfRanges >= 2 {
                let noteID = plainNSString.substring(with: match.range(at: 1))
                nsAttr.replaceCharacters(in: match.range, with: noteID)
                let newRange = NSRange(location: match.range.location, length: (noteID as NSString).length)
                nsAttr.addAttributes([.font: refFont, .foregroundColor: refColor, .baselineOffset: styleConfig.size * scale * 0.25], range: newRange)
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    private static func applyDefinitionListMarkdown(to nsAttr: NSMutableAttributedString, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool) {
        guard let regex = cachedRegex(pattern: #"(?m)^([^\n:][^\n]*?)\n:\s+([^\n]+)$"#) else { return }
        let termFont = resolveUIFont(name: styleConfig.fontName, size: styleConfig.size * scale, isBold: true)
        let definitionColor = isDark ? UIColor.systemGray : UIColor.darkGray
        var hasMatch = true
        while hasMatch {
            let plainNSString = nsAttr.string as NSString
            let fullRange = NSRange(location: 0, length: plainNSString.length)
            if let match = regex.firstMatch(in: plainNSString as String, options: [], range: fullRange), match.numberOfRanges >= 3 {
                let term = plainNSString.substring(with: match.range(at: 1))
                let definition = plainNSString.substring(with: match.range(at: 2))
                let replacement = "\(term)\n\(definition)"
                nsAttr.replaceCharacters(in: match.range, with: replacement)
                let termRange = NSRange(location: match.range.location, length: (term as NSString).length)
                let definitionRange = NSRange(location: termRange.location + termRange.length + 1, length: (definition as NSString).length)
                let paragraph = NSMutableParagraphStyle()
                paragraph.headIndent = styleConfig.size * scale * 1.2
                nsAttr.addAttributes([.font: termFont], range: termRange)
                nsAttr.addAttributes([.foregroundColor: definitionColor, .paragraphStyle: paragraph], range: definitionRange)
            } else {
                hasMatch = false
            }
        }
    }

    @MainActor
    static func renderFullDocumentForPDF(text: String, style: LPGlobalStyle, isDark: Bool) -> NSAttributedString {
        let lines = text.components(separatedBy: .newlines)
        var nodes: [LPRowNode] = []
        for line in lines {
            var type: LPNodeType = .l1; var content = line
            let prefixes = ["###### ", "##### ", "#### ", "### ", "## ", "# ", "        - ", "      - ", "    - ", "  - ", "- ", "> "]
            for p in prefixes { if line.hasPrefix(p) { type = LPNodeType.from(prefix: p, content: ""); content = String(line.dropFirst(p.count)); break } }
            nodes.append(LPRowNode(type: type, content: content))
        }
        let finalAttrString = NSMutableAttributedString(); let scale: CGFloat = 0.4
        for node in nodes {
            let config: LPGlobalStyle.TextStyle = {
                switch node.type {
                case .h1: return style.h1; case .h2: return style.h2; case .h3: return style.h3
                case .h4: return style.h4; case .h5: return style.h5; case .h6: return style.h6
                case .l1, .l2, .l3, .l4, .l5: return style.body; case .quote: return style.quote
                }
            }()
            let lineAttr = renderNS(node.content, styleConfig: config, scale: scale, isDark: isDark, hierarchicalIndent: 20.0 * scale, availableWidth: 1000, includeImages: true)
            finalAttrString.append(lineAttr); finalAttrString.append(NSAttributedString(string: "\n"))
        }
        return finalAttrString
    }

    static func extractImageInfo(from raw: String) -> (assetID: String, widthCm: Double?)? {
        let htmlPattern = #"(?i)<img\s+[^>]*src\s*=\s*(?:["'“”])?asset:([\w\.-]+\.(?:jpg|jpeg|png))(?:["'“”])?(?:[^>]*width\s*=\s*(?:["'“”])?([\d\.]+)(cm|%|px)?(?:["'“”])?)?[^>]*>"#
        if let regex = try? NSRegularExpression(pattern: htmlPattern, options: []) {
            let ns = raw as NSString
            if let match = regex.firstMatch(in: raw, options: [], range: NSRange(location: 0, length: ns.length)) {
                let assetID = ns.substring(with: match.range(at: 1))
                var widthCm: Double? = nil
                if match.numberOfRanges > 2 && match.range(at: 2).location != NSNotFound {
                    let widthStr = ns.substring(with: match.range(at: 2))
                    let unit = (match.numberOfRanges > 3 && match.range(at: 3).location != NSNotFound)
                        ? ns.substring(with: match.range(at: 3)).lowercased()
                        : "cm"
                    if let widthVal = Double(widthStr) {
                        if unit == "px" {
                            widthCm = widthVal / pointsPerCm
                        } else if unit == "cm" || unit.isEmpty {
                            widthCm = widthVal
                        }
                    }
                }
                return (assetID, widthCm)
            }
        }
        if let assetID = extractAssetIDFallback(from: raw) {
            let widthCm = extractWidthFallback(from: raw)
            return (assetID, widthCm)
        }
        let mdPattern = #"!\[.*?\]\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
        if let regex = try? NSRegularExpression(pattern: mdPattern, options: []) {
            let ns = raw as NSString
            if let match = regex.firstMatch(in: raw, options: [], range: NSRange(location: 0, length: ns.length)) { return (ns.substring(with: match.range(at: 1)), nil) }
        }
        return nil
    }

    private static func extractAssetIDFallback(from raw: String) -> String? {
        guard let assetRange = raw.range(of: "asset:", options: .caseInsensitive) else { return nil }
        let start = assetRange.upperBound
        let slice = raw[start...]
        let end = slice.firstIndex(where: { ch in
            ch == "\"" || ch == "'" || ch == "“" || ch == "”" || ch == " " || ch == ">" || ch == "\n" || ch == "\t"
        }) ?? raw.endIndex
        let id = String(raw[start..<end])
        return id.isEmpty ? nil : id
    }

    private static func extractWidthFallback(from raw: String) -> Double? {
        guard let widthRange = raw.range(of: "width", options: .caseInsensitive) else { return nil }
        let after = raw[widthRange.upperBound...]
        guard let eqIndex = after.firstIndex(of: "=") else { return nil }
        var idx = after.index(after: eqIndex)
        while idx < after.endIndex, after[idx].isWhitespace { idx = after.index(after: idx) }
        if idx < after.endIndex, "\"'“”".contains(after[idx]) { idx = after.index(after: idx) }
        var numberStr = ""
        var unitStr = ""
        var i = idx
        while i < after.endIndex, (after[i].isNumber || after[i] == ".") {
            numberStr.append(after[i])
            i = after.index(after: i)
        }
        while i < after.endIndex, after[i].isLetter || after[i] == "%" {
            unitStr.append(after[i])
            i = after.index(after: i)
        }
        guard let value = Double(numberStr) else { return nil }
        let unit = unitStr.lowercased()
        if unit == "px" {
            return value / pointsPerCm
        }
        if unit == "cm" || unit.isEmpty {
            return value
        }
        return nil
    }

    static func getAllAssetIDs(from text: String) -> Set<String> {
        var ids = Set<String>(); let hPattern = #"(?i)src= ["'“”]asset:([\w\.-]+\.(?:jpg|jpeg|png))["'“”]"#
        if let regex = try? NSRegularExpression(pattern: hPattern, options: []) {
            let ns = text as NSString; let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: ns.length))
            for m in matches { ids.insert(ns.substring(with: m.range(at: 1))) }
        }
        let mPattern = #"\(asset:([\w\.-]+\.(?:jpg|jpeg|png))\)"#
        if let regex = try? NSRegularExpression(pattern: mPattern, options: []) {
            let ns = text as NSString; let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: ns.length))
            for m in matches { ids.insert(ns.substring(with: m.range(at: 1))) }
        }
        return ids
    }

    static func resolveFont(name: String, size: CGFloat, isBold: Bool) -> Font {
        let weight: Font.Weight = isBold ? .bold : .regular
        switch name.lowercased() {
        case "system": return .system(size: size, weight: weight)
        case "serif": return .system(size: size, weight: weight, design: .serif)
        case "mono", "monospaced": return .system(size: size, weight: weight, design: .monospaced)
        case "rounded": return .system(size: size, weight: weight, design: .rounded)
        default: return .custom(name, size: size).weight(weight)
        }
    }

    static func resolveUIFont(name: String, size: CGFloat, isBold: Bool) -> UIFont {
        let cacheKey = FontCacheKey(name: name.lowercased(), sizeKey: Int((size * 100).rounded()), isBold: isBold)
        if let cached = fontCache[cacheKey] {
            return cached
        }

        let weight: UIFont.Weight = isBold ? .bold : .regular; let baseFont: UIFont
        switch name.lowercased() {
        case "system": baseFont = UIFont.systemFont(ofSize: size, weight: weight)
        case "serif": baseFont = UIFont.systemFont(ofSize: size, weight: weight).with(design: .serif) ?? UIFont.systemFont(ofSize: size, weight: weight)
        case "mono", "monospaced": baseFont = UIFont.monospacedSystemFont(ofSize: size, weight: weight)
        case "rounded": baseFont = UIFont.systemFont(ofSize: size, weight: weight).with(design: .rounded) ?? UIFont.systemFont(ofSize: size, weight: weight)
        default: baseFont = UIFont(name: name, size: size) ?? UIFont.systemFont(ofSize: size, weight: weight)
        }
        let resolvedFont: UIFont
        if isBold {
            resolvedFont = cachedFontVariant(baseFont, traits: .traitBold) ?? baseFont
        } else {
            resolvedFont = baseFont
        }
        fontCache[cacheKey] = resolvedFont
        return resolvedFont
    }
    
    static func lpAdaptiveColor(hex: String, dark: Bool) -> Color { if hex.hasPrefix("#"), let uiColor = UIColor(hexString: hex) { return Color(uiColor) }; switch hex { case "white": return dark ? .white : .black; case "gray": return dark ? .gray : Color(white: 0.3); case "red": return .red; case "orange": return .orange; case "yellow": return dark ? .yellow : .orange; case "green": return dark ? .green : Color(red: 0, green: 0.6, blue: 0.2); case "blue": return dark ? Color(red: 0.4, green: 0.7, blue: 1.0) : .blue; case "purple": return dark ? Color(red: 0.8, green: 0.5, blue: 1.0) : .purple; case "cyan": return dark ? .cyan : Color(red: 0, green: 0.5, blue: 0.6); default: return dark ? .white : .black } }
}

// MARK: - LPRenderer 代理结构 - v3 - 对齐底层方法调用

struct LPRenderer {
    static var pointsPerCm: CGFloat { LPRerender.pointsPerCm }
    
    @MainActor
    static func render(_ t: String, styleConfig: LPGlobalStyle.TextStyle, isDark: Bool, highlightRange: NSRange? = nil) -> AttributedString {
        LPRerender.render(t, styleConfig: styleConfig, isDark: isDark, highlightRange: highlightRange)
    }
    
    @MainActor
    static func renderNS(_ t: String, styleConfig: LPGlobalStyle.TextStyle, scale: CGFloat, isDark: Bool, hierarchicalIndent: CGFloat, highlightRange: NSRange? = nil) -> NSAttributedString {
        LPRerender.renderNS(t, styleConfig: styleConfig, scale: scale, isDark: isDark, hierarchicalIndent: hierarchicalIndent, highlightRange: highlightRange)
    }
    
    @MainActor
    static func renderFullDocumentForPDF(text: String, style: LPGlobalStyle, isDark: Bool) -> NSAttributedString {
        LPRerender.renderFullDocumentForPDF(text: text, style: style, isDark: isDark)
    }
    
    static func extractImageInfo(from r: String) -> (assetID: String, widthCm: Double?)? {
        LPRerender.extractImageInfo(from: r)
    }
    
    static func getAllAssetIDs(from t: String) -> Set<String> {
        LPRerender.getAllAssetIDs(from: t)
    }
    
    static func resolveFont(name: String, size: CGFloat, isBold: Bool) -> Font {
        LPRerender.resolveFont(name: name, size: size, isBold: isBold)
    }
    
    static func resolveUIFont(name: String, size: CGFloat, isBold: Bool) -> UIFont {
        LPRerender.resolveUIFont(name: name, size: size, isBold: isBold)
    }
    
    static func lpAdaptiveColor(hex: String, dark: Bool) -> Color {
        LPRerender.lpAdaptiveColor(hex: hex, dark: dark)
    }
}

// MARK: - 自定义高亮排版管理器 - v1 - 实现圆角/外扩效果
class LPCustomLayoutManager: NSLayoutManager {
    override func drawBackground(forGlyphRange glyphsToShow: NSRange, at origin: CGPoint) {
        // 先调用父类绘制非高亮背景（如果有的话，虽然这里主要就是为了覆盖默认行为）
        // super.drawBackground(forGlyphRange: glyphsToShow, at: origin)
        
        guard let textStorage = textStorage else { return }
        
        // 将字形范围转换为字符范围
        let characterRange = self.characterRange(forGlyphRange: glyphsToShow, actualGlyphRange: nil)
        
        textStorage.enumerateAttribute(.backgroundColor, in: characterRange, options: []) { (value, range, stop) in
            guard let color = value as? UIColor else { return }
            
            // 获取该属性覆盖的字形范围
            let glyphRange = self.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
            
            // 遍历字形矩形（处理换行情况）
            self.enumerateEnclosingRects(forGlyphRange: glyphRange, withinSelectedGlyphRange: NSRange(location: NSNotFound, length: 0), in: textContainers.first!) { (rect, stop) in
                // 【169号核心】：上下左右各外扩 5px
                let expandedRect = rect.insetBy(dx: -5, dy: -5)
                let finalRect = expandedRect.offsetBy(dx: origin.x, dy: origin.y)
                
                // 【169号核心】：圆角 25px
                let path = UIBezierPath(roundedRect: finalRect, cornerRadius: 25.0)
                
                color.setFill()
                path.fill()
            }
        }
    }
}

// MARK: - LPRenderedTextView - v16 - 修正类型名称拼写错误，维持高度拦截逻辑

#if os(iOS)
struct LPRenderedTextView: UIViewRepresentable {
    let attributedText: NSAttributedString
    let fixedWidth: CGFloat
    var onHeightCalculated: ((CGFloat) -> Void)? = nil

    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    func makeUIView(context: Context) -> DynamicTextView {
        let textStorage = NSTextStorage()
        let layoutManager = LPCustomLayoutManager()
        layoutManager.usesFontLeading = false
        textStorage.addLayoutManager(layoutManager)
        
        let textContainer = NSTextContainer(size: CGSize(width: fixedWidth, height: .greatestFiniteMagnitude))
        textContainer.widthTracksTextView = false
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 0
        textContainer.lineBreakMode = .byWordWrapping
        layoutManager.addTextContainer(textContainer)
        
        let customTextView = DynamicTextView(frame: .zero, textContainer: textContainer)
        customTextView.backgroundColor = .clear
        customTextView.isScrollEnabled = false
        customTextView.isEditable = false
        customTextView.isSelectable = false
        customTextView.isUserInteractionEnabled = false
        customTextView.textContainerInset = .zero
        
        return customTextView
    }
    
    func updateUIView(_ uiView: DynamicTextView, context: Context) {
        // 使用指纹判定，防止无效重绘
        let textHash = attributedText.string.hashValue
        
        if context.coordinator.lastTextHash != textHash || context.coordinator.lastWidth != fixedWidth {
            context.coordinator.lastTextHash = textHash
            context.coordinator.lastWidth = fixedWidth
            uiView.attributedText = attributedText
            
            // 物理同步宽度
            uiView.textContainer.size = CGSize(width: fixedWidth, height: .greatestFiniteMagnitude)
            
            DispatchQueue.main.async {
                context.coordinator.recalculateHeight(view: uiView)
            }
        }
    }
    
    class Coordinator: NSObject {
        var parent: LPRenderedTextView
        var lastTextHash: Int? = nil
        var lastWidth: CGFloat = 0
        var lastReportedHeight: CGFloat = 0
        private var isReportingHeight = false

        // 【380号物理修正】：纠正拼写错误以匹配外部结构体名称
        init(_ parent: LPRenderedTextView) {
            self.parent = parent
        }

        func recalculateHeight(view: UITextView) {
            guard !isReportingHeight else { return }
            
            let targetSize = CGSize(width: parent.fixedWidth, height: .greatestFiniteMagnitude)
            let size = view.sizeThatFits(targetSize)
            let finalH = size.height + 1.0
            
            // 差异超过 1.5px 才上报，防止浮点微变导致递归死循环
            if abs(finalH - lastReportedHeight) > 1.5 {
                isReportingHeight = true
                lastReportedHeight = finalH
                parent.onHeightCalculated?(finalH)
                
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
                    self.isReportingHeight = false
                }
            }
        }
    }
    
    class DynamicTextView: UITextView {
        override var intrinsicContentSize: CGSize {
            let targetW = bounds.width > 0 ? bounds.width : 500
            let size = sizeThatFits(CGSize(width: targetW, height: .greatestFiniteMagnitude))
            return CGSize(width: targetW, height: max(10, size.height))
        }
    }
}

#endif

#if os(macOS)
final class LPMacSourceNSTextView: NSTextView {
    var onReturnPressed: ((NSRange) -> Bool)?
    
    override func insertNewline(_ sender: Any?) {
        if let onReturnPressed, onReturnPressed(selectedRange()) {
            return
        }
        super.insertNewline(sender)
    }
}

struct LPSourceEditor: NSViewRepresentable {
    @Binding var text: String
    let style: LPGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    let initialState: EditorViewState?
    var onStateChange: ((EditorViewState) -> Void)?

    func makeNSView(context: Context) -> NSScrollView {
        let textStorage = NSTextStorage()
        let layoutManager = NSLayoutManager()
        let textContainer = NSTextContainer(size: .zero)
        textContainer.widthTracksTextView = true
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 0
        layoutManager.addTextContainer(textContainer)
        textStorage.addLayoutManager(layoutManager)
        
        let textView = LPMacSourceNSTextView(frame: .zero, textContainer: textContainer)
        textView.delegate = context.coordinator
        textView.drawsBackground = false
        textView.isRichText = false
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        textView.isAutomaticSpellingCorrectionEnabled = false
        textView.isAutomaticDataDetectionEnabled = false
        textView.isContinuousSpellCheckingEnabled = false
        textView.isGrammarCheckingEnabled = false
        textView.isHorizontallyResizable = false
        textView.isVerticallyResizable = true
        textView.autoresizingMask = [.width]
        textView.textContainerInset = NSSize(width: 15, height: 15)
        textView.textContainer?.containerSize = CGSize(width: 0, height: CGFloat.greatestFiniteMagnitude)
        textView.minSize = .zero
        textView.maxSize = CGSize(width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
        textView.onReturnPressed = { range in
            context.coordinator.handleReturn(in: textView, range: range)
        }
        
        let scrollView = NSScrollView()
        scrollView.drawsBackground = false
        scrollView.borderType = .noBorder
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = false
        scrollView.documentView = textView
        scrollView.contentView.postsBoundsChangedNotifications = true
        
        context.coordinator.attach(textView: textView, scrollView: scrollView)
        
        if !text.isEmpty {
            textView.string = text
            context.coordinator.applyLPSyntaxHighlighting(for: textView)
        }
        return scrollView
    }
    
    func updateNSView(_ nsView: NSScrollView, context: Context) {
        context.coordinator.parent = self
        guard let textView = nsView.documentView as? LPMacSourceNSTextView else { return }
        
        if !context.coordinator.hasRestored, let state = initialState {
            context.coordinator.hasRestored = true
            DispatchQueue.main.async {
                context.coordinator.restoreState(view: textView, state: state)
            }
        }
        
        let isFirstResponder = textView.window.map { $0.firstResponder === textView } ?? false
        if !isFirstResponder, textView.string != text {
            context.coordinator.isInternallyUpdating = true
            textView.string = text
            context.coordinator.applyLPSyntaxHighlighting(for: textView)
            context.coordinator.isInternallyUpdating = false
        } else if context.coordinator.currentStyle != style || context.coordinator.currentIsDarkMode != isDarkMode {
            context.coordinator.currentStyle = style
            context.coordinator.currentIsDarkMode = isDarkMode
            context.coordinator.applyLPSyntaxHighlighting(for: textView)
        }
        
        if let target = scrollTarget, target.location + target.length <= textView.string.utf16.count {
            textView.setSelectedRange(target)
            textView.scrollRangeToVisible(target)
            DispatchQueue.main.async { self.scrollTarget = nil }
        }
    }
    
    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }
    
    final class Coordinator: NSObject, NSTextViewDelegate {
        var parent: LPSourceEditor
        var isInternallyUpdating = false
        var hasRestored = false
        var currentStyle: LPGlobalStyle
        var currentIsDarkMode: Bool
        weak var activeTextView: LPMacSourceNSTextView?
        weak var activeScrollView: NSScrollView?
        
        init(_ parent: LPSourceEditor) {
            self.parent = parent
            self.currentStyle = parent.style
            self.currentIsDarkMode = parent.isDarkMode
        }
        
        deinit {
            if let clipView = activeScrollView?.contentView {
                NotificationCenter.default.removeObserver(self, name: NSView.boundsDidChangeNotification, object: clipView)
            }
        }
        
        func attach(textView: LPMacSourceNSTextView, scrollView: NSScrollView) {
            activeTextView = textView
            activeScrollView = scrollView
            NotificationCenter.default.removeObserver(self, name: NSView.boundsDidChangeNotification, object: scrollView.contentView)
            NotificationCenter.default.addObserver(self, selector: #selector(boundsDidChange(_:)), name: NSView.boundsDidChangeNotification, object: scrollView.contentView)
        }
        
        @objc private func boundsDidChange(_ note: Notification) {
            guard let textView = activeTextView else { return }
            reportState(for: textView)
        }
        
        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? LPMacSourceNSTextView, !isInternallyUpdating else { return }
            parent.text = textView.string
            applyLPSyntaxHighlighting(for: textView)
            reportState(for: textView)
        }
        
        func textViewDidChangeSelection(_ notification: Notification) {
            guard let textView = notification.object as? LPMacSourceNSTextView else { return }
            reportState(for: textView)
        }
        
        func restoreState(view: LPMacSourceNSTextView, state: EditorViewState) {
            let maxLen = view.string.utf16.count
            let safeLoc = min(state.selectedLocation, maxLen)
            let safeLen = min(state.selectedLength, max(0, maxLen - safeLoc))
            let range = NSRange(location: safeLoc, length: safeLen)
            view.setSelectedRange(range)
            view.scrollRangeToVisible(range)
            if let scrollView = activeScrollView {
                let maxOffset = max(0, view.bounds.height - scrollView.contentView.bounds.height)
                scrollView.contentView.scroll(to: CGPoint(x: 0, y: min(state.offsetY, maxOffset)))
                scrollView.reflectScrolledClipView(scrollView.contentView)
            }
            reportState(for: view)
        }
        
        func handleReturn(in textView: LPMacSourceNSTextView, range: NSRange) -> Bool {
            let content = textView.string as NSString
            guard range.location <= content.length else { return false }
            let lineRange = content.lineRange(for: NSRange(location: range.location, length: 0))
            let currentLine = content.substring(with: lineRange)
            guard let nextPrefix = calculateNextPrefix(currentLine) else { return false }
            textView.insertText("\n" + nextPrefix, replacementRange: range)
            return true
        }
        
        private func reportState(for textView: NSTextView) {
            let range = textView.selectedRange()
            let offsetY = activeScrollView?.contentView.bounds.origin.y ?? 0
            parent.onStateChange?(EditorViewState(selectedLocation: range.location, selectedLength: range.length, offsetY: offsetY))
        }
        
        func applyLPSyntaxHighlighting(for textView: NSTextView) {
            guard let storage = textView.textStorage else { return }
            let content = storage.string
            let fullRange = NSRange(location: 0, length: storage.length)
            guard fullRange.length > 0 else { return }
            
            let selectedRange = textView.selectedRange()
            storage.beginEditing()
            let baseFontSize = parent.style.body.size
            let codeFont = NSFont.monospacedSystemFont(ofSize: baseFontSize, weight: .regular)
            let boldCodeFont = NSFont.monospacedSystemFont(ofSize: baseFontSize, weight: .bold)
            let baseColor = lpAdaptiveColor(hex: parent.style.body.color, dark: parent.isDarkMode)
            
            storage.setAttributes([.font: codeFont, .foregroundColor: baseColor], range: fullRange)
            
            let h1Color = lpAdaptiveColor(hex: parent.style.h1.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^#\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h1Color, .font: boldCodeFont] }
            let h2Color = lpAdaptiveColor(hex: parent.style.h2.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^##\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h2Color, .font: boldCodeFont] }
            let h3Color = lpAdaptiveColor(hex: parent.style.h3.color, dark: parent.isDarkMode)
            applyLPRegex(pattern: "^###\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: h3Color, .font: boldCodeFont] }
            applyLPRegex(pattern: "^#{4,6}\\s.*$", text: content, storage: storage) { _ in [.foregroundColor: baseColor, .font: boldCodeFont] }
            
            let listMarkerColor = parent.isDarkMode ? NSColor.systemCyan : NSColor.systemBlue
            applyLPRegex(pattern: #"^(\s{0,10})-\s+"#, text: content, storage: storage) { _ in [.foregroundColor: listMarkerColor] }
            let boldColor = parent.isDarkMode ? NSColor.systemOrange : NSColor.orange
            applyLPRegex(pattern: "\\*\\*.*?\\*\\*", text: content, storage: storage) { _ in [.foregroundColor: boldColor, .font: boldCodeFont] }
            let accentColor = parent.isDarkMode ? NSColor.systemPink : NSColor.systemPurple
            applyLPRegex(pattern: "(`.*?`|(?ms)^```.*?^```)", text: content, storage: storage) { _ in [.foregroundColor: accentColor] }
            let mathColor = parent.isDarkMode ? NSColor.systemCyan : NSColor(calibratedRed: 0, green: 0.5, blue: 0.6, alpha: 1)
            applyLPRegex(pattern: "(?s)\\$\\$.*?\\$\\$|\\$.*?\\$", text: content, storage: storage) { _ in [.foregroundColor: mathColor] }
            let markBg = parent.isDarkMode ? NSColor.systemYellow.withAlphaComponent(0.3) : NSColor.systemYellow.withAlphaComponent(0.4)
            applyLPRegex(pattern: "<mark>.*?</mark>", text: content, storage: storage) { _ in [.backgroundColor: markBg] }
            storage.endEditing()
            
            if selectedRange.location + selectedRange.length <= textView.string.utf16.count {
                textView.setSelectedRange(selectedRange)
            }
        }
        
        private func calculateNextPrefix(_ line: String) -> String? {
            let pattern = #"^(\s{0,10})-\s+"#
            if let regex = try? NSRegularExpression(pattern: pattern, options: []),
               let match = regex.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) {
                return (line as NSString).substring(with: match.range)
            }
            if let range = line.range(of: #"^\s*-\s+"#, options: .regularExpression) {
                return String(line[range])
            }
            let bp = #"^(\s*)\((\d+)\)(\.?)\s+"#
            if let rx = try? NSRegularExpression(pattern: bp, options: []),
               let m = rx.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) {
                let s = (line as NSString).substring(with: m.range(at: 1))
                let n = Int((line as NSString).substring(with: m.range(at: 2))) ?? 0
                return "\(s)(\(n + 1))\((line as NSString).substring(with: m.range(at: 3))) "
            }
            let np = #"^(\s*)(\d+)(\.|\))(\.?)\s+"#
            if let rx = try? NSRegularExpression(pattern: np, options: []),
               let m = rx.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) {
                let s = (line as NSString).substring(with: m.range(at: 1))
                let n = Int((line as NSString).substring(with: m.range(at: 2))) ?? 0
                let su = (line as NSString).substring(with: m.range(at: 3))
                let d = (line as NSString).substring(with: m.range(at: 4))
                return "\(s)\(n + 1)\(su)\(d) "
            }
            return nil
        }
        
        private func applyLPRegex(pattern: String, text: String, storage: NSTextStorage, attrs: (NSRange) -> [NSAttributedString.Key: Any]) {
            var finalPattern = pattern
            var options: NSRegularExpression.Options = []
            if pattern.contains("^") { options.insert(.anchorsMatchLines) }
            if pattern.hasPrefix("(?s)") {
                options.insert(.dotMatchesLineSeparators)
                finalPattern = pattern.replacingOccurrences(of: "(?s)", with: "")
            }
            if pattern.hasPrefix("(?ms)") {
                options.insert(.anchorsMatchLines)
                options.insert(.dotMatchesLineSeparators)
                finalPattern = pattern.replacingOccurrences(of: "(?ms)", with: "")
            }
            guard let regex = try? NSRegularExpression(pattern: finalPattern, options: options) else { return }
            let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: (text as NSString).length))
            for match in matches {
                storage.addAttributes(attrs(match.range), range: match.range)
            }
        }
        
        private func lpAdaptiveColor(hex: String, dark: Bool) -> NSColor {
            switch hex {
            case "white": return dark ? .white : .black
            case "gray": return dark ? .gray : .darkGray
            case "yellow": return dark ? .systemYellow : .systemOrange
            default: return NSColor(hexString: hex) ?? (dark ? .white : .black)
            }
        }
    }
}

struct LPRenderedTextView: NSViewRepresentable {
    let attributedText: NSAttributedString
    let fixedWidth: CGFloat
    var onHeightCalculated: ((CGFloat) -> Void)? = nil

    func makeNSView(context: Context) -> NSTextView {
        let textStorage = NSTextStorage()
        let layoutManager = NSLayoutManager()
        layoutManager.usesFontLeading = false
        let textContainer = NSTextContainer(size: CGSize(width: fixedWidth, height: .greatestFiniteMagnitude))
        textContainer.widthTracksTextView = false
        textContainer.heightTracksTextView = false
        textContainer.lineFragmentPadding = 0
        textContainer.lineBreakMode = .byWordWrapping
        layoutManager.addTextContainer(textContainer)
        textStorage.addLayoutManager(layoutManager)

        let textView = NSTextView(frame: .zero, textContainer: textContainer)
        textView.isEditable = false
        textView.isSelectable = true
        textView.drawsBackground = false
        textView.textContainerInset = .zero
        textView.textContainer?.lineFragmentPadding = 0
        return textView
    }

    func updateNSView(_ nsView: NSTextView, context: Context) {
        nsView.textStorage?.setAttributedString(attributedText)
        nsView.frame.size.width = fixedWidth
        nsView.textContainer?.size = CGSize(width: fixedWidth, height: .greatestFiniteMagnitude)
        nsView.layoutManager?.ensureLayout(for: nsView.textContainer!)
        let usedRect = nsView.layoutManager?.usedRect(for: nsView.textContainer!) ?? .zero
        onHeightCalculated?(ceil(usedRect.height))
    }
}

final class LPMacLessonPlanTextView: NSTextView {
    var onTabPressed: ((Int) -> Void)?
    var onEscPressed: (() -> Void)?
    var onSplitRequested: ((String, String, String?) -> Void)?
    var onDeleteEmpty: (() -> Void)?
    var onMergeToPrevious: ((String) -> Void)?
    var onImagePasted: ((NSImage) -> Void)?

    override func keyDown(with event: NSEvent) {
        let isShift = event.modifierFlags.contains(.shift)
        switch event.keyCode {
        case 53: // esc
            window?.makeFirstResponder(nil)
            onEscPressed?()
            return
        case 48: // tab
            onTabPressed?(isShift ? -1 : 1)
            return
        case 36: // return
            if isShift {
                super.keyDown(with: event)
            } else {
                let caret = selectedRange().location
                let currentText = string
                let left = (currentText as NSString).substring(to: caret)
                let right = (currentText as NSString).substring(from: caret)
                onSplitRequested?(left, right, nil)
            }
            return
        case 51: // delete
            let range = selectedRange()
            if range.location == 0 && range.length == 0 {
                if string.isEmpty {
                    onDeleteEmpty?()
                } else {
                    onMergeToPrevious?(string)
                }
                return
            }
        default:
            break
        }
        super.keyDown(with: event)
    }

    override func paste(_ sender: Any?) {
        let pb = NSPasteboard.general
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: nil) as? [URL] {
            for url in urls {
                let ext = url.pathExtension.lowercased()
                if ["jpg", "jpeg", "png", "heic", "gif", "webp"].contains(ext),
                   let img = NSImage(contentsOf: url) {
                    onImagePasted?(img)
                    return
                }
            }
        }
        if let images = pb.readObjects(forClasses: [NSImage.self], options: nil) as? [NSImage], let img = images.first {
            onImagePasted?(img)
            return
        }
        super.paste(sender)
    }
}

struct LPRowEditor: NSViewRepresentable {
    @Binding var text: String
    @EnvironmentObject var teachingStore: TeachingStore
    let style: LPGlobalStyle.TextStyle
    let isDark: Bool
    @Binding var dynamicHeight: CGFloat
    var scopeID: UUID
    var number: String
    var fixedWidth: CGFloat
    var isH3: Bool
    var initialCursorOffset: Int? = nil
    var isFocused: Bool
    var focusRequestToken: Int = 0
    var onManualTap: () -> Void
    var onFocusChanged: (Bool, Int) -> Void = { _, _ in }
    var onEsc: (() -> Void)?
    var onMoveFocus: (FocusMoveDirection, CGFloat) -> Void
    var onSplit: (String, String, String?) -> Void
    var onIndent: (Int) -> Void
    var onTabRequest: (Int) -> Void
    var onDeleteEmpty: () -> Void
    var onMergeToPrevious: (String) -> Void
    var minimumHeight: CGFloat = 0

    init(
        text: Binding<String>,
        style: LPGlobalStyle.TextStyle,
        isDark: Bool,
        dynamicHeight: Binding<CGFloat>,
        scopeID: UUID,
        number: String,
        fixedWidth: CGFloat,
        isH3: Bool,
        initialCursorOffset: Int?,
        isFocused: Bool,
        focusRequestToken: Int,
        onManualTap: @escaping () -> Void,
        onFocusChanged: @escaping (Bool, Int) -> Void,
        onEsc: (() -> Void)?,
        onMoveFocus: @escaping (FocusMoveDirection, CGFloat) -> Void,
        onSplit: @escaping (String, String, String?) -> Void,
        onIndent: @escaping (Int) -> Void,
        onTabRequest: @escaping (Int) -> Void,
        onDeleteEmpty: @escaping () -> Void,
        onMergeToPrevious: @escaping (String) -> Void,
        minimumHeight: CGFloat
    ) {
        self._text = text
        self.style = style
        self.isDark = isDark
        self._dynamicHeight = dynamicHeight
        self.scopeID = scopeID
        self.number = number
        self.fixedWidth = fixedWidth
        self.isH3 = isH3
        self.initialCursorOffset = initialCursorOffset
        self.isFocused = isFocused
        self.focusRequestToken = focusRequestToken
        self.onManualTap = onManualTap
        self.onFocusChanged = onFocusChanged
        self.onEsc = onEsc
        self.onMoveFocus = onMoveFocus
        self.onSplit = onSplit
        self.onIndent = onIndent
        self.onTabRequest = onTabRequest
        self.onDeleteEmpty = onDeleteEmpty
        self.onMergeToPrevious = onMergeToPrevious
        self.minimumHeight = minimumHeight
    }

    private func numberPrefixWidth() -> CGFloat {
        LPRerender.numberLayoutMetrics(number: number, styleConfig: style, isDark: isDark)?.prefixWidth ?? 0
    }

    func makeNSView(context: Context) -> LPMacLessonPlanTextView {
        let textStorage = NSTextStorage()
        let layoutManager = NSLayoutManager()
        let textContainer = NSTextContainer(size: CGSize(width: fixedWidth, height: .greatestFiniteMagnitude))
        textContainer.widthTracksTextView = true
        layoutManager.addTextContainer(textContainer)
        textStorage.addLayoutManager(layoutManager)

        let textView = LPMacLessonPlanTextView(frame: .zero, textContainer: textContainer)
        textView.delegate = context.coordinator
        textView.drawsBackground = false
        textView.isEditable = true
        textView.isSelectable = true
        textView.isRichText = false
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        textView.textColor = .clear
        textView.insertionPointColor = isDark ? .white : .black
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.textContainerInset = .zero
        textView.textContainer?.lineFragmentPadding = 0
        let uiFont = LPRerender.resolveUIFont(name: style.fontName, size: style.size, isBold: style.isBold)
        let baseColor = LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark)
        let paragraph = LPRerender.makeEditorParagraphStyle(
            styleConfig: style,
            number: number,
            isDark: isDark,
            embedsNumber: false
        )
        textView.defaultParagraphStyle = paragraph
        textView.typingAttributes = [
            .font: uiFont,
            .foregroundColor: NSColor(baseColor),
            .paragraphStyle: paragraph,
            .kern: Double(style.letterSpacing)
        ]
        textView.layoutManager?.usesFontLeading = false
        if let storage = textView.textStorage {
            let attrs: [NSAttributedString.Key: Any] = [
                .font: uiFont,
                .foregroundColor: NSColor(baseColor),
                .paragraphStyle: paragraph,
                .kern: Double(style.letterSpacing)
            ]
            storage.setAttributedString(NSAttributedString(string: text, attributes: attrs))
        }
        textView.onTabPressed = { delta in onTabRequest(delta) }
        textView.onEscPressed = { onEsc?() }
        textView.onSplitRequested = { left, right, prefix in onSplit(left, right, prefix) }
        textView.onDeleteEmpty = { onDeleteEmpty() }
        textView.onMergeToPrevious = { content in onMergeToPrevious(content) }
        textView.onImagePasted = { image in
            context.coordinator.activeTextView = textView
            context.coordinator.handleImageImport(image)
        }
        return textView
    }

    func updateNSView(_ nsView: LPMacLessonPlanTextView, context: Context) {
        let uiFont = LPRerender.resolveUIFont(name: style.fontName, size: style.size, isBold: style.isBold)
        let baseColor = LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark)
        let paragraph = LPRerender.makeEditorParagraphStyle(
            styleConfig: style,
            number: number,
            isDark: isDark,
            embedsNumber: false
        )

        context.coordinator.parent = self
        if context.coordinator.lastFocusRequestToken != focusRequestToken {
            context.coordinator.hasAppliedInitialFocus = false
            context.coordinator.lastFocusRequestToken = focusRequestToken
        }
        let isEditing = nsView.window?.firstResponder === nsView
        if !context.coordinator.isInternallyUpdating && !isEditing {
            if nsView.string != text {
                if context.coordinator.skipNextTextSync {
                    context.coordinator.skipNextTextSync = false
                } else {
                    context.coordinator.isInternallyUpdating = true
                    let attrs: [NSAttributedString.Key: Any] = [
                        .font: uiFont,
                        .foregroundColor: NSColor(baseColor),
                        .paragraphStyle: paragraph
                    ]
                    nsView.textStorage?.setAttributedString(NSAttributedString(string: text, attributes: attrs))
                    context.coordinator.isInternallyUpdating = false
                }
            }
        }
        nsView.defaultParagraphStyle = paragraph
        nsView.typingAttributes = [
            .font: uiFont,
            .foregroundColor: NSColor(baseColor),
            .paragraphStyle: paragraph,
            .kern: Double(style.letterSpacing)
        ]
        nsView.layoutManager?.usesFontLeading = false
        if let storage = nsView.textStorage {
            let fullRange = NSRange(location: 0, length: storage.length)
            let isEditing = nsView.window?.firstResponder === nsView
            if fullRange.length > 0 && !isEditing {
                storage.addAttributes([.font: uiFont, .foregroundColor: NSColor(baseColor), .paragraphStyle: paragraph, .kern: Double(style.letterSpacing)], range: fullRange)
            }
        }

        let effectiveWidth = max(40, fixedWidth)
        nsView.textContainer?.size = CGSize(width: effectiveWidth, height: .greatestFiniteMagnitude)
        nsView.frame.size.width = fixedWidth
        if nsView.textContainerInset != .zero {
            nsView.textContainerInset = .zero
        }

        if isFocused {
            if !context.coordinator.hasAppliedInitialFocus {
                let targetPos = initialCursorOffset ?? nsView.string.utf16.count
                let applyFocus: () -> Void = {
                    nsView.window?.makeFirstResponder(nsView)
                    nsView.setSelectedRange(NSRange(location: min(targetPos, nsView.string.utf16.count), length: 0))
                }
                DispatchQueue.main.async {
                    if nsView.window != nil {
                        applyFocus()
                    } else {
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                            if nsView.window != nil { applyFocus() }
                        }
                    }
                }
                context.coordinator.hasAppliedInitialFocus = true
            }
        } else {
            context.coordinator.hasAppliedInitialFocus = false
        }

        if isEditing != context.coordinator.lastReportedFocusState {
            context.coordinator.lastReportedFocusState = isEditing
            DispatchQueue.main.async {
                self.onFocusChanged(isEditing, self.focusRequestToken)
            }
        }

        context.coordinator.recalculateHeight(for: nsView)
    }

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    class Coordinator: NSObject, NSTextViewDelegate {
        var parent: LPRowEditor
        var isInternallyUpdating = false
        var skipNextTextSync = false
        var lastSelection: NSRange = NSRange(location: 0, length: 0)
        var hasAppliedInitialFocus = false
        var lastFocusRequestToken: Int = 0
        var lastReportedFocusState = false
        weak var activeTextView: LPMacLessonPlanTextView?

        init(_ parent: LPRowEditor) { self.parent = parent }

        func textDidBeginEditing(_ notification: Notification) {
            parent.onFocusChanged(true, parent.focusRequestToken)
            lastReportedFocusState = true
        }

        func textDidEndEditing(_ notification: Notification) {
            parent.onFocusChanged(false, parent.focusRequestToken)
            lastReportedFocusState = false
        }

        func textView(_ textView: NSTextView, shouldChangeTextIn affectedCharRange: NSRange, replacementString: String?) -> Bool {
            let replacement = replacementString ?? ""
            if let (processed, newCursor) = applyLPQuickInputRulesForEdit(
                originalText: textView.string,
                affectedRange: affectedCharRange,
                replacement: replacement,
                rules: parent.teachingStore.config.quickInputRules
            ) {
                isInternallyUpdating = true
                textView.string = processed
                textView.setSelectedRange(NSRange(location: max(0, min(newCursor ?? processed.utf16.count, processed.utf16.count)), length: 0))
                isInternallyUpdating = false
                lastSelection = textView.selectedRange()
                skipNextTextSync = true
                parent.text = processed
                recalculateHeight(for: textView)
                return false
            }
            return true
        }

        func textDidChange(_ notification: Notification) {
            guard let tv = notification.object as? NSTextView, !isInternallyUpdating else { return }
            let currentCursor = tv.selectedRange().location
            let (processed, newCursor) = applyLPQuickInputRules(
                text: tv.string,
                cursorIndex: currentCursor,
                rules: parent.teachingStore.config.quickInputRules
            )
            if processed != tv.string {
                isInternallyUpdating = true
                tv.string = processed
                tv.setSelectedRange(NSRange(location: max(0, min(newCursor ?? processed.utf16.count, processed.utf16.count)), length: 0))
                isInternallyUpdating = false
            }
            lastSelection = tv.selectedRange()
            skipNextTextSync = true
            parent.text = tv.string
            recalculateHeight(for: tv)
        }

        func recalculateHeight(for textView: NSTextView) {
            guard let lm = textView.layoutManager, let tc = textView.textContainer else { return }
            lm.ensureLayout(for: tc)
            let used = lm.usedRect(for: tc)
            let minHeight = max(parent.style.size * 1.6, parent.minimumHeight)
            let newHeight = max(ceil(used.height), minHeight)
            DispatchQueue.main.async { [weak self] in
                self?.parent.dynamicHeight = newHeight
            }
        }

        func handleImageImport(_ image: NSImage) {
            let normalizedImage: NSImage = {
                if image.cgImage(forProposedRect: nil, context: nil, hints: nil) != nil {
                    return image
                }
                if let data = image.tiffRepresentation, let rebuilt = NSImage(data: data) {
                    return rebuilt
                }
                return image
            }()
            guard let id = MarkdownAssetManager.shared.saveImage(normalizedImage, tableID: parent.scopeID) else { return }
            let tag = "<img src=\"asset:\(id)\" width=\"600px\">"
            if let tv = activeTextView {
                isInternallyUpdating = true
                let range = tv.selectedRange()
                if let storage = tv.textStorage {
                    storage.replaceCharacters(in: range, with: tag)
                    tv.setSelectedRange(NSRange(location: range.location + tag.utf16.count, length: 0))
                } else {
                    tv.string = (tv.string as NSString).replacingCharacters(in: range, with: tag)
                    tv.setSelectedRange(NSRange(location: range.location + tag.utf16.count, length: 0))
                }
                parent.text = tv.string
                isInternallyUpdating = false
                recalculateHeight(for: tv)
            } else {
                parent.text.append(tag)
            }
        }

        func textView(_ view: NSTextView, menu: NSMenu, for event: NSEvent, at charIndex: Int) -> NSMenu? {
            activeTextView = view as? LPMacLessonPlanTextView
            let insertItem = NSMenuItem(title: "插入图片...", action: #selector(presentFilePicker), keyEquivalent: "")
            insertItem.target = self
            menu.addItem(NSMenuItem.separator())
            menu.addItem(insertItem)
            return menu
        }

        @objc private func presentFilePicker() {
            let panel = NSOpenPanel()
            panel.allowedContentTypes = [UTType.image]
            panel.allowsMultipleSelection = false
            if panel.runModal() == .OK, let url = panel.url, let image = NSImage(contentsOf: url) {
                handleImageImport(image)
            }
        }
    }
}

struct LPKaTeXInnerView: View {
    let text: String
    let style: LPGlobalStyle.TextStyle
    let isDark: Bool
    let availableWidth: CGFloat
    let number: String
    @Binding var height: CGFloat

    var body: some View {
        Text(text)
            .font(.system(size: style.size, design: .serif))
            .foregroundColor(isDark ? .white : .black)
            .frame(maxWidth: availableWidth, alignment: .leading)
            .onAppear { if height == 0 { height = style.size * 1.6 } }
    }
}

struct LPLiveEditor: View {
    @Binding var text: String
    @Binding var nodes: [LPRowNode]
    let style: LPGlobalStyle
    let isDarkMode: Bool
    @Binding var scrollTarget: NSRange?
    let initialState: EditorViewState
    var onStateChange: (EditorViewState) -> Void
    @Binding var externalFocusID: UUID?
    @Binding var externalTopAnchorID: UUID?

    @State private var activeEditingNodeID: UUID? = nil
    @State private var focusedEditorNodeID: UUID? = nil
    @State private var anchorNodeID: UUID? = nil
    @State private var targetScrollID: UUID? = nil
    @State private var targetSnapID: UUID? = nil

    @State private var editSession = LPActiveEditSession()

    @State private var heightCache: [UUID: CGFloat] = [:]
    @State private var focusedPacketIDs: Set<UUID> = []
    @State private var lastSearchHitNodeID: UUID? = nil
    @State private var numberingCache: [UUID: String] = [:]

    @State private var visibleNodeIDs: Set<UUID> = []
    @State private var renderedFormulaCache: [String: LPFormulaRenderAsset] = [:]
    @State private var renderNotifyNonce: Int = 0
    @State private var hasInitialJumped: Bool = false
    @State private var pendingCursorOffset: Int? = nil
    @State private var focusRequestToken: Int = 0

    @State private var precomputedLayoutMap: [UUID: LPNodeRowView.LayoutData] = [:]
    @State private var precomputeTask: Task<Void, Never>? = nil
    @State private var currentParentWidth: CGFloat = 0

    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @EnvironmentObject var settingsStore: GlobalSettingsStore

    var body: some View {
        GeometryReader { screenGeo in
            let parentWidth = screenGeo.size.width
            ZStack(alignment: .bottom) {
                nodesListView(screenGeo: screenGeo, parentWidth: parentWidth)
                if settingsStore.config.isDirtyPacketDebugEnabled { debugOverlay }
            }
            .onAppear {
                currentParentWidth = parentWidth
                schedulePrecomputeLayouts()
            }
            .onChange(of: screenGeo.size.width) { _, newWidth in
                currentParentWidth = newWidth
                precomputedLayoutMap.removeAll()
                schedulePrecomputeLayouts()
            }
        }
        .task(id: nodes) {
            updateNumberingCache()
            schedulePrecomputeLayouts()
            await ensureFormulasRendered()
        }
        .task(id: style) {
            updateNumberingCache()
            precomputedLayoutMap.removeAll()
            schedulePrecomputeLayouts()
            renderedFormulaCache.removeAll()
            await ensureFormulasRendered()
        }
        .onAppear { checkUpdateAvailability(); schedulePrecomputeLayouts() }
        .onChange(of: visibleNodeIDs) { _, _ in
            schedulePrecomputeLayouts()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPRowInsertAction"))) { note in
            if let insertNodes = note.userInfo? ["nodes"] as? [TeachingLessonNode] { insertExternalLessonNodes(insertNodes) }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPJournalSidebarAnchorRequest"))) { _ in
            if let aid = activeEditingNodeID { commitCurrentEdit(nodeID: aid); self.anchorNodeID = aid }
            withAnimation { activeEditingNodeID = nil }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPJournalExitAllEditing"))) { _ in
            exitEditingAction()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPSetSearchFocus"))) { note in
            if let userInfo = note.userInfo, let tid = userInfo["nodeID"] as? UUID {
                self.lastSearchHitNodeID = tid; self.targetScrollID = tid
            }
        }
    }

    private func handleHeightUpdate(id: UUID, newH: CGFloat) {
        let roundedH = ceil(newH)
        if heightCache[id] == roundedH { return }
        heightCache[id] = roundedH
    }

    private var debugOverlay: some View {
        VStack(spacing: 4) {
            Text("活跃节点: \(visibleNodeIDs.count) | 缓存公式: \(renderedFormulaCache.count)")
            if let topID = topmostVisibleNodeID {
                if let node = nodes.first(where: { $0.id == topID }) {
                    Text("视野锚点内容: \(node.content.prefix(15))...")
                }
                Text("锚点 UUID: \(topID.uuidString)").font(.system(size: 8, design: .monospaced)).foregroundColor(.yellow)
            }
        }
        .font(.system(size: 10, weight: .bold))
        .padding(10)
        .background(RoundedRectangle(cornerRadius: 12).fill(Color.black.opacity(0.75)))
        .foregroundColor(.green)
        .padding(.bottom, 25)
        .allowsHitTesting(false)
    }

    private var topmostVisibleNodeID: UUID? {
        for node in nodes { if visibleNodeIDs.contains(node.id) { return node.id } }
        return nil
    }

    private func handleVisibilityChange(id: UUID, isVisible: Bool) {
        if isVisible {
            visibleNodeIDs.insert(id)
        } else {
            visibleNodeIDs.remove(id)
        }
        schedulePrecomputeLayouts()
        if let top = topmostVisibleNodeID, externalTopAnchorID != top {
            externalTopAnchorID = top
        }
    }

    private func schedulePrecomputeLayouts() {
        guard currentParentWidth > 10, !nodes.isEmpty else { return }
        precomputeTask?.cancel()
        let snapshotNodes = nodes
        let visible = visibleNodeIDs
        let width = currentParentWidth
        let styleSnapshot = style
        let numbering = numberingCache
        let activeID = activeEditingNodeID
        precomputeTask = Task {
            if Task.isCancelled { return }
            var minIdx = Int.max
            var maxIdx = Int.min
            for (idx, node) in snapshotNodes.enumerated() {
                if visible.contains(node.id) {
                    minIdx = min(minIdx, idx)
                    maxIdx = max(maxIdx, idx)
                }
            }
            if minIdx == Int.max {
                if let aid = activeID, let idx = snapshotNodes.firstIndex(where: { $0.id == aid }) {
                    minIdx = idx
                    maxIdx = idx
                } else if !snapshotNodes.isEmpty {
                    minIdx = 0
                    maxIdx = 0
                }
            }
            if minIdx == Int.max { return }
            let start = max(0, minIdx - 50)
            let end = min(snapshotNodes.count - 1, maxIdx + 50)
            if start > end { return }
            var layouts: [UUID: LPNodeRowView.LayoutData] = [:]
            for i in start...end {
                let node = snapshotNodes[i]
                let config = resolveStyle(for: node.type, style: styleSnapshot)
                let contentWidth = max(50, width - staggerIndent(for: node.type) - 40)
                let number = numbering[node.id] ?? ""
                let pTextH = LPRerender.estimateNodeTextHeight(
                    text: node.content,
                    styleConfig: config,
                    width: contentWidth,
                    number: number,
                    isDark: isDarkMode
                )
                let info = LPRerender.extractImageInfo(from: node.content)
                var pImgH: CGFloat = 0
                if let aid = info?.assetID, let size = MarkdownAssetManager.shared.getImageSize(assetID: aid) {
                    let ratio = size.height / size.width
                    let targetW = (info?.widthCm ?? 15.0) * LPRerender.pointsPerCm
                    let finalW = min(targetW, contentWidth)
                    pImgH = (finalW * ratio) + 10
                    await MainActor.run {
                        _ = MarkdownAssetManager.shared.getThumbnail(assetID: aid, targetWidth: finalW)
                    }
                }
                layouts[node.id] = LPNodeRowView.LayoutData(
                    assetID: info?.assetID,
                    widthCm: info?.widthCm,
                    predictedImgH: pImgH,
                    predictedTextH: pTextH,
                    isReady: true
                )
            }
            await MainActor.run {
                for (id, layout) in layouts { self.precomputedLayoutMap[id] = layout }
            }
        }
    }

    private func resolveStyle(for type: LPNodeType, style: LPGlobalStyle) -> LPGlobalStyle.TextStyle {
        switch type {
        case .h1: return style.h1
        case .h2: return style.h2
        case .h3: return style.h3
        case .h4: return style.h4
        case .h5: return style.h5
        case .h6: return style.h6
        case .l1, .l2, .l3, .l4, .l5: return style.body
        case .quote: return style.quote
        }
    }

    private func staggerIndent(for type: LPNodeType) -> CGFloat {
        let step: CGFloat = 42.0
        switch type {
        case .h1: return 0
        case .h2: return step
        case .h3: return step * 2
        case .h4: return step * 3
        case .h5: return step * 4
        case .h6: return step * 5
        case .l1: return (step * 5) + (step * 2.0)
        case .l2: return (step * 7) + (step * 0.5)
        case .l3: return (step * 7) + (step * 1.0)
        case .l4: return (step * 7) + (step * 1.5)
        case .l5: return (step * 7) + (step * 2.0)
        case .quote: return (step * 9) + step
        }
    }

    private func editingBinding(for node: LPRowNode) -> Binding<String> {
        Binding(
            get: {
                if editSession.nodeID == node.id {
                    return editSession.draftText
                }
                return node.content
            },
            set: { newValue in
                guard editSession.nodeID == node.id else { return }
                editSession.draftText = newValue
            }
        )
    }

    private func rowItem(node: LPRowNode, parentWidth: CGFloat) -> LPLiveRowContainer {
        LPLiveRowContainer(
            node: node,
            number: numberingCache[node.id] ?? "",
            style: style,
            isDark: isDarkMode,
            parentWidth: parentWidth,
            renderNonce: renderNotifyNonce,
            editingText: editingBinding(for: node),
            isSearchTarget: lastSearchHitNodeID == node.id,
            isInFocusedPacket: focusedPacketIDs.contains(node.id),
            isBeingEdited: activeEditingNodeID == node.id,
            isEditorFocused: focusedEditorNodeID == node.id,
            isAnchorNode: anchorNodeID == node.id,
            isDirtyMaster: teachingStore.dirtyPacketIDs.contains(node.id),
            canPaste: teachingStore.clipboardPacket != nil,
            cachedHeight: heightCache[node.id],
            initialCursorOffset: (activeEditingNodeID == node.id) ? pendingCursorOffset : nil,
            reportVisibility: { isVisible in handleVisibilityChange(id: node.id, isVisible: isVisible) },
            formulaMap: renderedFormulaCache,
            precomputedLayout: precomputedLayoutMap[node.id],
            onHeightCalculated: { newH in handleHeightUpdate(id: node.id, newH: newH) },
            onDeleteH3Packet: { deleteH3Packet(h3ID: node.id) },
            onCutH3Packet: { cutH3Packet(h3ID: node.id) },
            onPasteH3Packet: { pasteH3Packet(targetID: node.id) },
            onBeginEditing: { id in beginEditingAction(id: id) },
            onSplit: { left, right, pref in splitNode(id: node.id, left: left, right: right, prefix: pref) },
            onIndent: { delta in applyIndent(to: node.id, delta: delta) },
            onTabRequest: { delta in handlePhysicalTab(to: node.id, delta: delta) },
            onDeleteEmpty: { deleteNodeAction(id: node.id) },
            onMergeToPrevious: { content in mergeToPrevAction(id: node.id, contentToMerge: content) },
            onExitEditing: { exitEditingAction() },
            focusRequestToken: focusRequestToken,
            onFocusStateChanged: { id, isFocused, token in handleEditorFocusChange(id: id, isFocused: isFocused, token: token) }
        )
    }

    @ViewBuilder private func nodesListView(screenGeo: GeometryProxy, parentWidth: CGFloat) -> some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: true) {
                LazyVStack(alignment: .leading, spacing: 0) {
                    ForEach(nodes) { node in
                        rowItem(node: node, parentWidth: parentWidth).equatable()
                    }
                    Color.clear.frame(height: screenGeo.size.height * 0.6)
                }
            }
            .onChange(of: nodes) { _, newNodes in
                if !hasInitialJumped && !newNodes.isEmpty {
                    if let anchorID = externalTopAnchorID { proxy.scrollTo(anchorID, anchor: .top); self.hasInitialJumped = true }
                    else if let lastID = newNodes.last?.id { proxy.scrollTo(lastID, anchor: .bottom); self.hasInitialJumped = true }
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: NSNotification.Name("LPRequestScroll"))) { note in
                if let id = note.userInfo? ["id"] as? UUID { withAnimation { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) } }
            }
            .onChange(of: targetSnapID) { _, newID in
                if let id = newID { proxy.scrollTo(id, anchor: .top); DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { self.targetSnapID = nil } }
            }
            .onChange(of: targetScrollID) { _, newID in
                if let id = newID { withAnimation(.easeOut(duration: 0.25)) { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) }; DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { self.targetScrollID = nil } }
            }
            .onChange(of: activeEditingNodeID) { _, newID in
                if let id = newID { withAnimation { proxy.scrollTo(id, anchor: UnitPoint(x: 0.5, y: 0.2)) } }
            }
        }
    }

    @MainActor
    private func ensureFormulasRendered() async {
        let allFormulas = Set(collectFormulas())
        let missingFormulas = allFormulas.filter { renderedFormulaCache[$0] == nil }
        guard !missingFormulas.isEmpty else { return }
        let results = await renderFormulas(missingFormulas)
        if results.isEmpty { return }
        var didUpdateFormulaCache: Bool = false
        for (formula, asset) in results {
            renderedFormulaCache[formula] = asset
            didUpdateFormulaCache = true
        }
        if didUpdateFormulaCache {
            renderNotifyNonce += 1
        }
    }

    @MainActor
    private func renderFormulas(_ formulas: Set<String>) async -> [String: LPFormulaRenderAsset] {
        await withCheckedContinuation { continuation in
            ArchiveStore.headlessMathRenderer.render(formulas: formulas, style: style.body, dark: isDarkMode) { results in
                continuation.resume(returning: results)
            }
        }
    }

    private func collectFormulas() -> [String] {
        var list: [String] = []
        for node in nodes {
            for request in LPRerender.extractFormulaRequests(from: node.content) {
                list.append(request.formulaText)
            }
        }
        return list
    }

    private func updateNumberingCache() {
        let newMap = LPNumberingEngine.generateNumbers(for: nodes, style: style)
        DispatchQueue.main.async { self.numberingCache = newMap }
    }

    private func beginEditingAction(id: UUID) {
        if activeEditingNodeID == id {
            focusedEditorNodeID = nil
            focusRequestToken += 1
            if editSession.nodeID == id {
                editSession.token = focusRequestToken
            }
            return
        }
        if let oid = activeEditingNodeID, oid != id { commitCurrentEdit(nodeID: oid) }
        anchorNodeID = nil
        lastSearchHitNodeID = nil
        focusedEditorNodeID = nil
        if let node = nodes.first(where: { $0.id == id }) {
            activeEditingNodeID = id
            focusRequestToken += 1
            editSession = LPActiveEditSession(nodeID: id, draftText: node.content, originalText: node.content, token: focusRequestToken)
            handleFocusIDChange(id)
        }
    }

    private func exitEditingAction() {
        if let aid = activeEditingNodeID { commitCurrentEdit(nodeID: aid) }
        withAnimation {
            self.activeEditingNodeID = nil
            self.focusedEditorNodeID = nil
            self.anchorNodeID = nil
            self.lastSearchHitNodeID = nil
            self.pendingCursorOffset = nil
            self.editSession = LPActiveEditSession()
        }
    }

    private func handleEditorFocusChange(id: UUID, isFocused: Bool, token: Int) {
        DispatchQueue.main.async {
            guard token == focusRequestToken else { return }
            if isFocused {
                focusedEditorNodeID = id
                if activeEditingNodeID != id {
                    activeEditingNodeID = id
                    handleFocusIDChange(id)
                }
            } else if focusedEditorNodeID == id {
                focusedEditorNodeID = nil
            }
        }
    }

    private func commitCurrentEdit(nodeID: UUID) {
        guard let idx = nodes.firstIndex(where: { $0.id == nodeID }) else { return }
        let draftText = (editSession.nodeID == nodeID) ? editSession.draftText : nodes[idx].content
        if nodes[idx].content != draftText {
            nodes[idx].content = draftText
            heightCache.removeValue(forKey: nodeID)
            let headIdx = findH3Head(at: idx, in: nodes)
            if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) }

            // 提交编辑后主动启动一次公式渲染，避免只依赖外层 task 对 nodes 的被动感知。
            updateNumberingCache()
            schedulePrecomputeLayouts()
            Task { @MainActor in
                await ensureFormulasRendered()
            }
        }
        checkUpdateAvailability()
    }

    private func splitNode(id: UUID, left: String, right: String, prefix: String?) {
        guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }
        nodes[idx].content = left; heightCache.removeValue(forKey: id)
        let newContent = (prefix ?? "") + right.trimmingCharacters(in: .newlines)
        let newNode = LPRowNode(id: UUID(), type: nodes[idx].type, content: newContent)
        nodes.insert(newNode, at: idx + 1)
        let headIdx = findH3Head(at: idx, in: nodes)
        if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) }
        focusedEditorNodeID = nil
        activeEditingNodeID = newNode.id
        focusRequestToken += 1
        self.editSession = LPActiveEditSession(nodeID: newNode.id, draftText: newContent, originalText: newContent, token: focusRequestToken)
        self.pendingCursorOffset = 0
        handleFocusIDChange(newNode.id)
    }

    private func insertExternalLessonNodes(_ insertNodes: [TeachingLessonNode]) {
        guard !insertNodes.isEmpty else { return }
        withAnimation {
            var currentNodes = self.nodes
            let normalizedPackets = insertNodes.compactMap { node -> [LPRowNode]? in
                if !node.content.isEmpty { return node.content }
                return [
                    LPRowNode(
                        id: node.sourceID ?? UUID(),
                        type: .h3,
                        content: node.title,
                        sourceNodeID: node.sourceID,
                        sourceFileName: node.sourceFile
                    )
                ]
            }
            let allNewNodes = normalizedPackets.flatMap { $0 }
            guard !allNewNodes.isEmpty else { return }
            let firstNewH3ID = allNewNodes.first?.id
            let insertionIndex: Int
            if let targetID = anchorNodeID ?? activeEditingNodeID, let idx = currentNodes.firstIndex(where: { $0.id == targetID }) {
                let nodeType = currentNodes[idx].type
                if nodeType == .h1 || nodeType == .h2 { insertionIndex = idx + 1 }
                else {
                    let head = findH3Head(at: idx, in: currentNodes)
                    let range = findH3PacketRange(at: head, in: currentNodes)
                    insertionIndex = range.upperBound + 1
                }
            } else { insertionIndex = currentNodes.count }
            currentNodes.insert(contentsOf: allNewNodes, at: insertionIndex)
            self.nodes = currentNodes; self.anchorNodeID = nil
            if let snapID = firstNewH3ID { DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { self.targetSnapID = snapID } }
            checkUpdateAvailability()
        }
    }

    private func handleFocusIDChange(_ newID: UUID?) {
        if let fid = newID {
            if let packet = getCurrentH3Packet(from: fid), let h3 = packet.first {
                self.focusedPacketIDs = Set(packet.map { $0.id })
                teachingStore.focusedH3PacketID = h3.id
                teachingStore.isFocusedPacketFromMaster = (h3.sourceNodeID != nil)
            }
        } else { focusedPacketIDs.removeAll(); teachingStore.focusedH3PacketID = nil }
    }
    private func checkUpdateAvailability() { let hasOriginal = nodes.contains { $0.type == .h3 && $0.sourceNodeID == nil }; let hasDirty = nodes.contains { $0.type == .h3 && $0.sourceNodeID != nil && teachingStore.dirtyPacketIDs.contains($0.id) }; teachingStore.isUpdateAvailable = hasOriginal || hasDirty }
    private func findH3PacketRange(at h3Idx: Int, in list: [LPRowNode]) -> ClosedRange<Int> { var endIdx = h3Idx; for j in (h3Idx + 1)..<list.count { if [.h1, .h2, .h3].contains(list[j].type) { break }; endIdx = j }; return h3Idx...endIdx }
    private func findH3Head(at curIdx: Int, in list: [LPRowNode]) -> Int { var head = curIdx; for i in (0...curIdx).reversed() { if list[i].type == .h3 { head = i; break }; if [.h1, .h2].contains(list[i].type) { break } }; return head }
    private func deleteH3Packet(h3ID: UUID) { activeEditingNodeID = nil; anchorNodeID = nil; DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { guard let idx = self.nodes.firstIndex(where: { $0.id == h3ID }) else { return }; let h3Node = self.nodes[idx]; if let sid = h3Node.sourceNodeID, let sfile = h3Node.sourceFileName { self.asStore.resetChecklistItem(sourceID: sid, sourceFile: sfile, studentName: self.teachingStore.config.currentSession?.studentName ?? "") }; var updatedNodes = self.nodes; let range = self.findH3PacketRange(at: idx, in: updatedNodes); withAnimation { updatedNodes.removeSubrange(range); self.nodes = updatedNodes } } }
    private func getCurrentH3Packet(from id: UUID) -> [LPRowNode]? { guard let curIdx = nodes.firstIndex(where: { $0.id == id }) else { return nil }; let head = findH3Head(at: curIdx, in: nodes); if nodes[head].type != .h3 { return nil }; let range = findH3PacketRange(at: head, in: nodes); return Array(nodes[range]) }
    private func deleteNodeAction(id: UUID) { guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }; withAnimation { nodes.remove(at: idx); activeEditingNodeID = nil; focusedEditorNodeID = nil; editSession = LPActiveEditSession() } }
    private func mergeToPrevAction(id: UUID, contentToMerge: String) { guard let idx = nodes.firstIndex(where: { $0.id == id }), idx > 0 else { return }; let prevIdx = idx - 1; let prevNodeID = nodes[prevIdx].id; let prevNodeNumber = numberingCache[prevNodeID] ?? ""; let prefixLen = prevNodeNumber.isEmpty ? 0 : "\(prevNodeNumber)  ".utf16.count; let oldContentLen = nodes[prevIdx].content.utf16.count; self.pendingCursorOffset = prefixLen + oldContentLen; withAnimation { nodes[prevIdx].content += contentToMerge; heightCache.removeValue(forKey: prevNodeID); nodes.remove(at: idx); let headIdx = findH3Head(at: prevIdx, in: nodes); if nodes[headIdx].type == .h3 && nodes[headIdx].sourceNodeID != nil { teachingStore.markPacketDirty(id: nodes[headIdx].id) } }; focusedEditorNodeID = nil; activeEditingNodeID = prevNodeID; focusRequestToken += 1; editSession = LPActiveEditSession(nodeID: prevNodeID, draftText: nodes[prevIdx].content, originalText: nodes[prevIdx].content, token: focusRequestToken); handleFocusIDChange(prevNodeID) }
    private func applyIndent(to id: UUID, delta: Int) { handlePhysicalTab(to: id, delta: delta) }
    private func handlePhysicalTab(to id: UUID, delta: Int) { commitCurrentEdit(nodeID: id); guard let idx = nodes.firstIndex(where: { $0.id == id }) else { return }; var node = nodes[idx]; node.type = (delta > 0) ? node.type.next : node.type.prev; heightCache.removeValue(forKey: id); nodes[idx] = node; self.editSession = LPActiveEditSession(nodeID: id, draftText: node.content, originalText: node.content); commitCurrentEdit(nodeID: id) }
    private func cutH3Packet(h3ID: UUID) { activeEditingNodeID = nil; guard let idx = nodes.firstIndex(where: { $0.id == h3ID }) else { return }; let range = findH3PacketRange(at: idx, in: nodes); teachingStore.clipboardPacket = Array(nodes[range]) }
    private func pasteH3Packet(targetID: UUID) { activeEditingNodeID = nil; DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { guard let clipboard = self.teachingStore.clipboardPacket, self.nodes.contains(where: { $0.id == targetID }) else { return }; var updatedNodes = self.nodes; guard let targetIdx = updatedNodes.firstIndex(where: { $0.id == targetID }) else { return }; let insIdx = self.findH3PacketRange(at: targetIdx, in: updatedNodes).upperBound + 1; updatedNodes.insert(contentsOf: clipboard, at: insIdx); self.nodes = updatedNodes; self.teachingStore.clipboardPacket = nil } }
}
#endif

