// MARK: - 教案节点类型定义 - v7 - 12级结构化体系 (双栏架构)
//
// enum LPNodeType
// (修改内容：
//  1. [Feature] 结构升级：确立 H1-H6, L1-L5, Quote 共 12 个逻辑层级，彻底废弃“无编号正文”。
//  2. [Logic] 标识符映射：L1-L5 映射到不同空格深度的 "- "，Quote 映射到 "> "。
//  3. [Logic] 转换引擎：from 方法现在能精准识别带空格缩进的列表标记，并将其归类。
//  4. [STABLE] 保持 next/prev 逻辑，适配 12 级连续切换。)

enum LPNodeType: String, Codable, CaseIterable {
    case h1, h2, h3, h4, h5, h6
    case l1, l2, l3, l4, l5
    case quote
    
    /// 映射到 CSV 存储的前缀标识 (Prefix 列内容)
    var csvPrefix: String {
        switch self {
        case .h1: return "# "
        case .h2: return "## "
        case .h3: return "### "
        case .h4: return "#### "
        case .h5: return "##### "
        case .h6: return "###### "
        case .l1: return "- "
        case .l2: return "  - "
        case .l3: return "    - "
        case .l4: return "      - "
        case .l5: return "        - "
        case .quote: return "> "
        }
    }
    
    /// 从 CSV 前缀解析类型
    static func from(prefix: String, content: String) -> LPNodeType {
        let p = prefix // 保持原始空格
        switch p {
        case "# ": return .h1; case "## ": return .h2; case "### ": return .h3
        case "#### ": return .h4; case "##### ": return .h5; case "###### ": return .h6
        case "- ": return .l1; case "  - ": return .l2; case "    - ": return .l3
        case "      - ": return .l4; case "        - ": return .l5
        case "> ": return .quote
        default:
            // 容错处理：如果 Prefix 为空或异常，根据内容进一步判定
            let trimmedP = p.trimmingCharacters(in: .whitespaces)
            if trimmedP == "#" { return .h1 }
            if trimmedP == ">" { return .quote }
            if trimmedP == "-" {
                let leadingSpaces = p.prefix(while: { $0 == " " }).count
                if leadingSpaces >= 8 { return .l5 }
                if leadingSpaces >= 6 { return .l4 }
                if leadingSpaces >= 4 { return .l3 }
                if leadingSpaces >= 2 { return .l2 }
                return .l1
            }
            return .l1 // 默认回退到 L1
        }
    }
    
    var next: LPNodeType {
        switch self {
        case .h1: return .h2; case .h2: return .h3; case .h3: return .h4; case .h4: return .h5; case .h5: return .h6
        case .h6: return .l1; case .l1: return .l2; case .l2: return .l3; case .l3: return .l4; case .l4: return .l5
        case .l5: return .quote; case .quote: return .quote
        }
    }
    
    var prev: LPNodeType {
        switch self {
        case .quote: return .l5; case .l5: return .l4; case .l4: return .l3; case .l3: return .l2; case .l2: return .l1
        case .l1: return .h6; case .h6: return .h5; case .h5: return .h4; case .h4: return .h3; case .h3: return .h2; case .h2: return .h1; case .h1: return .h1
        }
    }
}



