}

// MARK: - 教案行节点模型 - v7 - 增加来源文件名溯源支持

struct LPRowNode: Identifiable, Equatable, Codable {
    var id: UUID
    var type: LPNodeType
    var content: String
    
    // 溯源 ID，指向母本中的原始节点
    var sourceNodeID: UUID?
    // 【99号新增】：溯源文件名，精准定位母本文件
    var sourceFileName: String?
    
    init(id: UUID = UUID(), type: LPNodeType, content: String, sourceNodeID: UUID? = nil, sourceFileName: String? = nil) {
        self.id = id
        self.type = type
        self.content = content
        self.sourceNodeID = sourceNodeID
        self.sourceFileName = sourceFileName
    }
    
    static func == (lhs: LPRowNode, rhs: LPRowNode) -> Bool {
        return lhs.id == rhs.id &&
               lhs.type == rhs.type &&
               lhs.content == rhs.content &&
               lhs.sourceNodeID == rhs.sourceNodeID &&
               lhs.sourceFileName == rhs.sourceFileName
    }
}

// MARK: - 教案编号引擎 - v5 - 强制绑定 TeachingStore 配置源，修复设置失效

struct LPNumberingEngine {
    @MainActor
    static func generateNumbers(for nodes: [LPRowNode], style: LPGlobalStyle) -> [UUID: String] {
        var results: [UUID: String] = [:]
        var counters = [0, 0, 0, 0, 0, 0] // 对应 H1-H6
        
        // 【核心修复】：获取教学管理中心存储的最新的编号规则
        let globalConfigs = TeachingStore.shared.config.numberingConfigs
        
        for node in nodes {
            // 1. 处理 L1-L5 列表符号 (保持物理固定符号)
            switch node.type {
            case .l1: results[node.id] = "•"; continue
            case .l2: results[node.id] = "◦"; continue
            case .l3: results[node.id] = "▪"; continue
            case .l4: results[node.id] = "▫"; continue
            case .l5: results[node.id] = "›"; continue
            default: break
            }
            
            // 2. 处理 H1-H6 数字编号
            let levelIndex: Int? = {
                switch node.type {
                case .h1: return 0; case .h2: return 1; case .h3: return 2
                case .h4: return 3; case .h5: return 4; case .h6: return 5
                default: return nil
                }
            }()
            
            if let idx = levelIndex {
                counters[idx] += 1
                // 级联重置：父级变动，子级全部归零
                for j in (idx + 1)..<6 { counters[j] = 0 }
                
                // 【核心修复点】：优先使用 TeachingStore 中的配置，若无则降级使用 style 的
                let config = globalConfigs.first(where: { $0.level == node.type.rawValue })
                            ?? style.numberingConfigs.first(where: { $0.level == node.type.rawValue })
                
                if let finalConfig = config {
                    let formattedValue = formatNumber(counters[idx], format: finalConfig.format)
                    results[node.id] = finalConfig.prefix + formattedValue + finalConfig.suffix
                } else {
                    results[node.id] = ""
                }
            } else {
                results[node.id] = "" // 引用等不显示编号
            }
        }
        return results
    }
    
    private static func formatNumber(_ n: Int, format: LPGlobalStyle.NumberFormat) -> String {
        switch format {
        case .chinese:
            let chars = ["", "一", "二", "三", "四", "五", "六", "七", "八", "九", "十"]
            if n <= 10 { return chars[n] }
            return "\(n)"
        case .heavenlyStems:
            let stems = ["", "甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸"]
            if n <= 10 { return stems[n] }
            return "\(n)"
        case .numeric: return "\(n)"
        case .numeric01: return n < 10 ? "0\(n)" : "\(n)"
        case .romanSmall:
            let romans = ["", "i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x"]
            if n <= 10 { return romans[n] }
            return "\(n)"
        case .alphaSmall:
            let alphabets = " abcdefghijklmnopqrstuvwxyz".map { String($0) }
            if n <= 26 { return alphabets[n] }
            return "\(n)"
        }
    }
}

