    @ViewBuilder
    private func paletteSection<Content: View>(_ title: String, @ViewBuilder content: () -> Content) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(title)
                .font(.system(size: 14, weight: .bold))
                .foregroundColor(.secondary)
            VStack(alignment: .leading, spacing: 0) {
                content()
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 14)
            .background(
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(colorScheme == .dark ? Color.white.opacity(0.06) : Color.black.opacity(0.04))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .stroke(colorScheme == .dark ? Color.white.opacity(0.08) : Color.black.opacity(0.08), lineWidth: 1)
            )
        }
    }
    
    @ViewBuilder
    func lpStyleRow(label: String, config: Binding<LPGlobalStyle.TextStyle>) -> some View {
        // 【修复】：在 ViewBuilder 内部正确计算动态颜色数组
        let currentColors: [String] = {
            var colors = baseColorOptions
            if colorScheme == .light {
                colors[0] = "black"
            }
            return colors
        }()
        
        VStack(alignment: .leading, spacing: 10) {
            HStack(spacing: 10) {
                Text(label).font(.system(size: 14, weight: .black)).frame(width: 30, alignment: .leading)
                
                HStack(spacing: 2) {
                    Text("T").font(.system(size: 9)).foregroundColor(.gray)
                    compactTextField(value: config.size, width: 35)
                }
                
                Toggle("B", isOn: config.isBold).labelsHidden().scaleEffect(0.7).frame(width: 35)
                Toggle("BG", isOn: config.showBackground).labelsHidden().scaleEffect(0.7).frame(width: 35)
                
                Spacer()
                
                ColorPicker("", selection: Binding(
                    get: { lpConvertColor(config.wrappedValue.color) },
                    set: { config.wrappedValue.color = colorToHexString($0) }
                ))
                .labelsHidden()
                .scaleEffect(0.8)
                .frame(width: 40)
            }
            
            HStack(spacing: 8) {
                NavigationLink(destination: FontSelectionSheet(selection: config.fontName)) {
                    HStack(spacing: 4) {
                        Image(systemName: "f.cursive").font(.system(size: 9))
                        Text(getChineseFontName(config.wrappedValue.fontName))
                            .lineLimit(1)
                            .font(.system(size: 10, weight: .bold))
                        Spacer()
                        Image(systemName: "chevron.right").font(.system(size: 8))
                    }
                    .padding(.horizontal, 8)
                    .padding(.vertical, 3)
                    .background(RoundedRectangle(cornerRadius: 6).fill(Color.blue.opacity(0.15)))
                }
                .buttonStyle(.plain)
                .frame(width: 150)
                
                Spacer()
                
                spacingInput(label: "段前", value: config.spaceAbove)
                spacingInput(label: "段后", value: config.spaceBelow)
                spacingInput(label: "行间", value: config.lineSpacing)
                spacingInput(label: "字距", value: config.letterSpacing)
            }
            
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 10) {
                    ForEach(currentColors, id: \.self) { hex in
                        Circle()
                            .fill(lpConvertColor(hex))
                            .frame(width: 22, height: 22)
                            .overlay(Circle().stroke(Color.white, lineWidth: (config.wrappedValue.color == hex) ? 1.5 : 0))
                            .onTapGesture { config.wrappedValue.color = hex }
                    }
                }
            }
        }
        .padding(.vertical, 6)
    }

    private func lpConvertColor(_ hex: String) -> Color {
        if hex == "white" { return .white }
        if hex == "black" { return .black }
        if hex == "gray" { return .gray }
        if hex.hasPrefix("#"), let uiColor = UIColor(hexString: hex) { return Color(uiColor) }
        return .gray
    }
    
    private func colorToHexString(_ color: Color) -> String {
        let uiColor = UIColor(color)
        var r: CGFloat = 0, g: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
        uiColor.getRed(&r, green: &g, blue: &b, alpha: &a)
        return String(format: "#%02X%02X%02X", Int(r * 255), Int(g * 255), Int(b * 255))
    }

    @ViewBuilder
    private func spacingInput(label: String, value: Binding<CGFloat>) -> some View {
        VStack(spacing: 3) {
            // 【154号修改】：标签字号显著加大至 24
            Text(label).font(.system(size: 24, weight: .black)).foregroundColor(.gray)
            compactTextField(value: value, width: 36) // 略微加宽输入框以匹配大字号
        }
    }

    @ViewBuilder
    private func compactTextField(value: Binding<CGFloat>, width: CGFloat) -> some View {
        TextField("", text: Binding(
            get: { String(format: "%.0f", value.wrappedValue) },
            set: { if let n = Double($0) { value.wrappedValue = CGFloat(n) } }
        ))
        .font(.system(size: 11, design: .monospaced))
        .multilineTextAlignment(.center).frame(width: width).padding(.vertical, 2).background(Color.white.opacity(0.1)).cornerRadius(4).keyboardType(.numbersAndPunctuation)
    }
    
    private func getChineseFontName(_ name: String) -> String {
        if name == "system" || name.isEmpty { return "系统默认" }
        if name == "serif" { return "系统衬线" }
        if name == "mono" || name == "monospaced" { return "系统等宽" }
        if name == "rounded" { return "系统圆体" }
        let ctFont = CTFontCreateWithName(name as CFString, 12, nil)
        if let localizedName = CTFontCopyLocalizedName(ctFont, kCTFontFamilyNameKey, nil) as String? {
            return localizedName
        }
        return name
    }
}

// MARK: - 教案编号详细设置 - v1 - 自动编号规则定义
//
// struct LPNumberingSettingView
// (逻辑说明：
//  1. 对应 H1-H6 的 6 层结构。
//  2. 提供前缀、后缀编辑框。
