                                Text("格式").font(.caption).foregroundColor(.gray)
                                Picker("", selection: $configs[index].format) {
                                    ForEach(LPGlobalStyle.NumberFormat.allCases, id: \.self) {
                                        Text($0.rawValue).tag($0)
                                    }
                                }
                                .pickerStyle(.menu)
                                .frame(maxWidth: .infinity, alignment: .leading)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)

                            VStack(alignment: .leading, spacing: 6) {
                                Text("后缀").font(.caption).foregroundColor(.gray)
                                TextField("如：章", text: $configs[index].suffix)
                                    .textFieldStyle(.roundedBorder)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }

                        HStack(spacing: 8) {
                            Text("预览结果：").font(.caption).foregroundColor(.gray)
                            Text(generatePreview(configs[index]))
                                .fontWeight(.bold)
                                .foregroundColor(.orange)
                        }
                    }
                    .padding(.horizontal, 18)
                    .padding(.vertical, 16)
                    .background(
                        RoundedRectangle(cornerRadius: 18, style: .continuous)
                            .fill(Color.white.opacity(0.05))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 18, style: .continuous)
                            .stroke(Color.white.opacity(0.08), lineWidth: 1)
                    )
                }
            }
            .padding(.horizontal, 24)
            .padding(.vertical, 20)
        }
        .navigationTitle("自动编号设置")
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    }
    
    func generatePreview(_ cfg: LPGlobalStyle.NumberingConfig) -> String {
        let sample: String
        switch cfg.format {
        case .chinese: sample = "三"
        case .heavenlyStems: sample = "丙"
        case .numeric: sample = "3"
        case .numeric01: sample = "03"
        case .romanSmall: sample = "iii"
        case .alphaSmall: sample = "c"
        }
        return cfg.prefix + sample + cfg.suffix
    }
}

// MARK: - LPRowEditor - v43 - 物理隔离合并边界，确保退格时不泄露编号

enum FocusMoveDirection { case up, down }

#if os(iOS)
struct LPRowEditor: UIViewRepresentable {
    @Binding var text: String
    @EnvironmentObject var teachingStore: TeachingStore
    let style: LPGlobalStyle.TextStyle
    let isDark: Bool
    @Binding var dynamicHeight: CGFloat
    
    var scopeID: UUID
    var number: String
    var fixedWidth: CGFloat
    var isH3: Bool
    
    var initialCursorOffset: Int? = nil
    
    var isFocused: Bool
    var focusRequestToken: Int = 0
    var onManualTap: () -> Void
    var onFocusChanged: (Bool, Int) -> Void = { _, _ in }
    var onEsc: (() -> Void)?
    var minimumHeight: CGFloat = 0

    func makeUIView(context: Context) -> LPLessonPlanTextEngine {
        let tv = LPLessonPlanTextEngine(frame: .zero, textContainer: nil)
        tv.delegate = context.coordinator
        tv.isEditable = true; tv.isSelectable = true; tv.isScrollEnabled = true
        tv.textContainer.lineFragmentPadding = 0
        tv.textContainerInset = .zero
        
        tv.onUpPressed = { x in onMoveFocus(.up, x) }
        tv.onDownPressed = { x in onMoveFocus(.down, x) }
        tv.onTabPressed = { delta in onTabRequest(delta) }
        tv.onEscPressed = { onEsc?() }
        tv.onImagePasted = { image in
            context.coordinator.activeTV = tv
            context.coordinator.handleImageImport(image)
        }
        tv.onUrlPasted = { url in
            context.coordinator.activeTV = tv
            context.coordinator.downloadAndImportImage(from: url)
        }
        
        if isFocused {
            DispatchQueue.main.async {
                tv.becomeFirstResponder()
                let targetPos = initialCursorOffset ?? tv.textStorage.length
                tv.selectedRange = NSRange(location: min(targetPos, tv.textStorage.length), length: 0)
            }
        }
        return tv
    }
    
    @MainActor
    func updateUIView(_ uiView: LPLessonPlanTextEngine, context: Context) {
        context.coordinator.parent = self
        if context.coordinator.lastFocusRequestToken != focusRequestToken {
            context.coordinator.lastFocusRequestToken = focusRequestToken
        }
        
        let nF = LPRenderer.resolveUIFont(name: style.fontName, size: style.size, isBold: style.isBold)
        let nC = UIColor(LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark))
        
        let pS = LPRerender.makeEditorParagraphStyle(
            styleConfig: style,
            number: number,
            isDark: isDark,
            embedsNumber: true
        )

        let attrs: [NSAttributedString.Key: Any] = [
            .font: nF,
            .foregroundColor: nC,
            .paragraphStyle: pS,
            .kern: style.letterSpacing
        ]
        uiView.typingAttributes = attrs
        
        let textChanged = (context.coordinator.lastText != text)
        let styleChanged = (context.coordinator.lastStyle != style)
        let themeChanged = (context.coordinator.lastIsDark != isDark)
        let numberChanged = (context.coordinator.lastNumber != number)
        
        if textChanged || styleChanged || themeChanged || numberChanged {
            let savedRange = uiView.selectedRange
            let oldLength = uiView.textStorage.length
            
            context.coordinator.isInternallyUpdating = true
            context.coordinator.lastText = text
            context.coordinator.lastStyle = style
            context.coordinator.lastIsDark = isDark
            context.coordinator.lastNumber = number
            
            if text.isEmpty && number.isEmpty {
                uiView.text = ""
                uiView.attributedText = NSAttributedString(string: "", attributes: [:])
            } else {
                let finalAttrString = LPRerender.renderNS(
                    text,
                    styleConfig: style,
                    scale: 1.0,
                    isDark: isDark,
                    hierarchicalIndent: 0,
                    formulaImages: nil,
                    number: number,
                    isEditing: true
                )
                uiView.attributedText = finalAttrString
            }
            context.coordinator.isInternallyUpdating = false
            uiView.layoutIfNeeded()
            
            if uiView.isFirstResponder {
                let newLength = uiView.textStorage.length
                let diff = newLength - oldLength
                let newLocation = max(context.coordinator.currentPrefixLength, min(savedRange.location + diff, newLength))
                uiView.selectedRange = NSRange(location: newLocation, length: 0)
            }
            context.coordinator.enqueueRecalculate(view: uiView)
        }
        
        if isFocused && !uiView.isFirstResponder {
            DispatchQueue.main.async {
                if !uiView.isFirstResponder {
                    uiView.becomeFirstResponder()
                    let targetPos = initialCursorOffset ?? uiView.textStorage.length
                    uiView.selectedRange = NSRange(location: min(targetPos, uiView.textStorage.length), length: 0)
                }
            }
        }
        if uiView.isFirstResponder != context.coordinator.lastReportedFocusState {
            context.coordinator.lastReportedFocusState = uiView.isFirstResponder
            DispatchQueue.main.async {
                self.onFocusChanged(uiView.isFirstResponder, self.focusRequestToken)
            }
        }
        if uiView.frame.width != fixedWidth {
            uiView.frame.size.width = fixedWidth
            context.coordinator.enqueueRecalculate(view: uiView)
        }
    }

    var onMoveFocus: (FocusMoveDirection, CGFloat) -> Void
    var onSplit: (String, String, String?) -> Void
    var onIndent: (Int) -> Void
    var onTabRequest: (Int) -> Void
    var onDeleteEmpty: () -> Void
    // 【367号重构】：回调接收剥离后的纯内容
    var onMergeToPrevious: (String) -> Void

    func makeCoordinator() -> Coordinator { Coordinator(self) }
    
    class Coordinator: NSObject, UITextViewDelegate, PHPickerViewControllerDelegate, UIDocumentPickerDelegate {
        var parent: LPRowEditor; weak var activeTV: LPLessonPlanTextEngine?
        var isInternallyUpdating = false
        var lastStyle: LPGlobalStyle.TextStyle? = nil
        var lastIsDark: Bool? = nil
        var lastText: String = ""
        var lastNumber: String = ""
        var lastFocusRequestToken: Int = 0
        var lastReportedFocusState = false
        
        var currentPrefixLength: Int {
            LPRerender.numberLayoutMetrics(number: parent.number, styleConfig: parent.style, isDark: parent.isDark)?
                .prefixText.utf16.count ?? 0
        }
        
        init(_ parent: LPRowEditor) { self.parent = parent }

        func textViewDidBeginEditing(_ textView: UITextView) {
            parent.onFocusChanged(true, parent.focusRequestToken)
            lastReportedFocusState = true
        }

        func textViewDidEndEditing(_ textView: UITextView) {
            parent.onFocusChanged(false, parent.focusRequestToken)
            lastReportedFocusState = false
        }
        
        func textViewDidChangeSelection(_ textView: UITextView) {
            if isInternallyUpdating { return }
            let prefixLen = currentPrefixLength
            if prefixLen > 0 {
                if textView.selectedRange.location < prefixLen {
                    isInternallyUpdating = true
                    if textView.selectedRange.length > 0 {
                        let newStart = prefixLen
                        let newEnd = max(prefixLen, textView.selectedRange.location + textView.selectedRange.length)
                        textView.selectedRange = NSRange(location: newStart, length: newEnd - newStart)
                    } else {
                        textView.selectedRange = NSRange(location: prefixLen, length: 0)
                    }
                    isInternallyUpdating = false
                }
            }
        }
        
        func textViewDidChange(_ textView: UITextView) {
            if textView.markedTextRange != nil { return }
            if isInternallyUpdating { return }
            _ = applyQuickInputRules(on: textView)
            if !isInternallyUpdating {
                let fullText = textView.text ?? ""
                let prefixLen = currentPrefixLength
                let cleanText: String
                if prefixLen > 0 && fullText.count >= prefixLen {
                    cleanText = String(fullText.dropFirst(prefixLen))
                } else {
                    cleanText = fullText
                }
                self.lastText = cleanText
                self.lastNumber = parent.number
                parent.text = cleanText
            }
            enqueueRecalculate(view: textView)
        }
        
        private func applyQuickInputRules(on textView: UITextView) -> Bool {
            guard let selectedRange = textView.selectedTextRange else { return false }
            let cursorOffset = textView.offset(from: textView.beginningOfDocument, to: selectedRange.start)
            let fullText = textView.text ?? ""
            let (processed, newCursor) = applyLPQuickInputRules(
                text: fullText,
                cursorIndex: cursorOffset,
                rules: parent.teachingStore.config.quickInputRules
            )
            guard processed != fullText else { return false }

            self.isInternallyUpdating = true
            textView.textStorage.replaceCharacters(
                in: NSRange(location: 0, length: (fullText as NSString).length),
                with: processed
            )
            let targetOffset = newCursor ?? processed.utf16.count
            if let position = textView.position(from: textView.beginningOfDocument, offset: targetOffset) {
                textView.selectedTextRange = textView.textRange(from: position, to: position)
            }
            self.isInternallyUpdating = false
            return true
        }

        func enqueueRecalculate(view: UITextView) {
            DispatchQueue.main.async {
                let width = self.parent.fixedWidth
                if width <= 10 { return }
                let size = view.sizeThatFits(CGSize(width: width, height: .greatestFiniteMagnitude))
                let currentFont = view.typingAttributes[.font] as? UIFont ?? UIFont.systemFont(ofSize: self.parent.style.size)
                let minCharHeight = max(currentFont.lineHeight, self.parent.minimumHeight)
                let finalH = max(size.height, minCharHeight)
                if abs(self.parent.dynamicHeight - finalH) > 0.5 { self.parent.dynamicHeight = finalH }
            }
        }
        
        func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool {
            let prefixLen = currentPrefixLength
            if text.isEmpty && range.length > 0 {
                if range.location < prefixLen {
                    if parent.isH3 { return false } else {
                        // 【367号核心修复】：实时物理剥离内容并传出，彻底阻断编号泄露
                        let fullText = textView.text ?? ""
                        let contentToMerge = fullText.count >= prefixLen ? String(fullText.dropFirst(prefixLen)) : ""
                        parent.onMergeToPrevious(contentToMerge)
                        return false
                    }
                }
            }
            if range.location < prefixLen { return false }
            if text == "\n" {
                if let engine = textView as? LPLessonPlanTextEngine, engine.isProcessingShiftEnter { return true };
                let nsContent = (textView.text ?? "") as NSString;
                let left = nsContent.substring(to: range.location);
                let right = nsContent.substring(from: range.location + range.length);
                let prefix = "\(parent.number)  "
                let cleanLeft = left.hasPrefix(prefix) ? String(left.dropFirst(prefix.utf16.count)) : left
                parent.onSplit(cleanLeft, right, nil); return false
            };
            return true
        }
        
        func textView(_ textView: UITextView, editMenuForTextIn range: NSRange, suggestedActions: [UIMenuElement]) -> UIMenu? { var actions = suggestedActions; let photoAction = UIAction(title: "插入相册图片", image: UIImage(systemName: "photo.on.rectangle")) { [weak self] _ in self?.activeTV = textView as? LPLessonPlanTextEngine; self?.presentPhotoPicker() }; let fileAction = UIAction(title: "插入文件夹图片", image: UIImage(systemName: "folder")) { [weak self] _ in self?.activeTV = textView as? LPLessonPlanTextEngine; self?.presentFilePicker() }; actions.append(UIMenu(title: "多媒体", image: UIImage(systemName: "plus.square"), children: [photoAction, fileAction])); return UIMenu(children: actions) }
        private func presentPhotoPicker() { var config = PHPickerConfiguration(); config.filter = .images; config.selectionLimit = 1; let picker = PHPickerViewController(configuration: config); picker.delegate = self; if let vc = findVC() { vc.present(picker, animated: true) } }
        private func presentFilePicker() { let picker = UIDocumentPickerViewController(forOpeningContentTypes: [.image]); picker.delegate = self; if let vc = findVC() { vc.present(picker, animated: true) } }
        private func findVC() -> UIViewController? { if let activeScene = UIApplication.shared.connectedScenes.first(where: { $0.activationState == .foregroundActive }) as? UIWindowScene, let root = activeScene.windows.first(where: { $0.isKeyWindow })?.rootViewController { return root }; return UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.flatMap { $0.windows }.first { $0.isKeyWindow }?.rootViewController }
        func picker(_ picker: PHPickerViewController, didFinishPicking results: [PHPickerResult]) { picker.dismiss(animated: true); guard let provider = results.first?.itemProvider, provider.canLoadObject(ofClass: UIImage.self) else { return }; provider.loadObject(ofClass: UIImage.self) { [weak self] image, _ in if let uiImage = image as? UIImage { DispatchQueue.main.async { self?.handleImageImport(uiImage) } } } }
        func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let url = urls.first, let data = try? Data(contentsOf: url), let image = UIImage(data: data) else { return }; handleImageImport(image) }
        func downloadAndImportImage(from url: URL) { URLSession.shared.dataTask(with: url) { [weak self] data, _, error in guard let data = data, error == nil, let image = UIImage(data: data) else { return }; DispatchQueue.main.async { self?.handleImageImport(image) } }.resume() }
        func handleImageImport(_ image: UIImage) { guard let id = MarkdownAssetManager.shared.saveImage(image, tableID: parent.scopeID) else { return }; let tag = "<img src=\"asset:\(id)\" width=\"20cm\">"; if let tv = activeTV { self.isInternallyUpdating = true; tv.insertText(tag); let fullText = tv.text ?? ""; let prefixLen = currentPrefixLength; let cleanText: String; if prefixLen > 0 && fullText.count >= prefixLen { cleanText = String(fullText.dropFirst(prefixLen)) } else { cleanText = fullText }; self.lastText = cleanText; self.lastNumber = parent.number; parent.text = cleanText; self.isInternallyUpdating = false; enqueueRecalculate(view: tv) } else { parent.text.append(tag) }; UIImpactFeedbackGenerator(style: .medium).impactOccurred() }
    }
}

// MARK: - LPLessonPlanTextEngine - v21 - 335号物理归零内边距

class LPLessonPlanTextEngine: UITextView {
    var onUpPressed: ((CGFloat) -> Void)?
    var onDownPressed: ((CGFloat) -> Void)?
    var onTabPressed: ((Int) -> Void)?
    var onImagePasted: ((UIImage) -> Void)?
    var onUrlPasted: ((URL) -> Void)?
    var onRequestEdit: (() -> Void)?
    var onEscPressed: (() -> Void)?
    
    var isProcessingShiftEnter = false
    
    override init(frame: CGRect, textContainer: NSTextContainer?) {
        let storage = NSTextStorage()
        let layoutManager = LPCustomLayoutManager()
        storage.addLayoutManager(layoutManager)
        let container = NSTextContainer(size: .zero)
        container.widthTracksTextView = true
        layoutManager.addTextContainer(container)
        super.init(frame: frame, textContainer: container)
        setupDefaults()
    }
    
    required init?(coder: NSCoder) { super.init(coder: coder); setupDefaults() }
    
    private func setupDefaults() {
        self.backgroundColor = .clear
        self.isScrollEnabled = false
        // 【335号核心修改】：物理归零内边距，使 spaceAbove: 0 真正生效
        self.textContainerInset = .zero
        self.textContainer.lineFragmentPadding = 0
        self.layoutManager.usesFontLeading = false
        self.layoutManager.allowsNonContiguousLayout = false
        self.autocapitalizationType = .none
        self.autocorrectionType = .no
        self.spellCheckingType = .no
        self.smartQuotesType = .no
        self.smartDashesType = .no
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        if !isEditable { onRequestEdit?() }
        super.touchesEnded(touches, with: event)
    }

    override var keyCommands: [UIKeyCommand]? {
        return [
            UIKeyCommand(input: "\r", modifierFlags: .shift, action: #selector(handleShiftEnter)),
            UIKeyCommand(input: "\t", modifierFlags: [], action: #selector(handleTab)),
            UIKeyCommand(input: "\t", modifierFlags: .shift, action: #selector(handleShiftTab)),
            UIKeyCommand(input: "\u{1B}", modifierFlags: [], action: #selector(handleEsc))
        ]
    }
    
    @objc func handleShiftEnter() { isProcessingShiftEnter = true; insertText("\n"); isProcessingShiftEnter = false }
    @objc func handleTab() { onTabPressed?(1) }
    @objc func handleShiftTab() { onTabPressed?(-1) }
    @objc func handleEsc() { resignFirstResponder(); onEscPressed?() }
    
    override func paste(_ sender: Any?) {
        let pb = UIPasteboard.general
        if let image = pb.image { onImagePasted?(image); return }
        for url in pb.urls ?? [] {
            let ext = url.pathExtension.lowercased()
            if ["jpg", "jpeg", "png", "heic", "gif", "webp"].contains(ext) {
                if let data = try? Data(contentsOf: url), let img = UIImage(data: data) { onImagePasted?(img); return }
            }
        }
        if let providers = pb.itemProviders.first(where: { $0.canLoadObject(ofClass: UIImage.self) }) {
            providers.loadObject(ofClass: UIImage.self) { [weak self] image, _ in if let img = image as? UIImage { DispatchQueue.main.async { self?.onImagePasted?(img) } } }
            return
        }
        if let text = pb.string?.trimmingCharacters(in: .whitespacesAndNewlines) {
            let pattern = #"^https?://.*?\.(jpg|jpeg|png|webp|gif)(\?.*)?$"#
            if let regex = try? NSRegularExpression(pattern: pattern, options: .caseInsensitive), regex.firstMatch(in: text, range: NSRange(location: 0, length: text.utf16.count)) != nil, let url = URL(string: text) { onUrlPasted?(url); return }
        }
        super.paste(sender)
    }

    override func pressesBegan(_ presses: Set<UIPress>, with event: UIPressesEvent?) {
        guard let key = presses.first?.key else { super.pressesBegan(presses, with: event); return }
        let currentX = self.caretRect(for: selectedTextRange?.start ?? endOfDocument).origin.x
        if key.keyCode == .keyboardUpArrow { if isAtFirstLine() { onUpPressed?(currentX); return } }
        else if key.keyCode == .keyboardDownArrow { if isAtLastLine() { onDownPressed?(currentX); return } }
        super.pressesBegan(presses, with: event)
    }

    private func isAtFirstLine() -> Bool {
        if selectedRange.location == 0 { return true }
        guard let start = selectedTextRange?.start else { return true }
        let offset = self.offset(from: beginningOfDocument, to: start)
        let glyphIndex = layoutManager.glyphIndexForCharacter(at: offset)
        let lineRect = layoutManager.lineFragmentRect(forGlyphAt: glyphIndex, effectiveRange: nil)
        return lineRect.origin.y <= 1.0
    }
    
    private func isAtLastLine() -> Bool {
        let textLength = self.text.utf16.count
        if selectedRange.location == textLength { return true }
        guard let start = selectedTextRange?.start else { return true }
        let offset = self.offset(from: beginningOfDocument, to: start)
        let glyphIndex = layoutManager.glyphIndexForCharacter(at: offset)
        let lineRect = layoutManager.lineFragmentRect(forGlyphAt: glyphIndex, effectiveRange: nil)
        let usedHeight = layoutManager.usedRect(for: textContainer).height
        return lineRect.maxY >= usedHeight - 1.0
    }
}

// MARK: - 教案专用文本输入容器 - v3 - 物理隔离命名
//
// LPRowInternalTextContainer
// (逻辑：作为 UITextView 的底层实现，监听键盘 Up/Down 方向键，并在触碰段落物理边界时向上级反馈坐标。)
class LPRowInternalTextContainer: UITextView {
    var onUpPressed: ((CGFloat) -> Void)?
    var onDownPressed: ((CGFloat) -> Void)?

    override var keyCommands: [UIKeyCommand]? {
        return [
            UIKeyCommand(input: UIKeyCommand.inputUpArrow, modifierFlags: [], action: #selector(handleUpKey)),
            UIKeyCommand(input: UIKeyCommand.inputDownArrow, modifierFlags: [], action: #selector(handleDownKey))
        ]
    }

    @objc func handleUpKey() {
        let pos = selectedRange.location
        let rect = layoutManager.lineFragmentRect(forGlyphAt: pos, effectiveRange: nil)
        // 首行判定
        if rect.origin.y <= 1.0 {
            let caretX = self.caretRect(for: selectedTextRange?.start ?? endOfDocument).origin.x
            onUpPressed?(caretX)
        } else {
            // 系统默认上移逻辑
            let currentCaret = self.caretRect(for: selectedTextRange?.start ?? endOfDocument)
            let targetPoint = CGPoint(x: currentCaret.midX, y: rect.midY - rect.height)
            if let targetPos = closestPosition(to: targetPoint) {
                selectedTextRange = textRange(from: targetPos, to: targetPos)
            }
        }
    }

    @objc func handleDownKey() {
        let pos = selectedRange.location
        let rect = layoutManager.lineFragmentRect(forGlyphAt: pos, effectiveRange: nil)
        let totalHeight = layoutManager.usedRect(for: textContainer).height
        // 末行判定
        if rect.maxY >= totalHeight - 1.0 {
            let caretX = self.caretRect(for: selectedTextRange?.start ?? endOfDocument).origin.x
            onDownPressed?(caretX)
        } else {
            // 系统默认下移逻辑
            let currentCaret = self.caretRect(for: selectedTextRange?.start ?? endOfDocument)
            let targetPoint = CGPoint(x: currentCaret.midX, y: rect.midY + rect.height)
            if let targetPos = closestPosition(to: targetPoint) {
                selectedTextRange = textRange(from: targetPos, to: targetPos)
            }
        }
    }
}

// MARK: - 教案专用内部文本视图组件 - v1
//
// LPInternalTextView
// (逻辑：物理拦截键盘方向键，利用 LayoutManager 判断光标是否处于视觉上的首行或末行。)
class LPInternalTextView: UITextView {
    var onMoveFocusRequest: ((Int, CGFloat) -> Void)?
    
    override func pressesBegan(_ presses: Set<UIPress>, with event: UIPressesEvent?) {
        guard let key = presses.first?.key else {
            super.pressesBegan(presses, with: event)
            return
        }
        
        let currentX = caretRect(for: selectedTextRange?.start ?? endOfDocument).origin.x

        if key.keyCode == .keyboardDownArrow {
            if isAtLastLine() {
                onMoveFocusRequest?(1, currentX)
                return
            }
        } else if key.keyCode == .keyboardUpArrow {
            if isAtFirstLine() {
                onMoveFocusRequest?(-1, currentX)
                return
            }
        }
        
        super.pressesBegan(presses, with: event)
    }
    
    private func isAtFirstLine() -> Bool {
        guard let start = selectedTextRange?.start else { return true }
        let offset = self.offset(from: beginningOfDocument, to: start)
        let glyphIndex = layoutManager.glyphIndexForCharacter(at: offset)
        let lineRect = layoutManager.lineFragmentRect(forGlyphAt: glyphIndex, effectiveRange: nil)
        return lineRect.origin.y <= 0
    }
    
    private func isAtLastLine() -> Bool {
        guard let start = selectedTextRange?.start else { return true }
        let offset = self.offset(from: beginningOfDocument, to: start)
        let glyphIndex = layoutManager.glyphIndexForCharacter(at: offset)
        let lineRect = layoutManager.lineFragmentRect(forGlyphAt: glyphIndex, effectiveRange: nil)
        let totalContentHeight = layoutManager.usedRect(for: textContainer).height
        // 允许 1 像素误差
        return lineRect.maxY >= totalContentHeight - 1
    }
}

// MARK: - LPKaTeXView - v14 - 增加编号参数以实现公式行物理对齐

struct LPKaTeXView: View {
    let text: String
    let style: LPGlobalStyle.TextStyle
    let isDark: Bool
    let availableWidth: CGFloat
    let number: String // 【343号新增】：集成行编号
    var onHeightCalculated: ((CGFloat) -> Void)? = nil
    
    @State private var webViewHeight: CGFloat = 44
    @State private var renderedImage: UIImage? = nil
    @State private var renderID = UUID()

    var body: some View {
        ZStack(alignment: .topLeading) {
            // 如果已有快照，直接显示
            if let img = renderedImage {
                Image(uiImage: img)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: availableWidth)
                    .frame(height: webViewHeight)
            }
            
            // WebView 后台运行或在无快照时显示
            if renderedImage == nil {
                LPKaTeXInnerView(
                    text: text,
                    style: style,
                    isDark: isDark,
                    availableWidth: availableWidth,
                    number: number, // 【核心修改】：向下传递编号
                    height: $webViewHeight,
                    onImageCaptured: { img in
                        withAnimation(.fast) {
                            self.renderedImage = img
                        }
                    }
                )
                .id(renderID)
                .frame(width: availableWidth, height: webViewHeight)
                .opacity(0.01)
            }
        }
        .frame(minHeight: 40)
        .onChange(of: text) { _, _ in
            renderedImage = nil
            renderID = UUID()
        }
        .onChange(of: number) { _, _ in // 编号变化时也重绘
            renderedImage = nil
            renderID = UUID()
        }
        .onChange(of: availableWidth) { _, _ in
            renderedImage = nil
            renderID = UUID()
        }
        .onChange(of: webViewHeight) { oldH, newH in
            if oldH > 0 && abs(newH - oldH) > (oldH * 0.1) {
                if renderedImage != nil {
                    renderedImage = nil
                }
            }
            if newH > 10 {
                onHeightCalculated?(newH + 4)
            }
        }
    }
}

// MARK: - LPKaTeXInnerView - v21 - 精确对齐编号间距，实现 Native 与 Web 视觉同构

struct LPKaTeXInnerView: UIViewRepresentable {
    let text: String
    let style: LPGlobalStyle.TextStyle
    let isDark: Bool
    let availableWidth: CGFloat
    let number: String
    @Binding var height: CGFloat
    var onImageCaptured: (UIImage) -> Void

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    func makeUIView(context: Context) -> WKWebView {
        let config = WKWebViewConfiguration()
        let controller = WKUserContentController()
        controller.removeScriptMessageHandler(forName: "heightHandler")
        controller.add(context.coordinator, name: "heightHandler")
        config.userContentController = controller
        
        let webView = WKWebView(frame: .zero, configuration: config)
        webView.scrollView.isScrollEnabled = false
        webView.isOpaque = false
        webView.backgroundColor = .clear
        return webView
    }

    func updateUIView(_ uiView: WKWebView, context: Context) {
        let fingerprint = "\(text)_\(number)_\(isDark)_\(style.size)_\(style.color)_\(style.fontName)_\(availableWidth)"
        if context.coordinator.lastFingerprint == fingerprint { return }
        context.coordinator.lastFingerprint = fingerprint

        let processedText = resolveAssetImages(in: text)
        let base64Text = processedText.data(using: .utf8)?.base64EncodedString() ?? ""
        let base64Number = number.data(using: .utf8)?.base64EncodedString() ?? ""
        
        let cssColor = colorToHex(LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark))
        let fontFamily = style.fontName.lowercased() == "system" ? "-apple-system" : "'\(style.fontName)'"
        
        // 【345号核心修复】：计算与 Native 两个空格一致的物理间距
        // 逻辑：Native 渲染中使用的是 "\(number)  "，因此间距应为 2 个字符宽度
        let spaceGap = style.size * 0.5 * 2

        let html = """
        <!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no">
        <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css">
        <script defer src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"></script>
        <script defer src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js"></script>
        <style>
            * { box-sizing: border-box; -webkit-print-color-adjust: exact; }
            body { 
                margin: 0; padding: 0 !important; 
                color: \(cssColor); font-size: \(style.size)px; font-family: \(fontFamily);
                line-height: 1.4; background: transparent; overflow: visible; 
                width: \(availableWidth)px; 
            }
            .row-container { 
                display: flex; 
                align-items: flex-start; 
                width: 100%;
                padding: 0; /* 物理对齐：内边距归零 */
            }
            .number-cell { 
                flex-shrink: 0; 
                margin-right: \(spaceGap)px; /* 物理对齐：使用计算出的像素间距 */
                white-space: nowrap;
                font-weight: \(style.isBold ? "bold" : "normal");
            }
            .content-cell { 
                flex-grow: 1; 
                word-wrap: break-word; 
                min-width: 0;
            }
            img { max-width: 100% !important; height: auto !important; border-radius: 8px; margin: 2px 0; display: block; }
            .katex { font-size: 1.1em !important; }
        </style></head><body>
            <div class="row-container">
                <div id="num" class="number-cell"></div>
                <div id="math" class="content-cell"></div>
            </div>
        <script>
            function decodeB64(b) { return decodeURIComponent(escape(window.atob(b))); }
            let lastReportedH = 0;
            let reportTimer;

            function doReport() {
                const h = Math.ceil(document.documentElement.scrollHeight + 2);
                if (Math.abs(h - lastReportedH) > 1) {
                    lastReportedH = h;
                    window.webkit.messageHandlers.heightHandler.postMessage(h);
                }
            }

            function init() {
                const numEl = document.getElementById('num');
                const mathEl = document.getElementById('math');
                
                numEl.innerText = decodeB64('\(base64Number)');
                mathEl.innerHTML = decodeB64('\(base64Text)');
                
                if(window.renderMathInElement) {
                    renderMathInElement(mathEl, { delimiters: [{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}], throwOnError:false });
                }

                document.fonts.ready.then(() => {
                    doReport();
                    const observer = new ResizeObserver(() => {
                        clearTimeout(reportTimer);
                        reportTimer = setTimeout(doReport, 150);
                    });
                    observer.observe(document.body);
                });
            }
            window.onload = init;
        </script></body></html>
        """
        uiView.loadHTMLString(html, baseURL: nil)
    }

    private func resolveAssetImages(in rawText: String) -> String {
        let pattern = #"(?i)asset:([\w\.-]+\.jpg)"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return rawText }
        var result = rawText; let nsString = rawText as NSString; let matches = regex.matches(in: rawText, options: [], range: NSRange(location: 0, length: nsString.length))
        for match in matches.reversed() {
            let assetID = nsString.substring(with: match.range(at: 1)); let fileURL = MarkdownAssetManager.shared.getFileURL(assetID: assetID)
            if let data = try? Data(contentsOf: fileURL) { let base64 = data.base64EncodedString(); result = (result as NSString).replacingCharacters(in: match.range, with: "data:image/jpeg;base64,\(base64)") }
        }
        return result
    }

    private func colorToHex(_ color: Color) -> String {
        let uiColor = UIColor(color); var r: CGFloat = 0; var g: CGFloat = 0; var b: CGFloat = 0; var a: CGFloat = 0
        uiColor.getRed(&r, green: &g, blue: &b, alpha: &a)
        return String(format: "#%02X%02X%02X", Int(r * 255), Int(g * 255), Int(b * 255))
    }

    class Coordinator: NSObject, WKScriptMessageHandler {
        var parent: LPKaTeXInnerView; var lastFingerprint: String = ""
        init(_ parent: LPKaTeXInnerView) { self.parent = parent }
        func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
            guard message.name == "heightHandler", let h = message.body as? CGFloat else { return }
            if h < 5 { return }
            DispatchQueue.main.async {
                self.parent.height = h
                let config = WKSnapshotConfiguration(); config.afterScreenUpdates = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                    message.webView?.takeSnapshot(with: config) { image, _ in
                        if let img = image { self.parent.onImageCaptured(img) }
                    }
                }
            }
        }
    }
}

#endif

// MARK: - LPRerender (macOS 使用通用实现)

// MARK: - 教案静默数学渲染器 - v1 - 负责将 LaTeX 转换为高清图片映射

import WebKit

@MainActor
class LPHeadlessMathRenderer: NSObject, WKScriptMessageHandler {
    private var webView: WKWebView?
    private var formulaQueue: [String] = []
    private var results: [String: LPFormulaRenderAsset] = [:]
    private var completion: (([String: LPFormulaRenderAsset]) -> Void)?
    
    private var currentStyle: LPGlobalStyle.TextStyle?
    private var isDark: Bool = false
    private var renderWidth: CGFloat = 1000 // 导出使用较宽基准确保清晰度
    
    // 核心入口：渲染一组公式
    func render(formulas: Set<String>, style: LPGlobalStyle.TextStyle, dark: Bool, completion: @escaping ([String: LPFormulaRenderAsset]) -> Void) {
        guard !formulas.isEmpty else {
            completion([:])
            return
        }
        
        self.formulaQueue = Array(formulas)
        self.results = [:]
        self.completion = completion
        self.currentStyle = style
        self.isDark = dark
        
        setupWebView()
        processNext()
    }
    
    private func setupWebView() {
        if webView == nil {
            let config = WKWebViewConfiguration()
            let controller = WKUserContentController()
            controller.add(self, name: "headlessHeightHandler")
            config.userContentController = controller
            
            // 物理尺寸设为固定大宽度
            webView = WKWebView(frame: CGRect(x: 0, y: 0, width: renderWidth, height: 1000), configuration: config)
            #if os(iOS)
            webView?.isOpaque = false
            webView?.backgroundColor = .clear
            #else
            webView?.setValue(false, forKey: "drawsBackground")
            webView?.wantsLayer = true
            webView?.layer?.backgroundColor = NSColor.clear.cgColor
            #endif
        }
    }
    
    private func processNext() {
        guard !formulaQueue.isEmpty else {
            completion?(results)
            cleanup()
            return
        }
        
        let formula = formulaQueue.removeFirst()
        loadFormulaInWebView(formula)
    }
    
    private func loadFormulaInWebView(_ formula: String) {
        guard let style = currentStyle else { return }
        
        // 颜色转换
        let uiColor = LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark)
        let cssColor = colorToHex(uiColor)
        // 转换图片资源路径 (如果有)
        let processedText = formula.data(using: .utf8)?.base64EncodedString() ?? ""
        
        #if os(macOS)
        let localCss = Bundle.main.url(forResource: "katex.min", withExtension: "css", subdirectory: "markdown_assets")
        let localJs = Bundle.main.url(forResource: "katex.min", withExtension: "js", subdirectory: "markdown_assets")
        let localAuto = Bundle.main.url(forResource: "auto-render.min", withExtension: "js", subdirectory: "markdown_assets")
        let useLocal = (localCss != nil && localJs != nil && localAuto != nil)
        let assetBaseURL = useLocal ? Bundle.main.resourceURL?.appendingPathComponent("markdown_assets") : nil
        let katexCss = useLocal ? "katex.min.css" : "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css"
        let katexJs = useLocal ? "katex.min.js" : "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"
        let autoRenderJs = useLocal ? "auto-render.min.js" : "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js"
        #else
        let assetBaseURL: URL? = nil
        let katexCss = "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css"
        let katexJs = "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"
        let autoRenderJs = "https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js"
        #endif

        let isDisplay = formula.hasPrefix("$$") || formula.hasPrefix("\\[")
        let formulaFontSize = style.size * (isDisplay ? 0.74 : 0.70)
        let html = #"""
        <!DOCTYPE html><html><head><meta charset="UTF-8">
        <link rel="stylesheet" href="\#(katexCss)">
        <script defer src="\#(katexJs)"></script>
        <script defer src="\#(autoRenderJs)"></script>
        <style>
            body { 
                margin: 0; padding: 0 !important; 
                color: \#(cssColor) !important; font-size: \#(formulaFontSize)px;
                background: transparent; overflow: hidden;
                display: inline-block; line-height: 1; /* 紧凑布局 */
                -webkit-font-smoothing: antialiased;
                text-rendering: geometricPrecision;
            }
            #math { display: inline-block; word-wrap: break-word; color: \#(cssColor) !important; line-height: 1; padding: \#(isDisplay ? "4px 0 2px 0" : "0"); }
            #math .katex, #math .katex * { color: \#(cssColor) !important; }
            #math .katex { font-size: 1em !important; }
            #math .katex-display { margin: 0; }
            #math .katex-display > .katex { display: inline-block; }
        </style></head><body><div id="math"></div><script>
            function decodeB64(b) { return decodeURIComponent(escape(window.atob(b))); }
            window.onload = function() {
                const el = document.getElementById('math');
                el.style.color = '\#(cssColor)';
                let raw = decodeB64('\#(processedText)');
                el.innerHTML = raw;
                if(window.renderMathInElement) {
                    renderMathInElement(el, { delimiters: [{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false},{left:'\\[',right:'\\]',display:true}], throwOnError:false });
                }
                // 等待字体加载并渲染完成后通知高度
                document.fonts.ready.then(() => {
                    setTimeout(() => {
                        const rect = el.getBoundingClientRect();
                        window.webkit.messageHandlers.headlessHeightHandler.postMessage({
                            width: rect.width,
                            height: rect.height + (raw.startsWith('$$') || raw.startsWith('\\[') ? 10 : 4),
                            formula: '\#(processedText)', // 回传标识
                            html: el.innerHTML
                        });
                    }, 100);
                });
            }
        </script></body></html>
        """#
        webView?.loadHTMLString(html, baseURL: assetBaseURL)
    }

    private func makeSVGMarkup(
        width: CGFloat,
        height: CGFloat,
        innerHTML: String,
        textColorHex: String,
        fontFamily: String,
        fontSize: CGFloat
    ) -> String {
        return """
        <svg xmlns="http://www.w3.org/2000/svg" width="\(width)" height="\(height)" viewBox="0 0 \(width) \(height)">
          <foreignObject x="0" y="0" width="100%" height="100%">
            <div xmlns="http://www.w3.org/1999/xhtml" style="margin:0;padding:0;color:\(textColorHex);font-family:\(fontFamily);font-size:\(fontSize)px;line-height:1;background:transparent;">
              \(innerHTML)
            </div>
          </foreignObject>
        </svg>
        """
    }
    
    // 收到渲染完成通知，执行截图
    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        guard let dict = message.body as? [String: Any],
              let w = dict["width"] as? CGFloat,
              let h = dict["height"] as? CGFloat,
              let b64Formula = dict["formula"] as? String,
              let formulaKey = decodeB64(b64Formula) else { return }
        let renderedHTML = (dict["html"] as? String) ?? ""
        guard let style = currentStyle else { return }
        let uiColor = LPRerender.lpAdaptiveColor(hex: style.color, dark: isDark)
        let cssColor = colorToHex(uiColor)
        let isDisplay = formulaKey.hasPrefix("$$") || formulaKey.hasPrefix("\\[")
        let formulaFontSize = style.size * (isDisplay ? 0.74 : 0.70)
        let svgMarkup = makeSVGMarkup(
            width: w,
            height: h,
            innerHTML: renderedHTML,
            textColorHex: cssColor,
            fontFamily: "-apple-system",
            fontSize: formulaFontSize
        )

        let config = WKSnapshotConfiguration()
        config.rect = CGRect(x: 0, y: 0, width: w, height: h)
        config.afterScreenUpdates = true

        #if os(macOS)
        if #available(macOS 12.0, *) {
            let scale = NSScreen.main?.backingScaleFactor ?? 2.0
            config.snapshotWidth = NSNumber(value: Double(config.rect.width * scale * 2.0))
        }
        #endif

        webView?.takeSnapshot(with: config) { [weak self] image, _ in
            guard let self = self else { return }
            if let img = image {
                self.results[formulaKey] = LPFormulaRenderAsset(image: img, svgMarkup: svgMarkup, logicalSize: CGSize(width: w, height: h))
            } else {
                self.results[formulaKey] = LPFormulaRenderAsset(image: nil, svgMarkup: svgMarkup, logicalSize: CGSize(width: w, height: h))
            }
            self.processNext()
        }
    }
    
    private func decodeB64(_ b: String) -> String? {
        guard let data = Data(base64Encoded: b) else { return nil }
        return String(data: data, encoding: .utf8)
    }
    
    
    private func colorToHex(_ color: Color) -> String {
        let uiColor = UIColor(color); var r: CGFloat = 0; var g: CGFloat = 0; var b: CGFloat = 0; var a: CGFloat = 0
        uiColor.getRed(&r, green: &g, blue: &b, alpha: &a)
        return String(format: "#%02X%02X%02X", Int(r * 255), Int(g * 255), Int(b * 255))
    }
    
    private func cleanup() {
        webView = nil
        completion = nil
        currentStyle = nil
    }
}


























