// MARK: - Web视图包装器 - v2 - 适配 macOS
//
// WebView
// (修改内容：使用 #if !os(macOS) 和 #else 支持 Mac 原生 NSViewRepresentable)

import SwiftUI
import WebKit

#if !os(macOS)
struct WebView: UIViewRepresentable {
    let htmlContent: String
    
    func makeUIView(context: Context) -> WKWebView {
        let config = WKWebViewConfiguration()
        let webView = WKWebView(frame: .zero, configuration: config)
        webView.isOpaque = false
        webView.backgroundColor = UIColor.clear
        webView.scrollView.backgroundColor = UIColor.clear
        return webView
    }
    
    func updateUIView(_ uiView: WKWebView, context: Context) {
        uiView.loadHTMLString(htmlContent, baseURL: nil)
    }
}
#else
struct WebView: NSViewRepresentable {
    let htmlContent: String
    
    func makeNSView(context: Context) -> WKWebView {
        let config = WKWebViewConfiguration()
        let webView = WKWebView(frame: .zero, configuration: config)
        webView.setValue(false, forKey: "drawsBackground") // Mac端开启透明背景
        return webView
    }
    
    func updateNSView(_ nsView: WKWebView, context: Context) {
        nsView.loadHTMLString(htmlContent, baseURL: nil)
    }
}
#endif

// MARK: - 模板管理器视图 - v22 - 适配 macOS 震动反馈

struct TemplateManagerView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @Environment(\.dismiss) var dismiss
    
    // 状态管理
    @State private var selectedTab: ArchiveTemplate.TemplateType = .table
    @Environment(\.editMode) private var editMode
    @State private var selectedTemplateIDs = Set<UUID>()
    
    // 搜索状态
    @State private var searchText: String = ""
    
    // 新建与重命名
    @State private var showingAddTable = false
    @State private var showingAddList = false
    @State private var newName = ""
    @State private var showDuplicateAlert = false
    
    @State private var renamingTemplate: ArchiveTemplate?
    @State private var renameText = ""
    @State private var showRenameAlert = false
    @State private var showRenameDuplicateAlert = false
    
    // 合并与删除
    @State private var mergeSource: ArchiveTemplate? = nil
    @State private var showMergeSheet = false
    @State private var templateToDelete: ArchiveTemplate?
    @State private var showDeleteAlert = false
    @State private var showBatchDeleteAlert = false
    
    // 排序
    enum SortOption: String, CaseIterable {
        case defaultSort = "默认顺序"
        case nameAsc = "名称正序"
        case nameDesc = "名称倒序"
    }
    @State private var sortOption: SortOption = .defaultSort
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var processedTemplates: [ArchiveTemplate] {
        var filtered = asStore.templates.filter { $0.type == selectedTab }
        
        if !searchText.isEmpty {
            filtered = filtered.filter { $0.title.localizedCaseInsensitiveContains(searchText) }
        }
        
        switch sortOption {
        case .nameAsc: return filtered.sorted { $0.title.localizedStandardCompare($1.title) == .orderedAscending }
        case .nameDesc: return filtered.sorted { $0.title.localizedStandardCompare($1.title) == .orderedDescending }
        case .defaultSort: return filtered
        }
    }
    
    var isEditing: Bool { editMode?.wrappedValue.isEditing == true }
    
    var body: some View {
        contentWithCreationAlerts
            .alert("删除模板？", isPresented: $showDeleteAlert, presenting: templateToDelete) { tmpl in
                Button("取消", role: .cancel) { }
                Button("确认删除", role: .destructive) { asStore.deleteTemplateWithCascade(templateID: tmpl.id) }
            } message: { tmpl in Text("警告：删除“\(tmpl.title)”将同步删除所有使用该模板的表格文件。\n\n此操作不可撤销，确定要继续吗？") }
            .alert("批量删除", isPresented: $showBatchDeleteAlert) {
                Button("取消", role: .cancel) { }
                Button("确认删除 \(selectedTemplateIDs.count) 项", role: .destructive) { deleteSelected() }
            } message: { Text("删除模板将同步删除所有关联文件。此操作不可恢复。") }
            .sheet(isPresented: $showMergeSheet) {
                if let src = mergeSource {
                    TTModalSheetContainer(minWidth: 900, minHeight: 720) {
                        TemplateMergeView(sourceTemplate: src)
                    }
                }
            }
            .onChange(of: isEditing) { _, newVal in if !newVal { selectedTemplateIDs.removeAll() } }
    }
    
    var contentWithCreationAlerts: some View {
        ZStack {
            backgroundLayer
            VStack(spacing: 0) {
                headerTabs
                templateList
            }
            if isEditing && !selectedTemplateIDs.isEmpty {
                VStack { Spacer(); bottomActionMenu }.transition(.move(edge: .bottom))
            }
        }
        .navigationTitle("模板管理")
        .ttToolbarBackground(.hidden, for: .navigationBar)
        .ttToolbarColorScheme(.dark, for: .navigationBar)
        .ttSearchable(text: $searchText, prompt: "搜索模板名...")
        .toolbar { toolbarContent }
        .alert("新建表格模板", isPresented: $showingAddTable) {
            TextField("名称", text: $newName)
            Button("取消", role: .cancel) { newName = "" }
            Button("创建") { createTemplate(type: .table) }
        }
        .alert("新建清单模板", isPresented: $showingAddList) {
            TextField("名称", text: $newName)
            Button("取消", role: .cancel) { newName = "" }
            Button("创建") { createTemplate(type: .taskList) }
        }
        .alert("名称已存在", isPresented: $showDuplicateAlert) {
            Button("确定", role: .cancel) { }
        } message: { Text("模板名称“\(newName)”已存在，请换一个名称。") }
        .alert("重命名模板", isPresented: $showRenameAlert) {
            TextField("新名称", text: $renameText)
            Button("取消", role: .cancel) { }
            Button("保存") { validateAndRename() }
        }
        .alert("名称重复", isPresented: $showRenameDuplicateAlert) {
            Button("确定", role: .cancel) { DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { showRenameAlert = true } }
        } message: { Text("该名称已被使用。") }
    }
    
    private var backgroundLayer: some View {
        GeometryReader { geo in MainBackgroundView(themeColor: themeColor).frame(height: UIScreen.mainSafe.bounds.height).offset(y: -geo.frame(in: .global).minY) }.ignoresSafeArea()
    }
    
    private var headerTabs: some View {
        HStack {
            HStack(spacing: 0) {
                TabPill(title: "表格", isSelected: selectedTab == .table) { selectedTab = .table }
                TabPill(title: "清单", isSelected: selectedTab == .taskList) { selectedTab = .taskList }
            }
            .padding(4).background(Capsule().fill(Color.white.opacity(0.1)))
            Spacer()
        }.padding(.horizontal, 24).padding(.vertical, 16)
    }
    
    private var templateList: some View {
        List {
            if processedTemplates.isEmpty {
                VStack(spacing: 12) { Spacer().frame(height: 50); Image(systemName: "doc.on.doc").font(.largeTitle).opacity(0.2); Text(searchText.isEmpty ? "暂无模板" : "未找到匹配项").font(.caption).opacity(0.4) }.frame(maxWidth: .infinity).listRowBackground(Color.clear).listRowSeparator(.hidden)
            } else {
                ForEach(processedTemplates) { template in rowView(for: template) }
            }
            Color.clear.frame(height: 100).listRowBackground(Color.clear).listRowSeparator(.hidden)
        }.listStyle(.plain).scrollContentBackground(.hidden)
    }
    
    @ViewBuilder
    private func rowView(for template: ArchiveTemplate) -> some View {
        ZStack {
            if !isEditing { NavigationLink(destination: destinationView(for: template)) { EmptyView() }.opacity(0).buttonStyle(.plain) }
            TemplateRowView(template: template, isEditing: isEditing, isSelected: selectedTemplateIDs.contains(template.id))
            if isEditing {
                Color.white.opacity(0.001).frame(maxWidth: .infinity, maxHeight: .infinity).contentShape(Rectangle())
                .onTapGesture {
                    toggleSelection(template.id)
                    #if !os(macOS)
                    UIImpactFeedbackGenerator(style: .light).impactOccurred()
                    #endif
                }
            }
        }
        .listRowInsets(EdgeInsets(top: 6, leading: 20, bottom: 6, trailing: 20)).listRowBackground(Color.clear).listRowSeparator(.hidden)
        .contextMenu {
            if !isEditing {
                Button { renamingTemplate = template; renameText = template.title; showRenameAlert = true } label: { Label("重命名", systemImage: "pencil") }
                Button { mergeSource = template; showMergeSheet = true } label: { Label("合并建议", systemImage: "arrow.triangle.merge") }
                Divider(); Button(role: .destructive) { confirmDelete(template) } label: { Label("删除模板", systemImage: "trash") }
            }
        }
        .swipeActions(edge: .trailing, allowsFullSwipe: false) { if !isEditing { Button(role: .destructive) { confirmDelete(template) } label: { Label("删除", systemImage: "trash") } } }
    }
    
    private var toolbarContent: some ToolbarContent {
        ToolbarItem(placement: .topBarTrailing) {
            HStack(spacing: 28) {
                if !isEditing {
                    Menu { Picker("排序方式", selection: $sortOption) { ForEach(SortOption.allCases, id: \.self) { Text($0.rawValue).tag($0) } } } label: { Image(systemName: "arrow.up.arrow.down.circle").font(.system(size: 24)) }
                }
                Button { withAnimation { if isEditing { editMode?.wrappedValue = .inactive } else { editMode?.wrappedValue = .active } } } label: { Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle").font(.system(size: 24)).foregroundColor(isEditing ? .green : .white) }
                if !isEditing { Button { if selectedTab == .table { showingAddTable = true } else { showingAddList = true } } label: { Image(systemName: "plus.circle.fill").font(.system(size: 24)) } }
            }
        }
    }
    
    private var bottomActionMenu: some View {
        HStack {
            Button(role: .destructive) { showBatchDeleteAlert = true } label: { Image(systemName: "trash.fill").font(.title2) }.foregroundColor(.red)
            Spacer(); Text("已选 \(selectedTemplateIDs.count)").font(.system(size: 13, weight: .bold, design: .rounded)); Spacer(); Image(systemName: "trash.fill").font(.title2).opacity(0)
        }.padding(.horizontal, 32).padding(.vertical, 16).background(.ultraThinMaterial).clipShape(Capsule()).overlay(Capsule().stroke(Color.white.opacity(0.1), lineWidth: 0.5)).shadow(radius: 20).padding(.horizontal, 24).padding(.bottom, 50)
    }
    
    @ViewBuilder func destinationView(for template: ArchiveTemplate) -> some View { if template.type == .table { TemplateEditorView(templateID: template.id) } else { TaskListTemplateEditor(templateID: template.id) } }
    func createTemplate(type: ArchiveTemplate.TemplateType) { let trimmed = newName.trimmingCharacters(in: .whitespaces); if asStore.checkTemplateNameExists(name: trimmed) { showDuplicateAlert = true } else { _ = asStore.addTemplate(title: trimmed, keys:[], type: type); newName = "" } }
    func confirmDelete(_ template: ArchiveTemplate) { templateToDelete = template; showDeleteAlert = true }
    func validateAndRename() { guard let tmpl = renamingTemplate, !renameText.isEmpty else { return }; let trimmed = renameText.trimmingCharacters(in: .whitespaces); if asStore.checkTemplateNameExists(name: trimmed, excludeID: tmpl.id) { showRenameDuplicateAlert = true } else { asStore.renameTemplate(id: tmpl.id, newName: trimmed) } }
    func toggleSelection(_ id: UUID) { if selectedTemplateIDs.contains(id) { selectedTemplateIDs.remove(id) } else { selectedTemplateIDs.insert(id) } }
    func deleteSelected() { for id in selectedTemplateIDs { asStore.deleteTemplateWithCascade(templateID: id) }; selectedTemplateIDs.removeAll(); editMode?.wrappedValue = .inactive }
}

// MARK: - 模板编辑器 - v40 - 适配 macOS 震动反馈

struct TemplateEditorView: View {
    let templateID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @Environment(\.dismiss) var dismiss
    @Environment(\.editMode) private var editMode
    
    @State private var newKeyName = ""
    @State private var editingKeyID: String?
    @State private var showConfigSheet = false
    @State private var tempConfig = KeyStyleConfig()
    @State private var localTitle: String = ""
    @State private var showDuplicateAlert = false
    @State private var duplicateName = ""
    
    @State private var selectedKeyIDs = Set<UUID>()
    @State private var showBatchDeleteAlert = false
    @State private var showSingleDeleteAlert = false
    @State private var keyToDelete: TemplateKey?
    
    @FocusState private var focusedKeyID: String?
    @FocusState private var isAddingNew: Bool
    
    private let fontOptions:[(label: String, name: String?, design: String)] = [
        ("系统默认 (Default)", nil, "default"),
        ("圆体 (Rounded)", nil, "rounded"),
        ("衬线 (Serif)", nil, "serif"),
        ("等宽 (Monospaced)", nil, "monospaced")
    ]
    
    private let colorOptions: [(hex: String, name: String)] = [
        ("white", "白"), ("red", "红"), ("orange", "橙"),
        ("yellow", "黄"), ("green", "绿"), ("blue", "蓝"), ("purple", "紫")
    ]
    
    var template: ArchiveTemplate? { asStore.templates.first(where: { $0.id == templateID }) }
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var isEditing: Bool { editMode?.wrappedValue.isEditing == true }

    var body: some View {
        ZStack {
            backgroundLayer
            if let template = template {
                List {
                    headerSection
                    keyRows(template: template)
                    addKeySection
                    Section { Color.clear.frame(height: 400) }.listRowBackground(Color.clear)
                }
                .listStyle(.plain).scrollContentBackground(.hidden).environment(\.editMode, editMode)
            }
        }
        .onAppear { if let t = template { localTitle = t.title } }
        .ttNavigationBarTitleDisplayMode(.inline).ttToolbarBackground(.hidden, for: .navigationBar).ttToolbarColorScheme(.dark, for: .navigationBar)
        .toolbar { toolbarContent }
        .alert("名称已存在", isPresented: $showDuplicateAlert) { Button("确定", role: .cancel) { if let t = template { localTitle = t.title } } } message: { Text("模板名称“\(duplicateName)”已存在。") }
        .alert("确认删除词条？", isPresented: $showSingleDeleteAlert, presenting: keyToDelete) { tk in Button("取消", role: .cancel) { keyToDelete = nil }; Button("确认删除", role: .destructive) { performSingleDelete(tk: tk) } } message: { tk in Text("删除“\(tk.name)”将同步清除所有相关内容，且不可撤销。") }
        .alert("确认批量删除？", isPresented: $showBatchDeleteAlert) { Button("取消", role: .cancel) { }; Button("全部删除", role: .destructive) { performBatchDelete() } } message: { Text("操作将从模板中移除选中的 \(selectedKeyIDs.count) 个词条，并清理相关数据。") }
        .sheet(isPresented: $showConfigSheet) {
            TTModalSheetContainer(minWidth: 860, minHeight: 720) { configSheetView }
        }
    }
    
    private var backgroundLayer: some View {
        GeometryReader { geo in MainBackgroundView(themeColor: themeColor).frame(height: UIScreen.mainSafe.bounds.height).offset(y: -geo.frame(in: .global).minY) }.ignoresSafeArea()
    }
    private var headerSection: some View { Section { VStack(alignment: .leading, spacing: 10) { TextField("模板名称", text: $localTitle).font(.system(size: 34, weight: .black, design: .rounded)).foregroundColor(.white).onSubmit { validateAndRename() }; HStack { Text(isEditing ? "批量编辑模式" : "按回车快速新建下一行"); Spacer(); if isEditing && !(template?.keys.isEmpty ?? true) { Button(selectedKeyIDs.count == (template?.keys.count ?? 0) ? "取消全选" : "全选") { if selectedKeyIDs.count == (template?.keys.count ?? 0) { selectedKeyIDs.removeAll() } else { selectedKeyIDs = Set(template?.keys.map { $0.id } ?? []) } }.font(.caption.bold()).foregroundColor(.blue) } }.font(.system(size: 13, weight: .medium)).foregroundColor(.white.opacity(0.4)) }.padding(.top, 20).padding(.bottom, 24) }.listRowBackground(Color.clear).listRowSeparator(.hidden).listRowInsets(EdgeInsets(top: 0, leading: 24, bottom: 0, trailing: 24)) }
    private func keyRows(template: ArchiveTemplate) -> some View { ForEach(Array(template.keys.enumerated()), id: \.element.id) { index, tk in let config = asStore.getKeyConfigObj(templateID: templateID, key: tk.id.uuidString); ZStack { TemplateKeyCard(key: tk.name, config: config, onRename: { newVal in asStore.renameTemplateKey(templateID: templateID, index: index, newName: newVal) }, onSubmit: { handleRowSubmit(at: index) }, isFocused: focusedKeyID == tk.id.uuidString, isEditing: isEditing, isSelected: selectedKeyIDs.contains(tk.id)).tag(tk.id).focused($focusedKeyID, equals: tk.id.uuidString); if isEditing { Color.white.opacity(0.001).frame(maxWidth: .infinity, maxHeight: .infinity).contentShape(Rectangle()).onTapGesture { toggleSelection(tk.id);
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        #endif
    } } }.listRowInsets(EdgeInsets(top: 4, leading: 20, bottom: 4, trailing: 20)).listRowBackground(Color.clear).listRowSeparator(.hidden).swipeActions(edge: .trailing) { if !isEditing { Button(role: .destructive) { keyToDelete = tk; showSingleDeleteAlert = true } label: { Label("删除", systemImage: "trash") } } } }.onMove { src, dst in asStore.moveTemplateKeys(templateID: templateID, from: src, to: dst) } }
    private var addKeySection: some View { Group { if !isEditing { Section { HStack { Image(systemName: "plus.circle.fill").foregroundColor(.blue); TextField("输入新词条...", text: $newKeyName).focused($isAddingNew).submitLabel(.done).onSubmit { addKey() } }.padding(16).background(RoundedRectangle(cornerRadius: 16).fill(Color.white.opacity(0.06))).overlay(RoundedRectangle(cornerRadius: 16).stroke(isAddingNew ? Color.blue.opacity(0.5) : Color.white.opacity(0.1), lineWidth: 0.5)) }.listRowInsets(EdgeInsets(top: 12, leading: 20, bottom: 0, trailing: 20)).listRowBackground(Color.clear).listRowSeparator(.hidden) } } }
    @ToolbarContentBuilder private var toolbarContent: some ToolbarContent { ToolbarItem(placement: .topBarTrailing) { HStack(spacing: 28) { if isEditing { Button(role: .destructive) { if !selectedKeyIDs.isEmpty { showBatchDeleteAlert = true } } label: { Image(systemName: "trash.fill").font(.system(size: 24)).foregroundColor(selectedKeyIDs.isEmpty ? .gray : .red) }.disabled(selectedKeyIDs.isEmpty) } else { Button { if let fid = focusedKeyID { editingKeyID = fid; tempConfig = asStore.getKeyConfigObj(templateID: templateID, key: fid); showConfigSheet = true } } label: { Image(systemName: "paintpalette.fill").font(.system(size: 24)).foregroundColor(focusedKeyID == nil ? .gray : .blue) }.disabled(focusedKeyID == nil) }; Button { withAnimation { if isEditing { editMode?.wrappedValue = .inactive; selectedKeyIDs.removeAll() } else { focusedKeyID = nil; isAddingNew = false; editMode?.wrappedValue = .active } } } label: { Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle").font(.system(size: 24)).foregroundColor(isEditing ? .green : .white) } } } }
    private var configSheetView: some View { NavigationStack { Form { Section(header: Text("外观设置")) { Picker("字体", selection: Binding<String>(get: { if let name = tempConfig.customFontName { return name }; if tempConfig.fontDesign != "default" { return "sys_\(tempConfig.fontDesign)" }; return "sys_default" }, set: { if $0.starts(with: "sys_") { tempConfig.fontDesign = String($0.dropFirst(4)); tempConfig.customFontName = nil } else { tempConfig.customFontName = $0; tempConfig.fontDesign = "default" } })) { ForEach(fontOptions, id: \.label) { opt in let tagValue = opt.name ?? "sys_\(opt.design)"; Text(opt.label).tag(tagValue) } }; Stepper("字号: \(Int(tempConfig.fontSize))", value: $tempConfig.fontSize, in: 12...60); Toggle("加粗显示", isOn: $tempConfig.isBold) }; Section(header: Text("文字颜色")) { LazyVGrid(columns:[GridItem(.adaptive(minimum: 40))], spacing: 15) { ForEach(colorOptions, id: \.hex) { colorOpt in ZStack { Circle().fill(colorFromStr(colorOpt.hex)).frame(width: 40, height: 40).overlay(Circle().stroke(Color.white.opacity(0.3), lineWidth: 1)); if tempConfig.color == colorOpt.hex { Image(systemName: "checkmark").font(.caption.bold()).foregroundColor(colorOpt.hex == "white" ? .black : .white) } }.onTapGesture { tempConfig.color = colorOpt.hex } } }.padding(.vertical, 8) }; Section(header: Text("辅助输入")) { NavigationLink("编辑预设 Tag") { PresetEditorView(presets: $tempConfig.presets) }; Picker("引用清单", selection: $tempConfig.refTableID) { Text("无").tag(String?.none); ForEach(asStore.taskLists) { list in Text(list.title).tag(list.id.uuidString as String?) } } } }.navigationTitle("样式配置").toolbar { Button("保存") { saveConfig(); showConfigSheet = false } } }.presentationDetents([.medium, .large]) }
    func toggleSelection(_ id: UUID) { if selectedKeyIDs.contains(id) { selectedKeyIDs.remove(id) } else { selectedKeyIDs.insert(id) } }
    func handleRowSubmit(at index: Int) { guard let keys = template?.keys else { return }; if index < keys.count - 1 { focusedKeyID = keys[index + 1].id.uuidString } else { if let newID = asStore.addKeyToTemplateCascade(templateID: templateID, newKey: "新词条") { DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { focusedKeyID = newID.uuidString } } } }
    func addKey() { if !newKeyName.isEmpty { if let newID = asStore.addKeyToTemplateCascade(templateID: templateID, newKey: newKeyName) { newKeyName = ""; DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { focusedKeyID = newID.uuidString } } } }
    func colorFromStr(_ s: String) -> Color { switch s { case "white": return .white; case "red": return .red; case "orange": return .orange; case "yellow": return .yellow; case "green": return .green; case "blue": return .blue; case "purple": return .purple; default: return .white } }
    func validateAndRename() { let trimmed = localTitle.trimmingCharacters(in: .whitespaces); if asStore.checkTemplateNameExists(name: trimmed, excludeID: templateID) { duplicateName = trimmed; showDuplicateAlert = true } else { asStore.renameTemplate(id: templateID, newName: trimmed) } }
    func saveConfig() { if let key = editingKeyID { asStore.saveKeyConfigObj(templateID: templateID, key: key, config: tempConfig) } }
    func performSingleDelete(tk: TemplateKey) { if let idx = template?.keys.firstIndex(where: { $0.id == tk.id }) { asStore.removeKeyFromTemplateCascade(templateID: templateID, keyIndex: idx, keyName: tk.name) } }
    func performBatchDelete() { asStore.deleteMultipleTemplateKeys(templateID: templateID, keyIDs: selectedKeyIDs); selectedKeyIDs.removeAll(); editMode?.wrappedValue = .inactive }
}

// MARK: - 辅助组件：胶囊切换项 - v3 - 放大触控区域
//
// TabPill
// (修改：显著增大字号 (13->16) 和内边距 (H:16->24, V:6->10)，
//  方便手指点击，提升操作体验。)

struct TabPill: View {
    let title: String
    let isSelected: Bool
    let action: () -> Void
    var body: some View {
        Text(title)
            .font(.system(size: 16, weight: .bold)) // 增大字体
            .padding(.horizontal, 24) // 增大横向点击区
            .padding(.vertical, 10)   // 增大纵向点击区
            .background(isSelected ? Capsule().fill(Color.blue) : Capsule().fill(Color.clear))
            .foregroundColor(isSelected ? .white : .white.opacity(0.5))
            .contentShape(Rectangle()) // 确保点击响应区域完整
            .onTapGesture { action() }
            .animation(.spring(response: 0.3), value: isSelected)
    }
}

// MARK: - 清单模板编辑器 - v48 - 修复数组初始化空格语法报错

struct TaskListTemplateEditor: View {
    let templateID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @Environment(\.editMode) private var editMode
    
    @State private var newNodeTitle = ""
    @State private var selectedIDs = Set<UUID>()
    @State private var showBatchDeleteAlert = false
    
    @State private var localUndoStack: [[ArchiveRow]] = []
    @State private var localRedoStack: [[ArchiveRow]] = []
    
    @State private var searchText = ""
    @State private var matchIDs: [UUID] = []
    @State private var currentMatchIndex: Int = 0
    
    @State private var foldedIDs = Set<UUID>()
    @State private var maxDisplayLevel: Int = 100
    
    @State private var targetScrollID: UUID? = nil
    @State private var showLevelStyleSheet = false
    
    @FocusState private var focusedRowID: UUID?
    @FocusState private var isNewInputFocused: Bool
    
    var template: ArchiveTemplate? { asStore.templates.first(where: { $0.id == templateID }) }
    
    // 【核心修改】：适配 macOS 的设备判定
    private var isIPhone: Bool {
        #if os(macOS)
        return false
        #else
        return UIDevice.current.userInterfaceIdiom == .phone
        #endif
    }
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var isEditing: Bool { editMode?.wrappedValue.isEditing == true }
    
    var body: some View {
        let btnSpacing: CGFloat = isIPhone ? 6 : 20
        let innerSpacing: CGFloat = isIPhone ? 5 : 12
        let iconScale: CGFloat = isIPhone ? 0.6 : 1.0
        
        ZStack(alignment: .bottom) {
            GeometryReader { geo in MainBackgroundView(themeColor: themeColor).frame(height: UIScreen.mainSafe.bounds.height).offset(y: -geo.frame(in: .global).minY) }.ignoresSafeArea()
            
            ScrollViewReader { proxy in
                List {
                    Section {
                        VStack(alignment: .leading, spacing: 10) {
                            TextField("模板名称", text: Binding(get: { template?.title ?? "" }, set: { asStore.renameTemplate(id: templateID, newName: $0) })).font(.system(size: 34, weight: .black, design: .rounded)).foregroundColor(.white)
                            HStack {
                                Text(isEditing ? "分支集体操作" : (searchText.isEmpty ? "逻辑树结构设计" : "匹配项 \(matchIDs.isEmpty ? 0 : currentMatchIndex + 1) / \(matchIDs.count)"))
                                Spacer()
                                if isEditing && !(template?.taskRows.isEmpty ?? true) {
                                    Button(selectedIDs.count == (template?.taskRows.count ?? 0) ? "取消全选" : "全选") {
                                        if selectedIDs.count == (template?.taskRows.count ?? 0) { selectedIDs.removeAll() }
                                        else { selectedIDs = Set(template?.taskRows.map { $0.id } ?? []) }
                                    }.font(.caption.bold()).foregroundColor(.blue)
                                }
                            }.font(.system(size: 13, weight: .medium)).foregroundColor(.white.opacity(0.4))
                        }.padding(.top, 20).padding(.bottom, 24)
                    }
                    .listRowBackground(Color.clear).listRowSeparator(.hidden).listRowInsets(EdgeInsets(top: 0, leading: 24, bottom: 0, trailing: 24))
                    
                    Section {
                        if let rows = template?.taskRows {
                            ForEach(Array(rows.enumerated()), id: \.element.id) { index, row in
                                if !isRowHidden(index: index, in: rows) {
                                    TaskListTemplateRow(
                                        row: row,
                                        index: index,
                                        allRows: rows,
                                        isSelected: selectedIDs.contains(row.id),
                                        isSearchHit: matchIDs.indices.contains(currentMatchIndex) && matchIDs[currentMatchIndex] == row.id,
                                        isFolded: foldedIDs.contains(row.id),
                                        templateID: templateID,
                                        onSelect: {
                                            if isEditing {
                                                if selectedIDs.contains(row.id) { selectedIDs.remove(row.id) } else { selectedIDs.insert(row.id) }
                                            } else { focusedRowID = row.id }
                                        },
                                        onToggleFold: { isDeep in
                                            if isDeep { toggleBranchDeep(at: index, in: rows) }
                                            else { toggleFoldSingle(rowID: row.id) }
                                        },
                                        onTextUpdate: { newText in updateNodeTitle(index: index, newText: newText) },
                                        focusedRowID: $focusedRowID
                                    )
                                    .listRowBackground(Color.clear).listRowSeparator(.hidden).listRowInsets(EdgeInsets(top: 4, leading: 20, bottom: 4, trailing: 20))
                                    .id(row.id)
                                }
                            }
                            .onMove(perform: moveRows)
                        }
                        
                        HStack {
                            Image(systemName: "plus.circle.fill").foregroundColor(.green).font(.system(size: 20))
                            TextField("在末尾添加新根节点...", text: $newNodeTitle).focused($isNewInputFocused).onSubmit { addItem() }.submitLabel(.done)
                        }.padding(16).background(RoundedRectangle(cornerRadius: 16).fill(Color.white.opacity(0.06))).overlay(RoundedRectangle(cornerRadius: 16).stroke(Color.white.opacity(0.1), lineWidth: 0.5)).listRowBackground(Color.clear).listRowSeparator(.hidden).listRowInsets(EdgeInsets(top: 12, leading: 20, bottom: 0, trailing: 20))
                    }
                    Section { Color.clear.frame(height: 200) }.listRowBackground(Color.clear)
                }
                .listStyle(.plain).scrollContentBackground(.hidden)
                .ttSearchable(text: $searchText, prompt: "查找清单项...")
                .onChange(of: searchText) { _, _ in updateMatches() }
                .onChange(of: targetScrollID) { _, id in if let id = id { withAnimation { proxy.scrollTo(id, anchor: .center) }; targetScrollID = nil } }
            }
            
            if let msg = asStore.collisionMessage {
                Text(msg).font(.system(size: 14, weight: .bold)).foregroundColor(.white).padding(.horizontal, 20).padding(.vertical, 12).background(Capsule().fill(Color.red.opacity(0.9)).shadow(radius: 10)).padding(.bottom, 100).transition(.move(edge: .bottom).combined(with: .opacity)).zIndex(1000)
            }
        }
        .ttNavigationBarTitleDisplayMode(.inline).ttToolbarBackground(.hidden, for: .navigationBar).ttToolbarColorScheme(.dark, for: .navigationBar)
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                HStack(spacing: btnSpacing) {
                    if !matchIDs.isEmpty {
                        HStack(spacing: isIPhone ? 4 : 10) {
                            Button { navigateMatch(delta: -1) } label: { Image(systemName: "chevron.up") }.foregroundColor(.blue)
                            Button { navigateMatch(delta: 1) } label: { Image(systemName: "chevron.down") }.foregroundColor(.blue)
                        }.scaleEffect(iconScale).padding(.horizontal, isIPhone ? 4 : 8).padding(.vertical, 4).background(Capsule().fill(Color.white.opacity(0.1)))
                    }

                    if isEditing {
                        HStack(spacing: btnSpacing) {
                            Button { pushUndo(); asStore.adjustBranchLevel(templateID: templateID, rootIDs: selectedIDs, delta: -1) } label: { Image(systemName: "arrow.left.to.line.compact") }.disabled(selectedIDs.isEmpty)
                            Button { pushUndo(); asStore.adjustBranchLevel(templateID: templateID, rootIDs: selectedIDs, delta: 1) } label: { Image(systemName: "arrow.right.to.line.compact") }.disabled(selectedIDs.isEmpty)
                            Button { if !selectedIDs.isEmpty { showBatchDeleteAlert = true } } label: { Image(systemName: "trash.fill").foregroundColor(selectedIDs.isEmpty ? .gray : .red) }.disabled(selectedIDs.isEmpty)
                        }.font(.system(size: isIPhone ? 18 : 24)).scaleEffect(iconScale)
                    } else {
                        HStack(spacing: innerSpacing) {
                            Button { popUndo() } label: { Image(systemName: "arrow.uturn.backward.circle.fill").foregroundColor(localUndoStack.isEmpty ? .gray.opacity(0.3) : .white) }.disabled(localUndoStack.isEmpty)
                            Button { popRedo() } label: { Image(systemName: "arrow.uturn.forward.circle.fill").foregroundColor(localRedoStack.isEmpty ? .gray.opacity(0.3) : .blue) }.disabled(localRedoStack.isEmpty)
                        }.font(.system(size: isIPhone ? 16 : 22)).scaleEffect(iconScale)

                        HStack(spacing: innerSpacing) {
                            Button { toolbarInsert(mode: .siblingEnd) } label: { Image(systemName: "plus.square.fill.on.square.fill") }.disabled(focusedRowID == nil)
                            Button { toolbarInsert(mode: .childStart) } label: { Image(systemName: "arrow.turn.down.right") }.disabled(focusedRowID == nil)
                            Button { toolbarInsert(mode: .childEnd) } label: { Image(systemName: "arrow.uturn.down.circle") }.disabled(focusedRowID == nil)
                        }.font(.system(size: isIPhone ? 18 : 24)).scaleEffect(iconScale)

                        Button { showLevelStyleSheet = true } label: { Image(systemName: "paintpalette.fill").foregroundColor(.blue) }.font(.system(size: isIPhone ? 18 : 24)).scaleEffect(iconScale)
                    }
                    
                    Button { withAnimation { if isEditing { editMode?.wrappedValue = .inactive; selectedIDs.removeAll() } else { focusedRowID = nil; isNewInputFocused = false; editMode?.wrappedValue = .active } } } label: { Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle").foregroundColor(isEditing ? .green : .white) }.font(.system(size: isIPhone ? 18 : 24)).scaleEffect(iconScale)
                    
                    if !isEditing {
                        Menu {
                            Picker("层级视图", selection: $maxDisplayLevel) {
                                Text("全部").tag(100)
                                Text("L0 (1.)").tag(0)
                                Text("L1 (a.)").tag(1)
                                Text("L2 (i.)").tag(2)
                                Text("L3 (括号)").tag(3)
                                Text("L4 (尖括号)").tag(4)
                                Text("L5 (项目符号)").tag(5)
                            }
                            .onChange(of: maxDisplayLevel) { _, newValue in applyMaxLevelFolding(newValue) }
                        } label: { Image(systemName: "line.3.horizontal.decrease.circle").foregroundColor(.orange) }.font(.system(size: isIPhone ? 16 : 20)).scaleEffect(iconScale)
                    }
                }
            }
        }
        .sheet(isPresented: $showLevelStyleSheet) {
            TTModalSheetContainer(minWidth: 860, minHeight: 720) {
                TaskListLevelStyleView(templateID: templateID)
                    .environmentObject(asStore)
            }
        }
        .alert("确认删除选中的分支？", isPresented: $showBatchDeleteAlert) { Button("取消", role: .cancel) { }; Button("集体删除", role: .destructive) { if !selectedIDs.isEmpty { pushUndo(); asStore.deleteBranches(templateID: templateID, rootIDs: selectedIDs); selectedIDs.removeAll() } } } message: { Text("系统将自动物理删除所选节点及其下属的所有子孙项。") }
        .onDisappear { localUndoStack.removeAll(); localRedoStack.removeAll() }
    }
    
    func isRowHidden(index: Int, in rows: [ArchiveRow]) -> Bool { if foldedIDs.isEmpty { return false }; let parentIndices = asStore.findParentIndices(in: rows, for: index); return parentIndices.contains { foldedIDs.contains(rows[$0].id) } }
    func toggleFoldSingle(rowID: UUID) { withAnimation(.spring(response: 0.3)) { if foldedIDs.contains(rowID) { foldedIDs.remove(rowID) } else { foldedIDs.insert(rowID) } } }
    func toggleBranchDeep(at index: Int, in rows: [ArchiveRow]) { let rootID = rows[index].id; let descendantIDs = asStore.getAllDescendantIDs(in: rows, from: index); withAnimation(.spring()) { if foldedIDs.contains(rootID) { foldedIDs.remove(rootID); descendantIDs.forEach { foldedIDs.remove($0) } } else { foldedIDs.insert(rootID); descendantIDs.forEach { foldedIDs.insert($0) } } } }
    func applyMaxLevelFolding(_ level: Int) { guard let rows = template?.taskRows else { return }; withAnimation(.spring(response: 0.35)) { foldedIDs.removeAll(); if level >= 100 { return }; for (idx, row) in rows.enumerated() { if let data = asStore.parseTaskData(row.value), data.level == level { if asStore.hasChildren(in: rows, at: idx) { foldedIDs.insert(row.id) } } } } }
    func updateMatches() { guard let rows = template?.taskRows else { return }; if searchText.isEmpty { matchIDs = []; currentMatchIndex = 0; return }; let found = rows.compactMap { row -> UUID? in if let data = asStore.parseTaskData(row.value), data.title.localizedCaseInsensitiveContains(searchText) { return row.id }; return nil }; matchIDs = found; currentMatchIndex = 0; if !found.isEmpty { asStore.expandParentsOfMatches(rows: rows, matchIDs: found, foldedIDs: &foldedIDs); targetScrollID = found.first } }
    func navigateMatch(delta: Int) { guard !matchIDs.isEmpty else { return }; currentMatchIndex = (currentMatchIndex + delta + matchIDs.count) % matchIDs.count; targetScrollID = matchIDs[currentMatchIndex] }
    enum InsertMode { case siblingEnd, childStart, childEnd }
    func toolbarInsert(mode: InsertMode) { guard let curID = focusedRowID, let rows = template?.taskRows, let idx = rows.firstIndex(where: { $0.id == curID }), let source = asStore.parseTaskData(rows[idx].value) else { return }; pushUndo(); var update = rows; let newLevel: Int; let targetIdx: Int; switch mode { case .siblingEnd: newLevel = source.level; targetIdx = asStore.findSubtreeRange(in: update, from: idx).upperBound + 1; case .childStart: newLevel = min(5, source.level + 1); targetIdx = idx + 1; case .childEnd: newLevel = min(5, source.level + 1); targetIdx = asStore.findSubtreeRange(in: update, from: idx).upperBound + 1 }; let newData = TaskRowData(title: "", isCompleted: false, level: newLevel); if let json = try? JSONEncoder().encode(newData), let s = String(data: json, encoding: .utf8) { let newID = UUID(); let newRow = ArchiveRow(id: newID, key: newID.uuidString, value: s); update.insert(newRow, at: targetIdx); asStore.saveTaskListTemplate(templateID: templateID, rows: update); DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { focusedRowID = newID } } }
    func pushUndo() { if let rows = template?.taskRows { localUndoStack.append(rows); localRedoStack.removeAll(); if localUndoStack.count > 50 { localUndoStack.removeFirst() } } }
    
    func popUndo() {
        guard let prev = localUndoStack.popLast(), let current = template?.taskRows else { return }
        localRedoStack.append(current)
        asStore.saveTaskListTemplate(templateID: templateID, rows: prev)
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        #endif
    }
    
    func popRedo() {
        guard let next = localRedoStack.popLast(), let current = template?.taskRows else { return }
        localUndoStack.append(current)
        asStore.saveTaskListTemplate(templateID: templateID, rows: next)
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
        #endif
    }
    
    func updateNodeTitle(index: Int, newText: String) { var rows = template?.taskRows ?? []; if var data = asStore.parseTaskData(rows[index].value) { data.title = newText; if let json = try? JSONEncoder().encode(data), let s = String(data: json, encoding: .utf8) { rows[index].value = s; asStore.saveTaskListTemplate(templateID: templateID, rows: rows) } } }
    func addItem() { guard !newNodeTitle.isEmpty, let rows = template?.taskRows else { return }; pushUndo(); let lastLevel = rows.last.flatMap { asStore.parseTaskData($0.value)?.level } ?? 0; let data = TaskRowData(title: newNodeTitle, isCompleted: false, level: lastLevel); let newID = UUID(); if let json = try? JSONEncoder().encode(data), let js = String(data: json, encoding: .utf8) { var update = rows; update.append(ArchiveRow(id: newID, key: newID.uuidString, value: js)); asStore.saveTaskListTemplate(templateID: templateID, rows: update); newNodeTitle = ""; isNewInputFocused = true } }
    func moveRows(from src: IndexSet, to dst: Int) { guard let rows = template?.taskRows else { return }; pushUndo(); var update = rows; update.move(fromOffsets: src, toOffset: dst); asStore.validateHierarchy(&update); asStore.saveTaskListTemplate(templateID: templateID, rows: update) }
}

// MARK: - 模板任务行组件 - v15 - 逻辑树交互增强
//
// TaskListTemplateRow
// (修改内容：
//  1. [Feature] 逻辑树折叠交互：右侧增加 + (展开一层) 和 ++ (深度展开/折叠) 按钮。
//  2. [UI] 折叠视觉增强：被折叠行显示 ... 符号，背景呈现逻辑树专属蓝色调。
//  3. [Interaction] 增大全行点击热区，支持非编辑模式下的快速聚焦。)

struct TaskListTemplateRow: View {
    let row: ArchiveRow
    let index: Int
    let allRows: [ArchiveRow]
    var isSelected: Bool
    var isSearchHit: Bool = false
    var isFolded: Bool = false
    let templateID: UUID
    var onSelect: () -> Void
    var onToggleFold: (Bool) -> Void // Bool 代表是否深度切换
    var onTextUpdate: (String) -> Void
    
    @Environment(\.editMode) private var editMode
    @EnvironmentObject var asStore: ArchiveStore
    
    @State private var localTitle: String = ""
    @State private var level: Int = 0
    
    var focusedRowID: FocusState<UUID?>.Binding
    
    var hasChildren: Bool { asStore.hasChildren(in: allRows, at: index) }
    
    var body: some View {
        let isEditingMode = editMode?.wrappedValue.isEditing == true
        let levelStyle = asStore.getLevelStyleObj(templateID: templateID, level: level)
        
        HStack(spacing: 12) {
            // 1. 层级缩进占位
            if level > 0 { Color.clear.frame(width: CGFloat(level) * 24, height: 1) }
            
            // 2. 核心内容卡片
            ZStack {
                if isEditingMode {
                    Button(action: { onSelect(); UIImpactFeedbackGenerator(style: .light).impactOccurred() }) {
                        HStack(spacing: 12) {
                            ZStack {
                                Circle().stroke(isSelected ? Color.blue : Color.white.opacity(0.2), lineWidth: 1.5).frame(width: 22, height: 22)
                                if isSelected { Image(systemName: "checkmark.circle.fill").font(.system(size: 22)).foregroundColor(.blue) }
                            }
                            Text(localTitle.isEmpty ? "未命名结构项" : localTitle).font(getFont(levelStyle)).foregroundColor(isSelected ? .white : colorFromStr(levelStyle.color).opacity(0.8)).lineLimit(1)
                            Spacer()
                            Text("L\(level)").font(.system(size: 10, weight: .bold, design: .monospaced)).foregroundColor(.blue.opacity(0.6)).padding(.horizontal, 6).padding(.vertical, 2).background(Capsule().fill(Color.blue.opacity(0.1)))
                        }
                        .padding(16).frame(maxWidth: .infinity).contentShape(Rectangle())
                    }.buttonStyle(.plain)
                } else {
                    HStack(spacing: 12) {
                        Image(systemName: "line.3.horizontal").font(.system(size: 12)).foregroundColor(.white.opacity(0.15))
                        
                        TextField("任务内容", text: $localTitle)
                            .font(getFont(levelStyle))
                            .foregroundColor(colorFromStr(levelStyle.color))
                            .focused(focusedRowID, equals: row.id)
                            .onSubmit { onTextUpdate(localTitle) }
                            .onTapGesture { focusedRowID.wrappedValue = row.id }
                        
                        if isFolded {
                            Text("...")
                                .font(.system(size: 14, weight: .bold))
                                .foregroundColor(.blue.opacity(0.6))
                                .padding(.horizontal, 6)
                                .background(Capsule().fill(Color.blue.opacity(0.1)))
                        }
                        
                        Spacer()
                        
                        // 【核心改动】：逻辑树分支交互按钮
                        if hasChildren {
                            HStack(spacing: 10) {
                                if isFolded {
                                    Button { onToggleFold(false) } label: {
                                        Image(systemName: "plus.circle")
                                            .font(.system(size: 16))
                                            .foregroundColor(.blue)
                                    }.buttonStyle(.plain)
                                }
                                
                                Button { onToggleFold(true) } label: {
                                    HStack(spacing: -8) {
                                        Image(systemName: isFolded ? "plus.circle.fill" : "minus.circle")
                                        Image(systemName: isFolded ? "plus.circle.fill" : "minus.circle")
                                            .offset(x: 4, y: 4)
                                    }
                                    .font(.system(size: 16))
                                    .foregroundColor(isFolded ? .cyan : .white.opacity(0.2))
                                }.buttonStyle(.plain)
                            }
                        }
                    }
                    .padding(16)
                    .background(RoundedRectangle(cornerRadius: 16).fill(focusedRowID.wrappedValue == row.id ? Color.white.opacity(0.08) : Color.clear))
                }
            }
            .background {
                RoundedRectangle(cornerRadius: 16)
                    .fill(isSelected && isEditingMode ? Color.blue.opacity(0.1) : (isFolded ? Color.blue.opacity(0.05) : Color.white.opacity(0.06)))
            }
            .overlay {
                RoundedRectangle(cornerRadius: 16)
                    .stroke(isSearchHit ? Color.blue : (isSelected && isEditingMode ? Color.blue.opacity(0.5) : Color.white.opacity(0.1)), lineWidth: (isSearchHit || isSelected) ? 2.0 : 0.5)
            }
        }
        .onAppear { parseData() }
        .onChange(of: row.value) { _, _ in parseData() }
    }
    
    func parseData() { if let data = asStore.parseTaskData(row.value) { self.localTitle = data.title; self.level = data.level } }
    func getFont(_ cfg: KeyStyleConfig) -> Font {
        let weight: Font.Weight = cfg.isBold ? .bold : .semibold
        let size = max(14, cfg.fontSize * 0.7)
        if let name = cfg.customFontName { return .custom(name, size: size).weight(weight) }
        switch cfg.fontDesign {
        case "rounded": return .system(size: size, weight: weight, design: .rounded)
        case "monospaced": return .system(size: size, weight: weight, design: .monospaced)
        case "serif": return .system(size: size, weight: weight, design: .serif)
        default: return .system(size: size, weight: weight, design: .default)
        }
    }
    func colorFromStr(_ s: String) -> Color {
        switch s {
        case "red": return .red; case "blue": return .blue; case "green": return .green
        case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan
        case "white": return .white; default: return .white
        }
    }
}

// MARK: - 模板使用列表视图 - v3 - 修复编译器超时
struct TemplateUsageListView: View {
    let template: ArchiveTemplate
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var renamingTable: ArchiveTable?
    @State private var newName = ""
    @State private var showRenameAlert = false
    
    var body: some View {
        NavigationStack {
            let items = asStore.getTablesByTemplate(templateID: template.id)
            
            VStack {
                if items.isEmpty {
                    VStack(spacing: 15) {
                        Image(systemName: "doc.text.magnifyingglass").font(.system(size: 50)).foregroundColor(.gray.opacity(0.3))
                        Text("没有文件使用此模板").foregroundColor(.gray)
                    }
                } else {
                    List {
                        ForEach(items, id: \.table.id) { item in
                            TemplateUsageRow(
                                item: item,
                                asStore: asStore,
                                onRename: {
                                    renamingTable = item.table
                                    newName = item.table.title
                                    showRenameAlert = true
                                }
                            )
                        }
                    }
                    .scrollContentBackground(.hidden)
                }
            }
            .background(Color.black.ignoresSafeArea())
            .navigationTitle("\"\(template.title)\" 的文件")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } }
            .alert("重命名表格", isPresented: $showRenameAlert) {
                TextField("新名称", text: $newName)
                Button("取消", role: .cancel) { }
                Button("保存") {
                    if let t = renamingTable, !newName.isEmpty {
                        // 查找 CategoryID
                        for cat in asStore.categories {
                            if cat.tables.contains(where: {$0.id == t.id}) {
                                asStore.renameTable(catID: cat.id, tableID: t.id, newName: newName)
                                break
                            }
                        }
                    }
                }
            }
        }
    }
}

// 独立的行视图
