    let item: (table: ArchiveTable, categoryName: String, categoryID: UUID)
    let asStore: ArchiveStore
    let onRename: () -> Void
    
    var body: some View {
        NavigationLink(destination: ArchiveDetailTableView(categoryID: item.categoryID, table: item.table)) {
            HStack(spacing: 12) {
                Image(systemName: "tablecells").foregroundColor(.green).font(.title2)
                VStack(alignment: .leading, spacing: 2) {
                    Text(item.table.title).font(.headline).foregroundColor(.white)
                    HStack {
                        Text(item.categoryName).font(.caption).foregroundColor(.blue).padding(2).background(Color.blue.opacity(0.1)).cornerRadius(4)
                        Text("• \(Formatters.mmDD.string(from: item.table.createdAt))").font(.caption).foregroundColor(.gray)
                    }
                }
            }
            .padding(.vertical, 4)
        }
        .listRowBackground(Color(white: 0.1))
