// MARK: - 模板行组件 - v3 - 支持编辑模式选中视觉
//
// TemplateRowView
// (修改：新增 isEditing 和 isSelected 状态支持。
//  在编辑模式下，左侧显示勾选框，内容右移，与 ArchiveTableListView 的交互体验保持一致。)

struct TemplateRowView: View {
    let template: ArchiveTemplate
    var isEditing: Bool = false
    var isSelected: Bool = false
    
    var body: some View {
        HStack(spacing: 12) {
            // 编辑模式下的勾选框
            if isEditing {
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 22, weight: .bold))
                    .foregroundColor(isSelected ? .purple : .white.opacity(0.3))
                    .transition(.move(edge: .leading).combined(with: .opacity))
            }
            
            HStack(spacing: 14) {
                // 类型图标背景
                ZStack {
                    Circle()
                        .fill(template.type == .table ? Color.purple.opacity(0.15) : Color.green.opacity(0.15))
                        .frame(width: 40, height: 40)
                    
                    Image(systemName: template.type == .table ? "tablecells" : "list.bullet.clipboard")
                        .font(.system(size: 16, weight: .bold))
                        .foregroundColor(template.type == .table ? .purple : .green)
                }
                
                VStack(alignment: .leading, spacing: 2) {
                    Text(template.title)
                        .font(.system(size: 17, weight: .bold, design: .rounded))
                        .foregroundColor(.white)
                    
                    Text(template.type == .table ? "表格结构 (\(template.keys.count))" : "清单项 (\(template.taskRows.count))")
                        .font(.system(size: 12))
                        .foregroundColor(.white.opacity(0.4))
                }
                
                Spacer()
                
                // 非编辑模式下显示箭头
                if !isEditing {
                    Image(systemName: "chevron.right")
                        .font(.system(size: 12, weight: .black))
                        .foregroundColor(.white.opacity(0.15))
                }
            }
            .padding(14)
            .background {
                RoundedRectangle(cornerRadius: 16)
                    .fill(Color.white.opacity(0.06))
            }
            .overlay {
                RoundedRectangle(cornerRadius: 16)
                    .stroke(Color.white.opacity(0.1), lineWidth: 0.5)
            }
        }
        .contentShape(Rectangle()) // 确保点击区域完整
        .animation(.spring(response: 0.3), value: isEditing)
    }
}


// MARK: - 词条编辑卡片 - v9 - 支持多选视觉状态
//
// TemplateKeyCard
// (修改：
//  1. 新增 isEditing 和 isSelected 状态。
//  2. 编辑模式下显示左侧勾选圈，禁用输入框并调整文字颜色。)

struct TemplateKeyCard: View {
    let key: String
    let config: KeyStyleConfig
    let onRename: (String) -> Void
    var onSubmit: (() -> Void)? = nil
    
    var isFocused: Bool
    var isEditing: Bool = false      // 【新增】
    var isSelected: Bool = false     // 【新增】
    
    @Environment(\.editMode) private var editMode
    
    var body: some View {
        HStack(spacing: 12) {
            // 1. 编辑模式勾选圈
            if isEditing {
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 22, weight: .bold))
                    .foregroundColor(isSelected ? .green : .white.opacity(0.3))
                    .transition(.move(edge: .leading).combined(with: .opacity))
            }
            
            // 2. 输入框区域
            HStack {
                TextField("词条名", text: Binding(get: { key }, set: { onRename($0) }))
                    .font(getKeyFont(config: config))
                    .foregroundColor(isEditing ? .gray : colorFromStr(config.color)) // 编辑模式变灰
                    .submitLabel(.next)
                    .disabled(isEditing) // 编辑模式禁止输入
                    .onSubmit { onSubmit?() }
                
                Spacer()
                
                // 聚焦时的笔图标 (仅非编辑模式显示)
                if isFocused && !isEditing {
                    Image(systemName: "pencil.and.outline")
                        .font(.caption2)
                        .foregroundColor(.blue.opacity(0.8))
                        .transition(.opacity)
                }
            }
            .padding(16)
            .background(RoundedRectangle(cornerRadius: 16).fill(Color.white.opacity(isFocused ? 0.12 : 0.06)))
            .overlay(RoundedRectangle(cornerRadius: 16).stroke((isFocused && !isEditing) ? Color.blue.opacity(0.5) : Color.white.opacity(0.1), lineWidth: 0.5))
        }
        .animation(.spring(response: 0.3), value: isEditing) // 平滑过渡
    }
    
    private func getKeyFont(config: KeyStyleConfig) -> Font {
        let size = max(16, config.fontSize * 0.8); let weight: Font.Weight = config.isBold ? .bold : .semibold
        if let name = config.customFontName { return .custom(name, size: size).weight(weight) }
        switch config.fontDesign {
        case "rounded": return .system(size: size, weight: weight, design: .rounded)
        case "monospaced": return .system(size: size, weight: weight, design: .monospaced)
        case "serif": return .system(size: size, weight: weight, design: .serif)
        default: return .system(size: size, weight: weight, design: .default)
        }
    }
    
    private func colorFromStr(_ s: String) -> Color {
        switch s {
        case "white": return .white; case "red": return .red; case "orange": return .orange; case "yellow": return .yellow; case "green": return .green; case "blue": return .blue; case "purple": return .purple; default: return .white
        }
    }
}


// MARK: - 预设文字编辑器 - v1 - 新增
struct PresetEditorView: View {
