// MARK: - 日历时间轴列组件 - v28 - 适配 macOS 震动反馈

struct CalendarDayColumn: View {
    let date: Date
    let width: CGFloat
    let height: CGFloat
    let enableDrag: Bool
    let enableEdit: Bool
    let isDrafting: Bool
    
    @EnvironmentObject var cs: CalendarStore
    @State private var editingEvent: CalendarEventWrapper?
    
    var events: [CalendarEventWrapper] {
        cs.getEvents(for: date).filter { !$0.isAllDay }
    }
    
    var body: some View {
        ZStack(alignment: .topLeading) {
            TimelineGridBackground(width: width, totalHeight: height)
            
            ForEach(events) { event in
                CalendarEventBlock(
                    event: event,
                    dayStart: Calendar.current.startOfDay(for: date),
                    totalHeight: height,
                    columnWidth: width
                )
                .opacity(isDrafting ? 0.3 : 1.0)
                .onLongPressGesture {
                    if enableEdit && !isDrafting {
                        #if !os(macOS)
                        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
                        #endif
                    }
                }
            }
        }
        .frame(width: width, height: height)
        .clipped()
    }
}

  // MARK: - 日历事件块 - V1
  struct CalendarEventBlock: View {
      let event: CalendarEventWrapper
      let dayStart: Date
      let totalHeight: CGFloat
      let columnWidth: CGFloat
      
      var body: some View {
          let frame = calculateFrame()
          if frame.height > 0 {
              RoundedRectangle(cornerRadius: 6)
                  .fill(event.color.opacity(0.8))
                  .overlay(
                      VStack(alignment: .leading, spacing: 0) {
                          Text(event.title)
                              .font(.system(size: 11, weight: .bold))
                              .foregroundColor(.white)
                              .lineLimit(1)
                          if frame.height > 30 {
                              Text(Formatters.hhMM.string(from: event.startDate))
                                  .font(.system(size: 9))
                                  .foregroundColor(.white.opacity(0.8))
                          }
                          Spacer()
                      }
                      .padding(4)
                      , alignment: .topLeading
                  )
                  .frame(width: columnWidth - 4, height: frame.height)
                  .offset(y: frame.top)
                  .padding(.horizontal, 2)
          }
      }
      
      func calculateFrame() -> (top: CGFloat, height: CGFloat) {
          let start = max(event.startDate, dayStart)
          let end = min(event.endDate, dayStart.addingTimeInterval(24*3600))
          
          let startMins = start.timeIntervalSince(dayStart) / 60.0
          let durationMins = end.timeIntervalSince(start) / 60.0
          
          let scale = totalHeight / (24 * 60)
          return (CGFloat(startMins) * scale, max(10, CGFloat(durationMins) * scale))
      }
  }

// MARK: - 档案主页 - v79 - 适配 macOS 下的震动反馈与功能恢复

struct ArchivesView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @EnvironmentObject var teachingStore: TeachingStore
    
    @State private var showingAddCat = false
    @State private var newCatName = ""
    @State private var renamingCategory: ArchiveCategory?
    @State private var renameText = ""
    @State private var showRenameAlert = false
    
    @State private var selectedCategoryIDs = Set<UUID>()
    @State private var showBatchDeleteAlert = false
    @Environment(\.editMode) private var editMode
    
    @State private var showingImportPicker = false
    @State private var navPath = NavigationPath()
    
    enum ArchiveRoute: Hashable { case templateManager, autoFill, smartFolder, recycleBin, folder(UUID) }

    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var isEditing: Bool { editMode?.wrappedValue.isEditing == true }

    var body: some View {
        NavigationStack(path: $navPath) {
            ZStack(alignment: .bottom) {
                GeometryReader { geo in
                    MainBackgroundView(themeColor: themeColor)
                        .frame(height: UIScreen.mainSafe.bounds.height)
                        .offset(y: -geo.frame(in: .global).minY)
                }
                .ignoresSafeArea()
                
                VStack(spacing: 0) {
                    List {
                        Section {
                            HStack(spacing: 0) {
                                Button { navPath.append(ArchiveRoute.templateManager) } label: { SystemIconButton(title: "模板管理", icon: "doc.badge.plus", color: .purple) }
                                if asStore.getAutoFill() != nil {
                                    Button { navPath.append(ArchiveRoute.autoFill) } label: { SystemIconButton(title: "自动填写", icon: "wand.and.stars", color: .blue) }
                                }
                                Button { navPath.append(ArchiveRoute.smartFolder) } label: { SystemIconButton(title: "智能聚合", icon: "doc.text.magnifyingglass", color: .orange) }
                                if asStore.getRecycleBin() != nil {
                                    Button { navPath.append(ArchiveRoute.recycleBin) } label: { SystemIconButton(title: "删除回收", icon: "trash.fill", color: .red) }
                                }
                            }
                            .buttonStyle(.plain)
                            .listRowInsets(EdgeInsets(top: 10, leading: 0, bottom: 10, trailing: 0))
                            .listRowBackground(Color.clear)
                            .listRowSeparator(.hidden)
                        }
                        .deleteDisabled(true)
                        .moveDisabled(true)
                        
                        Section {
                            ForEach(asStore.userCategories) { cat in
                                ZStack {
                                    if !isEditing {
                                        Button { navPath.append(ArchiveRoute.folder(cat.id)) } label: {
                                            CategoryCardRow(category: cat)
                                        }
                                        .buttonStyle(.plain)
                                    } else {
                                        HStack(spacing: 12) {
                                            Image(systemName: selectedCategoryIDs.contains(cat.id) ? "checkmark.circle.fill" : "circle")
                                                .font(.system(size: 22, weight: .bold))
                                                .foregroundColor(selectedCategoryIDs.contains(cat.id) ? .indigo : .white.opacity(0.3))
                                            
                                            CategoryCardRow(category: cat)
                                        }
                                        .contentShape(Rectangle())
                                        .onTapGesture {
                                            toggleSelection(cat.id)
                                            #if !os(macOS)
                                            UIImpactFeedbackGenerator(style: .light).impactOccurred()
                                            #endif
                                        }
                                    }
                                }
                                .listRowInsets(EdgeInsets(top: 8, leading: 24, bottom: 8, trailing: 24))
                                .listRowBackground(Color.clear)
                                .listRowSeparator(.hidden)
                                .contextMenu {
                                    if !isEditing && cat.id != ArchiveStore.SystemIDs.importFolder {
                                        Button { renamingCategory = cat; renameText = cat.title; showRenameAlert = true } label: { Label("重命名", systemImage: "pencil") }
                                        Button(role: .destructive) { asStore.deleteCategory(id: cat.id) } label: { Label("删除分类", systemImage: "trash") }
                                    }
                                }
                                .swipeActions(edge: .trailing) {
                                    if !isEditing && cat.id != ArchiveStore.SystemIDs.importFolder {
                                        Button(role: .destructive) { asStore.deleteCategory(id: cat.id) } label: { Label("删除", systemImage: "trash") }
                                        Button { renamingCategory = cat; renameText = cat.title; showRenameAlert = true } label: { Label("重命名", systemImage: "pencil") }.tint(.blue)
                                    }
                                }
                            }
                            .onMove(perform: moveCategory)
                            
                            Color.clear.frame(height: 150)
                                .listRowBackground(Color.clear)
                                .listRowSeparator(.hidden)
                                .deleteDisabled(true)
                                .moveDisabled(true)
                        }
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)
                }
                
                if isEditing && !selectedCategoryIDs.isEmpty {
                    VStack {
                        Spacer()
                        HStack {
                            Button(role: .destructive) { showBatchDeleteAlert = true } label: {
                                Image(systemName: "trash.fill").font(.title2)
                            }.foregroundColor(.red)
                            Spacer()
                            Text("已选 \(selectedCategoryIDs.count) 个目录").font(.system(size: 13, weight: .bold, design: .rounded))
                            Spacer()
                            Image(systemName: "trash.fill").font(.title2).opacity(0)
                        }
                        .padding(.horizontal, 32).padding(.vertical, 16)
                        .background(.ultraThinMaterial).clipShape(Capsule())
                        .overlay(Capsule().stroke(Color.white.opacity(0.12), lineWidth: 0.5))
                        .padding(.horizontal, 24).padding(.bottom, 100)
                    }
                    .transition(.move(edge: .bottom))
                }
            }
            .navigationTitle("")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItemGroup(placement: .topBarTrailing) {
                    if !isEditing {
                        Menu {
                            Picker("排序规则", selection: $asStore.categorySortOption) {
                                ForEach(ArchiveStore.CategorySortOption.allCases, id: \.self) { option in
                                    Text(option.rawValue).tag(option)
                                }
                            }
                        } label: {
                            Image(systemName: "arrow.up.arrow.down.circle")
                                .font(.system(size: 20))
                                .foregroundColor(asStore.categorySortOption == .custom ? .orange : .white)
                        }
                    }
                    
                    Button {
                        withAnimation {
                            if isEditing {
                                editMode?.wrappedValue = .inactive
                                selectedCategoryIDs.removeAll()
                            } else {
                                editMode?.wrappedValue = .active
                            }
                        }
                    } label: {
                        Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle")
                            .font(.system(size: 20))
                            .foregroundColor(isEditing ? .green : .white)
                    }
                    
                    if !isEditing {
                        Button { showingAddCat = true } label: {
                            Image(systemName: "plus.circle.fill")
                                .font(.system(size: 20))
                                .foregroundColor(.white)
                        }
                    }
                }
            }
            .navigationDestination(for: ArchiveRoute.self) { route in
                switch route {
                case .templateManager: TemplateManagerView()
                case .autoFill: if let cat = asStore.getAutoFill() { ArchiveTableListView(category: cat, isRecycleBin: false) }
                case .smartFolder: SmartFolderView()
                case .recycleBin: if let cat = asStore.getRecycleBin() { ArchiveTableListView(category: cat, isRecycleBin: true) }
                case .folder(let id): if let cat = asStore.categories.first(where: { $0.id == id }) { ArchiveTableListView(category: cat, isRecycleBin: false) }
                }
            }
            .alert("新建文件夹", isPresented: $showingAddCat) {
                TextField("名称", text: $newCatName)
                Button("取消", role: .cancel) { newCatName = "" }
                Button("创建") { if !newCatName.isEmpty { asStore.addCategory(title: newCatName); newCatName = "" } }
            }
            .alert("重命名分类", isPresented: $showRenameAlert) {
                TextField("新名称", text: $renameText)
                Button("取消", role: .cancel) { }
                Button("保存") { if let cat = renamingCategory, !renameText.isEmpty { asStore.renameCategory(cat, newName: renameText) } }
            }
            .alert("确认删除选中的文件夹？", isPresented: $showBatchDeleteAlert) {
                Button("取消", role: .cancel) { }
                Button("确认删除", role: .destructive) {
                    for id in selectedCategoryIDs { asStore.deleteCategory(id: id) }
                    selectedCategoryIDs.removeAll()
                    editMode?.wrappedValue = .inactive
                }
            } message: {
                Text("删除文件夹将同步删除其内部的所有表格文件，此操作不可撤销。")
            }
        }
    }
    
    func toggleSelection(_ id: UUID) {
        let protectedIDs = [ArchiveStore.SystemIDs.recycleBin, ArchiveStore.SystemIDs.autoFill, ArchiveStore.SystemIDs.importFolder]
        if protectedIDs.contains(id) { return }
        
        if selectedCategoryIDs.contains(id) { selectedCategoryIDs.remove(id) }
        else { selectedCategoryIDs.insert(id) }
    }
    
    func moveCategory(from src: IndexSet, to dst: Int) {
        guard asStore.categorySortOption == .custom else { return }
        asStore.moveCategory(from: src, to: dst)
    }
}

// MARK: - 口算训练视图 - v6 - 适配 macOS 震动反馈屏蔽

struct MentalMathView: View {
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    
    @State private var num1: Int = 0
    @State private var num2: Int = 0
    @State private var userInput: String = ""
    @State private var totalSolved: Int = 0
    @State private var correctCount: Int = 0
    @State private var usedNumbers: Set<Int> = []
    @State private var showSuccessFeedback: Bool = false
    @FocusState private var isTextFieldFocused: Bool
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        return GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore) >= 80 ? .yellow : .green
    }
    
    var body: some View {
        ZStack {
            MainBackgroundView(themeColor: themeColor).ignoresSafeArea()
            
            VStack(spacing: 0) {
                // 1. 顶部统计
                HStack(spacing: 16) {
                    statCard(title: I18n.t(.math_solved), value: "\(totalSolved)", color: .gray)
                    statCard(title: I18n.t(.math_correct), value: "\(correctCount)", color: .green)
                }
                .padding(.horizontal, 24).padding(.top, 10)
                
                // 【166号修正】：间距从 50 减至 10，上移 40px
                Spacer().frame(height: 10)
                
                // 2. 题目显示
                HStack(spacing: 15) {
                    numberBox(value: num1)
                    Text("×").font(.system(size: 32, weight: .black)).foregroundColor(.orange)
                    numberBox(value: num2)
                }
                // 【166号修正】：间距从 40 减至 20，输入框相对再上移 20px（总计 60px）
                .padding(.bottom, 20)
                
                // 3. 输入区
                VStack(spacing: 12) {
                    TextField(I18n.t(.math_input), text: $userInput)
                        .focused($isTextFieldFocused)
                        .keyboardType(.numberPad)
                        .font(.system(size: 54, weight: .black, design: .monospaced))
                        .multilineTextAlignment(.center)
                        .padding(.vertical, 20)
                        .background(RoundedRectangle(cornerRadius: 24).fill(Color.white.opacity(0.08)))
                        .overlay(RoundedRectangle(cornerRadius: 24).stroke(Color.white.opacity(0.15), lineWidth: 1))
                        .onChange(of: userInput) { _, _ in checkAnswer() }
                    
                    Text(I18n.t(.math_hint)).font(.caption).foregroundColor(.white.opacity(0.3))
                }
                .padding(.horizontal, 30)
                
                Spacer()
                
                Button(I18n.t(.math_reset)) {
                    totalSolved = 0; correctCount = 0; usedNumbers.removeAll(); generateNewProblem()
                }
                .font(.caption).foregroundColor(.red.opacity(0.4)).padding(.bottom, 20)
            }
            .ignoresSafeArea(.keyboard, edges: .bottom)
            
            if showSuccessFeedback {
                ZStack {
                    Color.black.opacity(0.6).ignoresSafeArea()
                    VStack(spacing: 15) {
                        Image(systemName: "checkmark.seal.fill").font(.system(size: 100)).foregroundColor(.green)
                        Text(I18n.t(.math_success)).font(.system(size: 40, weight: .black, design: .rounded)).foregroundColor(.green)
                    }
                    .transition(.scale.combined(with: .opacity))
                }.zIndex(100)
            }
        }
        .onAppear { generateNewProblem(); isTextFieldFocused = true }
    }
    
    private func statCard(title: String, value: String, color: Color) -> some View {
        VStack(spacing: 2) { Text(title).font(.system(size: 11, weight: .bold)).foregroundColor(.white.opacity(0.5)); Text(value).font(.system(size: 24, weight: .black, design: .rounded)).foregroundColor(color) }
        .frame(maxWidth: .infinity).padding(.vertical, 10).background(RoundedRectangle(cornerRadius: 14).fill(Color.white.opacity(0.05)))
    }
    
    private func numberBox(value: Int) -> some View {
        Text("\(value)").font(.system(size: 48, weight: .black, design: .monospaced)).foregroundColor(.white).frame(width: 100, height: 100).background(RoundedRectangle(cornerRadius: 22).fill(Color.white.opacity(0.12)))
    }
    
    private func generateNewProblem() {
        num1 = getValidRandomNumber(); num2 = getValidRandomNumber(); userInput = ""
    }
    
    private func getValidRandomNumber() -> Int {
        var attempts = 0
        while attempts < 100 {
            let n = Int.random(in: 21...99)
            let lastDigit = n % 10
            if lastDigit > 1 && !usedNumbers.contains(n) {
                usedNumbers.insert(n)
                return n
            }
            attempts += 1
        }
        usedNumbers.removeAll()
        return Int.random(in: 22...99)
    }
    
    private func checkAnswer() {
        guard let val = Int(userInput) else { return }
        if val == (num1 * num2) {
            correctCount += 1
            totalSolved += 1
            
            #if !os(macOS)
            UIImpactFeedbackGenerator(style: .heavy).impactOccurred()
            #endif
            
            withAnimation(.spring()) {
                showSuccessFeedback = true
            }
            
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                withAnimation {
                    showSuccessFeedback = false
                    generateNewProblem()
                }
            }
        }
    }
}

// MARK: - 内部导入选择器 - v1 - 自动过滤与单击导入
//
// InternalImportPicker
// (逻辑：
//  1. 扫描 CloudFileManager.shared.getImportDir() 目录。
//  2. 仅显示表头为“表格/词条名/清单/任务项”的 CSV 文件。
//  3. 点击即触发导入并自动物理移动原文件。)

struct InternalImportPicker: View {
    @EnvironmentObject var asStore: ArchiveStore
    @Binding var isPresented: Bool
    
    @State private var availableFiles: [URL] = []
    
    var body: some View {
        NavigationStack {
            ZStack {
                Color.black.ignoresSafeArea()
                
                if availableFiles.isEmpty {
                    VStack(spacing: 20) {
                        Image(systemName: "tray.and.arrow.down").font(.system(size: 60)).foregroundColor(.gray.opacity(0.3))
                        Text("没有可导入的文件").font(.headline).foregroundColor(.white.opacity(0.6))
                        Text("请将符合格式的 CSV 文件放入\niCloud Drive/李知本时间管理/导入")
                            .font(.caption).foregroundColor(.gray).multilineTextAlignment(.center)
                    }
                } else {
                    List {
                        Section(header: Text("检测到符合条件的文件")) {
                            ForEach(availableFiles, id: \.self) { url in
                                Button {
                                    asStore.importInternalFile(url: url)
                                    isPresented = false
                                } label: {
                                    HStack {
                                        Image(systemName: "doc.text.fill").foregroundColor(.blue)
                                        Text(url.lastPathComponent).foregroundColor(.white)
                                        Spacer()
                                        Image(systemName: "plus.circle").foregroundColor(.green)
                                    }
                                }
                                .listRowBackground(Color(white: 0.12))
                            }
                        }
                    }
                    .scrollContentBackground(.hidden)
                }
            }
            .navigationTitle("内部导入")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { isPresented = false }
                }
            }
            .onAppear {
                refreshFileList()
            }
        }
        .presentationDetents([.medium, .large])
    }
    
    private func refreshFileList() {
        let allCSV = asStore.getImportableFiles()
        // 进行预筛选：只有符合四类表头的才展示
        self.availableFiles = allCSV.filter { url in
            if let content = try? String(contentsOf: url, encoding: .utf8), !content.isEmpty {
                let firstLine = content.components(separatedBy: .newlines).first ?? ""
                let header = firstLine.components(separatedBy: ",").first?.trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "\u{FEFF}", with: "") ?? ""
                return ["表格", "词条名", "清单", "任务项"].contains(header)
            }
            return false
        }
    }
}



  // MARK: - 任务详情视图 - v1 - 新增
  //
  // TaskDetailView
  // (功能：展示层级任务，支持添加子任务、勾选联动。)

  struct TaskDetailView: View {
      let tableID: UUID
      let title: String
      @EnvironmentObject var asStore: ArchiveStore
      @State private var showingAddNode = false
      @State private var newTaskName = ""
      @State private var parentIDForAdd: UUID? = nil
      
      var table: ArchiveTable? { asStore.taskLists.first(where: { $0.id == tableID }) }
      
      var body: some View {
          VStack {
              if let table = table {
                  List {
                      // 递归构建树形结构
                      // 这里为了简化，先找出所有根节点 (parentID == nil)
                      let roots = table.rows.filter {
                          guard let d = asStore.parseTaskData($0.value) else { return false }
                          return d.parentID == nil
                      }
                      
                      ForEach(roots, id: \.key) { row in
                          TaskNodeRow(table: table, row: row, level: 0, onAdd: { pid in
                              parentIDForAdd = pid; showingAddNode = true
                          })
                      }
                  }
                  .listStyle(.plain)
                  .scrollContentBackground(.hidden)
              } else {
                  Text("清单不存在").foregroundColor(.gray)
              }
          }
          
          
          .background(Color.black.ignoresSafeArea())
          .navigationTitle(title)
          .toolbar {
              ToolbarItem(placement: .primaryAction) {
                  Button { parentIDForAdd = nil; showingAddNode = true } label: { Image(systemName: "plus") }
              }
          }
          
          
          
          .alert("添加任务", isPresented: $showingAddNode) {
              TextField("任务内容", text: $newTaskName)
              Button("取消", role: .cancel) { newTaskName = "" }
              Button("添加") {
                  if !newTaskName.isEmpty {
                      asStore.addTaskNode(tableID: tableID, title: newTaskName, parentID: parentIDForAdd)
                      newTaskName = ""
                  }
              }
          }
      }
  }


// MARK: - 任务清单管理视图 - v2 - 增加重命名功能
//
// TaskListManagerView
// (修改：
//  1. 列表项增加 .contextMenu，提供重命名和删除入口。
//  2. 增加重命名弹窗逻辑，通过 update list title 并 saveTaskList 实现改名。)

struct TaskListManagerView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    @State private var showingAdd = false
    @State private var newName = ""
    
    // 【新增】重命名状态
    @State private var renamingList: ArchiveTable?
    @State private var renameText = ""
    @State private var showRenameAlert = false
    
    var body: some View {
        NavigationStack {
            List {
                ForEach(asStore.taskLists) { list in
                    NavigationLink(destination: TaskDetailView(tableID: list.id, title: list.title)) {
                        HStack {
                            Image(systemName: "list.bullet.clipboard").foregroundColor(.green)
                            Text(list.title).foregroundColor(.white)
                        }
                    }
                    .listRowBackground(Color(white: 0.1))
                    // 【新增】长按菜单
                    .contextMenu {
                        Button {
                            renamingList = list
                            renameText = list.title
                            showRenameAlert = true
                        } label: {
                            Label("重命名", systemImage: "pencil")
                        }
                        
                        Button(role: .destructive) {
                            asStore.deleteTaskList(id: list.id)
                        } label: {
                            Label("删除", systemImage: "trash")
                        }
                    }
                    .swipeActions(edge: .trailing) {
                        Button(role: .destructive) { asStore.deleteTaskList(id: list.id) } label: { Label("删除", systemImage: "trash") }
                    }
                }
            }
            .scrollContentBackground(.hidden)
            .background(Color.black.ignoresSafeArea())
            .navigationTitle("任务清单库")
            .toolbar {
                ToolbarItem(placement: .primaryAction) { Button { showingAdd = true } label: { Image(systemName: "plus") } }
                ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } }
            }
            .alert("新建清单", isPresented: $showingAdd) {
                TextField("名称", text: $newName)
                Button("取消", role: .cancel) { newName = "" }
                Button("创建") {
                    if !newName.isEmpty { asStore.addTaskList(title: newName); newName = "" }
                }
            }
            // 【新增】重命名弹窗
            .alert("重命名清单", isPresented: $showRenameAlert) {
                TextField("新名称", text: $renameText)
                Button("取消", role: .cancel) { }
                Button("保存") {
                    if let list = renamingList, !renameText.isEmpty {
                        var newList = list
                        newList.title = renameText
                        asStore.saveTaskList(newList)
                    }
                }
            }
        }
    }
}


  // MARK: - 递归行组件 - V1
  struct TaskNodeRow: View {
      let table: ArchiveTable
      let row: ArchiveRow
      let level: Int
      let onAdd: (UUID) -> Void
      @EnvironmentObject var asStore: ArchiveStore
      
      var body: some View {
          let data = asStore.parseTaskData(row.value)
          let isDone = data?.isCompleted ?? false
          let title = data?.title ?? "Unknown"
          let myID = UUID(uuidString: row.key)
          
          // 查找子节点
          let children = table.rows.filter {
              guard let d = asStore.parseTaskData($0.value) else { return false }
              return d.parentID == myID
          }
          
          Group {
              HStack {
                  // 缩进
                  Color.clear.frame(width: CGFloat(level * 20), height: 1)
                  
                  Button {
                      asStore.toggleTaskNode(tableID: table.id, nodeID: row.key)
                  } label: {
                      Image(systemName: isDone ? "checkmark.square.fill" : "square")
                          .foregroundColor(isDone ? .green : .gray)
                          .font(.title3)
                  }
                  .buttonStyle(.plain)
                  
                  Text(title)
                      .strikethrough(isDone, color: .gray)
                      .foregroundColor(isDone ? .gray : .white)
                  
                  Spacer()
                  
                  Button {
                      if let mid = myID { onAdd(mid) }
                  } label: {
                      Image(systemName: "plus.circle").foregroundColor(.blue)
                  }
                  .buttonStyle(.plain)
              }
              .listRowBackground(Color(white: 0.1))
              .listRowSeparator(.hidden)
              
              // 递归渲染子节点
              ForEach(children, id: \.key) { child in
                  TaskNodeRow(table: table, row: child, level: level + 1, onAdd: onAdd)
              }
          }
      }
  }


