// MARK: - 专门处理未匹配文件的视图 - v3 - 修复算分接口调用
//
// UnmatchedTablesView
// (修改内容：修正 themeColor 计算属性，通过 getRecordsForDisplay 传入切片后的记录数组以适配新接口。)

struct UnmatchedTablesView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        // 【核心修复】适配新接口，传入切片后的记录数据
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var body: some View {
        ZStack {
            GeometryReader { geo in
                MainBackgroundView(themeColor: themeColor)
                    .frame(height: UIScreen.mainSafe.bounds.height)
                    .offset(y: -geo.frame(in: .global).minY)
            }
            .ignoresSafeArea()
            
            List {
                if asStore.unmatchedTables.isEmpty {
                    VStack(spacing: 20) {
                        Spacer().frame(height: 50)
                        Image(systemName: "checkmark.circle").font(.system(size: 60)).foregroundColor(.gray.opacity(0.3))
                        Text("暂无未匹配文件").foregroundColor(.gray)
                    }
                    .frame(maxWidth: .infinity)
                    .listRowBackground(Color.clear)
                    .listRowSeparator(.hidden)
                } else {
                    ForEach(asStore.unmatchedTables) { table in
                        VStack(alignment: .leading) {
                            Text(table.title).font(.headline).foregroundColor(.red)
                            Text("包含Keys: \(table.rows.map { $0.key }.joined(separator: ", "))")
                                .font(.caption).foregroundColor(.gray).lineLimit(2)
                            
                            Menu("选择匹配的模板...") {
                                ForEach(asStore.templates) { template in
                                    Button(template.title) {
                                        asStore.convertUnmatchedTable(tableID: table.id, templateID: template.id)
                                    }
                                }
                            }
                            .font(.caption).padding(.top, 4)
                        }
                        .padding(.vertical, 8)
                        .listRowBackground(Color.clear)
                        .listRowSeparator(.hidden)
                        .swipeActions(edge: .trailing) {
                            Button(role: .destructive) {
                                if let idx = asStore.unmatchedTables.firstIndex(of: table) {
                                    asStore.deleteUnmatchedTable(at: IndexSet(integer: idx))
                                }
                            } label: { Label("删除", systemImage: "trash") }
                        }
                    }
                }
            }
            .listStyle(.plain)
            .scrollContentBackground(.hidden)
        }
        .navigationTitle("待处理导入文件")
        .ttNavigationBarTitleDisplayMode(.inline)
        .ttToolbarBackground(.hidden, for: .navigationBar)
        .ttToolbarColorScheme(.dark, for: .navigationBar)
    }
}


