// MARK: - ArchiveTableListView - v66 - 修复 Mac 多选布局收缩，加固点选稳定性

struct ArchiveTableListView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    
    let category: ArchiveCategory
    var isRecycleBin: Bool = false
    
    @State private var selectedTableIDs = Set<UUID>()
    @Environment(\.editMode) var editMode
    @State private var showingCreateSheet = false
    @State private var showingHistory = false
    @State private var selectedTableID_History: UUID? = nil
    @State private var showingMoveSheet = false
    @State private var renamingTable: ArchiveTable? = nil
    @State private var newTableName = ""
    @State private var showRenameAlert = false
    @State private var showDuplicateAlert = false
    @State private var showEmptyTrashAlert = false
    @State private var showingTemplatePicker = false
    @State private var tableToChangeTemplate: ArchiveTable? = nil
    @State private var searchText: String = ""

    var isAutoFill: Bool { category.title == "自动填写" }
    var isEditing: Bool { editMode?.wrappedValue.isEditing ?? false }

    var sortedTables: [ArchiveTable] {
        let base = asStore.categories.first(where: { $0.id == category.id })?.tables ?? []
        let filtered = searchText.isEmpty ? base : base.filter { $0.title.localizedCaseInsensitiveContains(searchText) }
        return filtered.sorted { t1, t2 in
            if t1.type != t2.type { return t1.type == .taskList }
            switch asStore.tableSortOption {
            case .nameAsc: return t1.title.localizedStandardCompare(t2.title) == .orderedAscending
            case .nameDesc: return t1.title.localizedStandardCompare(t2.title) == .orderedDescending
            case .timeAsc: return t1.createdAt < t2.createdAt
            case .timeDesc: return t1.createdAt > t2.createdAt
            }
        }
    }
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var body: some View {
        ZStack {
            GeometryReader { geo in MainBackgroundView(themeColor: themeColor).frame(height: UIScreen.mainSafe.bounds.height).offset(y: -geo.frame(in: .global).minY) }.ignoresSafeArea()
            VStack(spacing: 0) {
                if sortedTables.isEmpty && searchText.isEmpty { emptyStateView }
                else {
                    List {
                        Color.clear.frame(height: 10).listRowBackground(Color.clear).listRowSeparator(.hidden)
                        ForEach(sortedTables) { table in
                            ZStack {
                                if !isEditing {
                                    NavigationLink(destination: destinationView(for: table)) {
                                        EmptyView()
                                    }
                                    .opacity(0)
                                }
                                
                                TableRowView(
                                    table: table,
                                    isRecycleBin: isRecycleBin,
                                    isAutoFill: isAutoFill,
                                    isSelected: selectedTableIDs.contains(table.id),
                                    asStore: asStore,
                                    categoryID: category.id,
                                    isEditing: isEditing,
                                    onRestore: { asStore.restoreTable(tableID: table.id) },
                                    onDelete: { if isRecycleBin { asStore.permanentDeleteTable(tableID: table.id) } else { asStore.softDeleteTable(tableID: table.id, categoryID: category.id) } },
                                    onHistory: { selectedTableID_History = table.id; showingHistory = true },
                                    onRename: { renamingTable = table; newTableName = table.title; showRenameAlert = true },
                                    onMove: { selectedTableIDs = [table.id]; showingMoveSheet = true },
                                    onChangeTemplate: { tableToChangeTemplate = table; showingTemplatePicker = true },
                                    onToggleSelection: { toggleSelection(for: table.id) }
                                )
                            }
                            .listRowInsets(EdgeInsets(top: 6, leading: 20, bottom: 6, trailing: 20))
                            .listRowBackground(Color.clear)
                            .listRowSeparator(.hidden)
                        }
                        Color.clear.frame(height: 150).listRowBackground(Color.clear).listRowSeparator(.hidden)
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)
                    // 【366号核心修正】：物理移除 Mac 上的安全区忽略，防止多选时宽度坍塌
                }
            }
            if isEditing && !selectedTableIDs.isEmpty { VStack { Spacer(); bottomActionMenu } }
        }
        .navigationTitle(category.title)
        .ttSearchable(text: $searchText, prompt: "搜索文件名...")
        .toolbar { toolbarContent }
        .sheet(isPresented: $showingCreateSheet) {
            TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                CreateTableSheet(categoryID: category.id)
            }
        }
        .sheet(isPresented: $showingHistory) {
            if let id = selectedTableID_History {
                TTModalSheetContainer(minWidth: 900, minHeight: 680) {
                    SingleTableHistoryView(tableID: id)
                }
            }
        }
        .sheet(isPresented: $showingMoveSheet) {
            TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                MoveDestinationSheet(currentCategoryID: category.id) {
                    asStore.moveTables(tableIDs: selectedTableIDs, from: category.id, to: $0)
                    selectedTableIDs.removeAll()
                    editMode?.wrappedValue = .inactive
                }
            }
        }
        .sheet(isPresented: $showingTemplatePicker) {
            if let t = tableToChangeTemplate {
                TTModalSheetContainer(minWidth: 860, minHeight: 720) {
                    TemplatePickerSheet(currentTable: t, categoryID: category.id).environmentObject(asStore)
                }
            }
        }
        .alert("重命名表格", isPresented: $showRenameAlert) { TextField("新名称", text: $newTableName); Button("取消", role: .cancel) { }; Button("保存") { validateAndRename() } }
        .alert("名称重复", isPresented: $showDuplicateAlert) { Button("确定", role: .cancel) { DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { showRenameAlert = true } } } message: { Text("当前文件夹下已存在同名文件。") }
        .alert("清空回收站", isPresented: $showEmptyTrashAlert) { Button("取消", role: .cancel) { }; Button("确认清空", role: .destructive) { asStore.emptyRecycleBin() } } message: { Text("此操作将永久删除。") }
        .onChange(of: isEditing) { _, nv in if !nv { selectedTableIDs.removeAll() } }
    }
    
    @ViewBuilder
    private func destinationView(for table: ArchiveTable) -> some View {
        if table.title == "上课收集" {
            HarvestWorkbenchView(table: table).environmentObject(asStore)
        } else {
            ArchiveDetailTableView(categoryID: category.id, table: table).environmentObject(asStore)
        }
    }
    
    var toolbarContent: some ToolbarContent { ToolbarItem(placement: .primaryAction) { HStack(spacing: 28) { if isRecycleBin && !sortedTables.isEmpty { Button(role: .destructive) { showEmptyTrashAlert = true } label: { Text("清空").foregroundColor(.red).font(.subheadline.bold()) } }; if !isEditing { Menu { Picker("排序方式", selection: $asStore.tableSortOption) { ForEach(ArchiveStore.TableSortOption.allCases, id: \.self) { Text($0.rawValue).tag($0) } } } label: { Image(systemName: "arrow.up.arrow.down.circle").font(.system(size: 24)) } }; Button { withAnimation { if isEditing { editMode?.wrappedValue = .inactive } else { editMode?.wrappedValue = .active } } } label: { Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle").font(.system(size: 24)).foregroundColor(isEditing ? .green : .white) }; if !isRecycleBin && !isEditing { Button { showingCreateSheet = true } label: { Image(systemName: "plus.circle.fill").font(.system(size: 24)) } } } } }
    var bottomActionMenu: some View { HStack { Button(role: .destructive) { deleteSelected() } label: { Image(systemName: "trash.fill").font(.title2) }.foregroundColor(.red); Spacer(); Text("已选 \(selectedTableIDs.count)").font(.system(size: 13, weight: .bold, design: .rounded)); Spacer(); if isRecycleBin { Button { restoreSelected() } label: { Image(systemName: "arrow.uturn.backward.circle.fill").font(.title2) }.foregroundColor(.blue) } else if !isAutoFill { Button { showingMoveSheet = true } label: { Image(systemName: "folder.fill").font(.title2) }.foregroundColor(.indigo) } else { Image(systemName: "trash.fill").font(.title2).opacity(0) } }.padding(.horizontal, 32).padding(.vertical, 16).background(.ultraThinMaterial).clipShape(Capsule()).overlay(Capsule().stroke(Color.white.opacity(0.1), lineWidth: 0.5)).shadow(radius: 20).padding(.horizontal, 24).padding(.bottom, 100) }
    var emptyStateView: some View { VStack { Spacer(); Image(systemName: "doc.on.doc").font(.system(size: 60)).opacity(0.2); Text("文件夹为空").foregroundColor(.gray); Spacer() } }
    func toggleSelection(for id: UUID) { if selectedTableIDs.contains(id) { selectedTableIDs.remove(id) } else { selectedTableIDs.insert(id) } }
    func validateAndRename() { guard let t = renamingTable, !newTableName.isEmpty else { return }; let trimmed = newTableName.trimmingCharacters(in: .whitespaces); if asStore.checkTableExists(title: trimmed, inCategoryID: category.id, excludeTableID: t.id) { showDuplicateAlert = true } else { asStore.renameTable(catID: category.id, tableID: t.id, newName: trimmed) } }
    func deleteSelected() { for id in selectedTableIDs { if isRecycleBin { asStore.permanentDeleteTable(tableID: id) } else { asStore.softDeleteTable(tableID: id, categoryID: category.id) } }; selectedTableIDs.removeAll(); editMode?.wrappedValue = .inactive }
    func restoreSelected() { for id in selectedTableIDs { asStore.restoreTable(tableID: id) }; selectedTableIDs.removeAll(); editMode?.wrappedValue = .inactive }
}

// MARK: - 更换模板选择器 - v5 - 修复私有渲染歧义
//
// TemplatePickerSheet
// (修改：
//  1. 优化 changeTableTemplate 调用路径：确保 asStore 在 renderRow 作用域内被正确识别。
//  2. 结构保持：维持 v4 拆分出的 emptyState 与 templateList 属性，确保编译速度。
//  3. 功能完整：支持更换具体表格模板并执行内容自动迁移。)

struct TemplatePickerSheet: View {
    let currentTable: ArchiveTable
    let categoryID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    private var allTableTemplates: [ArchiveTemplate] {
        asStore.templates.filter { $0.type == .table }
    }
    
    var body: some View {
        NavigationStack {
            ZStack {
                Color.black.ignoresSafeArea()
                if allTableTemplates.isEmpty {
                    emptyState
                } else {
                    templateList
                }
            }
            .navigationTitle("更换模板")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { dismiss() }
                }
            }
        }
        .presentationDetents([.medium, .large])
    }
    
    private var emptyState: some View {
        VStack(spacing: 20) {
            Image(systemName: "square.dashed").font(.system(size: 60)).foregroundColor(.gray.opacity(0.3))
            Text("未发现具体表格模板").foregroundColor(.gray)
        }
    }
    
    private var templateList: some View {
        List {
            Section {
                ForEach(allTableTemplates) { tmpl in
                    renderRow(for: tmpl)
                }
            } header: {
                Text("请选择新目标模板").font(.caption).foregroundColor(.gray)
            } footer: {
                Text("归并逻辑：系统将根据【词条名字】自动迁移内容，不匹配的项将留空。原表将备份至回收站。")
                    .font(.system(size: 11))
                    .foregroundColor(.gray.opacity(0.6))
                    .padding(.top, 8)
            }
        }
        .scrollContentBackground(.hidden)
    }
    
    @ViewBuilder
    private func renderRow(for tmpl: ArchiveTemplate) -> some View {
        let isCurrent = (tmpl.id == currentTable.templateID)
        
        Button {
            if !isCurrent {
                // 【核心修复】：明确使用 store 对象调用方法
                self.asStore.changeTableTemplate(tableID: currentTable.id, categoryID: categoryID, newTemplateID: tmpl.id)
                dismiss()
            }
        } label: {
            HStack(spacing: 16) {
                ZStack {
                    Circle().fill(isCurrent ? Color.gray.opacity(0.2) : Color.blue.opacity(0.15)).frame(width: 40, height: 40)
                    Image(systemName: "tablecells").font(.system(size: 16)).foregroundColor(isCurrent ? .gray : .blue)
                }
                VStack(alignment: .leading, spacing: 4) {
                    Text(tmpl.title).font(.headline).foregroundColor(isCurrent ? .gray : .white)
                    Text("\(tmpl.keys.count) 个词条结构").font(.caption).foregroundColor(.gray)
                }
                Spacer()
                if isCurrent {
                    Text("当前使用").font(.system(size: 10, weight: .bold)).padding(.horizontal, 8).padding(.vertical, 4).background(Capsule().fill(Color.white.opacity(0.1))).foregroundColor(.gray)
                } else {
                    Image(systemName: "chevron.right").font(.system(size: 12, weight: .bold)).foregroundColor(.white.opacity(0.2))
                }
            }
            .padding(.vertical, 4)
        }
        .listRowBackground(Color(white: 0.12))
        .disabled(isCurrent)
    }
}

// MARK: - TableRowView - v19 - 锁定物理宽度，修复 Mac 多选布局坍塌与交互死角

struct TableRowView: View {
    let table: ArchiveTable
    let isRecycleBin: Bool
    let isAutoFill: Bool
    let isSelected: Bool
    let asStore: ArchiveStore
    let categoryID: UUID
    let isEditing: Bool
    
    let onRestore: () -> Void
    let onDelete: () -> Void
    let onHistory: () -> Void
    let onRename: () -> Void
    let onMove: () -> Void
    var onChangeTemplate: (() -> Void)? = nil
    var onToggleSelection: (() -> Void)? = nil
    
    var body: some View {
        HStack(spacing: 12) {
            // 1. 编辑态勾选按钮
            if isEditing {
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 22, weight: .bold))
                    .foregroundColor(isSelected ? .indigo : .white.opacity(0.3))
                    .transition(.move(edge: .leading).combined(with: .opacity))
            }
            
            // 2. 主卡片容器
            HStack(alignment: .center, spacing: 16) {
                VStack(spacing: 6) {
                    ZStack {
                        Circle()
                            .fill(getIconBackgroundColor())
                            .frame(width: 44, height: 44)
                        
                        Image(systemName: getIconName())
                            .font(.system(size: 18, weight: .bold))
                            .foregroundColor(getIconForegroundColor())
                    }
                    Text(getTypeLabel())
                        .font(.system(size: 10, weight: .medium))
                        .foregroundColor(.white.opacity(0.5))
                        .lineLimit(1)
                        .frame(maxWidth: 60)
                }
                
                VStack(alignment: .leading, spacing: 4) {
                    Text(table.title)
                        .font(.system(size: 17, weight: .bold, design: .rounded))
                        .foregroundColor(isRecycleBin ? .white.opacity(0.4) : .white)
                        .strikethrough(isRecycleBin, color: .white.opacity(0.4))
                        .lineLimit(nil)
                        .fixedSize(horizontal: false, vertical: true)
                    
                    if isRecycleBin, let d = table.deletedAt {
                        Text("删除于 \(d.formatted(date: .numeric, time: .shortened))")
                            .font(.system(size: 11, design: .monospaced))
                            .foregroundColor(.red.opacity(0.7))
                    } else {
                        Text("上次更新: \(Formatters.mmDD.string(from: table.createdAt))")
                            .font(.system(size: 11))
                            .foregroundColor(.white.opacity(0.3))
                    }
                }
                Spacer()
            }
            .padding(14)
            .frame(maxWidth: .infinity) // 【366号核心修复】：强制锁定最大宽度，防止 Mac 端多选时收缩
            .background {
                RoundedRectangle(cornerRadius: 18)
                    .fill(isRecycleBin ? Color.black.opacity(0.2) : Color.white.opacity(0.06))
            }
            .overlay {
                RoundedRectangle(cornerRadius: 18)
                    .stroke(isRecycleBin ? Color.red.opacity(0.2) : (isSelected && isEditing ? Color.indigo : Color.white.opacity(0.1)), lineWidth: (isSelected && isEditing) ? 2 : 0.5)
            }
            // 【366号核心修复】：在编辑模式下，使用覆盖层物理拦截所有点击事件
            .overlay {
                if isEditing {
                    Color.white.opacity(0.001)
                        .contentShape(Rectangle())
                        .onTapGesture {
                            onToggleSelection?()
                            UIImpactFeedbackGenerator(style: .light).impactOccurred()
                        }
                }
            }
        }
        .frame(maxWidth: .infinity) // 【366号核心修复】：外层也锁定宽度
        .contextMenu {
            if !isEditing {
                if isRecycleBin {
                    Button(action: onRestore) { Label("还原表格", systemImage: "arrow.uturn.backward") }
                    Button(role: .destructive, action: onDelete) { Label("彻底删除", systemImage: "xmark.bin.fill") }
                } else {
                    Button(action: onHistory) { Label("查看历史版本", systemImage: "clock.arrow.circlepath") }
                    Button(action: onRename) { Label("重命名", systemImage: "pencil") }
                    if table.type == .standard { Button { onChangeTemplate?() } label: { Label("更换模板", systemImage: "rectangle.2.swap") } }
                    if !isAutoFill { Button(action: onMove) { Label("移动到...", systemImage: "folder") } }
                    Divider()
                    Button(role: .destructive, action: onDelete) { Label("删除", systemImage: "trash") }
                }
            }
        }
        .swipeActions(edge: .trailing, allowsFullSwipe: true) {
            if !isEditing {
                Button(role: .destructive, action: onDelete) {
                    Label(isRecycleBin ? "彻底删除" : "删除", systemImage: isRecycleBin ? "xmark.bin.fill" : "trash")
                }
            }
        }
        .animation(.spring(response: 0.3), value: isEditing)
    }
    
    func getIconName() -> String {
        if isRecycleBin { return "trash.fill" }
        if isAutoFill { return "wand.and.stars" }
        switch table.type {
        case .markdown: return "doc.text.fill"; case .taskList: return "list.bullet.clipboard"; case .standard: return "tablecells"; case .lessonPlanNodes: return "book.closed.fill"
        }
    }
    func getIconBackgroundColor() -> Color {
        if isRecycleBin { return Color.red.opacity(0.15) }
        if isAutoFill { return Color.blue.opacity(0.15) }
        switch table.type {
        case .markdown: return Color.orange.opacity(0.15); case .taskList: return Color.green.opacity(0.15); case .standard: return Color.purple.opacity(0.15); case .lessonPlanNodes: return Color.orange.opacity(0.2)
        }
    }
    func getIconForegroundColor() -> Color {
        if isRecycleBin { return .red }
        if isAutoFill { return .blue }
        switch table.type {
        case .markdown: return .orange; case .taskList: return .green; case .standard: return .purple; case .lessonPlanNodes: return .orange
        }
    }
    func getTypeLabel() -> String {
        switch table.type {
        case .markdown: return "MARKDOWN"; case .taskList: return "任务清单"; case .standard: return asStore.getTemplateName(by: table.templateID); case .lessonPlanNodes: return "随堂笔记"
        }
    }
}

  // MARK: - 日历设置存储 - v1 - 新增
  //
  // CalendarSettingsStore
  // (功能：管理日历的默认设置，如默认标题、时长、提醒时间等)

  struct CalendarSettingsStore {
      @AppStorage("cal_default_title") static var defaultTitle: String = "新日程"
      @AppStorage("cal_default_duration") static var defaultDuration: Int = 60 // 分钟
      @AppStorage("cal_default_alarm_offset") static var defaultAlarmOffset: Int = -15 // 分钟, 0为无
      // 默认日历ID暂存，实际使用时需校验 CalendarStore 中的日历是否存在
      @AppStorage("cal_default_calendar_id") static var defaultCalendarID: String = ""
  }



// MARK: - 日历设置视图 - v4 - 适配 GlobalSettingsStore
struct CalendarSettingsView: View {
    @Environment(\.dismiss) var dismiss
    @EnvironmentObject var cs: CalendarStore
    // 【核心变化】使用全局设置
    @EnvironmentObject var store: GlobalSettingsStore
    
    let alarmOptions = [0: "无", -300: "5分钟前", -900: "15分钟前", -1800: "30分钟前", -3600: "1小时前", -86400: "1天前"]
    let durationOptions = [15, 30, 45, 60, 90, 120]
    
    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("APP 联动设置")) {
                    Picker("默认行动类型", selection: $store.config.calDefaultCategory) {
                        ForEach(allCategories.filter{$0 != "空"}, id: \.self) { cat in
                            HStack {
                                Circle().fill(getColor(for: cat)).frame(width: 8, height: 8)
                                Text(I18n.cat(cat))
                            }.tag(cat)
                        }
                    }
                    Text("所有新建日程将默认关联此行动类型，到点提醒切换。").font(.caption).foregroundColor(.gray)
                }
                
                Section(header: Text("默认日程信息")) {
                    HStack {
                        Text("默认标题")
                        TextField("例如：新日程", text: $store.config.calDefaultTitle).multilineTextAlignment(.trailing)
                    }
                    
                    Picker("默认时长", selection: $store.config.calDefaultDuration) {
                        ForEach(durationOptions, id: \.self) { min in Text("\(min) 分钟").tag(min) }
                    }
                }
                
                Section(header: Text("偏好设置")) {
                    Picker("默认提醒", selection: $store.config.calDefaultAlarmOffset) {
                        ForEach(alarmOptions.keys.sorted(by: >), id: \.self) { key in
                            Text(alarmOptions[key] ?? "").tag(key)
                        }
                    }
                    
                    Picker("默认日历", selection: $store.config.calDefaultCalendarID) {
                        Text("系统默认").tag("")
                        ForEach(cs.calendars, id: \.calendarIdentifier) { cal in
                            HStack {
                                Circle().fill(Color(cgColor: cal.cgColor)).frame(width: 8, height: 8)
                                Text(cal.title)
                            }.tag(cal.calendarIdentifier)
                        }
                    }
                }
            }
            .navigationTitle("日历设置")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("完成") { dismiss() } }
            }
            .onAppear { cs.fetchAllCalendars() }
        }
    }
}


// MARK: - 移动目标选择页 - v2 - 限制移入自动填写
//
// MoveDestinationSheet
// (修改：过滤掉“自动填写”分类，禁止将表格移入其中。)

struct MoveDestinationSheet: View {
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    let currentCategoryID: UUID
    let onMove: (UUID) -> Void
    
    var body: some View {
        NavigationStack {
            // 过滤条件：排除当前、排除回收站、排除自动填写
            let targets = asStore.categories.filter {
                $0.id != currentCategoryID &&
                $0.title != "删除回收" &&
                $0.title != "自动填写"
            }
            
            if targets.isEmpty {
                VStack(spacing: 20) {
                    Image(systemName: "folder.badge.questionmark").font(.largeTitle).foregroundColor(.gray)
                    Text("没有其他分类可移动").foregroundColor(.gray)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity).background(Color.black.ignoresSafeArea())
                .toolbar { ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } }
            } else {
                List {
                    ForEach(targets) { cat in
                        Button { onMove(cat.id); dismiss() } label: {
                            HStack {
                                Image(systemName: "folder.fill").foregroundColor(.indigo)
                                Text(cat.title).foregroundColor(.white)
                                Spacer()
                                Image(systemName: "arrow.turn.down.right").foregroundColor(.gray)
                            }
                        }
                        .listRowBackground(Color(white: 0.1))
                    }
                }
                .scrollContentBackground(.hidden).background(Color.black.ignoresSafeArea()).navigationTitle("移动到...")
                .toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } } }
            }
        }
    }
}

// MARK: - 新建表格页 - v17 - 支持 Markdown 创建
//
// struct CreateTableSheet
// (修改：CreationMode 增加 .markdown，处理创建逻辑)

struct CreateTableSheet: View {
    let categoryID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var settingsStore: GlobalSettingsStore
    @EnvironmentObject var purchaseManager: PurchaseManager
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @Environment(\.dismiss) var dismiss
    
    @State private var tableName = ""
    @State private var selectedTemplateID: UUID?
    @State private var selectedSourceTableID: UUID?
    
    // 【修改】增加 markdown
    enum CreationMode { case empty, autoFill, taskList, markdown }
    @State private var mode: CreationMode = .empty
    
    @State private var showDuplicateAlert = false
    @State private var showPaywall = false
    var onCreated: ((UUID) -> Void)? = nil
    var currentTotalTables: Int { asStore.categories.reduce(0) { $0 + $1.tables.count } }
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var body: some View {
        NavigationStack {
            ZStack {
                MainBackgroundView(themeColor: themeColor).ignoresSafeArea()
                Form {
                    Section { if !settingsStore.isProEffective { HStack(spacing: 12) { ZStack { Circle().fill(Color.orange.opacity(0.2)).frame(width: 32, height: 32); Image(systemName: "crown.fill").font(.caption).foregroundColor(.orange) }; VStack(alignment: .leading, spacing: 2) { Text("免费版限额").font(.subheadline).fontWeight(.bold); Text("当前已创建 \(currentTotalTables) / 2").font(.caption).foregroundColor(.gray) }; Spacer(); Button("去解锁") { showPaywall = true }.font(.caption.bold()).padding(.horizontal, 10).padding(.vertical, 4).background(Capsule().fill(Color.orange.opacity(0.1))) }.padding(.vertical, 4) } else { HStack { Image(systemName: "checkmark.seal.fill").foregroundColor(.green); Text("Pro 无限创建权限").foregroundColor(.gray) } } }
                    
                    Section(header: Text("创建模式")) {
                        Picker("模式", selection: $mode) {
                            Text("空白模板").tag(CreationMode.empty)
                            Text("自动填写").tag(CreationMode.autoFill)
                            Text("任务清单").tag(CreationMode.taskList)
                            Text("Markdown").tag(CreationMode.markdown) // 【新增】
                        }
                        .pickerStyle(.segmented) // 可能会比较挤，建议改 Menu 或者保持 segmented 试试
                        .padding(.vertical, 4)
                    }
                    
                    Section(header: Text("内容配置")) {
                        if mode == .empty {
                            let tableTemplates = asStore.templates.filter { $0.type == .table }
                            Picker(selection: $selectedTemplateID) {
                                Text("请选择模板...").tag(UUID?.none)
                                ForEach(tableTemplates) { t in Text(t.title).tag(t.id as UUID?) }
                            } label: { Label("选择模板", systemImage: "rectangle.stack") }
                        } else if mode == .taskList {
                            let listTemplates = asStore.templates.filter { $0.type == .taskList }
                            Picker(selection: $selectedTemplateID) {
                                Text("请选择样式...").tag(UUID?.none)
                                ForEach(listTemplates) { t in Text(t.title).tag(t.id as UUID?) }
                            } label: { Label("清单样式", systemImage: "checklist") }
                        } else if mode == .markdown {
                            // Markdown 不需要模板
                            Text("创建一个空白的 Markdown 文档").font(.caption).foregroundColor(.gray)
                        } else {
                            let autoFillTables = asStore.getTablesInAutoFillFolder()
                            Picker(selection: $selectedSourceTableID) {
                                Text("请选择参考源...").tag(UUID?.none)
                                ForEach(autoFillTables) { t in Text(t.title).tag(t.id as UUID?) }
                            } label: { Label("参考源", systemImage: "wand.and.stars") }
                            .onChange(of: selectedSourceTableID) { _, newID in
                                if let id = newID, let src = asStore.getTable(by: id), let tid = src.templateID {
                                    selectedTemplateID = tid
                                }
                            }
                        }
                    }
                    
                    Section(header: Text("基本信息")) { VStack(alignment: .leading, spacing: 12) { TextField("输入标题", text: $tableName).font(.headline); ScrollView(.horizontal, showsIndicators: false) { HStack(spacing: 8) { namingHelperBtn(title: nameHelperTitle) { insertNameWithUnderscore() }; namingHelperBtn(title: dateStr("yyMMdd")) { tableName += dateStr("yyMMdd") }; namingHelperBtn(title: dateStr("HHmm")) { tableName += dateStr("HHmm") } } } }.padding(.vertical, 8) }
                    
                    Section { Button { if !settingsStore.isProEffective && currentTotalTables >= 2 { showPaywall = true } else { validateAndCreate() } } label: { HStack { Spacer(); Text(settingsStore.isProEffective ? "立即创建" : (currentTotalTables >= 2 ? "解锁无限额度" : "免费创建")).fontWeight(.black); Spacer() } }.disabled(isCreateDisabled).listRowBackground(LinearGradient(colors: [Color.blue, Color.cyan], startPoint: .leading, endPoint: .trailing).opacity(isCreateDisabled ? 0.3 : 1.0)).foregroundColor(.white) }
                }.scrollContentBackground(.hidden)
            }
            .navigationTitle("新建").ttNavigationBarTitleDisplayMode(.inline).toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } } }
            .alert("名称重复", isPresented: $showDuplicateAlert) { Button("确定", role: .cancel) { } }
            .sheet(isPresented: $showPaywall) {
                TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                    PaywallView().environmentObject(settingsStore).environmentObject(purchaseManager)
                }
            }
        }
    }
    
    private func namingHelperBtn(title: String, action: @escaping () -> Void) -> some View { Button(action: action) { Text(title).font(.caption.bold()).padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().fill(Color.white.opacity(0.1))).overlay(Capsule().stroke(Color.white.opacity(0.1), lineWidth: 1)) }.buttonStyle(.plain) }
    
    var nameHelperTitle: String {
        switch mode {
        case .empty: return "模板名"
        case .taskList: return "清单名"
        case .autoFill: return "源文件名"
        case .markdown: return "文档名"
        }
    }
    
    func insertNameWithUnderscore() { var text = ""; if mode == .autoFill { if let sid = selectedSourceTableID, let src = asStore.getTable(by: sid) { text = src.title } } else { if let tid = selectedTemplateID, let t = asStore.templates.first(where: {$0.id == tid}) { text = t.title } }; if !text.isEmpty { tableName += text + "_" } }
    
    var isCreateDisabled: Bool {
        if tableName.isEmpty { return true }
        if mode == .autoFill { return selectedSourceTableID == nil }
        if mode == .markdown { return false } // Markdown 无需模板
        return selectedTemplateID == nil
    }
    
    func dateStr(_ f: String) -> String { let df = DateFormatter(); df.dateFormat = f; return df.string(from: Date()) }
    
    func validateAndCreate() {
        if asStore.checkTableExists(title: tableName, inCategoryID: categoryID) { showDuplicateAlert = true; return }
        
        // 【新增】Markdown 创建逻辑
        if mode == .markdown {
            // 创建一个没有模板 ID 的 ArchiveTable，类型为 .markdown
            let row = ArchiveRow(key: "content", value: asStore.wrapMarkdownContent("")) // 空内容
            let nt = ArchiveTable(title: tableName, rows: [row], templateID: nil, type: .markdown)
            
            // 插入到分类
            if let idx = asStore.categories.firstIndex(where: { $0.id == categoryID }) {
                asStore.categories[idx].tables.insert(nt, at: 0)
                asStore.saveTableToFile(nt, categoryTitle: asStore.categories[idx].title)
                asStore.clearSmartCache()
                onCreated?(nt.id)
            }
            dismiss()
            return
        }
        
        guard let tid = selectedTemplateID, let tmpl = asStore.templates.first(where: {$0.id == tid}) else { return }
        let srcID = (mode == .autoFill) ? selectedSourceTableID : nil
        if let newID = asStore.addTableFromTemplate(to: categoryID, template: tmpl, customTitle: tableName, sourceTableID: srcID) { onCreated?(newID) }; dismiss()
    }
}


// MARK: - 智能聚合主页 - v40 - 修复算分接口调用
//
// SmartFolderView
// (修改内容：修正 themeColor 计算属性，将 ts 改为 timeStore.getRecordsForDisplay(for: yesterday) 以适配新接口。)

struct SmartFolderView: View {
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    @Environment(\.dismiss) var dismiss
    @Environment(\.editMode) private var editMode
    
    @State private var showingCreate = false
    @State private var editingSmartView: SmartViewConfig? = nil
    
    @State private var showRenameAlert = false
    @State private var newName = ""
    @State private var showDuplicateAlert = false
    
    @State private var selectedIDs: Set<UUID> = []
    @State private var showDeleteAlert = false
    
    enum SortOption: String, CaseIterable {
        case custom = "用户自调"
        case nameAsc = "名称正序"
        case nameDesc = "名称倒序"
    }
    @State private var sortOption: SortOption = .custom
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        // 【核心修复】
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var isEditing: Bool { editMode?.wrappedValue.isEditing == true }
    
    var processedViews: [SmartViewConfig] {
        switch sortOption {
        case .custom: return asStore.smartViews
        case .nameAsc: return asStore.smartViews.sorted { $0.title.localizedStandardCompare($1.title) == .orderedAscending }
        case .nameDesc: return asStore.smartViews.sorted { $0.title.localizedStandardCompare($1.title) == .orderedDescending }
        }
    }
    
    var body: some View {
        ZStack(alignment: .bottom) {
            backgroundLayer
            VStack(spacing: 0) {
                listView
            }
            if isEditing && !selectedIDs.isEmpty {
                bottomBar
            }
        }
        .navigationTitle("智能聚合")
        .ttToolbarBackground(.hidden, for: .navigationBar)
        .ttToolbarColorScheme(.dark, for: .navigationBar)
        .toolbar { toolbarContent }
        .sheet(isPresented: $showingCreate) {
            TTModalSheetContainer(minWidth: 760, minHeight: 620) {
                SmartViewCreateSheet()
            }
        }
        .alert("重命名", isPresented: $showRenameAlert) {
            TextField("新名称", text: $newName)
            Button("取消", role: .cancel) { }
            Button("确定") { validateAndRename() }
        }
        .alert("名称已存在", isPresented: $showDuplicateAlert) {
            Button("确定", role: .cancel) {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { showRenameAlert = true }
            }
        } message: { Text("名称“\(newName)”已存在。") }
        .alert("确认删除？", isPresented: $showDeleteAlert) {
            Button("取消", role: .cancel) { }
            Button("删除 \(selectedIDs.count) 项", role: .destructive) { deleteSelected() }
        }
        .onChange(of: isEditing) { _, newVal in
            if !newVal { selectedIDs.removeAll() }
        }
    }
    
    private var backgroundLayer: some View {
        GeometryReader { geo in
            MainBackgroundView(themeColor: themeColor)
                .frame(height: UIScreen.mainSafe.bounds.height)
                .offset(y: -geo.frame(in: .global).minY)
        }
        .ignoresSafeArea()
    }
    
    private var listView: some View {
        List {
            if asStore.smartViews.isEmpty {
                emptyStateRow
            } else {
                Color.clear.frame(height: 10)
                    .listRowBackground(Color.clear)
                    .listRowSeparator(.hidden)
                
                ForEach(processedViews) { viewConfig in
                    ZStack {
                        if !isEditing {
                            NavigationLink(destination: SmartResultListView(config: viewConfig)) { EmptyView() }
                                .opacity(0).buttonStyle(.plain)
                        }
                        HStack(spacing: 12) {
                            if isEditing {
                                Image(systemName: selectedIDs.contains(viewConfig.id) ? "checkmark.circle.fill" : "circle")
                                    .font(.system(size: 22, weight: .bold))
                                    .foregroundColor(selectedIDs.contains(viewConfig.id) ? .orange : .white.opacity(0.3))
                                    .onTapGesture { toggleSelection(viewConfig.id) }
                            }
                            SmartViewCard(config: viewConfig)
                        }
                    }
                    .listRowInsets(EdgeInsets(top: 6, leading: 20, bottom: 6, trailing: 20))
                    .listRowBackground(Color.clear)
                    .listRowSeparator(.hidden)
                    .swipeActions(edge: .trailing, allowsFullSwipe: false) {
                        if !isEditing {
                            Button(role: .destructive) {
                                if let idx = asStore.smartViews.firstIndex(of: viewConfig) {
                                    asStore.deleteSmartView(at: IndexSet(integer: idx))
                                }
                            } label: { Label("删除", systemImage: "trash") }
                            Button {
                                editingSmartView = viewConfig
                                newName = viewConfig.title
                                showRenameAlert = true
                            } label: { Label("重命名", systemImage: "pencil") }.tint(.blue)
                        }
                    }
                }
                .onMove(perform: moveSmartViews)
                Color.clear.frame(height: 120)
                    .listRowBackground(Color.clear)
                    .listRowSeparator(.hidden)
            }
        }
        .listStyle(.plain)
        .scrollContentBackground(.hidden)
    }
    
    private var emptyStateRow: some View {
        VStack(spacing: 20) {
            Spacer().frame(height: 50)
            Image(systemName: "sparkles.rectangle.stack").font(.system(size: 60)).opacity(0.2)
            Text("定义规则，自动跨表格提取关键信息").font(.subheadline).foregroundColor(.gray)
            Button { showingCreate = true } label: {
                Text("开始创建")
                    .fontWeight(.bold).foregroundColor(.black)
                    .padding(.horizontal, 30).padding(.vertical, 12)
                    .background(Capsule().fill(Color.orange))
            }
        }
        .frame(maxWidth: .infinity)
        .listRowBackground(Color.clear)
        .listRowSeparator(.hidden)
    }
    
    private var toolbarContent: some ToolbarContent {
        ToolbarItem(placement: .topBarTrailing) {
            HStack(spacing: 28) {
                if !isEditing {
                    Menu {
                        Picker("排序方式", selection: $sortOption) {
                            ForEach(SortOption.allCases, id: \.self) { option in
                                Text(option.rawValue).tag(option)
                            }
                        }
                    } label: {
                        Image(systemName: "arrow.up.arrow.down.circle").font(.system(size: 24))
                    }
                }
                Button {
                    withAnimation {
                        if isEditing { editMode?.wrappedValue = .inactive }
                        else { editMode?.wrappedValue = .active }
                    }
                } label: {
                    Image(systemName: isEditing ? "checkmark.circle.fill" : "checkmark.circle")
                        .font(.system(size: 24))
                        .foregroundColor(isEditing ? .green : .white)
                }
                if !isEditing {
                    Button { showingCreate = true } label: {
                        Image(systemName: "plus.circle.fill").font(.system(size: 24))
                    }
                }
            }
        }
    }
    
    private var bottomBar: some View {
        HStack {
            Button(role: .destructive) { showDeleteAlert = true } label: {
                Image(systemName: "trash.fill").font(.title2)
            }.foregroundColor(.red)
            Spacer()
            Text("已选 \(selectedIDs.count) 项")
                .font(.system(size: 14, weight: .bold, design: .rounded))
                .foregroundColor(.white.opacity(0.8))
            Spacer()
            Image(systemName: "trash.fill").font(.title2).opacity(0)
        }
        .padding(.horizontal, 32).padding(.vertical, 16).frame(maxWidth: 400).background(.ultraThinMaterial).clipShape(Capsule()).overlay(Capsule().stroke(Color.white.opacity(0.12), lineWidth: 0.5)).shadow(color: .black.opacity(0.5), radius: 20, x: 0, y: 10).padding(.bottom, 50).transition(.move(edge: .bottom).combined(with: .opacity))
    }
    
    func validateAndRename() {
        guard let sv = editingSmartView, !newName.isEmpty else { return }
        let trimmed = newName.trimmingCharacters(in: .whitespaces)
        if asStore.checkSmartViewNameExists(name: trimmed, excludeID: sv.id) {
            showDuplicateAlert = true
        } else {
            asStore.renameSmartView(id: sv.id, newName: trimmed)
        }
    }
    
    func toggleSelection(_ id: UUID) {
        if selectedIDs.contains(id) { selectedIDs.remove(id) }
        else { selectedIDs.insert(id) }
    }
    
    func deleteSelected() {
        asStore.deleteSmartViews(ids: selectedIDs)
        selectedIDs.removeAll()
        editMode?.wrappedValue = .inactive
    }
    
    func moveSmartViews(from source: IndexSet, to destination: Int) {
        guard sortOption == .custom else { return }
        asStore.smartViews.move(fromOffsets: source, toOffset: destination)
        if let first = asStore.smartViews.first {
            asStore.renameSmartView(id: first.id, newName: first.title)
        }
    }
}

