// MARK: - 新建智能聚集视图 - v4 - 修复 TemplateKey 类型匹配错误
//
// SmartViewCreateSheet
// (修改：
//  1. 修复 availableKeys：由于模板 keys 已升级为对象数组，此处使用 .map { $0.name } 转换为字符串数组。
//  2. 修复 selectableKeys：同步适配字符串过滤逻辑。)

struct SmartViewCreateSheet: View {
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var title = ""
    @State private var selectedTemplateID: UUID?
    @State private var filters: [SmartFilterCondition] = []
    @State private var tempFilterKey = ""
    @State private var tempFilterContent = ""
    @State private var displayKeys: Set<String> = []
    @State private var showDuplicateAlert = false
    
    // 【核心修复】将对象数组转换为字符串数组以适配 UI
    var availableKeys: [String] {
        if let tid = selectedTemplateID, let t = asStore.templates.first(where: { $0.id == tid }) {
            return t.keys.map { $0.name }
        }
        return []
    }
    
    var selectableKeys: [String] {
        let filterKeys = filters.map { $0.key }
        return availableKeys.filter { !filterKeys.contains($0) }
    }
    
    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("基础设置")) {
                    TextField("聚合名称 (例如: 待办汇总)", text: $title)
                    Picker("选择数据源模板", selection: $selectedTemplateID) {
                        Text("请选择模板...").tag(UUID?.none)
                        ForEach(asStore.templates) { t in Text(t.title).tag(t.id as UUID?) }
                    }
                    .onChange(of: selectedTemplateID) { _, _ in displayKeys = []; filters = []; tempFilterKey = "" }
                }
                
                if selectedTemplateID != nil {
                    Section(header: Text("筛选过滤 (符合以下条件才显示)")) {
                        ForEach(Array(filters.enumerated()), id: \.offset) { index, filter in
                            HStack {
                                Text(filter.key).fontWeight(.bold).foregroundColor(.orange)
                                Text("包含").font(.caption).foregroundColor(.gray)
                                Text("“\(filter.value)”")
                                Spacer()
                            }
                            .swipeActions { Button(role: .destructive) { filters.remove(at: index) } label: { Image(systemName: "trash") } }
                        }
                        
                        VStack(spacing: 12) {
                            Picker("选择词条", selection: $tempFilterKey) {
                                Text("点击选择字段...").tag("")
                                ForEach(availableKeys, id: \.self) { Text($0).tag($0) }
                            }
                            .pickerStyle(.menu)
                            
                            if !tempFilterKey.isEmpty {
                                HStack {
                                    TextField("输入内容关键词", text: $tempFilterContent)
                                        .textFieldStyle(.roundedBorder)
                                    Button("添加条件") {
                                        filters.append(SmartFilterCondition(key: tempFilterKey, value: tempFilterContent))
                                        displayKeys.remove(tempFilterKey)
                                        tempFilterContent = ""; tempFilterKey = ""
                                    }
                                    .buttonStyle(.borderedProminent)
                                    .disabled(tempFilterContent.isEmpty)
                                }
                            }
                        }
                    }
                    
                    Section(header: Text("列表展示字段 (可选多项)")) {
                        if selectableKeys.isEmpty {
                            Text("已选择所有字段").font(.caption).foregroundColor(.gray)
                        } else {
                            ForEach(selectableKeys, id: \.self) { key in
                                Button {
                                    if displayKeys.contains(key) { displayKeys.remove(key) }
                                    else { displayKeys.insert(key) }
                                } label: {
                                    HStack {
                                        Text(key).foregroundColor(.white)
                                        Spacer()
                                        if displayKeys.contains(key) { Image(systemName: "checkmark").foregroundColor(.blue).fontWeight(.bold) }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            .navigationTitle("新建规则")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }
                ToolbarItem(placement: .confirmationAction) {
                    Button("创建") { create() }
                        .disabled(title.isEmpty || selectedTemplateID == nil)
                        .fontWeight(.bold)
                }
            }
            .alert("名称已存在", isPresented: $showDuplicateAlert) { Button("确定", role: .cancel) { } }
        }
    }
    
    func create() {
        let trimmed = title.trimmingCharacters(in: .whitespaces)
        if asStore.checkSmartViewNameExists(name: trimmed) { showDuplicateAlert = true; return }
        guard let tid = selectedTemplateID else { return }
        let sortedDisplayKeys = availableKeys.filter { displayKeys.contains($0) }
        asStore.addSmartView(SmartViewConfig(title: trimmed, templateID: tid, filters: filters, displayKeys: sortedDisplayKeys))
        dismiss()
    }
}


// MARK: - 智能视图结果列表 - v18 - 修复算分接口调用
//
// SmartResultListView
// (修改内容：修正 themeColor 计算属性，将 ts 改为 ts.getRecordsForDisplay(for: yesterday) 以适配新接口。)

struct SmartResultListView: View {
    let config: SmartViewConfig
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var timeStore: TimeStore
    @EnvironmentObject var efficiencyStore: EfficiencyStore
    
    @State private var results: [SmartResultItem] = []
    @State private var isLoading: Bool = true
    
    var themeColor: Color {
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!
        // 【修复点】
        let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore)
        if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }
        if s >= 80 { return .yellow }
        if s >= 60 { return .green }
        return Color(white: 0.6)
    }
    
    var body: some View {
        ZStack {
            GeometryReader { geo in MainBackgroundView(themeColor: themeColor).frame(height: UIScreen.mainSafe.bounds.height).offset(y: -geo.frame(in: .global).minY) }.ignoresSafeArea()
            ScrollView {
                LazyVStack(spacing: 16) {
                    VStack(alignment: .leading, spacing: 16) {
                        Text(config.title).font(.system(size: 34, weight: .black, design: .rounded)).foregroundColor(.white)
                        if !config.filters.isEmpty { ScrollView(.horizontal, showsIndicators: false) { HStack(spacing: 8) { ForEach(config.filters, id: \.key) { f in HStack(spacing: 4) { Text(f.key).fontWeight(.bold).foregroundColor(.white.opacity(0.8)); Text(":"); Text(f.value).fontWeight(.bold).foregroundColor(.orange) }.font(.system(size: 13)).padding(.horizontal, 14).padding(.vertical, 8).background(Capsule().fill(Color.white.opacity(0.1))).overlay(Capsule().stroke(Color.orange.opacity(0.5), lineWidth: 1)) } } } }
                    }.padding(.top, 20).padding(.bottom, 8).padding(.horizontal, 24)
                    if isLoading { VStack(spacing: 20) { Spacer().frame(height: 100); ProgressView().tint(.orange).scaleEffect(1.2); Text("正在聚合...").font(.caption).foregroundColor(.gray) } }
                    else if results.isEmpty { VStack(spacing: 20) { Spacer().frame(height: 100); Image(systemName: "doc.text.magnifyingglass").font(.system(size: 48)).opacity(0.15); Text("无数据").foregroundColor(.gray) } }
                    else { ForEach(results) { item in let catID: UUID = { for cat in asStore.categories { if cat.tables.contains(where: { $0.id == item.id }) { return cat.id } }; return UUID() }(); SmartResultEditableRow(item: item, categoryID: catID).padding(.horizontal, 20) } }
                    Color.clear.frame(height: 400)
                }
            }
        }
        .ttNavigationBarTitleDisplayMode(.inline).ttToolbarBackground(.hidden, for: .navigationBar).ttToolbarColorScheme(.dark, for: .navigationBar)
        .toolbar { ToolbarItem(placement: .primaryAction) { Menu { Picker("排序", selection: Binding(get: { config.sortKey }, set: { asStore.updateSmartViewSort(id: config.id, sortKey: $0, isAscending: config.isAscending); refreshResults() })) { Text("创建时间").tag("created"); if let first = results.first { ForEach(first.displayValuesWithStyle.map { $0.key }, id: \.self) { Text($0).tag($0) } } }; Divider(); Button { asStore.updateSmartViewSort(id: config.id, sortKey: config.sortKey, isAscending: !config.isAscending); refreshResults() } label: { Label(config.isAscending ? "正序" : "倒序", systemImage: config.isAscending ? "arrow.up" : "arrow.down") } } label: { Image(systemName: "arrow.up.arrow.down.circle").font(.system(size: 18, weight: .semibold)) } } }
        .task { refreshResults() }.onChange(of: asStore.templates) { _, _ in refreshResults() }
    }
    private func refreshResults() { Task { isLoading = true; let data = await asStore.performSmartQuery(config: config); withAnimation { self.results = data; self.isLoading = false } } }
}


// MARK: - 聚合结果卡片 - v16 - 修复标题被内容挤出屏幕
//
// SmartResultEditableRow
// (修改：
//  1. [CRITICAL] 为 SmartEditableField 增加 maxWidth: .infinity，确保其在 HStack 内受限，触发内部 TextField 换行。
//  2. 保持 110 固定宽度的 Title 不受挤压。
//  3. 优化视觉稳定性。)

struct SmartResultEditableRow: View {
    let item: SmartResultItem
    let categoryID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    
    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // 1. Header: 表格来源信息
            NavigationLink(destination: ArchiveDetailTableView(categoryID: categoryID, table: item.originalTable)) {
                HStack {
                    HStack(spacing: 6) {
                        Image(systemName: "tablecells.fill").font(.system(size: 12))
                        Text(item.tableName).font(.system(size: 14, weight: .bold, design: .rounded))
                    }
                    .foregroundColor(.white)
                    
                    Spacer()
                    
                    Text(item.tableCreatedAt.formatted(date: .numeric, time: .omitted))
                        .font(.system(size: 10, design: .monospaced))
                        .foregroundColor(.white.opacity(0.3))
                    
                    Image(systemName: "chevron.right").font(.system(size: 10, weight: .bold)).foregroundColor(.white.opacity(0.3))
                }
                .padding(.horizontal, 16).padding(.vertical, 12)
                .background(Color.blue.opacity(0.15))
            }
            .buttonStyle(.plain)

            Divider().background(Color.white.opacity(0.1))

            // 2. Body: 数据列表
            VStack(alignment: .leading, spacing: 0) {
                if item.displayValuesWithStyle.isEmpty {
                    Text("无显示列").font(.caption).foregroundColor(.gray).padding(16)
                } else {
                    ForEach(Array(item.displayValuesWithStyle.enumerated()), id: \.offset) { index, tuple in
                        HStack(alignment: .center, spacing: 12) {
                            // 左侧：词条名 (宽度固定，绝不收缩)
                            Text(tuple.key)
                                .font(getKeyFont(config: tuple.style))
                                .foregroundColor(colorFromStr(tuple.style.color))
                                .multilineTextAlignment(.center)
                                .fixedSize(horizontal: false, vertical: true)
                                .frame(width: 110, alignment: .center)
                            
                            // 右侧：输入框容器 (占用剩余宽度并强制换行)
                            SmartEditableField(
                                tableID: item.id,
                                key: tuple.key,
                                initialValue: tuple.value,
                                config: tuple.style
                            )
                            .frame(maxWidth: .infinity, alignment: .leading) // 【核心修复】
                        }
                        .padding(.horizontal, 16)
                        .padding(.vertical, 4)
                        
                        if index < item.displayValuesWithStyle.count - 1 {
                            Divider().background(Color.white.opacity(0.05)).padding(.leading, 16)
                        }
                    }
                }
            }
            .padding(.vertical, 8)
        }
        .background { RoundedRectangle(cornerRadius: 16).fill(.ultraThinMaterial).shadow(color: .black.opacity(0.2), radius: 8, x: 0, y: 4) }
        .clipShape(RoundedRectangle(cornerRadius: 16))
        .overlay { RoundedRectangle(cornerRadius: 16).stroke(Color.white.opacity(0.1), lineWidth: 0.5) }
    }
    
    func getKeyFont(config: KeyStyleConfig) -> Font {
        let size = max(13, config.fontSize * 0.7)
        let weight: Font.Weight = config.isBold ? .bold : .semibold
        if let name = config.customFontName { return .custom(name, size: size).weight(weight) }
        switch config.fontDesign {
        case "rounded": return .system(size: size, weight: weight, design: .rounded)
        case "monospaced": return .system(size: size, weight: weight, design: .monospaced)
        case "serif": return .system(size: size, weight: weight, design: .serif)
        default: return .system(size: size, weight: weight, design: .default)
        }
    }
    
    func colorFromStr(_ s: String) -> Color {
        switch s {
        case "red": return .red; case "blue": return .blue; case "green": return .green; case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan
        case "white": return .white; default: return .gray
        }
    }
}


// MARK: - 聚合字段编辑组件 - v40 - 适配横向宽度约束
//
// SmartEditableField
// (修改：
//  1. 容器增加 maxWidth: .infinity 确保在 HStack 中占据剩余空间。
//  2. 配合 TextField(axis: .vertical) 实现自动换行。)

struct SmartEditableField: View {
    let tableID: UUID
    let key: String
    let initialRawValue: String
    let config: KeyStyleConfig
    
    @State private var contentValue: String
    @EnvironmentObject var asStore: ArchiveStore
    @FocusState private var isFocused: Bool
    
    init(tableID: UUID, key: String, initialValue: String, config: KeyStyleConfig) {
        self.tableID = tableID
        self.key = key
        self.initialRawValue = initialValue
        self.config = config
        
        if let data = initialValue.data(using: .utf8),
           let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) {
            _contentValue = State(initialValue: decoded.content)
        } else {
            _contentValue = State(initialValue: initialValue)
        }
    }
    
    var body: some View {
        TextField("点击输入...", text: $contentValue, axis: .vertical)
            .font(.system(size: 16, weight: .regular, design: .rounded))
            .lineSpacing(4)
            .multilineTextAlignment(.leading)
            .foregroundColor(.white.opacity(0.9))
            .padding(.horizontal, 12)
            .padding(.vertical, 10)
            .background(Color.white.opacity(0.05))
            .cornerRadius(8)
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(Color.white.opacity(isFocused ? 0.3 : 0.05), lineWidth: 0.5)
            )
            .focused($isFocused)
            // 【关键修复】确保它不向父容器要求超出屏幕的宽度
            .frame(maxWidth: .infinity, alignment: .leading)
            .onChange(of: isFocused) { _, focused in
                if !focused { save() }
            }
    }
    
    func save() {
        var currentTitle = key
        if let data = initialRawValue.data(using: .utf8),
           let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) {
            currentTitle = decoded.title
        }
        
        let newData = StandardRowData(title: currentTitle, content: contentValue)
        if let jsonData = try? JSONEncoder().encode(newData),
           let jsonStr = String(data: jsonData, encoding: .utf8) {
            if jsonStr != initialRawValue {
                asStore.updateValueByTableID(tableID: tableID, key: key, newValue: jsonStr)
            }
        }
    }
}

// MARK: - 表格时光机视图 - v4 - 适配 macOS 震动反馈

struct SingleTableHistoryView: View {
    let tableID: UUID
    @EnvironmentObject var asStore: ArchiveStore
    @Environment(\.dismiss) var dismiss
    
    @State private var backups: [BackupFile] = []
    
    private let dateFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateStyle = .medium
        f.timeStyle = .medium
        return f
    }()
    
    var body: some View {
        NavigationStack {
            ZStack {
                Color.black.ignoresSafeArea()
                
                if backups.isEmpty {
                    VStack(spacing: 20) {
                        Image(systemName: "clock.arrow.circlepath").font(.system(size: 60)).foregroundColor(.gray.opacity(0.3))
                        Text("暂无历史存档").font(.headline).foregroundColor(.gray)
                        Text("修改表格内容并保存后\n会自动生成历史快照").font(.caption).foregroundColor(.gray.opacity(0.5)).multilineTextAlignment(.center)
                    }
                } else {
                    List {
                        Section(header: Text("备份记录 (点击恢复)")) {
                            ForEach(backups) { backup in
                                Button {
                                    restore(backup)
                                } label: {
                                    HStack {
                                        VStack(alignment: .leading, spacing: 4) {
                                            Text(getTimeAgo(backup.date)).font(.headline).foregroundColor(.white)
                                            Text(dateFormatter.string(from: backup.date)).font(.caption2).fontDesign(.monospaced).foregroundColor(.gray)
                                        }
                                        Spacer()
                                        Image(systemName: "arrow.uturn.backward.circle").font(.title2).foregroundColor(.orange)
                                    }
                                    .padding(.vertical, 4)
                                }
                                .listRowBackground(Color(white: 0.1))
                            }
                        }
                    }
                    .scrollContentBackground(.hidden)
                }
            }
            .navigationTitle("历史版本")
            .ttNavigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } }
            .onAppear { backups = asStore.getTableHistory(tableID: tableID) }
        }
    }
    
    func restore(_ backup: BackupFile) {
        asStore.restoreTable(from: backup, targetTableID: tableID)
        
        #if !os(macOS)
        let gen = UINotificationFeedbackGenerator()
        gen.notificationOccurred(.success)
        #endif
        
        dismiss()
    }
    
    func getTimeAgo(_ date: Date) -> String {
        let diff = Int(Date().timeIntervalSince(date))
        if diff < 60 { return "刚刚" }
        if diff < 3600 { return "\(diff / 60)分钟前" }
        if diff < 86400 { return "\(diff / 3600)小时前" }
        return "\(diff / 86400)天前"
    }
}

