// MARK: - 导出专用行组件 - v13 - 物理适配 2x 超宽画布

struct TableExportRow: View {
    let row: ArchiveRow
    let index: Int
    let templateID: UUID?
    let asStore: ArchiveStore
    
    // 全局边距对齐
    private let sidePadding: CGFloat = 120
    
    var body: some View {
        if let taskData = asStore.parseTaskData(row.value) {
            let cfg = asStore.getLevelStyleObj(templateID: templateID, level: taskData.level)
            let keyColor = colorFromStr(cfg.color)
            HStack(alignment: .top, spacing: 0) {
                if taskData.level > 0 { Color.clear.frame(width: CGFloat(taskData.level) * 60) }
                ZStack {
                    Circle().stroke(keyColor.opacity(0.5), lineWidth: 4).frame(width: 44, height: 44)
                    if taskData.isCompleted { Circle().fill(keyColor).frame(width: 28, height: 28) }
                }.padding(.top, 8).padding(.trailing, 40)
                
                Text(taskData.title)
                    .font(getFont(cfg)) // 内部已根据配置缩放
                    .foregroundColor(taskData.isCompleted ? .white.opacity(0.3) : keyColor)
                    .strikethrough(taskData.isCompleted)
                    .lineSpacing(12)
                    .padding(.bottom, 60)
                Spacer()
            }.padding(.horizontal, sidePadding).padding(.top, index == 0 ? 60 : 0)
        }
        else if row.key == "content" {
            let rawContent = asStore.unwrapMarkdownContent(row.value)
            renderMarkdownContent(rawContent)
        }
        else {
            let config = asStore.getKeyConfigObj(templateID: templateID, key: row.key)
            let keyColor = colorFromStr(config.color)
            let displayTitle = (try? JSONDecoder().decode(StandardRowData.self, from: row.value.data(using: .utf8) ?? Data()))?.title ?? row.key
            let displayContent = (try? JSONDecoder().decode(StandardRowData.self, from: row.value.data(using: .utf8) ?? Data()))?.content ?? row.value
            
            HStack(alignment: .top, spacing: 0) {
                // 左侧标题栏宽度同步扩增至 320
                Text(displayTitle)
                    .font(.system(size: 52, weight: .heavy, design: .rounded))
                    .foregroundColor(keyColor.opacity(0.95))
                    .multilineTextAlignment(.leading)
                    .fixedSize(horizontal: false, vertical: true)
                    .frame(width: 280, alignment: .leading)
                    .padding(.trailing, 40)
                    .frame(width: 320)
                
                ZStack(alignment: .top) {
                    Rectangle().fill(Color.white.opacity(0.12)).frame(width: 3).frame(maxHeight: .infinity)
                    Circle().fill(keyColor).frame(width: 14, height: 14).offset(y: 30)
                }
                
                // 右侧内容区：享受翻倍后的宽度空间
                Text(displayContent.isEmpty ? "—" : displayContent.replacingOccurrences(of: "\t", with: "    "))
                    .font(getFont(config))
                    .foregroundColor(.white)
                    .lineSpacing(18)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(.leading, 60)
                    .padding(.top, 16)
                    .padding(.bottom, 80)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            .padding(.horizontal, 100).padding(.top, index == 0 ? 80 : 0)
        }
    }
    
    @ViewBuilder
    private func renderMarkdownContent(_ content: String) -> some View {
        let lines = content.components(separatedBy: .newlines)
        VStack(alignment: .leading, spacing: 24) {
            ForEach(Array(lines.enumerated()), id: \.offset) { _, line in
                if let assetID = extractAssetID(from: line) {
                    let imagePath = MarkdownAssetManager.shared.getFileURL(assetID: assetID).path
                    if let image = UIImage(contentsOfFile: imagePath) {
                        Image(uiImage: image).resizable().aspectRatio(contentMode: .fit).cornerRadius(24).padding(.vertical, 20).shadow(color: .black.opacity(0.5), radius: 30, x: 0, y: 15)
                    } else {
                        HStack { Image(systemName: "photo"); Text("图片未找到") }.font(.system(size: 30)).foregroundColor(.gray).padding(40).background(RoundedRectangle(cornerRadius: 20).stroke(Color.gray.opacity(0.3)))
                    }
                } else if !line.trimmingCharacters(in: .whitespaces).isEmpty {
                    Text(line).foregroundColor(.white).font(.system(size: 42)).lineSpacing(16) // 字号由 26 提至 42
                }
            }
        }.padding(.horizontal, sidePadding).padding(.vertical, 60)
    }
    
    private func extractAssetID(from line: String) -> String? {
        let pattern = "\\(asset:([^)]+)\\)"
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return nil }
        let nsLine = line as NSString
        if let match = regex.firstMatch(in: line, options: [], range: NSRange(location: 0, length: nsLine.length)) {
            return nsLine.substring(with: match.range(at: 1)).trimmingCharacters(in: .whitespacesAndNewlines)
        }
        return nil
    }
    
    private func getFont(_ cfg: KeyStyleConfig) -> Font {
        let size = cfg.fontSize * 1.5; let weight: Font.Weight = cfg.isBold ? .bold : .regular // 增加物理显示字号
        if let name = cfg.customFontName { return .custom(name, size: size).weight(weight) }
        switch cfg.fontDesign {
        case "rounded": return .system(size: size, weight: weight, design: .rounded); case "monospaced": return .system(size: size, weight: weight, design: .monospaced); case "serif": return .system(size: size, weight: weight, design: .serif); default: return .system(size: size, weight: weight, design: .default)
        }
    }
    
    private func colorFromStr(_ s: String) -> Color {
        switch s { case "red": return .red; case "blue": return .blue; case "green": return .green; case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan; case "white": return .white; default: return .blue }
    }
}

