        }
        .ttNavigationBarTitleDisplayMode(.inline).ttToolbarBackground(.hidden, for: .navigationBar).ttToolbarColorScheme(.dark, for: .navigationBar)
        .toolbar {
            if liveTable.type != .markdown && liveTable.type != .lessonPlanNodes {
                ToolbarItemGroup(placement: .primaryAction) {
                    HStack(spacing: innerSpacing) { Button { popUndo() } label: { Image(systemName: "arrow.uturn.backward.circle.fill").foregroundColor(localUndoStack.isEmpty ? .gray.opacity(0.3) : .white) }.disabled(localUndoStack.isEmpty); Button { popRedo() } label: { Image(systemName: "arrow.uturn.forward.circle.fill").foregroundColor(localRedoStack.isEmpty ? .gray.opacity(0.3) : .blue) }.disabled(localRedoStack.isEmpty) }.font(.system(size: isIPhone ? 16 : 22)).scaleEffect(iconScale)
                    if focusedRowID != nil || activeEditingID != nil { HStack(spacing: 0) { Button { applyIndentation(delta: -1) } label: { Image(systemName: "arrow.left.to.line.compact") }; Button { applyIndentation(delta: 1) } label: { Image(systemName: "arrow.right.to.line.compact") } }; Menu { let config = getFocusedRowConfig(); if !config.presets.isEmpty { Section("预设") { ForEach(config.presets, id: \.self) { p in Button(p) { insertTextIntoFocusedRow(p) } } } }; Section("智能列表") { Button { applySmartListAction(.startNew) } label: { Label("新开编号", systemImage: "list.number") }; Button { applySmartListAction(.continueExisting) } label: { Label("继续编号", systemImage: "arrow.down.forward.circle") } }; Section("文本插入") { Button { insertTextIntoFocusedRow(formatDate("yyMMdd")) } label: { Label("插入日期 yyMMdd", systemImage: "calendar") }; Button { insertTextIntoFocusedRow(formatDate("HHmm")) } label: { Label("插入时刻 HHmm", systemImage: "clock") } }; Divider(); Button(role: .destructive) { clearFocusedRow() } label: { Label("清空行内容", systemImage: "eraser.fill") } } label: { Image(systemName: "sparkles") } }
                    if liveTable.type == .taskList { Menu { Picker("显示层级", selection: $maxDisplayLevel) { Text("全部").tag(100); Text("L0 (1.)").tag(0); Text("L1 (a.)").tag(1); Text("L2 (i.)").tag(2); Text("L3 (括号)").tag(3); Text("L4 (尖括号)").tag(4); Text("L5 (项目符号)").tag(5) }.onChange(of: maxDisplayLevel) { _, val in applyMaxLevelFolding(val) } } label: { Image(systemName: "line.3.horizontal.decrease.circle").font(.system(size: 18, weight: .semibold)).foregroundColor(maxDisplayLevel < 100 ? .orange : .white) } }
                    Menu {
                        Button { if let url = asStore.exportCSVFile(for: liveTable) { shareItems = [url]; showShareSheet = true } } label: { Label("导出CSV", systemImage: "doc.text") }
                        Button {
                            Task {
                                if let img = await generateImage(), let url = saveImageToTempFile(img) {
                                    await MainActor.run {
                                        self.shareItems = [url]
                                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { self.showShareSheet = true }
                                    }
                                }
                            }
                        } label: { Label("导出图片", systemImage: "photo") }
                    } label: { Image(systemName: "square.and.arrow.up").font(.system(size: 18, weight: .semibold)) }
                }
            }
        }
        .background(ShareSheet(isPresented: $showShareSheet, items: shareItems))
        .onAppear {
            guard !isLoaded else { return }
            applyLiveTableSnapshot()
        }
        .onChange(of: liveTable.id) { _, _ in
            applyLiveTableSnapshot()
        }
        .onDisappear { if liveTable.type != .markdown && liveTable.type != .lessonPlanNodes { saveToDisk(isSessionEnd: true); asStore.isUserEditing = false; localUndoStack.removeAll(); localRedoStack.removeAll() } }
        .onReceive(autoSaveTimer) { _ in if liveTable.type != .markdown && liveTable.type != .lessonPlanNodes { saveToDisk(isSessionEnd: false) } }
    }
    
    private var wordSearchHeader: some View {
        HStack(spacing: 12) {
            HStack {
                Image(systemName: "magnifyingglass").foregroundColor(.orange).font(.system(size: 13, weight: .bold))
                TextField("Word式定位查找...", text: $searchText)
                    .font(.system(size: 14, weight: .medium))
                    .foregroundColor(.white)
                    .submitLabel(.search)
                    .onSubmit { updateMatches() }
                if !searchText.isEmpty {
                    Button { searchText = ""; matchIDs = [] } label: { Image(systemName: "xmark.circle.fill").foregroundColor(.gray).font(.system(size: 14)) }
                }
            }
            .padding(.horizontal, 10).padding(.vertical, 8)
            .background(Color.white.opacity(0.08)).cornerRadius(10)
            
            if !matchIDs.isEmpty {
                HStack(spacing: 15) {
                    Button { navigateMatch(delta: -1) } label: { Image(systemName: "chevron.up") }
                    Button { navigateMatch(delta: 1) } label: { Image(systemName: "chevron.down") }
                }
                .font(.system(size: 16, weight: .bold)).foregroundColor(.blue)
            }
        }
        .padding(.horizontal, 16).padding(.vertical, 10)
        .background(Color.black.opacity(0.3))
        .overlay(Rectangle().fill(Color.white.opacity(0.1)).frame(height: 0.5), alignment: .bottom)
    }

    func pushUndo() { localUndoStack.append(sandboxRows); localRedoStack.removeAll(); if localUndoStack.count > 50 { localUndoStack.removeFirst() } }
    
    // 【核心修改】：针对 macOS 包装 UIImpactFeedbackGenerator
    func popUndo() {
        guard let prev = localUndoStack.popLast() else { return }
        localRedoStack.append(sandboxRows)
        sandboxRows = prev
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        #endif
    }
    
    func popRedo() {
        guard let next = localRedoStack.popLast() else { return }
        localUndoStack.append(sandboxRows)
        sandboxRows = next
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
        #endif
    }
    
    func clearContent(id: UUID) {
        guard let index = sandboxRows.firstIndex(where: { $0.id == id }) else { return }
        pushUndo()
        var row = sandboxRows[index]
        row.value = updateRowValue(originalValue: row.value, originalKey: row.key, newContent: "")
        sandboxRows[index] = row
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
        #endif
    }

    private func applyLiveTableSnapshot() {
        guard liveTable.type != .markdown && liveTable.type != .lessonPlanNodes else { return }
        localTitle = liveTable.title
        sandboxRows = liveTable.rows
        initialTitle = liveTable.title
        initialRows = liveTable.rows
        localUndoStack.removeAll()
        localRedoStack.removeAll()
        searchText = ""
        matchIDs = []
        currentMatchIndex = 0
        targetScrollID = nil
        focusedRowID = nil
        activeEditingID = nil
        asStore.editingTableID = liveTable.id
        isLoaded = true
    }
    
    func isRowHidden(index: Int, in rows:[ArchiveRow]) -> Bool { if foldedIDs.isEmpty { return false }; let parentIndices = asStore.findParentIndices(in: rows, for: index); return parentIndices.contains { foldedIDs.contains(rows[$0].id) } }
    func applyMaxLevelFolding(_ level: Int) { withAnimation(.spring(response: 0.35)) { foldedIDs.removeAll(); if level >= 100 { return }; for (idx, row) in sandboxRows.enumerated() { if let data = asStore.parseTaskData(row.value), data.level == level { if asStore.hasChildren(in: sandboxRows, at: idx) { foldedIDs.insert(row.id) } } } } }
    
    func updateMatches() {
        if searchText.isEmpty { matchIDs = []; currentMatchIndex = 0; return }
        let found = sandboxRows.compactMap { row -> UUID? in
            let rawVal = row.value
            let rawKey = row.key
            if rawKey.localizedCaseInsensitiveContains(searchText) { return row.id }
            if let data = rawVal.data(using: .utf8) {
                if let standard = try? JSONDecoder().decode(StandardRowData.self, from: data) {
                    if standard.title.localizedCaseInsensitiveContains(searchText) || standard.content.localizedCaseInsensitiveContains(searchText) { return row.id }
                }
                if let task = try? JSONDecoder().decode(TaskRowData.self, from: data) {
                    if task.title.localizedCaseInsensitiveContains(searchText) { return row.id }
                }
            }
            return nil
        }
        matchIDs = found
        currentMatchIndex = 0
        if let first = found.first {
            asStore.expandParentsOfMatches(rows: sandboxRows, matchIDs: found, foldedIDs: &foldedIDs)
            targetScrollID = first
        }
    }
    
    func navigateMatch(delta: Int) { guard !matchIDs.isEmpty else { return }; currentMatchIndex = (currentMatchIndex + delta + matchIDs.count) % matchIDs.count; targetScrollID = matchIDs[currentMatchIndex] }
    var themeColor: Color { let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: Date())!; let s = GlobalLogic.calculateScore(for: yesterday, records: timeStore.getRecordsForDisplay(for: yesterday), es: efficiencyStore); if s >= 100 { return Color(red: 0.6, green: 0.2, blue: 1.0) }; if s >= 80 { return .yellow }; if s >= 60 { return .green }; return Color(white: 0.6) }
    func focusNextRow(currentID: UUID) { guard let index = sandboxRows.firstIndex(where: { $0.id == currentID }) else { return }; if index < sandboxRows.count - 1 { let nextID = sandboxRows[index + 1].id; focusedRowID = nil; DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { focusedRowID = nextID } } }
    
    private func applyIndentation(delta: Int) { guard let id = focusedRowID ?? activeEditingID, let idx = sandboxRows.firstIndex(where: { $0.id == id }) else { return }; applyIndentationToRow(at: idx, delta: delta) }
    
    private func applyIndentationToRow(at idx: Int, delta: Int) {
        var row = sandboxRows[idx]
        if let taskData = asStore.parseTaskData(row.value) {
            var modified = taskData
            modified.level = max(0, taskData.level + delta)
            if let encoded = try? JSONEncoder().encode(modified), let jsonStr = String(data: encoded, encoding: .utf8) {
                row.value = jsonStr
                sandboxRows[idx] = row
                #if !os(macOS)
                UIImpactFeedbackGenerator(style: .light).impactOccurred()
                #endif
            }
        } else {
            let raw = getRawContent(from: row.value)
            let normalized = asStore.normalizeListLine(raw)
            if asStore.detectLevel(of: normalized) == -1 { return }
            let processed = delta > 0 ? asStore.increaseListLevel(text: normalized) : asStore.smartDecreaseIndent(text: normalized, allRows: sandboxRows, currentIndex: idx)
            if processed != raw {
                row.value = updateRowValue(originalValue: row.value, originalKey: row.key, newContent: processed)
                sandboxRows[idx] = row
                #if !os(macOS)
                UIImpactFeedbackGenerator(style: .light).impactOccurred()
                #endif
            }
        }
    }
    
    private enum SmartAction { case startNew, continueExisting }
    
    private func applySmartListAction(_ action: SmartAction) {
        guard let id = focusedRowID ?? activeEditingID, let idx = sandboxRows.firstIndex(where: { $0.id == id }) else { return }
        var row = sandboxRows[idx]
        let raw = getRawContent(from: row.value)
        let processed = action == .startNew ? asStore.startNewNumbering(text: raw) : asStore.continueNumbering(text: raw)
        row.value = updateRowValue(originalValue: row.value, originalKey: row.key, newContent: processed)
        sandboxRows[idx] = row
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
        #endif
    }
    
    private func getRawContent(from v: String) -> String { if let data = v.data(using: .utf8), let d = try? JSONDecoder().decode(StandardRowData.self, from: data) { return d.content }; return v }
    private func updateRowValue(originalValue: String, originalKey: String, newContent: String) -> String { if let data = originalValue.data(using: .utf8), var decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) { decoded.content = newContent; if let enc = try? JSONEncoder().encode(decoded), let str = String(data: enc, encoding: .utf8) { return str } }; return newContent }
    private func getFocusedRowConfig() -> KeyStyleConfig { guard let id = focusedRowID ?? activeEditingID, let row = sandboxRows.first(where: { $0.id == id }) else { return KeyStyleConfig() }; return asStore.getKeyConfigObj(templateID: table.templateID, key: row.key) }
    private func insertTextIntoFocusedRow(_ t: String) { guard let id = focusedRowID ?? activeEditingID, let idx = sandboxRows.firstIndex(where: { $0.id == id }) else { return }; var row = sandboxRows[idx]; let raw = getRawContent(from: row.value); let processed = raw + (raw.isEmpty || raw.hasSuffix("\n") ? "" : " ") + t; row.value = updateRowValue(originalValue: row.value, originalKey: row.key, newContent: processed); sandboxRows[idx] = row }
    private func formatDate(_ f: String) -> String { let df = DateFormatter(); df.dateFormat = f; return df.string(from: Date()) }
    private func clearFocusedRow() { guard let id = focusedRowID ?? activeEditingID, let idx = sandboxRows.firstIndex(where: { $0.id == id }) else { return }; var row = sandboxRows[idx]; row.value = updateRowValue(originalValue: row.value, originalKey: row.key, newContent: ""); sandboxRows[idx] = row }
    
    private func saveImageToTempFile(_ img: UIImage) -> URL? {
        let safeName = CloudFileManager.shared.getSanitizedFileName(localTitle.isEmpty ? "Export" : localTitle)
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("\(safeName).png")
        if let data = img.pngData() {
            try? data.write(to: url)
            return url
        }
        return nil
    }
    
    func saveToDisk(isSessionEnd: Bool) { let hasChanges = (liveTable.title != localTitle) || (liveTable.rows != sandboxRows); if hasChanges { var t = liveTable; t.title = localTitle; t.rows = sandboxRows; asStore.persistTableChanges(table: t, categoryID: categoryID, oldTitle: initialTitle) } ; if isSessionEnd { let sessionChanged = (localTitle != initialTitle) || (sandboxRows != initialRows); if sessionChanged { var finalTable = liveTable; finalTable.title = localTitle; finalTable.rows = sandboxRows; if let data = try? JSONEncoder().encode(finalTable) { BackupManager.shared.saveBackup(data: data, module: "Archives", subID: table.id.uuidString) } } } }
    @MainActor private func generateImage() async -> UIImage? { let r = ImageRenderer(content: TableExportView(table: liveTable, asStore: asStore).environmentObject(settingsStore)); r.scale = displayScale; return r.uiImage }
    func moveRows(from src: IndexSet, to dst: Int) { sandboxRows.move(fromOffsets: src, toOffset: dst) }
}

// MARK: - 专用清单行组件 - v14 - 适配 macOS 震动反馈

struct TaskListRowView: View {
    @Binding var row: ArchiveRow
    var isSearchHit: Bool = false
    var templateID: UUID?
    @EnvironmentObject var asStore: ArchiveStore
    
    var focusedRowID: FocusState<UUID?>.Binding
    var onNextRow: () -> Void
    var onToggleCascade: (UUID) -> Void

    private var taskBinding: Binding<TaskRowData> {
        Binding(
            get: { asStore.parseTaskData(row.value) ?? TaskRowData(title: row.value, isCompleted: false, parentID: nil, level: 0) },
            set: { newData in if let json = try? JSONEncoder().encode(newData), let str = String(data: json, encoding: .utf8) { row.value = str } }
        )
    }

    var body: some View {
        let task = taskBinding.wrappedValue
        let indent: CGFloat = CGFloat(task.level) * 24.0
        
        let levelStyle = asStore.getLevelStyleObj(templateID: templateID, level: task.level)
        
        Button { toggleCompletion() } label: {
            HStack(alignment: .top, spacing: 12) {
                if indent > 0 { Color.clear.frame(width: indent, height: 1) }
                ZStack {
                    Circle().stroke(task.isCompleted ? Color.blue.opacity(0.5) : colorFromStr(levelStyle.color), lineWidth: 1.5).frame(width: 22, height: 22)
                    if task.isCompleted { Circle().fill(colorFromStr(levelStyle.color)).frame(width: 14, height: 14) }
                }.padding(.top, 2)
                
                Text(task.title.isEmpty ? "无标题任务" : task.title)
                    .font(getFont(levelStyle))
                    .foregroundColor(task.isCompleted ? .white.opacity(0.4) : colorFromStr(levelStyle.color))
                    .strikethrough(task.isCompleted)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.vertical, 2)
                
                Spacer()
            }.contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .padding(.vertical, 6).padding(.horizontal, 12)
        .background {
            RoundedRectangle(cornerRadius: 12)
                .stroke(isSearchHit ? Color.blue : Color.clear, lineWidth: 2)
                .shadow(color: isSearchHit ? Color.blue.opacity(0.6) : .clear, radius: 6)
        }
    }
    
    func toggleCompletion() {
        var t = taskBinding.wrappedValue
        t.isCompleted.toggle()
        taskBinding.wrappedValue = t
        onToggleCascade(row.id)
        
        #if !os(macOS)
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
        #endif
    }

    func getFont(_ cfg: KeyStyleConfig) -> Font {
        let weight: Font.Weight = cfg.isBold ? .bold : .regular
        let size = max(14, cfg.fontSize * 0.8)
        if let name = cfg.customFontName { return .custom(name, size: size).weight(weight) }
        switch cfg.fontDesign {
        case "rounded": return .system(size: size, weight: weight, design: .rounded)
        case "monospaced": return .system(size: size, weight: weight, design: .monospaced)
        case "serif": return .system(size: size, weight: weight, design: .serif)
        default: return .system(size: size, weight: weight, design: .default)
        }
    }

    func colorFromStr(_ s: String) -> Color {
        switch s {
        case "red": return .red; case "blue": return .blue; case "green": return .green
        case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan
        case "white": return .white; default: return .white
        }
    }
}

// MARK: - 智能文本编辑器 (UIKit/AppKit Wrapper) - v10 - 适配 macOS
//
// SmartTextEditor
// (修改内容：补充 AppKit 的 NSTextView 实现，确保智能输入规则和自适应高度在双端兼容)

import SwiftUI

#if !os(macOS)
struct SmartTextEditor: UIViewRepresentable {
    @Binding var text: String
    @Binding var dynamicHeight: CGFloat
    
    var onEditingChanged: (Bool) -> Void
    var onSmartInput: (String, String, Int) -> (String, Int?)
    
    func makeUIView(context: Context) -> UITextView {
        let textView = UITextView()
        textView.isScrollEnabled = false
        textView.backgroundColor = .clear
        textView.font = .systemFont(ofSize: 18, weight: .regular)
        textView.textColor = UIColor(white: 0.9, alpha: 1.0)
        textView.textContainerInset = .zero
        textView.textContainer.lineFragmentPadding = 0
        textView.textContainer.lineBreakMode = .byCharWrapping
        textView.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        
        textView.delegate = context.coordinator
        return textView
    }
    
    func updateUIView(_ uiView: UITextView, context: Context) {
        // 1. 同步文字内容
        if uiView.text != text {
            let oldSelectedRange = uiView.selectedRange
            let oldTextLength = uiView.text.utf16.count
            uiView.text = text
            
            if uiView.isFirstResponder {
                let newTextLength = text.utf16.count
                let lengthDiff = newTextLength - oldTextLength
                if lengthDiff != 0 && oldSelectedRange.location > 0 {
                    let newLocation = oldSelectedRange.location + lengthDiff
                    let finalLocation = max(0, min(newLocation, newTextLength))
                    uiView.selectedRange = NSRange(location: finalLocation, length: 0)
                }
            }
        }
        
        DispatchQueue.main.async {
            context.coordinator.recalculateHeight(view: uiView)
        }
    }
    
    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }
    
    class Coordinator: NSObject, UITextViewDelegate {
        var parent: SmartTextEditor
        init(_ parent: SmartTextEditor) { self.parent = parent }
        
        func textViewDidBeginEditing(_ textView: UITextView) { parent.onEditingChanged(true) }
        func textViewDidEndEditing(_ textView: UITextView) { parent.onEditingChanged(false) }

        func textView(_ textView: UITextView, shouldChangeTextIn range: NSRange, replacementText text: String) -> Bool {
            if let (processed, newCursor) = applySmartEditorTransformForEdit(
                originalText: textView.text ?? "",
                affectedRange: range,
                replacement: text,
                transform: parent.onSmartInput
            ) {
                textView.text = processed
                let target = newCursor ?? (range.location + (text as NSString).length)
                textView.selectedRange = NSRange(location: max(0, min(target, processed.utf16.count)), length: 0)
                parent.text = processed
                recalculateHeight(view: textView)
                return false
            }
            return true
        }
        
        func textViewDidChange(_ textView: UITextView) {
            let oldValue = parent.text
            let newValue = textView.text ?? ""
            let currentCursor = textView.selectedRange.location
            
            let (processed, newCursor) = parent.onSmartInput(oldValue, newValue, currentCursor)
            
            if processed != newValue {
                textView.text = processed
                if let specifiedCursor = newCursor {
                    textView.selectedRange = NSRange(location: max(0, min(specifiedCursor, processed.utf16.count)), length: 0)
                } else {
                    let diff = processed.utf16.count - newValue.utf16.count
                    let candidate = currentCursor + diff
                    textView.selectedRange = NSRange(location: max(0, min(candidate, processed.utf16.count)), length: 0)
                }
                parent.text = processed
            } else {
                parent.text = newValue
            }
            recalculateHeight(view: textView)
        }
        
        func recalculateHeight(view: UITextView) {
            let width = view.bounds.width
            if width <= 0 { return }
            let size = view.sizeThatFits(CGSize(width: width, height: .greatestFiniteMagnitude))
            if abs(parent.dynamicHeight - size.height) > 0.1 {
                parent.dynamicHeight = size.height
            }
        }
    }
}
#else
import AppKit

struct SmartTextEditor: NSViewRepresentable {
    @Binding var text: String
    @Binding var dynamicHeight: CGFloat
    
    var onEditingChanged: (Bool) -> Void
    var onSmartInput: (String, String, Int) -> (String, Int?)
    
    func makeNSView(context: Context) -> NSTextView {
        let textView = NSTextView()
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.autoresizingMask = [.width]
        textView.backgroundColor = .clear
        textView.font = .systemFont(ofSize: 18, weight: .regular)
        textView.textColor = NSColor(white: 0.9, alpha: 1.0)
        textView.textContainerInset = .zero
        textView.textContainer?.lineFragmentPadding = 0
        
        textView.delegate = context.coordinator
        return textView
    }
    
    func updateNSView(_ nsView: NSTextView, context: Context) {
        if nsView.string != text {
            let oldSelectedRange = nsView.selectedRange()
            let oldTextLength = nsView.string.utf16.count
            nsView.string = text
            
            if nsView.window?.firstResponder == nsView {
                let newTextLength = text.utf16.count
                let lengthDiff = newTextLength - oldTextLength
                if lengthDiff != 0 && oldSelectedRange.location > 0 {
                    let newLocation = oldSelectedRange.location + lengthDiff
                    let finalLocation = max(0, min(newLocation, newTextLength))
                    nsView.setSelectedRange(NSRange(location: finalLocation, length: 0))
                }
            }
        }
        
        DispatchQueue.main.async {
            context.coordinator.recalculateHeight(view: nsView)
        }
    }
    
    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }
    
    class Coordinator: NSObject, NSTextViewDelegate {
        var parent: SmartTextEditor
        init(_ parent: SmartTextEditor) { self.parent = parent }
        
        func textDidBeginEditing(_ notification: Notification) { parent.onEditingChanged(true) }
        func textDidEndEditing(_ notification: Notification) { parent.onEditingChanged(false) }

        func textView(_ textView: NSTextView, shouldChangeTextIn affectedCharRange: NSRange, replacementString: String?) -> Bool {
            let replacement = replacementString ?? ""
            if let (processed, newCursor) = applySmartEditorTransformForEdit(
                originalText: textView.string,
                affectedRange: affectedCharRange,
                replacement: replacement,
                transform: parent.onSmartInput
            ) {
                textView.string = processed
                let target = newCursor ?? (affectedCharRange.location + (replacement as NSString).length)
                textView.setSelectedRange(NSRange(location: max(0, min(target, processed.utf16.count)), length: 0))
                parent.text = processed
                recalculateHeight(view: textView)
                return false
            }
            return true
        }
        
        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            let oldValue = parent.text
            let newValue = textView.string
            let currentCursor = textView.selectedRange().location
            
            let (processed, newCursor) = parent.onSmartInput(oldValue, newValue, currentCursor)
            
            if processed != newValue {
                textView.string = processed
                if let specifiedCursor = newCursor {
                    textView.setSelectedRange(NSRange(location: max(0, min(specifiedCursor, processed.utf16.count)), length: 0))
                } else {
                    let diff = processed.utf16.count - newValue.utf16.count
                    let candidate = currentCursor + diff
                    textView.setSelectedRange(NSRange(location: max(0, min(candidate, processed.utf16.count)), length: 0))
                }
                parent.text = processed
            } else {
                parent.text = newValue
            }
            recalculateHeight(view: textView)
        }
        
        func recalculateHeight(view: NSTextView) {
            guard let layoutManager = view.layoutManager, let textContainer = view.textContainer else { return }
            let width = view.bounds.width
            if width <= 0 { return }
            
            textContainer.containerSize = NSSize(width: width, height: .greatestFiniteMagnitude)
            layoutManager.ensureLayout(for: textContainer)
            let size = layoutManager.usedRect(for: textContainer).size
            
            if abs(parent.dynamicHeight - size.height) > 0.1 {
                parent.dynamicHeight = size.height
            }
        }
    }
}
#endif

// MARK: - 详情行编辑组件 - v41 - 修复未使用变量警告
//
// struct DetailRowView
// (修改：移除 proxyValue set 中未使用的 oldValue 变量)


struct DetailRowView: View {
    let categoryID: UUID
    let tableID: UUID
    @Binding var row: ArchiveRow
    var isSearchHit: Bool = false
    let templateID: UUID?
    
    var focusedRowID: FocusState<UUID?>.Binding
    @Binding var activeEditingID: UUID?
    var onNextRow: () -> Void = {}
    var onClear: () -> Void = {}
    
    @EnvironmentObject var asStore: ArchiveStore
    @EnvironmentObject var teachingStore: TeachingStore
    @State private var inputHeight: CGFloat = 24
    struct SheetItem: Identifiable { let id: UUID }
    @State private var activeRefSheetItem: SheetItem? = nil
    
    var proxyValue: Binding<String> {
        Binding(
            get: {
                if let data = row.value.data(using: .utf8), let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) { return decoded.content }
                if let data = asStore.parseTaskData(row.value) { return String(repeating: "\t", count: data.level) + data.title }
                return row.value
            },
            set: { newValue in
                // 【修复】移除未使用的 oldValue 计算
                
                if let data = row.value.data(using: .utf8), var decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) {
                    decoded.content = newValue
                    if let encoded = try? JSONEncoder().encode(decoded), let jsonStr = String(data: encoded, encoding: .utf8) { row.value = jsonStr }
                }
                else if var data = asStore.parseTaskData(row.value) {
                    let level = newValue.prefix(while: { $0 == "\t" }).count
                    data.title = String(newValue.drop(while: { $0 == "\t" })); data.level = level
                    if let json = try? JSONEncoder().encode(data), let jsonStr = String(data: json, encoding: .utf8) { row.value = jsonStr }
                }
                else {
                    let newData = StandardRowData(title: row.key, content: newValue)
                    if let encoded = try? JSONEncoder().encode(newData), let jsonStr = String(data: encoded, encoding: .utf8) { row.value = jsonStr } else { row.value = newValue }
                }
            }
        )
    }
    
    var body: some View {
        let isActive = (activeEditingID == row.id)
        let config = asStore.getKeyConfigObj(templateID: templateID, key: row.key)
        VStack(alignment: .leading, spacing: 8) {
            headerView(config: config)
            editorView
            if isActive && !config.presets.isEmpty {
                presetInputBar(config: config)
            }
        }
        .padding(16)
        .background(RoundedRectangle(cornerRadius: 16).fill(Color.white.opacity(isActive ? 0.08 : 0.05)))
        .overlay(
            RoundedRectangle(cornerRadius: 16)
                .stroke(isSearchHit ? Color.blue : (isActive ? Color.blue.opacity(0.3) : Color.white.opacity(0.1)),
                        lineWidth: isSearchHit ? 2 : 0.5)
                .shadow(color: isSearchHit ? Color.blue.opacity(0.6) : .clear, radius: 6)
        )
        .frame(maxWidth: .infinity, alignment: .leading).fixedSize(horizontal: false, vertical: true).padding(.vertical, 4)
        .sheet(item: $activeRefSheetItem) { item in
            TTModalSheetContainer(minWidth: 900, minHeight: 720) {
                TaskDetailView(tableID: item.id, title: "关联任务")
                    .toolbar {
                        ToolbarItem(placement: .confirmationAction) {
                            Button("完成") {
                                syncTaskContent(uuid: item.id)
                                activeRefSheetItem = nil
                            }
                        }
                    }
            }
        }
        .swipeActions(edge: .trailing, allowsFullSwipe: true) {
            Button { onClear() } label: { Label("清空", systemImage: "eraser.fill") }.tint(.orange)
        }
    }
    
    private func headerView(config: KeyStyleConfig) -> some View {
        return HStack(alignment: .center) {
            Text(getDisplayTitle()).font(getKeyFont(config: config)).foregroundColor(colorFromStr(config.color)).tracking(0.5)
            Spacer()
            if let refID = getRefID(config: config) { Button { if let uuid = UUID(uuidString: refID) { activeRefSheetItem = SheetItem(id: uuid) } } label: { Image(systemName: "arrow.up.right.square").font(.system(size: 14)).foregroundColor(.blue).padding(6).background(Circle().fill(Color.blue.opacity(0.1))) }.buttonStyle(.plain) }
        }
    }
    
    private var editorView: some View {
        ZStack {
            Button(action: { onNextRow() }) { }.keyboardShortcut(.return, modifiers: .command).opacity(0).frame(width: 0, height: 0)
            
            SmartTextEditor(
                text: proxyValue,
                dynamicHeight: $inputHeight,
                onEditingChanged: { isEditing in
                    DispatchQueue.main.async {
                        if isEditing { activeEditingID = row.id; focusedRowID.wrappedValue = row.id }
                        else { if activeEditingID == row.id { activeEditingID = nil } }
                    }
                },
                onSmartInput: { old, new, cursor in
                    let (smartListProcessed, smartListCursor) = asStore.handleSmartListInput(oldValue: old, newValue: new, cursorIndex: cursor)
                    let quickInputCursor = smartListCursor ?? cursor
                    return applyLPQuickInputRules(
                        text: smartListProcessed,
                        cursorIndex: quickInputCursor,
                        rules: teachingStore.config.quickInputRules
                    )
                }
            )
            .frame(height: inputHeight).frame(maxWidth: .infinity)
        }
    }

    private func presetInputBar(config: KeyStyleConfig) -> some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(config.presets, id: \.self) { preset in
                    Button {
                        applyPreset(preset)
                    } label: {
                        Text(preset)
                            .font(.system(size: 12, weight: .semibold))
                            .foregroundColor(.orange)
                            .padding(.horizontal, 12)
                            .padding(.vertical, 8)
                            .background(
                                Capsule().fill(Color.orange.opacity(0.12))
                            )
                            .overlay(
                                Capsule().stroke(Color.orange.opacity(0.25), lineWidth: 1)
                            )
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.top, 4)
        }
    }

    private func applyPreset(_ preset: String) {
        let raw = proxyValue.wrappedValue
        proxyValue.wrappedValue = raw + (raw.isEmpty || raw.hasSuffix("\n") ? "" : " ") + preset
        activeEditingID = row.id
        focusedRowID.wrappedValue = row.id
    }
    
    private func getDisplayTitle() -> String { if let data = row.value.data(using: .utf8), let decoded = try? JSONDecoder().decode(StandardRowData.self, from: data) { return decoded.title }; return row.key }
    func getRefID(config: KeyStyleConfig) -> String? { if let id = config.refTableID { return id }; if config.type.hasPrefix("ref:") { return String(config.type.dropFirst(4)) }; return nil }
    func syncTaskContent(uuid: UUID) { let report = asStore.generateTaskReport(tableID: uuid); if !proxyValue.wrappedValue.isEmpty { proxyValue.wrappedValue += "\n" + report } else { proxyValue.wrappedValue = report } }
    func getKeyFont(config: KeyStyleConfig) -> Font { let size = config.fontSize; let weight: Font.Weight = config.isBold ? .bold : .semibold; if let name = config.customFontName { return .custom(name, size: size).weight(weight) }; switch config.fontDesign { case "rounded": return .system(size: size, weight: weight, design: .rounded); case "monospaced": return .system(size: size, weight: weight, design: .monospaced); case "serif": return .system(size: size, weight: weight, design: .serif); default: return .system(size: size, weight: weight, design: .default) } }
    func colorFromStr(_ s: String) -> Color { switch s { case "red": return .red; case "blue": return .blue; case "green": return .green; case "orange": return .orange; case "purple": return .purple; case "yellow": return .yellow; case "cyan": return .cyan; case "white": return .white; default: return .white } }
}

