struct BackupListView: View {
  let backups: [BackupFile]
  let now: Date
  let onRestore: (BackupFile) -> Void
  var body: some View {
      List {
          ForEach(backups.indices, id: \.self) { index in
              let backup = backups[index]
              BackupRowView(backup: backup, timeAgo: getTimeAgo(backup.date), onRestore: { onRestore(backup) })
          }
      }.scrollContentBackground(.hidden)
  }
  func getTimeAgo(_ date: Date) -> String {
      let diff = Int(now.timeIntervalSince(date))
      if diff < 60 { return "刚刚" }
      if diff < 3600 { return "\(diff / 60) 分钟前" }
      if diff < 86400 { return "\(diff / 3600) 小时前" }
      return "\(diff / 86400) 天前"
  }
}

struct BackupRowView: View {
  let backup: BackupFile
  let timeAgo: String
  let onRestore: () -> Void
  var body: some View {
      HStack {
          VStack(alignment: .leading, spacing: 4) {
              Text(timeAgo).font(.headline).foregroundColor(.white)
              Text(backup.date.formatted(date: .numeric, time: .standard)).font(.caption2).foregroundColor(.gray)
          }
          Spacer()
          Button(action: onRestore) { Text("恢复").font(.subheadline).fontWeight(.bold).foregroundColor(.orange).padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().stroke(Color.orange, lineWidth: 1)) }.buttonStyle(.plain)
      }.padding(.vertical, 8).contentShape(Rectangle())
  }
}

struct HistoryBackupRow: View {
  let backup: BackupFile
  let currentTime: Date
  let onRestore: () -> Void
  var body: some View {
      HStack {
          VStack(alignment: .leading, spacing: 4) {
              Text(formatTimeAgo(backup.date, currentTime: currentTime)).font(.headline).foregroundColor(.white)
              Text(backup.date.formatted(date: .numeric, time: .shortened)).font(.caption).foregroundColor(.gray)
          }
          Spacer()
          Button(action: onRestore) { Text("恢复").font(.subheadline).fontWeight(.bold).foregroundColor(.orange).padding(.horizontal, 12).padding(.vertical, 6).background(Capsule().stroke(Color.orange, lineWidth: 1)) }.buttonStyle(.plain)
      }.padding(.vertical, 8)
  }
}

private func formatTimeAgo(_ date: Date, currentTime: Date) -> String {
  let diff = Int(currentTime.timeIntervalSince(date))
  if diff < 60 { return "刚刚" }
  else if diff < 3600 { return "\(diff / 60)分钟前" }
  else if diff < 86400 { return "\(diff / 3600)小时前" }
  else { return "\(diff / 86400)天前" }
}

