              Group { NarrowGoldSpike(height: h2, width: itemWidth).rotationEffect(.degrees(-spacingAngle), anchor: .bottom); NarrowGoldSpike(height: h2, width: itemWidth).rotationEffect(.degrees(spacingAngle), anchor: .bottom) }
